return {
  ["29:40f8"] = "Ten paciencia.\n¡Te buscaré\011POKéMON raros!",
  ["29:4126"] = "Yo también debo\nencaminarme hacia\011las montañas…",
  ["29:4158"] = "Tu teléfono está\nlleno.\012No puede registrar\nmi número.",
  ["29:418d"] = "¡Vale, de acuerdo!\012¡Mis POKéMON y\nyo estamos\011deseando empezar!",
  ["29:41c0"] = "Desde aquí puedo\nver el CENTRO\012COMERCIAL de\nCIUDAD TRIGAL.\012Suelen tener\nrebajas en la\012azotea muy a\nmenudo.\012¿Me das tu número\nde teléfono?\012Te llamaré cuando\nvea alguna ganga.",
  ["29:426a"] = "Si me das tu\nnúmero, te llamaré\012cuando tengan\nalguna ganga.",
  ["29:42ab"] = "Voy al CENTRO\nCOMERCIAL de\012CIUDAD TRIGAL\ntodos los días,\012así que sé cuándo\nhay rebajas.",
  ["29:42f2"] = "De todos modos…\012Si no tienes mucho\ndinero, apunta mi\011teléfono.\012Te llamaré si hay\nrebajas.",
  ["29:434a"] = "En tu teléfono\nno tienes espacio\011para más números.",
  ["29:4382"] = "¡Te esperaba!\n¡Incluso he dejado\012de hacer compras\npara mejorar a mis\011POKéMON!",
  ["29:4405"] = "Cuando veo a\nentrenadores\012fuertes, quiero\nser su animadora.\012Cuando voy de\npaseo, a veces\011recojo objetos.\012¡Si encuentro\nalgo, te lo daré!\012¿Quieres darme tu\nnúmero de\011teléfono?\012Te llamaré cuando\nencuentre algo.",
  ["29:44db"] = "¡Si encuentro\nalgo, te lo daré!\012¿Quieres darme tu\nnúmero de\011teléfono?",
  ["29:451d"] = "Te llamaré cuando\nencuentre algo.",
  ["29:4542"] = "¿Ésas tenemos?\nBueno… ¡Te estaré\011esperando!",
  ["29:4573"] = "¡Tu teléfono ya\nno tiene memoria!",
  ["29:4595"] = "¡Te esperaba!\012¡Le he cogido el\ntranquillo a esto!",
  ["29:45c9"] = "¡Así que por fin\nestás aquí!\012Creo que esto te\nva a alegrar.",
  ["29:4603"] = "Tu MOCHILA parece\nestar completa-\011mente llena.\012Tendré que\nguardarte esto.",
  ["29:4642"] = "¡Nunca antes había\nluchado con\011alguien tan bueno!\012¿Eh? ¿Tú salvaste\na todos los\011SLOWPOKE?\012Claro… ¡Era\nimposible ganarte!\012¿Te parece bien\ndarme tu número de\011teléfono?\012¡No me gustaría\nperderme nada de\012lo que hagas a\npartir de ahora!",
  ["29:470b"] = "¿Me dirás tu núme-\nro de teléfono?",
  ["29:4730"] = "¡Guau! ¡Gracias!\nAhora puedo\012llamarte cuando\nquiera, haya algo\011interesante o no.\012Ya sabes…\nPara charlar…",
  ["29:4794"] = "Oh, pero…\n¡Soy inofensivo!\012¡Sólo quiero\nllamar para hablar\012de todo y de nada\nal mismo tiempo!",
  ["29:47eb"] = "Tu agenda de\nteléfonos ya está\011llena…\012Debes de ser muy\npopular…",
  ["29:4829"] = "¿No sientes como\nsi hubiera más\012POKéMON raros\nque antes?\012Sé positivamente\nque sí, así que\012los busco todo el\ntiempo.\012Si encuentro uno,\nquiero contarle la\012buena nueva a todo\nel mundo.\012¡Ya sé!\nDame tu número de\011teléfono.",
  ["29:48fc"] = "Quiero avisar a la\ngente cuando vea\011POKéMON raros.\012¡Por favor, dame\ntu número de\011teléfono!",
  ["29:494d"] = "Si descubro algún\nPOKéMON curioso,\012¡ten por seguro\nque te llamaré!",
  ["29:498a"] = "¡Bua! ¡Quiero\ncontar mis\011descubrimientos!",
  ["29:49bd"] = "No hay espacio\npara mi número.\012Si borras algún\nnúmero, ¡registra\011el mío!",
  ["29:49fc"] = "¡Ahora me toca\nganar!\012¡Es hora de pasar\npágina!",
  ["29:4a31"] = "Leer libros de\ntexto a menudo\011merece la pena.\012Cuando camino y\nleo a la vez,\012tengo que mirar\nhacia abajo.\012Así que a veces\nencuentro objetos\011en el suelo.\012La próxima vez que\nencuentre algo,\011puedo dártelo.\012¿Me das tu número\nde teléfono?",
  ["29:4b03"] = "Si encuentro algo,\nes tuyo.\012¿Me das tu número\nde teléfono?",
  ["29:4b47"] = "Te llamaré tan\npronto como\011encuentre algo.\012¡Puedes contar con\nello!",
  ["29:4b87"] = "Oh… Pensaba que\nsería una buena\012idea llamarte\nmientras estudio…",
  ["29:4bcd"] = "No hay espacio\npara mi número.",
  ["29:4bec"] = "¡Estaba\nesperándote!\012¡Hoy estoy\npreparado a fondo!",
  ["29:4c24"] = "Esto, esto…\n¡Esto es para ti!",
  ["29:4c47"] = "¡Lástima!\012¡No puedes llevar\nmás objetos!\012Lo guardaré hasta\nque vuelvas.",
  ["29:4c8c"] = "¡Tienes habilidad\ncon los POKéMON!\012Los chicos me dan\nobjetos tras las \012batallas, pero a\nveces me dan\011demasiados.\012La próxima vez,\npuedo darte alguno\012si quieres. Dame\ntu número de\011teléfono.",
  ["29:4d36"] = "Compartiré mis\nregalos contigo.\012Dame tu número de\nteléfono.",
  ["29:4d72"] = "¡La próxima vez\nque alguien me dé\012algo tras una\nbatalla, lo\011compartiré!\012¿Está feo por mi\nparte?",
  ["29:4dcd"] = "¿Eh? ¿No quieres\nnada?\012Pero si todo es\ngratis…",
  ["29:4e01"] = "¡Tu teléfono ya\nno tiene memoria!",
  ["29:4e21"] = "¡Llegas muy tarde!\012¡Estaba deseando\nempezar!",
  ["71:502e"] = "Recibiste {NUM} ¥\npor {STRBUF}.",
  ["71:500d"] = "¿Puedo ayudarte\nen algo más?",
  ["71:4ff9"] = "¡Vuelve cuando\nquieras!",
  ["71:4fd7"] = "Lo siento. No te\npuedo comprar eso.",
  ["71:4fb7"] = "No puedes llevar\nmás objetos.",
  ["71:4f9a"] = "No tienes\nbastante dinero.",
  ["71:4f80"] = "Aquí tienes.\n¡Gracias!",
  ["71:4f62"] = "¡Bienvenido!\n¿Qué deseas?",
  ["71:4f3e"] = "Puedo pagarte\n{NUM}¥.\012¿Te parece bien?",
  ["71:4f33"] = "¿Cuántos?",
  ["71:4f12"] = "No tienes nada\npara vender.",
  ["71:4ef6"] = "De acuerdo.\nHasta luego.",
  ["71:4ed8"] = "¿Eh? No tienes\nbastante dinero.",
  ["71:4eb9"] = "No te queda\nsitio.",
  ["71:4eab"] = "¡Muchas gracias!",
  ["71:4e89"] = "{NUM} unidad/es\nde {STRBUF}\011serán {NUM}¥.",
  ["71:4e7e"] = "¿Cuántos?",
  ["71:4e5f"] = "¿Qué quieres?\n¿Alguna medicina?",
  ["71:4e46"] = "Vuelve en otra\nocasión.",
  ["71:4e28"] = "¡Oh! No tienes\nsuficiente dinero.",
  ["71:4df7"] = "Eso ya lo has\ncomprado. No me\011quedan más.",
  ["71:4dd6"] = "¡Oh! Tu MOCHILA\nestá a tope.",
  ["71:4dcd"] = "Gracias.",
  ["71:4db0"] = "{STRBUF}\ncuesta {NUM}¥.\011¿Lo quieres?",
  ["71:4d47"] = "¡Oye! ¿Quieres ver\nunas gangas?\012Vendo objetos que\nnadie posee, pero\012sólo un objeto de\ncada tipo.",
  ["71:4d2a"] = "Vuelve otra vez.\n¡Je, je, je…!",
  ["71:4d08"] = "¡Je, je…! No\ntienes ese dinero.",
  ["71:4cea"] = "¡Oh! Tu MOCHILA\nestá llena, hijo.",
  ["71:4cce"] = "Gracias, hijo.\n¡Je, je, je…!",
  ["71:4cae"] = "{NUM} unidad/es\nde {STRBUF}\011serán {NUM}¥.",
  ["71:4ca3"] = "¿Cuántos?",
  ["71:4c28"] = "Hola, hijo.\012Vendo hierbas\nmedicinales.\012Son buenas, pero\nun poco amargas.\012Quizá tus POKéMON\nno las quieran.\012¡Je, je, je…!",
  ["71:4c08"] = "{NUM} unidad/es\nde {STRBUF}\011serán {NUM}¥.",
  ["71:4bfd"] = "¿Cuántos?",
  ["70:5cc4"] = "La CARTA fue\nenviada a tu PC.",
  ["70:5ca9"] = "El BUZÓN de tu\nPC está lleno.",
  ["70:5c86"] = "¿Enviar la\nCARTA a tu PC?",
  ["70:5c62"] = "No hay bastante\nespacio para\011quitar la CARTA.",
  ["70:5c47"] = "Quitada CARTA de\n{STRBUF}.",
  ["70:5c22"] = "¿O prefieres\nborrar el mensaje?",
  ["70:5b6f"] = "Primero quita\nla CARTA.",
  ["70:502b"] = "Hay un POKéMON que\nlleva una CARTA.\012Por favor, quita\nla CARTA.",
  ["70:4f8d"] = "La CARTA fue\nsacada del BUZÓN.",
  ["19:6e67"] = "¡Lo siento, pero\nno tengo tiempo\012para hablar cuan-\ndo me entreno!\012¡Mañana podremos\ncharlar un rato!\012¡Yiiija!",
  ["17:4265"] = "¡Presta atención,\npor favor!\012¡Ups! A ver si\ndejo de hablar\012como si fuera\nuna maestra.\012Eres un entrenador\nPOKéMON.\012Como estás\ntrabajando tan\012duro, te voy\na dar esto.",
  ["17:430d"] = "Dale a un POKéMON\nesa GARRA RÁPIDA.\012Y a veces atacará\nel primero\011en combate.",
  ["17:435d"] = "Estoy jugando con\nlas pegatinas de\011mi POKéDEX.",
  ["15:61a6"] = "¡Son adorables!\012Enséñales unas\nbuenas MT.",
  ["19:7096"] = "Estás pensando que\nte gustaría luchar\012conmigo, ¿no es\ncierto?\012¡Sí! ¡Nos vemos en\n{STRBUF}!",
  ["17:442a"] = "Estoy imprimiendo\nmi POKéDEX.\012También puedes\nimprimir las\012CARTAS y\nCAJAS de tu PC.",
  ["15:6279"] = "La opción REGALO\nMISTERIOSO es para\011Game Boy Color.",
  ["17:44e4"] = "¿Qué, qué, qué?",
  ["15:62f3"] = "No puedes cambiar\nel nombre de un\012POKéMON que has\nintercambiado.\012El nombre refleja\nlos sentimientos\012del entrenador\noriginal.",
  ["70:4e54"] = "Está rebosante\nde energía.",
  ["70:4e24"] = "Es el {STRBUF}\nque dejé con el\012ENCARGADO de\nla GUARDERÍA.",
  ["70:4df3"] = "Es el {STRBUF}\nque dejé con\012la ENCARGADA de\nla GUARDERÍA.",
  ["70:4dd8"] = "¿Quieres darle\nun mote a\011{STRBUF}?",
  ["70:4dba"] = "¡{STRBUF}\nsalió del\011HUEVO!",
  ["1b:41a3"] = "Intentaremos no\nmolestar a nadie\011a partir de ahora.",
  ["70:4db0"] = "¿Qué?\012",
  ["6f:5ff2"] = "No tienes sitio en\ntu equipo. Vuelve\011en otro momento.",
  ["6f:5fd1"] = "Cuidaré de él.\n¡Gracias!",
  ["6f:5fba"] = "Cuídalo\nbien.",
  ["6f:5fa5"] = "¡{PLAYER} recibió\nel HUEVO!",
  ["6f:5f00"] = "¡Ah, eres tú!\012Estábamos cuidando\nde tus POKéMON y\012¡menuda sorpresa\nnos hemos llevado!\012¡Tus POKéMON han\ntenido un HUEVO!\012No sabemos cómo ha\nllegado ahí, pero\012es de tus POKéMON.\n¿Lo quieres?",
  ["6f:5ef6"] = "Aún no…",
  ["6f:5ee9"] = "Vuelve cuando\nquieras.",
  ["6f:5ed9"] = "No hay problema.",
  ["6f:5ebc"] = "No tienes\nbastante dinero.",
  ["6f:5ea2"] = "No tienes espacio\nsuficiente.",
  ["6f:5e32"] = "¿Ya de vuelta?\nTu {STRBUF}\012debería pasar más\ntiempo aquí. Pero\012recoger ahora\na tu POKéMON, te\011costará 100¥.",
  ["6f:5e1f"] = "{PLAYER} recogió\na {STRBUF}.",
  ["6f:5e04"] = "¡Perfecto! ¡Aquí\nestá tu POKéMON!",
  ["6f:5d96"] = "Tu {STRBUF}\nha crecido mucho.\012En cuanto a nivel,\nha subido {NUM}.\012Recuperar a tu\nPOKéMON te\011costará {NUM}¥.",
  ["6f:5d64"] = "¿Somos geniales o\nno? ¿Quieres ver a\011tu {STRBUF}?",
  ["6f:5d4b"] = "Vuelve a por él\nmás tarde.",
  ["6f:5d30"] = "Vale. Cuidaré de\ntu {STRBUF}.",
  ["6f:5cff"] = "Si me lo das,\n¿con quién vas\011a combatir?",
  ["6f:5cda"] = "Quita la CARTA y\nvuelve a verme.",
  ["6f:5cb8"] = "Perdona, pero no\nacepto HUEVOS.",
  ["6f:5c97"] = "¿Oh? Pero sólo\ntienes un POKéMON.",
  ["6f:5c79"] = "¿Cuál quieres\nque cuide?",
  ["6f:5bbb"] = "Soy la ENCARGADA\nde la GUARDERÍA.\012¿Sabes algo sobre\nlos HUEVOS?\012Mi marido y yo\nestábamos cuidando\011unos POKéMON.\012¡Y de pronto\nvimos un HUEVO!\012¿No te parece\nincreíble?\012¿Quieres que te\ncuide un POKéMON?",
  ["6f:5b85"] = "Soy la ENCARGADA\nde la GUARDERÍA.\012¿Quieres que te\ncuide un POKéMON?",
  ["6f:5ad8"] = "Soy el ENCARGADO\nde la GUARDERÍA.\012¿Sabes algo sobre\nlos HUEVOS?\012Mi mujer y yo\nestábamos cuidando\011unos POKéMON.\012¡Y de pronto\nvimos un HUEVO!\012¿No te parece\nincreíble?\012¿Quieres que te\ncuide un POKéMON?",
  ["6a:6e28"] = "CLUB DE FANS\nDE POKéMON\011¡Bienvenidos!",
  ["6d:7624"] = "Buenos días.",
  ["6d:75e5"] = "¿Estás mejorando\na tus POKéMON?\012¡El {STRBUF} de\n{STRBUF} está\011muy bien!",
  ["6d:75c9"] = "¡{PLAYER}!\012¡Soy {STRBUF}!\n¿Dónde estás?",
  ["6d:75ac"] = "¡{PLAYER}!\012¡Soy {STRBUF}!\n¿Trabajando mucho?",
  ["6d:758f"] = "¡{PLAYER}!\012¡Soy {STRBUF}!\n¡Buenos días!",
  ["6d:756f"] = "Sí, soy\n{STRBUF}…\012¡Hola, {PLAYER}!",
  ["6d:7548"] = "Sí, soy\n{STRBUF}…\012¡Hola, {PLAYER}!\n¡Yuju!",
  ["6d:751a"] = "Sí, soy\n{STRBUF}…\012¡Hola, {PLAYER}!\n¡Buenos días!",
  ["6d:74c8"] = "¿Qué tal están tus\nPOKéMON?\012¡Mi {STRBUF} y yo\nestamos muy bien!\011¡Ja, ja, ja, ja!",
  ["6d:749b"] = "¡{PLAYER}, soy\n{STRBUF}!\012¿Has cenado bien?",
  ["6d:746f"] = "¡{PLAYER}, soy\n{STRBUF}!\012¿Has comido bien?",
  ["6d:743f"] = "¡{PLAYER}, soy\n{STRBUF}!\012¿Has desayunado\nbien?",
  ["6a:6a6f"] = "Mi POKéMON está\npreparando el\012terreno donde\nedificar.\012Pero no tengo\ndinero para el\011proyecto…",
  ["6d:73ef"] = "¡Yup, yup!\n¡Soy {STRBUF}!\012Ah… ¡y aquí está\n{PLAYER}!",
  ["6d:73c7"] = "¡Yup, yup!\n¡Soy {STRBUF}!\012Ah… ¡y aquí está\n{PLAYER}!",
  ["6a:68e3"] = "RUTA 15\012CIUDAD FUCSIA -\nPUEBLO LAVANDA",
  ["6d:7397"] = "¡Eh, {PLAYER}!\n¡Soy {STRBUF}!",
  ["6d:737f"] = "¡Eh, {PLAYER}!\n¡Soy {STRBUF}!",
  ["6d:7357"] = "Soy {STRBUF}…\012¡{PLAYER}! Bonita\nluna, ¿verdad?",
  ["6d:7331"] = "Soy {STRBUF}…\012¡{PLAYER}! Qué buen\ntiempo, ¿verdad?",
  ["6b:6163"] = "PLAZA MT. MOON\012Sube las\nescaleras",
  ["6d:730b"] = "Soy {STRBUF}…\012¡{PLAYER}! Bonita\nmañana, ¿verdad?",
  ["6b:6214"] = "Estoy mejorando\nmis POKéMON.\012¿Quieres luchar\ncontra mí?",
  ["6d:72d0"] = "¿Han crecido algo\ntus POKéMON?\012Mi {STRBUF} ha\ncrecido un poco.",
  ["6b:6241"] = "¡Argh! He perdido\nesta vez…",
  ["6a:67bc"] = "¡Sayonara! Lo he\naprendido en la\011clase de japonés.",
  ["6b:6258"] = "Si tienes un\nPOKéMON que desees\012mejorar, ponlo en\nprimer lugar y\012cámbialo nada más\nempezar.\012Así es como hay\nque hacerlo.",
  ["6a:5e1b"] = "LÍDER DEL GIMNASIO\nPOKéMON DE\011CIUDAD VERDE:…\012El resto del texto\nes ilegible…",
  ["6b:62ce"] = "Presiento que\npuedo ganar.\012¡Veamos si\ntengo razón!",
  ["6b:4f9c"] = "¡Ayyyy!",
  ["6b:6306"] = "¡Uau! Eres\ndemasiado fuerte.",
  ["6a:61bd"] = "El C. COMERCIAL\nde CIUDAD AZULONA\012dispone de los\nmejores artículos.\012Si no encuentras\nalgo aquí, no lo\012encontrarás en\nningún otro sitio.\012¡Vaya…! Parezco\nuna vendedora.",
  ["6b:6320"] = "Dicen que CLEFAIRY\naparece en el\012MT. MOON.\n¿Pero dónde?",
  ["6b:500d"] = "Si no tienes una\nBICI, no podrás\012usar el atajo.",
  ["6b:635e"] = "¡Umm…!\nYo…",
  ["6b:5108"] = "¡Eh, tú! Eres de\nJOHTO, ¿verdad?",
  ["6b:6366"] = "…",
  ["6b:6369"] = "…Creo que seguiré\nentrenándome…",
  ["6b:513b"] = "¡No seas chulo,\npunki de JOHTO!",
  ["6b:6384"] = "PLAZA MT. MOON\012Sube las\nescaleras",
  ["6b:6421"] = "¡Ja, ja, ja!",
  ["6b:5178"] = "Pero tú no\npareces guay…",
  ["6b:642b"] = "¡Aaaaaaachís!",
  ["6b:51e0"] = "¡Eh! ¿Un combate\nrapidito?",
  ["6b:643b"] = "¡La alergia me\nhace estornudar!\011¡AAACHÚS!",
  ["6b:5225"] = "Montar sin manos\nen el CAMINO BICIS\011es muy guay.",
  ["6b:6468"] = "Te gustan los\nPOKéMON, ¿verdad?\012¡A mí también!",
  ["6b:527a"] = "¡Arrrg! ¡Chocar y\narder!",
  ["6b:648a"] = "Tengo que decir\nque son mi ruina.",
  ["6b:532f"] = "CAMINO de BICIS\012¡Cuesta abajo\npor la costa!",
  ["6b:64a9"] = "Mira lo que\nhas hecho a\011mis POKéMON.\012No lo\nolvidaré…",
  ["6d:7019"] = "¿Sí, diga?\n¡Soy {STRBUF}!\012¡Hola, {PLAYER}!\012¿Estás usando\nPOKéMON pájaro?",
  ["6b:64dc"] = "RUTA 10\012CIUDAD CELESTE -\nPUEBLO LAVANDA",
  ["6d:6f60"] = "¿Qué tal van tus\nPOKéMON?\012Espero que les\nlleves a un CENTRO\011POKéMON todos los\011días.\012Dosifica sus\nfuerzas.\012Mi {STRBUF} es\nbonito y vivaracho\012precisamente\nporque le llevo\012todos los días a\nun CENTRO POKéMON.",
  ["6b:653a"] = "MESETA AÑIL\012¡El objetivo\nfinal de los\011entrenadores!\012El CG de la\nLIGA POKéMON",
  ["6d:6f37"] = "¿Eres {PLAYER}?\012Buenas noches. Soy\n{STRBUF}.",
  ["6b:65a0"] = "Los entrenadores\nambiciosos escalan\012el MT. PLATEADO a\npesar del peligro.\012Con sus fieles\nPOKéMON, sentirán\012que pueden ir a\ncualquier lado…",
  ["6d:6f1c"] = "¿Eres {PLAYER}?\012Hola, soy\n{STRBUF}.",
  ["6d:6ef3"] = "¿Eres {PLAYER}?\012Buenos días. Soy\n{STRBUF}.",
  ["6d:6ec9"] = "¿Sí? Soy\n{STRBUF}.\012Oh, {PLAYER}.\nBuenas noches.",
  ["6d:6ea6"] = "¿Sí? Soy\n{STRBUF}.\012Oh, {PLAYER}.\nHola.",
  ["6d:6e7c"] = "¿Sí? Soy\n{STRBUF}.\012Oh, {PLAYER}.\nBuenos días.",
  ["6d:6db9"] = "Ah, sí. El otro\ndía vi como salías\012de un CENTRO\nPOKéMON.\012Curas a tus POKé-\nMON habitualmente,\012¿verdad?\nMe impresiona.\012Eh, mi {STRBUF}\nes tan duro, que\012no necesita ir a\nlos CENTROS POKé-\011MON a menudo. ¡Je!",
  ["6d:6d88"] = "Hola, {PLAYER}.\n¿Qué tal te va?\012¡Eh! Soy yo,\n{STRBUF}.",
  ["6d:6d57"] = "Hola, {PLAYER}.\n¿Qué tal te va?\012¡Eh! Soy yo,\n{STRBUF}.",
  ["6d:6d26"] = "Hola, {PLAYER}.\n¿Qué tal te va?\012¡Eh! Soy yo,\n{STRBUF}.",
  ["6d:6cf6"] = "¿Sí? Soy {STRBUF}…\012Ah, {PLAYER}.\n¿Puedo ayudarte?",
  ["6d:6cc6"] = "¿Sí? Soy {STRBUF}…\012Ah, {PLAYER}.\n¿Puedo ayudarte?",
  ["6d:6c96"] = "¿Sí? Soy {STRBUF}…\012Ah, {PLAYER}.\n¿Puedo ayudarte?",
  ["6d:6c56"] = "¿Qué tal va tu\nviaje?\012¡No puedo quejarme\nde mi pesca!",
  ["6d:6c23"] = "¡Hola!\nAquí {STRBUF}…\012¡Hace una noche\nideal para pescar!",
  ["6d:6bef"] = "¡Hola!\nAquí {STRBUF}…\012¡Hace un día per-\nfecto para pescar!",
  ["6d:6bb9"] = "¡Hola!\nAquí {STRBUF}…\012¡Buenos días!\n¡Hace un tiempo\011genial!",
  ["6d:6b92"] = "Hola, soy\n{STRBUF}…\012¡Debes de ser\n{PLAYER}!",
  ["6d:6b65"] = "Hola, soy\n{STRBUF}…\012Esa voz…\n{PLAYER}, ¿verdad?",
  ["6d:6b39"] = "Hola, soy\n{STRBUF}…\012Oh, buenos días,\n{PLAYER}.",
  ["6d:6ac2"] = "¡Tienes que oír\nesto! ¡Mi adorable\012{STRBUF} me\nmiró y me sonrió!\012¡Será porque\nsomos almas\011gemelas!",
  ["6d:6a8b"] = "¡{PLAYER}, pika!\n¡Buenas noches!\012Soy {STRBUF}.\n¿Cómo pika estás?",
  ["6d:6a56"] = "¡{PLAYER}, pika!\n¡Buenos pika días!\012Soy {STRBUF}.\n¿Cómo pika estás?",
  ["6d:6a22"] = "¡{PLAYER}, pika!\n¡Buenos días!\012Soy {STRBUF}.\n¿Cómo pika estás?",
  ["6d:69f8"] = "Hola, ¿{PLAYER}?\012Buenas noches,\npika.\011¿Qué pasa, pika?",
  ["6d:69d2"] = "Hola, ¿{PLAYER}?\012Buenos días, pika.\n¿Qué pasa, pika?",
  ["6d:69a8"] = "Hola, ¿{PLAYER}?\012Buenos días, pika.\n¿Qué pasa, pika?",
  ["6d:68e8"] = "¿Qué tal van tus\nPOKéMON?\012¡Conoces al PROF.\nOAK, entonces tus\012POKéMON deben de\nestar bien!\012Mis POKéMON\ntambién van bien.\012Pero bueno, es\nlógico teniendo en\012cuenta que estoy\nintentando ser un\011profesor POKéMON.",
  ["6d:68ba"] = "Hola, {PLAYER}.\n¡Buenas noches!\012Soy {STRBUF}.\n¿Qué tal estás?",
  ["6d:6890"] = "Hola, {PLAYER}.\n¡Muy buenos días!\012Soy {STRBUF}.\n¿Qué tal estás?",
  ["6d:6862"] = "Hola, {PLAYER}.\n¡Buenos días!\012Soy {STRBUF}.\n¿Qué tal estás?",
  ["6d:6836"] = "Hola, soy\n{STRBUF}…\012¡Hola, {PLAYER}!\n¡Buenas noches!",
  ["6d:680e"] = "Hola, soy\n{STRBUF}…\012¡Hola, {PLAYER}!",
  ["6d:67e2"] = "Hola, soy\n{STRBUF}…\012¡Hola, {PLAYER}!\n¡Buenos días!",
  ["6d:6795"] = "Mi {STRBUF}\nestá tan lleno de\012energía que da un\npoco de miedo.\012¿Qué tal van tus\nPOKéMON?",
  ["6d:6776"] = "Uh… ¿{PLAYER}?\012¡Soy yo!\n¡Soy {STRBUF}!",
  ["6d:6757"] = "Uh… ¿{PLAYER}?\012¡Soy yo!\n¡Soy {STRBUF}!",
  ["6d:6738"] = "Uh… ¿{PLAYER}?\012¡Soy yo!\n¡Soy {STRBUF}!",
  ["6d:6713"] = "Hola, al habla\n{STRBUF}.\012¿{PLAYER}?\n¿Qué pasa?",
  ["6d:66ec"] = "Hola, al habla\n{STRBUF}.\012¡Ya sé!\n¡Eres {PLAYER}!",
  ["6d:66c8"] = "Hola, al habla\n{STRBUF}.\012¡Eh! ¡Pero si es\n{PLAYER}!",
  ["6d:6652"] = "{PLAYER}… ¿estás\ncuidando de tus\012POKéMON\nadecuadamente?\012He leído en un\nlibro que debes\012cuidar a los\nPOKéMON que cojas\011con amor y cariño.",
  ["16:6af2"] = "Necesitamos pasta,\n¿pero vendiendo\011COLAS de SLOWPOKE?\012¡Es muy duro ser\nun SOLDADO ROCKET!",
  ["6d:6624"] = "¡Hola! ¡Soy yo,\n{STRBUF}!",
  ["6d:660d"] = "¡Hola! ¡Soy yo,\n{STRBUF}!",
  ["6d:65e3"] = "¡Soy {STRBUF}!\012¿Eres {PLAYER}?\n¡Buenas noches!",
  ["6d:65c7"] = "¡Soy {STRBUF}!\012¿Eres {PLAYER}?",
  ["6d:659d"] = "¡Soy {STRBUF}!\012¿Eres {PLAYER}?\n¡Buenos días!",
  ["6d:656c"] = "Seguro que tus\nPOKéMON son más\011fuertes que antes.",
  ["6d:6539"] = "Sí, ¿hola?\nSoy {STRBUF}.\012¿Aún no te has\ndormido, {PLAYER}?",
  ["6d:6506"] = "Sí, ¿hola?\nSoy {STRBUF}.\012¿Dónde estás\nahora, {PLAYER}?",
  ["6d:64d2"] = "Sí, ¿hola?\nSoy {STRBUF}.\012¿Qué estás\nhaciendo, {PLAYER}?",
  ["19:5f17"] = "¡Tendríamos que\nluchar!\012Estaré pescando en\n{STRBUF}.\012Pásate por ahí si\ntienes tiempo.",
  ["16:6c09"] = "{PLAYER} lee\nla CARTA.\012Sé bueno y cuida\nla casa donde\012está el abuelo y\nSLOWPOKE.\012Te quiere, papá.",
  ["19:5f6e"] = "Bueno, nos vemos\npronto.",
  ["16:6c61"] = "Un SLOWPOKE\nsin COLA…",
  ["19:5ff2"] = "¿Que si he encon-\ntrado algo bueno?\012No, aún no.\012Es como pescar,\nten paciencia.",
  ["16:6d2a"] = "Me gustaría ver\ncómo evoluciona\011SLOWPOKE.\012Observándolos\nhe hecho un nuevo\011descubrimiento.\012Un SLOWPOKE con\nuna ROCA DEL REY\012suele ser mordido\npor un SHELLDER.\012Toma, compartiré\nuna ROCA DEL REY\011contigo.",
  ["19:6087"] = "Tengo algo bueno\npara ti.\012Ven rápido a\n{STRBUF}.",
  ["16:6df2"] = "Voy a ser como\nSLOWPOKE.\012Tendré paciencia\ny a ver si\011evoluciona alguno.",
  ["19:613c"] = "Ya lo creo, acabé\ncon este {STRBUF}\012salvaje.\nNo era bastante\012raro como para\natraparlo.",
  ["16:6e6d"] = "En este FARO se\nentrena la gente.\012No es fácil subir\nporque hay muchos\011entrenadores.",
  ["19:6214"] = "Tienes tiempo,\ncomo siempre, ¿eh?\012¿Te apetece entrar\nen combate?\012Será tu ocasión\npara ver a mis\012POKéMON raros.\n¡Merece la pena!\012Ya sabes dónde, en\n{STRBUF}.",
  ["16:6ec2"] = "Antes había unos\nPOKéMON que\012iluminaban el mar\nque rodea OLIVO.\012El FARO se\nconstruyó en honor\011a esos POKéMON.",
  ["19:62bc"] = "¿Sabías que…?\nParece ser que el\012padre de BILL es\nun POKéMANIAC.",
  ["16:707a"] = "¡Los hombres de\nmar siempre\011quieren luchar!",
  ["19:6335"] = "¿Sabías que…?\nBILL proviene de\011CIUDAD TRIGAL.",
  ["16:70b0"] = "¡Urf!\n¡He perdido!",
  ["19:63a1"] = "¿Sabías que…?\nABRA fue el primer\012POKéMON que BILL\ncapturó.",
  ["16:70f8"] = "¿Qué? Aquí\nno se juega.",
  ["19:6421"] = "¿Sabías que…?\nSe supone que BILL\012odia la leche y\nno puede tomarla.",
  ["16:711b"] = "¡Ah! Ya veo que\nvas en serio.",
  ["19:649b"] = "¿Sabías que…?\nParece que a BILL\012le gusta la chica\nde la FLORISTERÍA.",
  ["16:713e"] = "Arriba hay un\nPOKéMON que\011ilumina el FARO.\012Pero dicen que\nestá enfermo y que\012la medicina normal\nno puede curarle.",
  ["19:651e"] = "¿Querías saber más\nacerca de BILL?\012Lo siento, estoy\nmuy ocupado.\012Te llamaré cuando\ntenga tiempo.",
  ["19:65ad"] = "Mi {STRBUF} es\nadorable, ¿no\012crees?\nSiempre duermo\012con él, ¡es blando\ny calentito!",
  ["16:72c4"] = "Estás realmente\npreocupado…",
  ["16:7333"] = "Los marineros\nsomos fuertes y\011simpáticos. ¿Y tú?",
  ["16:7384"] = "Siempre que vuelvo\na CIUDAD OLIVO\011voy al GIMNASIO.\012El tipo de POKéMON\nde su LÍDER ha\012cambiado sin\ndarme cuenta.",
  ["16:7437"] = "(Suspiro…)\nDebo entrenar más.",
  ["19:40e6"] = "¡He oído algo\nsobre ti!\012Salvaste a ese\nPOKéMON del FARO,\011¿verdad?\012¡{PLAYER}, me\ngustaría que\012vinieses a verme\ncuando esté en\012cama con un\nresfriado!",
  ["19:4032"] = "¿{PLAYER}, te has\nenterado?\012¡La TORRE RADIO de\nCIUDAD TRIGAL\012ha sido tomada por\nel TEAM ROCKET!\012Um… ¿Qué es el\nTEAM ROCKET?",
  ["19:4000"] = "¡Siento tener que\ncolgarte!\012¡Luego te llamo!",
  ["16:75c5"] = "YASMINA es LÍDER\nde este GIMNASIO.\012Quería que viniera\nconmigo.\012¡No he encontrado\na nadie mejor!",
  ["19:6dab"] = "¡Bueno, volveremos\na charlar!",
  ["19:6e17"] = "Ahora estoy entre-\nnándome. Tendrás\012que llamarme en\notro momento.\012¡Oooooaaarrrgh!",
  ["6b:6040"] = "Sabía que\nperdería…",
  ["6b:6051"] = "Parecías fuerte.\012Me daba miedo\ndesafiarte…",
  ["6b:6082"] = "¡Puedo correr\ncomo el viento!",
  ["6b:609c"] = "¡He perdido!",
  ["6d:5d39"] = "Hola, soy el tío\n{STRBUF}.",
  ["6b:60a9"] = "Siempre llevo\npantalones cortos.\012Ésa es mi forma\nde vestir.",
  ["6b:60e7"] = "¡Sube y echa\nun vistazo!",
  ["6d:5cb6"] = "¿Sí? Ah, {PLAYER}.\012Eres muy cortés\nal presentarte\012cuando llamas por\nteléfono.",
  ["6b:6107"] = "¡Uau! ¡Eso quema!",
  ["6b:6118"] = "Soy el mejor\nCOMEFUEGOS de\011KANTO.\012Pero no el mejor\nentrenador…",
  ["19:60be"] = "Sí, conseguí un\nPOKéMON raro\012mediante intercam-\nbio hace un rato.\012¿Quieres saber\ncuál es?\012Je, je, ¡es un\nsecreto!",
  ["16:6a8d"] = "¿Dejar de cortar\nlas COLAS de\011los SLOWPOKE?\012¡Obedecerte\narruinaría la\012reputación del\nTEAM ROCKET!",
  ["6d:5b0b"] = "Hola, {PLAYER}.\012Soy yo, {STRBUF}.\n¿Qué tal va todo?",
  ["6d:5ad8"] = "¡{PLAYER}, buenos\ndías!\012Soy yo, {STRBUF}.\n¿A que hace un día\011estupendo?",
  ["6d:5a9f"] = "¿Hola? Al habla\n{STRBUF}.\012¡Hola, {PLAYER}!\n¡Buenas noches!",
  ["6d:5a74"] = "¿Diga? Al habla\n{STRBUF}.\012¡Hola, {PLAYER}!",
  ["6d:5a3b"] = "¿Diga? Al habla\n{STRBUF}.\012¡Hola, {PLAYER}!\n¡Buenos días!",
  ["6d:59b2"] = "¿Qué tal van tus\nPOKéMON?\012Mi {STRBUF}\nestá ansioso por\012luchar, como\nsiempre.\012Es el único que\ntengo. ¡Con él,\012llegaré a ser un\ngran entrenador!",
  ["16:698b"] = "¿Qué quieres?\012¡Si nos molestas,\nno esperes\011misericordia!",
  ["19:62a9"] = "Pues esto es todo.",
  ["16:68e8"] = "Sí, hemos estado\ncortando las colas\012de los SLOWPOKE\ny vendiéndolas.\012Lo hacemos sólo\npor dinero.\012¡Así es! Somos\nel TEAM ROCKET,\012¡y haríamos lo que\nfuera por dinero!",
  ["6d:58ea"] = "¡Hola, soy\n{STRBUF}!\012Oh, ¿{PLAYER}?\n¿Qué tal estás?",
  ["19:5cf9"] = "Quiero darte\nuna PEPITA.\012A mi PIKACHU\nle encanta.\012¡Seguro que\na tu PIKACHU\011también!",
  ["16:68cc"] = "¡Arrg! ¡Hoy NO\nes mi día!",
  ["19:62fc"] = "¿Sabías que…?\nAl parecer, el\012abuelo de BILL no\nes un POKéMANIAC.",
  ["6d:57e8"] = "¡Qué lentitud! \n¡Date prisa y\011contesta!\012¡Soy yo, {STRBUF}!",
  ["6c:4241"] = "Tus POKéMON\ntienen minúsculas\012formas de vida\nunidas a ellos.\012Tus POKéMON están\nsanos y parecen\011contentos.\012Pero no podemos\ndarte más\012información en un\nCENTRO POKéMON.",
  ["6c:42d6"] = "Tus POKéMON\ntienen minúsculas\012formas de vida\nunidas a ellos.\012Tus POKéMON están\nsanos y parecen\011contentos.\012Pero no podemos\ndarte más\011información.",
  ["6d:575a"] = "Hola, soy\n{STRBUF}…\012Oh, hola, {PLAYER}.\n¿Qué pasa?",
  ["6d:572e"] = "Hola, soy\n{STRBUF}…\012Oh, hola, {PLAYER}.\n¿Qué pasa?",
  ["6d:5702"] = "Hola, soy\n{STRBUF}…\012Oh. Hola, {PLAYER}.\n¿Qué pasa?",
  ["6d:5694"] = "Tus POKéMON,\n¿aún se entrenan?\012Mi {STRBUF}\ntiene mucha\011energía.\012Cuando despega, no\nvuelve en un rato.",
  ["6c:43d9"] = "VOTOS TEAM ROCKET\012Robar POKéMON para\nenriquecernos.\012Explotarlos para\nenriquecernos.\012¡Todo POKéMON\nexiste para gloria\011del TEAM ROCKET!",
  ["6d:564c"] = "Oh, ¿{PLAYER}?\012¡Genial! Sí, soy\nyo, {STRBUF}.",
  ["6d:5628"] = "Oh, ¿{PLAYER}?\012¡Genial! Sí, soy\nyo, {STRBUF}.",
  ["6d:55fc"] = "Hola, soy\n{STRBUF}…\012Oh, ¿{PLAYER}?\n¡Buenas noches!",
  ["6d:55da"] = "Hola, soy\n{STRBUF}…\012Oh, ¿{PLAYER}?\n¡Hola!",
  ["6d:55ae"] = "Hola, soy\n{STRBUF}…\012Oh, ¿{PLAYER}?\n¡Buenos días!",
  ["6d:5510"] = "¿Eres del tipo de\npersona que va a\012menudo a los\nCENTROS POKéMON?\012Yo voy todos los\ndías. Cuidar de\012la salud de tus\nPOKéMON es uno de\012los principios\nbásicos de\011entrenar POKéMON.",
  ["6d:54d4"] = "Hola, {PLAYER}.\nBuenas noches.\012Soy {STRBUF}.\012No estabas dur-\nmiendo, ¿verdad?",
  ["6d:54a6"] = "¡{PLAYER}, hola!\nSoy {STRBUF}.\012¿Tienes tiempo?",
  ["6d:5472"] = "¡Buenos días,\n{PLAYER}!\012Soy {STRBUF}.\n¿Dormías?",
  ["6d:5446"] = "Hola, soy\n{STRBUF}.\012Oh, {PLAYER}.\nBuenas noches.",
  ["6d:5424"] = "Hola, soy\n{STRBUF}.\012Oh. Hola, {PLAYER}.",
  ["6d:53f7"] = "Hola, soy\n{STRBUF}.\012Oh, {PLAYER}.\nBuenos días.",
  ["6d:5393"] = "¿Qué tal van tus\nPOKéMON?\012Mi {STRBUF}\nlo está haciendo\011mejor que nunca.\012¡Si seguimos así,\nseremos CAMPEONES\011POKéMON!",
  ["6d:535f"] = "¡{PLAYER}, buenas\nnoches!\012Soy yo, {STRBUF}.\n¿Qué tal vas?",
  ["6d:5335"] = "¡Hola, {PLAYER}!\012Soy yo, {STRBUF}.\n¿Qué tal vas?",
  ["6c:46b7"] = "A ver si mejoras\nla próxima vez.",
  ["6c:46d9"] = "Aquí tienes los\nPOKéMON que\012te estábamos\ncuidando.",
  ["6d:52a5"] = "Hola, al habla\n{STRBUF}…\012¡Hola, {PLAYER}!",
  ["6d:5270"] = "Hola, al habla\n{STRBUF}…\012¡Hola, {PLAYER}!\n¡Buenos días!",
  ["6d:522b"] = "Mi {STRBUF}\nparece más duro\011que nunca.\012¡Parece más fuerte\nque yo!",
  ["6d:518b"] = "¿Qué tal van tus\nPOKéMON?\012Mis POKéMON son\nagotadores…\012Sobre todo,\n{STRBUF}.\012Cada vez que ve a\nun entrenador,\011tiene que luchar.\012¡Es demasiado para\nmí!",
  ["6d:5154"] = "¡Hola, {PLAYER}!\n¿Estás durmiendo?\012¡Soy yo, {STRBUF}!\n¿Qué tal estás?",
  ["6d:511a"] = "¡Hola, {PLAYER}!\n¿Estás libre?\012¡Soy yo, {STRBUF}!\n¿Qué tal estás?",
  ["6d:50e9"] = "¡Hola, {PLAYER}!\n¿Sigues durmiendo?\012¡Soy yo, {STRBUF}!\n¿Qué tal estás?",
  ["6d:50c2"] = "Sí, soy\n{STRBUF}.\012¿Eh? ¿Qué pasa,\n{PLAYER}?",
  ["6d:509b"] = "Sí, soy\n{STRBUF}.\012¿Eh? ¿Qué pasa,\n{PLAYER}?",
  ["6d:5073"] = "Sí, soy\n{STRBUF}.\012¿Eh? ¿Qué pasa,\n{PLAYER}?",
  ["6d:502b"] = "¿Son felices tus\nPOKéMON?\012Mi {STRBUF}\nestá sano.\012Come mucho todos\nlos días.",
  ["19:6366"] = "¿Sabías que…?\nBILL vive en la\011RUTA 25, en KANTO.",
  ["16:66b5"] = "CÉSAR: ¡Hola,\n{PLAYER}!\012Los guardias de\narriba huyeron en\011cuanto les grité.\012Pero entonces me\ncaí por el POZO.\012Me golpeé en la\nespalda y ahora\011no puedo moverme.\012Si estuviera bien,\nmis POKéMON\012los habrían\nmachacado…\012¡Bah! Pero no\npuedo hacer nada.\012¡{PLAYER},\ndemuéstrales lo\011que vales!",
  ["19:63e6"] = "¿Sabías que…?\nLa hermana menor\012de BILL al parecer\nno sabe guiñar.",
  ["16:652b"] = "Cada semana viene\nun POKéMON hasta\011la orilla.\012Quería ver a ese\nPOKéMON…",
  ["19:645f"] = "¿Sabías que…?\nComo es obvio, a\012BILL no se le da\nbien luchar.",
  ["16:6507"] = "¡Preferiría cuidar\nde mis niños!",
  ["19:64dd"] = "¿Sabías que…?\nDicen que la madre\012de BILL fue una\nCHICA KIMONO.",
  ["16:64b6"] = "Si los POKéMON\nque me gustan\012estuvieran ahí,\niría sin pensarlo.\012Eso haría un\nbuen entrenador.",
  ["19:6579"] = "Quieres ver a mis\nPOKéMON raros.\012Apresúrate y ven a\n{STRBUF}.",
  ["6c:488c"] = "¡Uups! Tu MONEDERO\nestá lleno.",
  ["6c:48ad"] = "¿No quieres\nfichas?\012Vuelve cuando\nquieras.",
  ["6c:48cc"] = "¡Oh! Tu MOCHILA\nestá llena.\012Te guardaremos\nesto. Vuelve\012cuando tengas\nsitio.",
  ["6c:492a"] = "¡Uauu! ¡Tú y tus\nPOKéMON estáis\011muy unidos!",
  ["6c:4954"] = "Cuanto más tiempo\npases con los\012POKéMON, más\nte querrán.",
  ["6c:4989"] = "No has domesticado\na tu POKéMON.\012Si no eres amable,\néste se enfadará.",
  ["6c:49c4"] = "{PLAYER} grabó el\nNº de {STRBUF}.",
  ["6c:49e1"] = "{PLAYER} grabó el\nNº de {STRBUF}.",
  ["16:63f0"] = "El estilo de tus\nPOKéMON es\011sorprendente.\012¡Seguirás\nmejorando!",
  ["19:58c6"] = "El PROF. OAK tiene\nuna nieta llamada\011DALIA.\012Toma el té cada\ndía de tres a\012cuatro de la\ntarde.\012Me gustaría tomar\nel té con ella\012y charlar sobre\nel PROF. OAK.",
  ["16:63d5"] = "¡Tu estilo es\ndeslumbrante!",
  ["19:5810"] = "Hace mucho tiempo,\nel PROF. OAK era\011un entrenador.\012Pero los POKéMON\nen sí le parecían\012más interesantes\nque el combate.\012Así que abandonó\nsu entrenamiento\012y se centró en la\ninvestigación.",
  ["16:636e"] = "Hay dos tipos\nde personas.\012Los que tienen\nestilo y los que\011no lo tienen.\012¿A qué tipo\nperteneces tú?",
  ["19:574a"] = "La HORA POKéMON\ndel PROF. OAK es\012un programa muy\npopular.\012¿Sabías que al\nprincipio no\012quería encargarse\nde ese programa?\012Pero la energía y\ntenacidad de ROSA\011le convencieron.\012¡Así que hay que\nagradecérselo!",
  ["16:6230"] = "Debería reunir\ny publicar mis\011hallazgos.\012Podría hacerme\ntan famoso como\011el PROF. ELM.",
  ["19:569b"] = "La LIGA POKéMON\nes el lugar de\012encuentro de los\nentrenadores que\012quieren ser\nCAMPEONES.\012El PROF.OAK es el\nasesor del CUARTEL\012GENERAL de la LIGA\nPOKéMON.\012Es un gran\nhombre.",
  ["16:6217"] = "¡Lo has demostrado\nconmigo!",
  ["19:5628"] = "¿Conoces a CÉSAR,\nel creador de\011BALL?\012Él y el PROF. OAK\nse conocen desde\011hace mucho.\012¡Supongo que los\ngrandes hombres se\011atraen mutuamente!",
  ["16:61b0"] = "He venido hasta\naquí para estudiar\011a los POKéMON.\012¡Te demostraré\nmis hallazgos en\011un combate real!",
  ["16:6181"] = "Sólo yo y mis\nPOKéMON. ¡Me\011muero de alegría!",
  ["19:416d"] = "¡Lo sé, lo sé,\nlo sé!\012¡Acabaste con el\nescondite del\011TEAM ROCKET!\012¡Eres como los\nhéroes de las\011películas!\012Pero… ¿Qué era\nel TEAM ROCKET?",
  ["16:6173"] = "¡Fuera…!\n¡Lárgate!",
  ["19:5555"] = "Todos hablan del\nPROF. ELM.\012¡Era el ayudante\ndel gran PROF.\011OAK!\012¡Es tan genial!\n¡Le envidio!",
  ["16:614a"] = "¿Quién anda ahí?\012¡Déjame en paz,\na mí y a mis\011POKéMON!",
  ["19:4099"] = "¡{PLAYER}, me he\nenterado!\012¿Derrotaste a\nBLANCA?\012¡Me siento muy\norgulloso de ser\011tu amigo!",
  ["16:60fb"] = "Vivo aquí abajo.\012Y tú también\npodrías si\011quisieras.\012Como ves, hay\nmucho sitio.",
  ["19:54ea"] = "El PROF. OAK tiene\nuna nieta que se\011llama DALIA.\012Cuando está cerca,\nhasta el POKéMON\012más feroz se\ncalma.",
  ["16:60dd"] = "¡Jajaja! ¡Eres\nmuy susceptible!",
  ["16:60bf"] = "¡Qué sabes tú!\n¡Un visitante!",
  ["19:5481"] = "¿Conoces a AZUL?\012¡Es el nieto del\nPROF. OAK y\012antiguo CAMPEÓN de\nla LIGA POKéMON!\012¡Es un súper en-\ntrenador POKéMON!",
  ["16:6073"] = "Llevo perdido\nmucho tiempo…\012No es que me\nimporte, ¡pero\011estoy hambriento!",
  ["16:606a"] = "¡Uurggh…!",
  ["1b:71c0"] = "¿Quieres que te\nenseñe a trabajar\011con el carbón?\012¡En diez años\nserás el mejor!",
  ["16:601d"] = "Hace mucho\ntiempo que no\011veo a nadie.\012No seas tímido.\n¡Luchemos!",
  ["1b:721b"] = "¿Que qué hago?\012Agitar los árboles\ncon GOLPE CABEZA.\012Es muy divertido.\n¡Toma, pruébalo!",
  ["16:5efc"] = "El fuego de mi\nPOKéMON\011ilumina la cueva.",
  ["1b:726d"] = "Agita los árboles\ncon GOLPE CABEZA.\012A veces caen\nPOKéMON dormidos.",
  ["16:5ef4"] = "¡DESTELLO!",
  ["6c:53af"] = "Qué mal…\012Házmelo saber si\ncambias de idea.",
  ["6c:53e4"] = "Oh, no…\nTu teléfono ya\011no tiene memoria.",
  ["6c:5409"] = "¡Me has tenido\nesperando! ¡Vamos!",
  ["6c:542d"] = "Si mi {STRBUF}\nve algo bonito,\011va y lo coge.\012¿Te gustan las\ncosas bonitas?\012Puedo intercambiar\nobjetos si\011trae alguna más.\012¿Cuál es tu número\nde teléfono?\011Te llamaré.\012Tampoco esperes\nnada especial…",
  ["6c:54e4"] = "¿Te gustan las\ncosas bonitas?\012Puedo intercambiar\nsi FARFETCH'D\011trae alguna más.\012¿Cuál es tu número\nde teléfono?\011Te llamaré.",
  ["6c:5553"] = "Te llamaré tan\npronto como\012consiga algo\nbonito.",
  ["6c:5584"] = "¿Sí? Bueno, dímelo\nsi cambias de\011opinión.",
  ["6c:55b6"] = "¿Eh? La agenda de\ntu teléfono está\011llena.",
  ["6c:55d5"] = "¡Farf! ¡Farf!\012¡Te esperaba…!\n¡Ve, FARFETCH'D!",
  ["6c:5607"] = "¡Hacerme esperar…!\nMira…\012¿Qué? ¿A que es\nmuy bonito?",
  ["6c:564d"] = "¿Eh? No tienes\ndónde ponerlo.\012Vuelve más tarde\na por ello.",
  ["6c:5faa"] = "Te telefonearé si\noigo algo\011interesante.",
  ["6c:5f4e"] = "¡Estemos en\ncontacto! ¿Me das\012tu número de\nteléfono?\012¡Quiero enterarme\nde todo lo que\011vas viendo!",
  ["6c:5ebe"] = "¿Eh? ¿Estás\nrecorriéndote\011todo el mundo?\012¡Estemos en\ncontacto! ¿Me das\012tu número de\nteléfono?\012¡Quiero enterarme\nde todo lo que\011vas viendo!",
  ["6c:5e98"] = "¡Eh, joven!\012¡Hoy no pienso\nperder!",
  ["6c:5e50"] = "",
  ["6c:5df4"] = "Oh… Ni siquiera\nmis propios hijos\012me dan sus números\nde teléfono…\012¿Es así la gente\njoven hoy en día?",
  ["6c:5db9"] = "Sí, te llamaré si\nveo POKéMON raros.\012No te preocupes.\n¡No me olvidaré!",
  ["6c:5d85"] = "Así que quieres mi\nteléfono por si\011veo POKéMON raros…",
  ["6c:5cd5"] = "¿La gente joven ya\nno pesca?\012He visto POKéMON\nraros mientras\011pescaba…\012A la gente joven\nos gustan los\011POKéMON raros…\012¿Quieres mi número\nde teléfono?\012Te haré saber si\nveo alguno.",
  ["6c:5c91"] = "Vaya, tu MOCHILA\nestá llena.\011Mala suerte.\012Debes volver más\ntarde.",
  ["1c:45f7"] = "Mi caña se ha\nenredado…",
  ["15:5069"] = "Mi hermano BILL\ncreó el sistema\012de almacenamiento\nde los POKéMON.",
  ["15:5046"] = "No puedes grabar\nningún número más.",
  ["1c:458f"] = "¡No perderé como\npescador! Me paso\012el día capturando\nPOKéMON.",
  ["15:4ff3"] = "Mi hermano creó\nel sistema de\012almacenamiento de\nPOKéMON del PC.\012Te iba a dar el\nteléfono de\011BILL…",
  ["15:4fd9"] = "{PLAYER} grabó\nel número de BILL.",
  ["1c:4522"] = "¡Déjame luchar con\nel POKéMON que\011acabo de atrapar!",
  ["15:4f9e"] = "¿Eres entrenador?\012Tengo un número\nde teléfono que\011te será útil.",
  ["15:4f4e"] = "Mi marido era\nconocido como un\012POKéMANIAC.\nBILL ha debido de\012seguir los pasos\nde su padre.",
  ["6c:5954"] = "¡Te esperaba!\n¡Luchemos!",
  ["6c:5936"] = "¿Eh, cómo? Tu\nagenda está llena.",
  ["6c:5908"] = "Oh, bueno…\012¡Pero no volveré a\nperder contra ti!",
  ["6c:58d7"] = "¡Te llamaré\nsiempre que quiera\011luchar!",
  ["6c:587b"] = "¿Me das tu número\nde teléfono?\012¡No quiero perder\ncontra ti!\012Tenemos que luchar\nde nuevo, ¿vale?",
  ["6c:5800"] = "Dime, ¿me das tu\nnúmero de\011teléfono?\012Te llamaré para\nluchar.\012Yo también soy\nnovato, así que\012será una buena\nmotivación.",
  ["6c:57de"] = "¿Qué quieres?\n¡Empecemos!",
  ["69:646a"] = "¡Mira! ¡Hay un\ngran edificio ahí!\012¿Qué será?",
  ["6c:57ba"] = "¿Qué? ¡No queda\nespacio en la\011agenda!",
  ["69:649b"] = "¡Mmmmm! Mira cómo\nentran todos esos\012entrenadores tan\npreparados.\012¿Qué? ¿Qué?",
  ["6c:578a"] = "¡No me lo creo!\n¡Te vas a\011arrepentir!",
  ["69:64e6"] = "Vine en barco a\nC. OLIVO por las\012vistas y el aire\nque se respira.\012Como es un puerto,\nparece diferente\011de la gran ciudad.",
  ["6c:5755"] = "¡Que no se te\nsuban los humos!\012¡Ha sido chiripa!",
  ["69:6564"] = "¿Has estado en la\nTORRE BATALLA?\012Creo que en ella\nse han reunido mu-\011chos entrenadores\011muy fuertes.\012Aunque, teniendo\ntantas MEDALLAS,\012no debería resul-\ntarte difícil.",
  ["6c:5710"] = "¡Dame tu número de\nteléfono!\012¡Vas a practicar\nconmigo!",
  ["69:6606"] = "LUNA: Encantada de\nconocerte. Soy\012LUNA, por lunes.",
  ["6c:5690"] = "No está mal…\nGanarme ya es\012algo, aunque haya\nsido de chiripa…\012¡Me gustas! ¡Dame\ntu teléfono!\012¡Puedes practicar\nconmigo!",
  ["69:6636"] = "¡Como prueba de\nnuestra amistad,\012tengo un regalo\npara ti!",
  ["17:6934"] = "¿Bromeas?",
  ["69:666c"] = "LUNA: Es un objeto\nque aumenta el\012poder de los\nataques de vuelo.\012Deberías dar este\nobjeto a un\011POKéMON pájaro.",
  ["17:6944"] = "¡No me gusta\nperder!\012¡Odio a los\nPOKéMON inútiles!",
  ["69:66dc"] = "LUNA: Mis hermanos\ny hermanas están\012por todas\npartes.\012¡A ver si los\nencuentras!",
  ["17:697d"] = "¿Por qué se\nabrió la puerta?\012¿Acaso eres tú\nel responsable?",
  ["69:6737"] = "LUNA: No creo\nque hoy sea\011lunes. ¡Qué pena…!",
  ["17:69c2"] = "¡Es mi fin!",
  ["69:6767"] = "RUTA 40\012CIUDAD ORQUÍDEA -\nCIUDAD OLIVO",
  ["17:69d0"] = "¿Qué? ¿Esquivaste\na nuestros hombres\011del SUBTERRÁNEO?\012¿Cómo lo hiciste?",
  ["69:690f"] = "Aquí el agua está\ntemplada. Estoy\011muy a gusto.\012Por supuesto,\n¡lucharé contigo!",
  ["17:6a14"] = "¿Un niño que\nmerodea por aquí?\012¿Quién eres?",
  ["69:6952"] = "¡Vaya! ¡Estoy\ncomo una pasa!",
  ["17:6a43"] = "¡Vaya! ¡No te tomé\nmuy en serio!",
  ["69:696e"] = "¡Qué relajante\nes flotar\011así!",
  ["17:6a61"] = "¡Jajajajaja…!\012Desde aquí puedo\ntransmitir todo\011tipo de señales.",
  ["69:6999"] = "Estoy cansado. Si\ngano, ¿me prestas\011tus POKéMON?",
  ["17:6aa4"] = "Es la ranura de la\nLLAVE MAGNÉTICA.",
  ["69:69c7"] = "(jadeo…)",
  ["17:6abc"] = "{PLAYER}\nusó la\011LLAVE MAGNÉTICA.",
  ["69:69d4"] = "CIUDAD ORQUÍDEA\nestá muy lejos.\012Pero tampoco es\nfácil volver a\011CIUDAD OLIVO.\012¿Qué hacer?",
  ["17:6ad6"] = "P2 PERSONAL",
  ["69:6a2e"] = "¿Ves esas islas\naisladas por\011torbellinos?\012¡Tiene que haber\nun secreto!",
  ["17:6ae4"] = "MÚSICA POKéMON\ncon el DJ NARDO",
  ["19:5091"] = "Ahora estoy en\n{STRBUF}.\012¡Si estás cerca,\npodemos luchar!\012¡Te estaré\nesperando!",
  ["17:6c12"] = "Mientras estaba\nen las RUINAS\011oía la radio.\012Y escuché una\nextraña emisión.",
  ["19:50e2"] = "¡Hasta la vista!",
  ["17:6c68"] = "ROSA: ¿Por qué?\n¿Por qué debo\011sufrir?\012¡MEOWTH, ayúdame!",
  ["19:50ec"] = "¿Sabes una cosa?\n¡Conseguí un gran\011regalo!\012¡Como prometí, es\ntuyo!\012Sabía que te\ngustaría. ¡Ven a\011por él!\012¡Te espero en\n{STRBUF}!",
  ["17:6cab"] = "ROSA: ¡Oh! ¡Eres\nmi salvador!\012¿Aceptas esto como\nagradecimiento?",
  ["19:5161"] = "¡Oh! Querías un\nregalo, ¿verdad?\012Tengo uno, pero\nquiero quedármelo.\012¿Puedes esperar\nun poco más?",
  ["17:6cef"] = "ROSA: Es para los\nPOKéMON que\012saben movimientos\nnormales.",
  ["19:51bf"] = "¡Hola! No habrás\nolvidado tu\012promesa de luchar\nconmigo, ¿verdad?\012¡Te espero en\n{STRBUF}!",
  ["17:6d2c"] = "ROSA: Sintoniza\nconmigo en la\012HORA POKéMON\ndel PROF. OAK.",
  ["19:520f"] = "¿Hola?\012Si no vienes a por\ntu regalo pronto,\012se lo daré a otra\npersona.\012¡Te espero en\n{STRBUF}!",
  ["17:6d66"] = "MEOWTH: Meowth…",
  ["19:5271"] = "Hace poco empecé\na observar\012{STRBUF}\nsalvajes.\012He aprendido toda\nclase de cosas\012gracias a mis\nobservaciones.\012Ojalá llegue a ser\nun investigador\012POKéMON como el\nPROF. OAK pronto…",
  ["17:6d77"] = "¿Quieres rescatar\nal DIRECTOR?\012¡Pues ya te puedes\nir olvidando de\012eso, porque te\nvoy a ganar!",
  ["19:5318"] = "Oh, sí, conseguí\nnoquear a un\012{STRBUF} salvaje\nhace un rato.\012Bueno, teniendo en\ncuenta que estudio\012cada día, era\ninevitable.",
  ["17:6dcf"] = "¡No! ¡Increíble!",
  ["19:5399"] = "Ah, sí, estuve a\npunto de atrapar a\012un {STRBUF}\nsalvaje, pero\011se escapó.\012Durante mucho\ntiempo, he querido\012observar a los\n{STRBUF}.\011Lástima…",
  ["17:6de2"] = "¡Increíble!\n¡He perdido!",
  ["19:5419"] = "¿Quieres luchar?\nDebo hacerlo a\012menudo para no\nperder facultades.\012¡Estaré en\n{STRBUF}!",
  ["17:6e04"] = "¡Alto ahí!\n¡Me llaman la\012fortaleza del\nTEAM ROCKET!\012¡No des un\npaso más!",
  ["19:5471"] = "¡Hasta luego!",
  ["17:6e50"] = "¡La fortaleza\nse derrumbó!",
  ["69:6cda"] = "Estás tan elegante\nmontado en tu\011POKéMON.",
  ["17:6e69"] = "Te has ganado mi\nrespeto. ¡Te daré\011un consejo!\012Aún estás a\ntiempo de darte\011la vuelta.",
  ["6c:5fdd"] = "Eh… ¿No quieres\ndármelo?",
  ["17:6ec4"] = "¿Son buenos mis\nPOKéMON?\012¡Creeré que mis\nPOKéMON son buenos\012cuando derroten\na los tuyos!",
  ["6c:5ffa"] = "¡Espera! ¡La\nagenda está llena!",
  ["19:55c7"] = "",
  ["6c:601f"] = "¡Llegas tarde!\n¡Comencemos!",
  ["17:6f31"] = "¡Me gusta mi\npersonalidad!\012¿Qué importan\nlos POKéMON?",
  ["6c:6054"] = "MT. PLATEADO",
  ["17:6f62"] = "¡Extraordinario!\012Esta TORRE de\nRADIO completará\011nuestro gran plan.",
  ["6c:6086"] = "CENTRAL DE\nENERGÍA DE KANTO",
  ["17:6fa3"] = "¡Mmmm…!\012Todo gran plan\ntiene sus pegas.",
  ["6d:4000"] = "¿Dígame?\012¡Hola, {PLAYER}!\n¿Trabajando duro?",
  ["17:6fcb"] = "¿De verdad crees\nque puedes detener\011al TEAM ROCKET?",
  ["6d:4021"] = "Así que estás en\n{STRBUF}.\012¿No está ahí\n{STRBUF}?\012¿Has ido a echar\nun vistazo?",
  ["17:6ffe"] = "P3 PRODUCCIÓN",
  ["6d:406b"] = "¿Sí? ¿Estás en\n{STRBUF}?\012Nunca he estado\nallí. ¡Genial,\011{PLAYER}!",
  ["17:700d"] = "P3 ESTUDIO 2",
  ["6d:40b1"] = "¿Qué? ¿Estás en\n{STRBUF}?\012¡Ven a verme\ncuando quieras!",
  ["18:4128"] = "¡Tú! ¿Has venido\na rescatarme?",
  ["6d:40e4"] = "¿Estás visitando a\n{STRBUF}?\012¿Por qué no vienes\nun rato a casa?",
  ["18:4147"] = "¿Es eso lo que\nestabas esperando?\012¡Pues no!\n¡Soy un impostor!\012Me hice pasar por\nel director para\012preparar nuestra\ninvasión.\012¿Quieres saber\ndónde escondimos\011al DIRECTOR?\012Te lo diré,\n¡pero sólo si eres\011capaz de vencerme!",
  ["6d:411c"] = "¡Uau! ¿Estás en\n{STRBUF}?\012¡Suerte en tu\naventura POKéMON!",
  ["19:5ab2"] = "Escucha esto. Mi\n{STRBUF} sonríe\012alegre si le pe-\nllizco el moflete.\012Pero sólo si lo\nhago yo.\012Debo de ser\nespecial.",
  ["6d:4150"] = "Eso parece\nbastante duro.\012Pero, {PLAYER}, sé\nque estás decidido\012y que te irá bien,\n¿de acuerdo?",
  ["19:5b29"] = "¡Oh, hace poco mi\nPIKACHU venció a\012un {STRBUF}\nsalvaje!\012¡Un {STRBUF}\nsalvaje!\012¿No crees que es\nimpresionante?\012¡Mi PIKACHU es\nasombroso!\012¡Mi PIKACHU es el\nmejor!",
  ["6d:41a7"] = "Por cierto, has\nahorrado {STRBUF}¥.\012¿Quieres seguir\nahorrando dinero?",
  ["19:5bc8"] = "Oh, vi a un\n{STRBUF} salvaje\011hace un tiempo.\012Pero no era muy\nbonito, así que lo\012dejé…\nLos POKéMON han de\012ser bonitos, si\nno, no sirven.",
  ["6d:41ea"] = "Es importante que\nahorres dinero.",
  ["18:431e"] = "¡Esto no me puede\nestar pasando!\012He luchado y\nhe perdido…",
  ["6d:420d"] = "¡Oh, {PLAYER}!\nNo estás ahorrando\012dinero. ¿Quieres\nahorrar?",
  ["18:4358"] = "{PLAYER}, ¿verdad?\012Un mocoso como tú\nno puede apreciar\012la grandeza del\nTEAM ROCKET.\012¡Qué lástima!\nTendrías futuro\011con nosotros.",
  ["6d:4249"] = "Por cierto, has\nahorrado {STRBUF}¥.\012¿Quieres seguir\nahorrando?",
  ["18:43d1"] = "¿Cómo has logrado\nllegar tan lejos?\012Debes de ser un\nbuen entrenador.\012Queremos hacernos\ncon esta EMISORA\012de RADIO para\nanunciar nuestra\011vuelta.\012Eso debería\nhacer regresar a\012GIOVANNI de su\nentrenamiento.\012Vamos a recuperar\nla gloria\011perdida.\012Y no voy a\npermitir que\012interfieras en\nnuestros planes.",
  ["6d:4289"] = "Vale. Te guardaré\nel dinero.",
  ["18:44f3"] = "¡No! ¡Perdóname,\nGIOVANNI!",
  ["6d:42a3"] = "Vale. Dejaré de\nguardarte dinero.",
  ["18:450e"] = "¿Qué ha pasado?\012Nuestros sueños\nhechos añicos.\012No estaba listo\npara la tarea.\012Como ya hiciera\nGIOVANNI, hoy\012abandonaré yo el\nTEAM ROCKET.\012¡Adiós!",
  ["6d:42c0"] = "¡Sigue así,\n{PLAYER}!\011¡Estoy contigo!",
  ["18:45b2"] = "DIRECTOR: Gracias,\n{PLAYER}.\012Tu valiente\nacción ha salvado\012a los POKéMON\nde todo el país.\012Sé que no es\nmucho, pero\011acepta esto.",
  ["6d:42ea"] = "¿Dígame?\012¡Hola, {PLAYER}!\n¿No te esperaba\011el PROF. ELM?",
  ["18:462c"] = "Antiguamente,\nhabía una torre en\012CIUDAD TRIGAL,\njusto aquí.\012Pero estaba vieja\ny se caía.\012Así que la\nreemplazamos por\012nuestra TORRE\nRADIO.\012Encontramos esta\ncampana durante\011la construcción.\012He oído que, en\nel pasado, toda\012clase de POKéMON\nvivían en CIUDAD\011TRIGAL.\012Quizá…\012Quizá esa campana\ntenga alguna\012conexión con la\nTORRE HOJALATA de\011CIUDAD IRIS…\012¡Ah!\012Eso me recuerda…\012He oído cuchichear\nal TEAM ROCKET.\012Aparentemente,\nalgo pasa en la\011TORRE HOJALATA.\012No tengo ni idea\nde qué ocurrirá,\012pero debieras\nechar un vistazo.\012Vale. Será mejor\nque vaya a mi\011OFICINA.",
  ["6d:431d"] = "¿Dígame?\012¡Hola, {PLAYER}!\n¿Tienes una misión\012importante del\nPROF. ELM? ¡Bien!",
  ["18:4824"] = "DIRECTOR: ¡Hola,\n{PLAYER}!\012Ya sabes que amo\na los POKéMON.\012Construí la TORRE\nde RADIO para\012expresar mi amor\npor los POKéMON.\012¡Ojalá difrute la\ngente con nuestros\011programas!",
  ["6d:435f"] = "¿Dígame?\012¡Hola, {PLAYER}!\nCuando termines\012tu misión, vuelve\na casa.",
  ["18:48be"] = "NARDO: ¿Escuchas\nnuestra música?",
  ["6d:43a1"] = "¿Dígame?\012¿{PLAYER}…?\nMe dijo el PROF.\012ELM que saliste\nde viaje.\012Ojalá me lo\nhubieras dicho…\012¿Y el dinero? ¿Te\nlo guardo?",
  ["18:48e0"] = "P4 OFICINA\n   DEL DIRECTOR",
  ["6d:4427"] = "¡Buenos días!\012SERVICIO de\nADMÓN. del SISTEMA\012de ALMACENAMIENTO\nde los POKéMON.",
  ["18:48f9"] = "P4 ESTUDIO 1",
  ["6d:4470"] = "¡Buenos días!\012SERVICIO de\nADMÓN. del SISTEMA\012de ALMACENAMIENTO\nde los POKéMON.",
  ["18:49b3"] = "Quería luchar con\nYASMINA, pero no\012está disponible.\n¿Y tú, qué…?",
  ["6d:44b5"] = "¡Buenas noches!\012SERVICIO de\nADMÓN. del SISTEMA\012de ALMACENAMIENTO\nde los POKéMON.",
  ["18:49fe"] = "¡Uauu! ¡Eres\nincreíble!",
  ["6d:44fe"] = "¿Quién llama?\012{PLAYER}, ¿eres tú?\nEspera un segundo.\012……\n……",
  ["18:4a1f"] = "Ser LÍDER de un\nGIMNASIO no es\012sólo una cuestión\nde fuerza. Todo\012LÍDER también debe\nser compasivo.",
  ["6d:452a"] = "¡Gracias por\nesperar!\012{PLAYER}, en tu\nCAJA cabe/n {STRBUF}\011POKéMON más.\012¡Adelante!\n¡Llénala!",
  ["18:4a74"] = "Estamos bastante\naltos aquí. Mis\012POKéMON pájaro\nestán en forma.",
  ["6d:4587"] = "¡Gracias por\nesperar!\012{PLAYER}, en tu\nCAJA sólo cabe/n\011{STRBUF} POKéMON más.\012Quizá deberías\ncambiar de CAJA.",
  ["18:4aaf"] = "¡Uups…!\n¡Se estrellaron!",
  ["6d:45ed"] = "¡Gracias por\nesperar!\012¡{PLAYER}, tu\nCAJA está llena!\012Si quieres atrapar\nmás POKéMON,\012tendrás que\ncambiar de CAJA.",
  ["18:4ac3"] = "Mi POKéMON\naprendió VUELO en\011CIUDAD ORQUÍDEA.\012Y como soy un\nperdedor, cruzaré\011el mar VOLANDO…",
  ["6d:4652"] = "Hola, ¿{PLAYER}?\n¡Soy yo, BILL!\012Gracias por usar\nmi SISTEMA de\011ALMACENAMIENTO.\012Tu CAJA se llenó\ncon el último\012POKéMON que\nenviaste.\012Si quieres atrapar\nmás POKéMON,\012tendrás que\ncambiar de CAJA.\012¡Hasta luego!",
  ["18:4c81"] = "YASMINA: Este\nPOKéMON siempre\012iluminaba el mar\npor la noche.\012Pero de pronto\nenfermó… Le\011cuesta respirar…\012Dicen que hay\nuna FARMACIA\012estupenda en\nCIUDAD ORQUÍDEA…\012Pero está al otro\nlado del mar…\012Y no puedo dejar\nsolo a AMPHY…",
  ["6d:46fc"] = "Hola, ¿{PLAYER}?\012No te\nexcedas.\012No olvides curar\na tus POKéMON\011si están heridos.\n",
  ["18:4d64"] = "¿Podrías traerme\nsu medicina?\011¿Por favor?",
  ["6d:4749"] = "Hola, ¿{PLAYER}?\012¿Viste al SR.\nPOKéMON? ¡Genial!\011¡Vuelve ileso!",
  ["18:4d99"] = "YASMINA: ¡Ah…!\n¿Le das a AMPHY\011esa medicina?",
  ["6d:4784"] = "¿{PLAYER}? Ahora\nestoy muy triste.\012Nos han robado un\nPOKéMON. ¿Cómo\012han podido\nhacerlo?",
  ["18:4dc3"] = "{PLAYER} entregó\nla POCIÓN SECRETA\011a YASMINA.",
  ["6d:47d5"] = "Hola, ¿{PLAYER}?\012Estamos analizando\nel HUEVO. Parece\012ser un HUEVO de\nPOKéMON.",
  ["18:4dea"] = "YASMINA: ¡Mmm!\nPor favor, no te\011ofendas…\012AMPHY no aceptaría\nnada de nadie,\011sólo confía en mí.",
  ["6d:481c"] = "Hola, ¿{PLAYER}?\012¿Has visto a mi\nayudante? Está en\012el CENTRO POKéMON\nde CIUDAD MALVA.",
  ["18:4e44"] = "YASMINA: …\012AMPHY, ¿cómo te\nsientes?",
  ["6d:4868"] = "Hola, ¿{PLAYER}?\012¿Qué tal el HUEVO?\n¿Ha cambiado algo?\012Si pasa algo, por\nfavor llámame.",
  ["18:4e6c"] = "YASMINA: ¡Oh…!\n¡Qué alivio…!\012Es tan\nestupendo…\012Muchísimas\ngracias.\012Regresaré\nal GIMNASIO…",
  ["6d:48bb"] = "Hola, ¿{PLAYER}?\n¿Qué tal el HUEVO?\012¿Qué? ¿Se ha\nabierto? ¡Uau!\011¿Qué POKéMON es?\012¡Por favor, ven\na enseñármelo!",
  ["18:4edf"] = "YASMINA: Ya veo.",
  ["6d:491f"] = "Hola, ¿{PLAYER}?\012Acabo de hacer un\ndescubrimiento.\012El tiempo que\ntarda un HUEVO en\012abrirse depende\ndel POKéMON.",
  ["18:4ef1"] = "¡AMPHY, aguanta!",
  ["6d:4982"] = "Hola, ¿{PLAYER}?\012Los movimientos de\nun POKéMON recién\012nacido son\nun misterio.\012Ahora estamos\ninvestigando eso.",
  ["18:4f03"] = "AMPHY: ¡Am…\nAm… phyphy…!",
  ["6d:49e7"] = "Hola, ¿{PLAYER}?\012He descubierto\nalgo extraño.\012Parece haber algo\nllamado POKéRUS\012que infecta\na los POKéMON.\012¡Sí! Es como un\nvirus, por eso se\011llama POKéRUS.\012Se multiplica\nrápido e infecta\012a otros POKéMON.\nPero eso es todo.\012Parece que no\nhace nada y que\012desaparece con\nel tiempo.\012Creo que no hay\nde qué preocuparse\011¡Adiós!",
  ["18:4f19"] = "Apenas puede\nrespirar…",
  ["6d:4b17"] = "¿Hola? ¿{PLAYER}?\n¡Qué desastre!\012¡Ee…, ee…, es\nterrible!\012¿Qué hacer?\n¡Oh, no…!\012¡Vuelve aquí\nahora mismo!",
  ["18:4f3d"] = "AMPHY: ¡Amphy!\n¡Amphy!",
  ["6d:4b87"] = "Hola, ¿{PLAYER}?\n¡Hemos descubierto\012algo sobre el\nHUEVO!\012Mi ayudante está\nen el CENTRO\012POKéMON de CIUDAD\nMALVA. ¿Podrías\011hablar con él?",
  ["18:6105"] = "En el COLISEO de\narriba se lucha\011enlazado.\012Los récords se\napuntan en la\012pared, así que no\npuedo perder.",
  ["6d:4c06"] = "{PLAYER}, ¿qué tal\nvan las cosas?\012Te llamo porque\npasó algo raro\012con las emisiones\nde radio.\012Hablaban del\nTEAM ROCKET.\012{PLAYER}, ¿sabes\nalgo sobre\011esto?\012Quizá ha vuelto\nel TEAM ROCKET.\012No, no puede\nser cierto.\012Siento molestarte.\n¡Cuídate!",
  ["18:6260"] = "Un POKéMON de\nnivel superior no\011siempre gana.\012Aún así, su tipo\npuede tener alguna\011desventaja.\012No creo que haya\nun único POKéMON\012que sea el más\nfuerte.",
  ["6d:4d09"] = "Hola, ¿{PLAYER}?\012Tengo algo para\nti aquí.\012¿Puedes venir\nal LABORATORIO?\012¡Hasta luego!",
  ["18:62f0"] = "{PLAYER}, ¿no?\012¡Felicidades!\012¡Estamos de\npromoción, hemos\012recibido una GS\nBALL para ti!\012¡Por favor,\nacéptala!",
  ["6d:4dc5"] = "Hola. Soy\n{STRBUF}…\012¡Buenos días,\n{PLAYER}!",
  ["19:6605"] = "Oh, y teníamos\nque luchar contra\012un {STRBUF} sal-\nvaje hace un rato…\012¡Mi CLEFAIRY casi\nse desmaya!\012¿No es horrible?\012¡Odio a los\n{STRBUF}!",
  ["6d:4ded"] = "Hola. Soy\n{STRBUF}…\012¿Qué tal,\n{PLAYER}?",
  ["19:6688"] = "Oh, y teníamos que\nluchar contra un\012{STRBUF} sal-\nvaje hace un rato…\012¡Mi CLEFAIRY se\nasustó, así que\012huimos tan rápido\ncomo pudimos!\012No puedo evitar\nser protectora\011con mi CLEFAIRY.",
  ["6d:4e16"] = "Hola. Soy\n{STRBUF}…\012¡Buenas noches,\n{PLAYER}!",
  ["19:6730"] = "Sé que esto puede\nsorprenderte, pero\012¿querrías luchar\nconmigo?\012Te espero con\nCLEFAIRY en\011{STRBUF}.",
  ["6d:4e3e"] = "¡Buenos días,\n{PLAYER}!\012Soy yo, {STRBUF}.\n¿Qué tal estás?",
  ["19:6796"] = "¡{STRBUF}!\012Es horrible.\nMi CLEFAIRY…\012¿Eh? ¿{PLAYER}?\012¡Oh, lo siento!\nTenía prisa y…\012¡Debo irme!\n¡Adiós!",
  ["6d:4e72"] = "Hola, {PLAYER}.\012Soy yo, {STRBUF}.\n¿Qué tal va todo?",
  ["19:67f7"] = "¡Adiós!",
  ["6d:4e9e"] = "¡Buenas noches,\n{PLAYER}!\012Soy yo, {STRBUF}.\n¿Tienes un minuto?",
  ["19:6801"] = "Compré unos LAZOS\nROSA en el CENTRO\012COMERCIAL de\nCIUDAD TRIGAL\011para mi CLEFAIRY.\012¡Como tengo muchos\nte puedo dar uno!\012Recógelo en\n{STRBUF}.",
  ["6d:4ecd"] = "¿Qué tal lo están\nhaciendo tus\011POKéMON?\012Mi {STRBUF} es\nmuy curioso, es un\012problema. Quizá\nes como yo…",
  ["19:6882"] = "¡Me encanta\ndisfrazar a mi\011CLEFAIRY!",
  ["6d:4f21"] = "Hola, soy\n{STRBUF}.\012¡Oh! Buenos días,\n{PLAYER}.",
  ["19:68a3"] = "¿Qué ocurre?\n¿No puedes venir?\012CLEFAIRY se cansó\ny se durmió.\012No sé si podré\ndespertarle…\012¡Date prisa en\nvenir a\011{STRBUF}!",
  ["6d:4f4d"] = "Hola, soy\n{STRBUF}.\012¡Oh! ¿Qué tal,\n{PLAYER}?",
  ["19:691d"] = "¿Qué ocurre?\n¿No puedes venir?\012Seguro que esto\nle sienta bien a\011tu CLEFAIRY.\012¡Date prisa en\nvenir a\011{STRBUF}!",
  ["6d:4f75"] = "Hola, soy\n{STRBUF}.\012¡Oh! Buenas\nnoches, {PLAYER}.",
  ["19:6980"] = "Mi {STRBUF} está\nmás y más fuerte.\012¡Hemos despegado!",
  ["6d:4fa1"] = "Hola, {PLAYER}.\nBuenos días.\012Soy {STRBUF}.\n¿Estabas\011durmiendo?",
  ["19:69b2"] = "¡Podemos derrotar\na {STRBUF}\011sin problemas!\012¿Sí? ¿Tú también?\n¡Estupendo!",
  ["6d:4fda"] = "Hola, {PLAYER}.\nSoy {STRBUF}.\012¿Qué tal vas?",
  ["19:69ed"] = "Pero oye esto, un\n{STRBUF} salvaje\012justo acaba de\nesquivarnos.\012Quería usar VUELO\ny atraparle…",
  ["6d:5004"] = "Hola, {PLAYER}.\nSoy {STRBUF}.\012¿Ya te has\ndespertado?",
  ["19:6a3a"] = "Ahora estoy en\n{STRBUF}.\012Ya sabes, donde\nnos conocimos.\012¿Quieres luchar?\nTe espero aquí.",
  ["00:26f2"] = "Evento de objeto.",
  ["19:6a93"] = "¡Hasta la próxima!",
  ["03:4d41"] = "¡{STRBUF}\nusó FUERZA!",
  ["19:6aa5"] = "¡Estoy deseando\nvolver a enfren-\011tarme contigo!",
  ["03:4d46"] = "{STRBUF}\npuede mover\011las piedras.",
  ["19:6ad1"] = "¡Oh, {PLAYER}!\n¡Date prisa!\012¡{STRBUF}!\n¡Usa VUELO!",
  ["03:4d69"] = "Un POKéMON\npodría moverla.\012¿Quieres usar\nFUERZA?",
  ["19:6afc"] = "¡Mi {STRBUF} está\nimpresionante!\012¡También soy mejor\npescador!",
  ["03:4d6e"] = "¡Ahora se pueden\nmover las piedras!",
  ["19:6b3e"] = "Derrotamos a un\n{STRBUF}\011salvaje…\012¿Sabes? Me gusta\nmás pescar que\012luchar contra\nPOKéMON salvajes.",
  ["03:4d73"] = "Un POKéMON\npodría moverla.",
  ["19:6b8f"] = "Pero, hace nada,\nestuvimos a punto\012de darle a un\n{STRBUF}\011salvaje.\012Te aseguro que era\nenorme, en serio.",
  ["03:4f58"] = "¡{STRBUF}\nusó GOLPE ROCA!",
  ["19:6bf3"] = "Estoy pescando en\n{STRBUF},\011pero hoy no pican.\012Ayúdame a pasar\nel rato. Ven a\011luchar conmigo.",
  ["03:4f72"] = "Un POKéMON\npodría romperla.",
  ["19:6c58"] = "Vale, nos vemos.",
  ["03:4f77"] = "Esta roca se\npuede romper.\012¿Quieres usar el\nGOLPE ROCA?",
  ["19:6c6b"] = "Enganché un\nobjeto pescando.\012Recógelo en\n{STRBUF}.",
  ["09:6f9b"] = "MAPA del PUEBLO.",
  ["19:6ca7"] = "Nada, no he\nencontrado nada\012que merezca la\npena.\012Debes ser\npaciente.",
  ["09:6fa3"] = "Un póster de un\nsimpático PIKACHU.",
  ["6d:52cc"] = "Hola, al habla\n{STRBUF}…\012¡Hola, {PLAYER}!\n¡Buenas noches!",
  ["09:6fab"] = "Un póster de un\ngracioso CLEFAIRY.",
  ["6d:5301"] = "¡Buenos días,\n{PLAYER}!\012Soy yo, {STRBUF}.\n¿Qué tal estás?",
  ["09:6fb3"] = "Un póster de un\nbonito JIGGLYPUFF.",
  ["6c:4681"] = "¡Todos los demás\nreciben una BAYA\011como consolación!",
  ["09:6fd8"] = "Un/a formidable\n{STRBUF}.",
  ["6c:465b"] = "¡Participa en el\npróximo concurso!",
  ["09:6fe6"] = "¡Un muñeco de\npeluche muy mono!",
  ["6c:4648"] = "{PLAYER} recibió\n{STRBUF}.",
  ["15:4122"] = "¡Hola! Soy BLANCA.\012¡Todos jugaban a\nPOKéMON, así\011que yo también!\012¡Los POKéMON son\nmuy monos!\012¿Quieres luchar?\n¡Te lo advierto!\011¡Soy muy buena!",
  ["6c:4621"] = "{PLAYER} gana el\npremio n.º{STRBUF}:\011¡una {STRBUF}!",
  ["15:41a5"] = "¡Ayy…!\012¡Uaaaaaaa!\n¡Qué mal!\012¡No deberías ser\nasí! ¡Sí, tú!\011¡Te lo digo a ti!",
  ["6c:45bf"] = "Vamos a evaluar\na tus POKéMON.\012……\n……\012¡Hemos elegido a\nlos ganadores!\012¿Estás preparado?",
  ["15:41f4"] = "¡Uaaaaa!\012¡Uaaaaa!\012¡Buaa, buaa…!\n¡Eres malo!",
  ["6c:459c"] = "Todo lo necesario\npara tus POKéMON\012TIENDA POKéMON",
  ["15:4222"] = "¡Sniff…!\012¿Qué quieres?\n¿Una MEDALLA?\012¡Ah, sí! Se me\nolvidaba. Toma la\011MEDALLA PLANICIE.",
  ["6c:457f"] = "Cura a tus POKéMON\nCENTRO POKéMON",
  ["15:4273"] = "{PLAYER}\nrecibió la\011MEDALLA PLANICIE.",
  ["6c:4526"] = "Aquí dentro no\nhay nada…",
  ["15:428b"] = "Con MED. PLANICIE\nlos POKéMON\012podrán usar FUERZA\nfuera del combate.\012Además, aumentará\nla VELOCIDAD de\011tus POKéMON.\012¡Ah, toma esto\ntambién!",
  ["6c:44c9"] = "PÁGINA DE INICIO\nREVISTA POKéMON.\012No ha sido\nactualizada…",
  ["15:4302"] = "¡Es ATRACCIÓN!\nUtiliza todo el\012encanto de un\nPOKéMON.\012¿No es perfecto\npara una monada\011como yo?",
  ["6c:44be"] = "Es una TV.",
  ["15:4360"] = "¡Ah, ha estado\nmuy bien!\012¡Vuelve cuando\nquieras! ¡Adiós!",
  ["6c:44a0"] = "¡Mi reflejo!\n¡Qué guapo!",
  ["15:439b"] = "No dejes que te\nimpresione la\012belleza de mis\nPOKéMON.\011¡Son muy fuertes!",
  ["6c:448d"] = "MAPA del PUEBLO.",
  ["15:43d6"] = "¡Vaya…! Pensaba\nque eras débil…",
  ["6c:4472"] = "¡Cantidad de\nartículos POKéMON!",
  ["15:43f6"] = "¿Creen mis POKéMON\nque soy guapa?",
  ["6c:4448"] = "¿Qué es esto?\012¡Oh! ¡Es un\npebetero!",
  ["15:4411"] = "Prefiero un\nPOKéMON mono a\011un POKéMON fuerte.\012¡Mis POKéMON son\nmonos y fuertes!",
  ["6d:5670"] = "Oh, ¿{PLAYER}?\012¡Genial! Sí, soy\nyo, {STRBUF}.",
  ["15:445f"] = "¡Oh, no, no, no!",
  ["6c:43a3"] = "Revistas POKéMON…\nTELEVISOR POKéMON,\012MANUAL POKéMON,\nGRÁFICA POKéMON…",
  ["15:4470"] = "Intento vencer a\nBLANCA, pero…\011es deprimente.\012¡De acuerdo! ¡Si\npierdo, volveré\012a intentarlo\notra vez!",
  ["6c:4378"] = "¡Una colección de\nlibros ilustrados\011de POKéMON!",
  ["15:44d4"] = "¡Oh, no! Has hecho\nllorar a BLANCA.\012¡No te preocupes!\nPronto dejará de\012llorar. Siempre\nllora si pierde.",
  ["6c:435a"] = "Está llena de\nlibros complejos.",
  ["15:452d"] = "¡Eres muy\ngracioso! ¡Me\012gustas! ¡Pero\nno me rendiré!",
  ["6d:5786"] = "¡Qué lentitud! \n¡Date prisa y\011contesta!\012¡Soy yo, {STRBUF}!",
  ["15:4574"] = "Veamos… ¡Uups!\n¿Ya está?",
  ["6d:57b7"] = "¡Qué lentitud! \n¡Date prisa y\011contesta!\012¡Soy yo, {STRBUF}!",
  ["15:458f"] = "¡Uau! ¡Debes de\nser muy bueno para\012haberme ganado!\n¡Adelante!",
  ["6d:5819"] = "Eh, ¿qué tal van\ntus POKéMON?\012¿Cómo? ¿Genial?\nYa veo…\012¿Qué? ¿Mis\nPOKéMON?\012¡Claro que lo\nestán haciendo\012bien! ¿A qué te\nrefieres?",
  ["15:45be"] = "¡Hazlo lo mejor\nque puedas o\011acabaré contigo!",
  ["6d:589a"] = "¡Hola, soy\n{STRBUF}!\012Oh, ¿{PLAYER}?\n¿Qué tal estás?",
  ["15:45ed"] = "¡No! ¡Oh, MEOWTH,\nlo siento mucho!",
  ["6d:58c2"] = "¡Hola, soy\n{STRBUF}!\012Oh, ¿{PLAYER}?\n¿Qué tal estás?",
  ["15:460b"] = "Le había enseñado\na MEOWTH todo tipo\011de ataques…",
  ["6d:5912"] = "¡Hola, {PLAYER}!\n¿Qué tal estás?\012Soy {STRBUF}.\n¿Tienes un minuto?",
  ["15:463a"] = "¡Hola, futuro\ncampeón!\012Este GIMNASIO es\npara entrenadores\012que usan POKéMON\nde tipo normal.\012Te recomiendo usar\nlos POKéMON de\011tipo lucha.",
  ["6d:5948"] = "¡Hola, {PLAYER}!\n¿Qué tal estás?\012Soy {STRBUF}.\n¿Tienes un minuto?",
  ["15:46a7"] = "¿Has ganado?\n¡Genial! Yo estaba\012ocupado mirando\na las chicas.",
  ["6d:597c"] = "¡Hola, {PLAYER}!\n¿Qué tal estás?\012Soy {STRBUF}.\n¿Tienes un minuto?",
  ["15:4787"] = "(Suspiro…)\nMe trasladé aquí,\012pero no vendo mis\nBICIS. ¿Por qué?\012¿Montarías en una\nBICI para hacerme\011publicidad?",
  ["19:5d5c"] = "¿Cómo está tu\nPIKACHU?\012¡Reunámonos para\npresumir de\011nuestros PIKACHU!",
  ["15:47f8"] = "¿De verdad? ¡Bien!\012Dime tu nombre y\nnúmero de teléfono\012y te prestaré\nuna BICI.",
  ["16:69d0"] = "Lo hiciste bien\nhoy, pero… ¡espera\011a la próxima vez!",
  ["15:4848"] = "{PLAYER} tomó\nprestada una BICI.",
  ["19:618c"] = "",
  ["15:485f"] = "¡Mis BICIS son de\ngran calidad!\012Puedes usarlas en\ncualquier lugar.",
  ["16:69fc"] = "Sí, el TEAM ROCKET\nse separó hace\011tres años.\012Pero seguimos\nclandestinamente\012con nuestras\nactividades.\012¡Diviértete ahora\ncon nuestras\011fechorías!",
  ["15:4898"] = "(Suspiro…)\n¡Oh, por el amor\011de Dios…!",
  ["19:5da6"] = "¿Qué ocurre?\012Te espero en\n{STRBUF}.\012Ven a recoger esto\ncuando quieras.",
  ["15:48ed"] = "¡Es una BICI\nnovísima!",
  ["6d:5b37"] = "¡Buenas noches,\n{PLAYER}!\012Soy yo, {STRBUF}.\n¿Estabas\011durmiendo?",
  ["15:49a3"] = "Si tratas bien a\ntus POKéMON,\012ellos te\nquerrán.\012¿Eh? Déjame ver\ntu {STRBUF}…",
  ["6d:5b68"] = "¿Qué tal están tus\nPOKéMON?\012Mis POKéMON tienen\ndemasiada energía.\012Puede llegar a ser\nun problema.\012De todos mis POKé-\nMON, {STRBUF} es\012el más difícil de\ncontrolar.\012Trabajar con él\ncansa mucho.",
  ["15:49fc"] = "¡Parece muy feliz!\nTe debe de\011querer mucho.",
  ["6d:5c10"] = "¿Sí? Ah, {PLAYER}.\012Eres muy cortés\nal presentarte\012cuando llamas por\nteléfono.",
  ["15:4a2c"] = "Me parece que\nconfía mucho\011en ti.",
  ["6d:5c63"] = "¿Sí? Ah, {PLAYER}.\012Eres muy cortés\nal presentarte\012cuando llamas por\nteléfono.",
  ["15:4a5a"] = "Es cariñoso\ncontigo. Parece\011feliz.",
  ["6d:5d09"] = "Hola, soy el tío\n{STRBUF}.",
  ["15:4a8e"] = "Es bastante mono.",
  ["6d:5d21"] = "Hola, soy el tío\n{STRBUF}.",
  ["15:4a9f"] = "Deberías tratarlo\nmejor. No está\011acostumbrado a ti.",
  ["6d:5d51"] = "¿Estás cuidando\nbien de tus\012POKéMON? ¡Debes\ntratar bien a tus\011compañeros!",
  ["15:4ad1"] = "Da la impresión de\nque no le gustas.\011Parece malvado.",
  ["6d:5d9f"] = "Hola. {STRBUF}\nal habla.\012Oh, {PLAYER}.\nBuenos días.",
  ["15:4b04"] = "No dejo de perder\nen los combates y\012mis POKéMON acaban\ndesmayándose…\012Quizá sea ésa la\nrazón por la que\011no les gusto…",
  ["6d:5dcc"] = "Hola. {STRBUF}\nal habla.\012Oh, {PLAYER}.\n¿Qué tal estás?",
  ["15:4b67"] = "¡Si uso un objeto\ncon mi POKéMON,\011se pone contento!",
  ["6d:5df8"] = "Hola. {STRBUF}\nal habla.\012Oh, {PLAYER}.\nBuenas noches.",
  ["15:4c74"] = "BILL: ¡Hola,\n{PLAYER}! Haznos\012un favor y acepta\neste EEVEE.\012Apareció cuando\najustaba la\011CÁPSULA de TIEMPO.\012Alguien tiene que\ncuidarlo y a mí\011no me gusta salir.\012¿Puedo confiar en\nti para jugar con\011él, {PLAYER}?",
  ["6b:6021"] = "¡Mmm…! No sé\nqué hacer…",
  ["15:4d3f"] = "BILL: ¡Sabía que\naceptarías!\012¡Vamos! ¡Tú sí\nque vales!\012Bueno, cuento\ncontigo.\012¡Cuídalo bien!",
  ["6b:5ff7"] = "Cuando llueve,\nes difícil\011encenderlo…",
  ["15:4dae"] = "¡{PLAYER}\nrecibió\011a EEVEE!",
  ["6b:5fdb"] = "Hace sol, pero\nestoy mojado…",
  ["15:4dc1"] = "BILL: ELM dice que\nEEVEE evoluciona\012en formas nuevas\ny desconocidas.",
  ["6b:5fb8"] = "¡Ah! Hace un\ntiempo estupendo.",
  ["15:4e02"] = "No, espera. No\npuedes llevar\011más POKéMON.",
  ["6b:5ee1"] = "…\012¿Dices que TEAM\nROCKET adiós?\012¿Roto? ¿Eso\ndices?\012¡Oh, no! ¿Debo\nir por cuenta\011mía ahora?",
  ["15:4e2d"] = "¡Oh…! ¿Qué\nhacer ahora?",
  ["6b:5dc0"] = "Vale. Contar\nsecreto a ti.\012MAQUINARIA yo\nrobar, escondida\012en GIMNASIO de\nCELESTE.\012En agua yo poner.\nMirar en centro de\011agua de GIMNASIO.\012¡Pero tú no\nolvidar a mí!\012TEAM ROCKET seguro\nderrotar a ti.\012Míos amigos venir\nde JOHTO, sí.\011Vengar ellos a mí.",
  ["6b:5d67"] = "¡Ayyyy! ¡No, no,\nno! ¡Creer no\011puedo!\012¡Fuerte mucho\neres! ¡Rival\011para ti no soy!",
  ["6b:5c2e"] = "¡Eh, chico! ¡Un\nmiembro del TEAM\011ROCKET ser yo!\012Ser de otro país.\nEntrenador número\011uno, ¡yo ése!\012Pensar hice. Si\ncortar energía,\012¡mucho pánico\naquí todos!\012Misión secreta\nes, ¡no contar\011a ti!\012Pero, si ganar a\nmí, un hombre\012soy y secreto mío\na ti contar.\012¡Eh, chico!\n¡Lucha empezar!",
  ["6b:5b97"] = "¿Qué es esto?\012Casa en venta…\nNo vive nadie.",
  ["6b:5b66"] = "VÍA SUBTERRÁNEA\012CIUDAD CELESTE -\nCIUDAD CARMÍN",
  ["6b:5b22"] = "La carretera está\ncortada hasta que\012arreglen la\nCENTRAL ENERGÍA.",
  ["6b:5a88"] = "¡Mira qué adorable\nes mi TEDDIURSA!\012¿No es tan bonito\nque te emociona?",
  ["6b:5a79"] = "¡Mi TEDDIURSA!",
  ["6b:5a4f"] = "Mi TEDDIURSA es el\nmás bonito del\011mundo.",
  ["6b:59ff"] = "¡Mira qué adorable\nes mi PHANPY!\012¿No es tan bonito\nque te emociona?",
  ["6b:59f3"] = "¡Mi PHANPY!",
  ["6b:59cc"] = "Mi PHANPY es el\nmás bonito del\011mundo.",
  ["6b:599b"] = "VÍA SUBTERRÁNEA\012CIUDAD CELESTE -\nCIUDAD CARMÍN",
  ["6b:5957"] = "La carretera está\ncortada hasta que\012arreglen la\nCENTRAL ENERGÍA.",
  ["6b:5880"] = "CEMENTERIO\012Que las almas de\nlos POKéMON\011descansen en paz",
  ["6b:5861"] = "CASA POKéMON\nDE VOLUNTARIOS DE\011PUEBLO LAVANDA",
  ["6b:581c"] = "EMISORA DE\nKANTO\012¡Tus programas\nfavoritos a\011cualquier hora!",
  ["6b:57f7"] = "PUEBLO LAVANDA\012El noble pueblo\npúrpura",
  ["6b:57ac"] = "Para despertar a\nlos POKéMON,\012sintoniza FLAUTA\nPOKéMON.\012¡Todo entrenador\ndebería saberlo!",
  ["6b:575c"] = "Viene gente de\ntodas partes a\012rendir homenaje\na las almas de\012los POKéMON\nque han partido.",
  ["6b:573a"] = "KANTO tiene muchos\nprogramas buenos.",
  ["6b:5702"] = "Menudo\nedificio, ¿eh?\012Es la TORRE de\nRADIO de KANTO.",
  ["6b:5660"] = "Si hubiera un\nsistema fácil de\012identificar dónde\nobtuve mi POKéMON…",
  ["6b:5640"] = "¿Dónde conocí a\neste PSYDUCK?",
  ["6b:55e4"] = "Hola.\n¿Sabes qué…?\012Los POKéMON son\nmás amigables si\012los entrenas en un\nlugar que ellos\011recuerden.",
  ["6b:55a4"] = "¿Tienes POKéMON\nque conozcan la\012MO VUELO? ¿Sí?\n¡Qué envidia!",
  ["6b:5581"] = "Puedo soñar, pero\nnunca podré volar.",
  ["6b:5552"] = "Mi sueño es volar\ncon mi querido\011POKéMON pájaro.",
  ["6b:5508"] = "SQUIRTLE, CHARMAN-\nDER y BULBASAUR.\012Creo que es una\nbuena combinación.",
  ["6b:54ff"] = "¡Auuuu!",
  ["6b:54c2"] = "Que sepas que\nme costó mucho\012atrapar a mis\nqueridos POKéMON.",
  ["6b:5456"] = "Está cerrada…",
  ["6b:5388"] = "¿Y este cartel?\012Algunos\nentrenadores han\012estado luchando en\nVÍA SUBTERRÁNEA.\012Tras numerosas\nquejas de los\012vecinos, la VÍA\nSUBTERRÁNEA ha\012sido cerrada\nindefinidamente.\012POLICÍA C. AZULONA",
  ["6d:7057"] = "¿Sí, diga?\n¡Soy {STRBUF}!\012¡Hola, {PLAYER}!\012¿Están tus POKéMON\npájaro volando?",
  ["6b:5293"] = "¡Conducir de forma\nimprudente causa\012accidentes! ¡Ten\ncuidado!",
  ["6d:7092"] = "¿Sí, diga?\n¡Soy {STRBUF}!\012¡Buenas noches,\n{PLAYER}!\012¿Les das a tus\nPOKéMON pájaro\011algo de acción?",
  ["6b:525c"] = "¡Somos estrellas\nde la carretera!",
  ["6d:70e7"] = "¡Buenos días,\n{PLAYER}!\012¡Soy {STRBUF}!",
  ["6b:5203"] = "¡Vaya! ¡Qué\nvitalidad!",
  ["6d:7112"] = "¡Hola, {PLAYER}!\012¡Soy {STRBUF}!\n¿Me recuerdas?",
  ["6b:5196"] = "Soy guay, pero\nestoy débil. Por\011eso no lo parezco.\012Debería entrenar\nmucho más…",
  ["6d:7132"] = "¡Buenas noches,\n{PLAYER}!\012¡Soy {STRBUF}!\n¿Estás libre?",
  ["6b:515c"] = "¡Uau! ¡Qué BICI\nmás guay!",
  ["6d:7161"] = "¿Estáis bien tus\nPOKéMON y tú?\012¡Mi {STRBUF}\nparece que llegará\012a ser tan duro\ncomo para enfren-\011tarse y derrotar a\011los legendarios\011pájaros POKéMON!",
  ["6b:512a"] = "¡Venga, golpea!",
  ["6d:71d5"] = "Hola. Hablas\ncon {STRBUF}…\012Ah, {PLAYER}.",
  ["6b:5051"] = "RUTA 18\012CIUDAD AZULONA -\nCIUDAD FUCSIA",
  ["6d:71fc"] = "Hola. Hablas\ncon {STRBUF}…\012Ah, {PLAYER},\n¿verdad?",
  ["6b:5005"] = "¡Uau…!",
  ["6d:722a"] = "Hola. Hablas\ncon {STRBUF}…\012Ah, pero si es\n{PLAYER}.",
  ["6a:6155"] = "Hay un concurso\nde tragones\011en el restaurante.\012Sólo verlo hace\nque me sienta\011lleno…",
  ["6d:725c"] = "Ah, soy {STRBUF}…\012¿Tienes un\nmomento?",
  ["6a:5e60"] = "Ésta es la CIUDAD\nVERDE, la entrada\011a la MESETA AÑIL",
  ["6d:7283"] = "Ah, soy {STRBUF}…\012¿Puedo hablar\ncontigo?",
  ["6a:679f"] = "¡Me olvidé de\nhacer los deberes!",
  ["6d:72a5"] = "Ah, soy {STRBUF}…\012Siento llamarte\ntan tarde.",
  ["6a:67f1"] = "Vamos a la TORRE\nRADIO de LAVANDA\012para realizar unos\nestudios sociales.",
  ["26:627e"] = "¿Puedes causar\nalgún daño a\011nuestros POKéMON?",
  ["6a:6833"] = "¡Eres demasiado\nduro!",
  ["1a:639d"] = "Aquí tienes las\nPARQUE BALL para\011el Concurso.",
  ["6a:684a"] = "Estoy cansado de\ncaminar. Necesito\011un descanso.",
  ["1a:63c7"] = "{PLAYER} recibió\n20 PARQUE BALL.",
  ["6a:687a"] = "¡Mi asignatura\nfavorita es la\011gimnasia!",
  ["1a:63e2"] = "Aquél que consiga\nel POKéMON bicho\012más fuerte será\nel ganador.\012Tienes 20\nminutos.\012Si te quedas sin\nPARQUE BALL, has\011perdido.\012Puedes quedarte\nel último POKéMON\011que captures.\012¡Sal y captura\nel POKéMON\012bicho más fuerte\nque encuentres!",
  ["6a:6895"] = "¡Oh, no! ¿Cómo he\npodido perder?",
  ["26:6309"] = "¡He… he perdido!",
  ["6a:68b0"] = "¡Si los POKéMON\nfueran una\012asignatura, yo\nsería el mejor!",
  ["1a:6537"] = "Bien, guardaremos\nlos otros POKéMON\011mientras compites.",
  ["6d:73af"] = "¡Eh, {PLAYER}!\n¡Soy {STRBUF}!",
  ["26:633e"] = "¿Atónito por el\nsuelo invisible?\012¡Si quieres una\npista, vénceme!",
  ["6a:6a15"] = "CIUDAD CARMÍN\nes el puerto\012más importante\nde KANTO.\012En él atracan\nlujosos\012transatlánticos\nde todo el mundo.",
  ["1a:6597"] = "Elige el POKéMON\nque usarás en\012el Concurso y\nluego ven a verme.",
  ["6d:7417"] = "¡Yup, yup!\n¡Soy {STRBUF}!\012Ah… ¡y aquí está\n{PLAYER}!",
  ["26:638a"] = "Bien. Te contaré\nel secreto\012del suelo\ninvisible.\012¡La ruta está\nenfrente de ti!",
  ["6a:6aca"] = "MACHOP: ¡Machop\nmachop!",
  ["1a:6608"] = "¡Oh, oh…!\nEl primer POKéMON\012de tu equipo no\npuede luchar.\012Sustitúyelo por\nel POKéMON que\012quieras usar y\nluego ven a verme.",
  ["6a:6ae2"] = "Un MACHOP gruñe\nmientras pisotea\011el suelo.",
  ["26:6452"] = "¡Uauu, {PLAYER}!\n¡Genial!\012¡Me escondí en\nel rincón\011muerto de miedo!",
  ["6a:6b1a"] = "En KANTO hay ocho\nGIMNASIOS.\012Ese gran edificio\nes el GIMNASIO\012POKéMON de CIUDAD\nCARMÍN.",
  ["1a:671f"] = "¡Oh, oh…! Tienes\nun HUEVO como\012primer POKéMON\nde tu equipo.\012Sustitúyelo por\nel POKéMON que\012quieras usar y\nluego ven a verme.",
  ["6a:6b64"] = "SNORLAX duerme\nplácidamente…",
  ["26:663c"] = "¡Ah! ¿Vas de\naventura con tus\011POKéMON?\012¿Y qué es una\naventura sin\011un tesoro?\012¿Tengo razón\no no?",
  ["6a:6b84"] = "El POKéGEAR está\ncerca del\011SNORLAX dormido.\012…\012¡SNORLAX se\ndespertó!",
  ["1a:67db"] = "Bien. Espera en\nla Puerta Norte a\012que se anuncien\nlos ganadores.",
  ["6a:6bc8"] = "Los entrenadores\nexpertos se reúnen\011en KANTO.\012Los LÍDERES de\nGIMNASIO son\011muy fuertes.\012No serán fáciles\nde vencer.",
  ["26:670e"] = "Por aquí hay\nmuchos objetos\012que no se ven\ntan fácilmente.\012Utiliza el\nBUSCAOBJETOS para\012saber si hay algún\nobjeto cerca.\012Éste no indica el\nlugar exacto, así\012que tú tendrás\nque encontrarlo.\012¡Ah, sí! Dicen que\nhay muchos objetos\012en TORRE QUEMADA\nde CIUDAD IRIS.",
  ["6a:5def"] = "CIUDAD VERDE\012El Paraíso\nEternamente Verde",
  ["1a:684f"] = "El Concurso ha\nacabado. Esperamos\012volveros a ver\naquí pronto.",
  ["6a:5daa"] = "Dicen que en el\nsuelo del BOSQUE\012VERDE hay muchos\nobjetos.",
  ["1a:6894"] = "En el PARQUE se\nsuelen celebrar\012muchos Concursos.\nDeberías probar.",
  ["6a:5d86"] = "MT42 contiene\nCOME SUEÑOS…\012¡Zzzzz…!",
  ["1a:68d8"] = "¿Cuándo será el\npróximo Concurso\011Captura de Bichos?",
  ["6a:5cc4"] = "¡Qué sueño!\012Me habré quedado\ndormido al sol.\012He soñado que\nun DROWZEE se\012comía mi sueño.\nEs raro, ¿verdad?\012¿Eh?\n¿Qué es esto?\012¿De dónde ha\nsalido esta MT?\012¡Esto es muy\nmisterioso! Aquí\011tienes esta MT.",
  ["1a:690e"] = "El Concurso de\nCaptura de Bichos\012se celebra los\nmartes, jueves\011y sábados.\012No sólo ganarás un\npremio por parti-\011cipar. Además,\011podrás quedarte\012con el POKéMON\nbicho que tengas\012al final del\nconcurso.",
  ["6a:5c7e"] = "¿Vas a enfrentarte\nal LÍDER?\012¡Buena suerte! ¡La\nvas a necesitar!",
  ["1a:6a20"] = "¿No te imaginas\nquién podría\012hacer algo así?\n¿Y por qué?",
  ["6a:5c11"] = "Este GIMNASIO no\nha tenido LÍDER\011hasta hace poco.\012Un joven de\nPUEBLO PALETA se\012convirtió en LÍDER\npero viaja mucho.",
  ["1a:6a5b"] = "¿Has visto ese\nextraño árbol en\011el camino?\012Eso explica por\nqué vienen menos\012personas a visitar\nlas RUINAS ALFA.",
  ["6f:5aa9"] = "Soy el ENCARGADO\nde la GUARDERÍA.\012¿Quieres que\ncuide un POKéMON?",
  ["1a:6dd5"] = "Hoy es {STRBUF}.\nEso significa que\012hoy es el Concurso\nCaptura de Bichos.\012Las reglas son\nsencillas.\012Usa uno de tus\nPOKéMON y captura\012un POKéMON bicho\npara ganar.\012¿Te gustaría\nintentarlo?",
  ["1a:6e87"] = "Aquí tienes las\nPARQUE BALL para\011el Concurso.",
  ["1a:6eb1"] = "{PLAYER} recibió\n20 PARQUE BALL.",
  ["1a:6ecc"] = "Aquél que consiga\nel POKéMON bicho\012más fuerte será\nel ganador.\012Tienes 20\nminutos.\012Si te quedas sin\nPARQUE BALL, has\011perdido.\012Puedes quedarte\nel último POKéMON\011que captures.\012¡Sal y captura\nel POKéMON\012bicho más fuerte\nque encuentres!",
  ["1a:6fb0"] = "¡Oh, oh…!\012Tienes más de\nun POKéMON.\012Tendrás que usar\na {STRBUF},\012el primer POKéMON\nde tu equipo.\012¿Te parece\nbien?",
  ["1a:7021"] = "Bien, guardaremos\nlos otros POKéMON\011mientras compites.",
  ["1a:7055"] = "Los POKéMON de\n{PLAYER} se quedan\011con el AYUDANTE.",
  ["1a:7081"] = "Elige el POKéMON\nque usarás en\012el Concurso y\nluego ven a verme.",
  ["1a:70c6"] = "Muy bien.\nEsperamos verte\011pronto por aquí.",
  ["1a:70f2"] = "¡Oh, oh…!\nEl primer POKéMON\012de tu equipo no\npuede luchar.\012Sustitúyelo por\nel POKéMON que\012quieras usar y\nluego ven a verme.",
  ["1a:7166"] = "¡Oh, oh…!\nTu equipo y\012tu CAJA del PC\nestán llenos.\012No tienes sitio\npara guardar el\011POKéMON bicho.\012Haz sitio en\ntu equipo o en\012la CAJA del PC y\nluego ven a verme.",
  ["1a:7209"] = "¡Oh, oh…! Tienes\nun HUEVO como\012primer POKéMON\nde tu equipo.\012Sustitúyelo por\nel POKéMON que\012quieras usar y\nluego ven a verme.",
  ["1a:7284"] = "Aún te quedan\n{STRBUF} minuto(s).\012¿Quieres terminar\nahora?",
  ["1a:72c5"] = "Bien. Por favor,\nespera aquí\012a que se anuncien\nlos ganadores.",
  ["26:6efe"] = "SPEARY: ¡Spea!",
  ["1a:7300"] = "Bien. Por favor,\nvuelve fuera y\011termina.",
  ["26:6f10"] = "RATTEY: ¡Ratii!",
  ["1a:732b"] = "El Concurso ha\nacabado. Esperamos\012volveros a ver\naquí pronto.",
  ["1a:7370"] = "Algunos POKéMON\nsólo aparecen en\011el PARQUE.",
  ["6a:5bb7"] = "¿Qué? ¡Pequeño\nbribón!\012Si fuera un poco\nmás joven, te\012enseñaría un par\nde cosas. ¡Vaya!",
  ["1a:7399"] = "RAFA: ¡Uau! Me\nhas vencido. Eres\011bastante bueno.",
  ["6a:5b6f"] = "Muy bien. Sí, yo\nera algo fuera de\012lo normal. ¡Déjame\ncontártelo!",
  ["1a:73c4"] = "RAFA: La suerte\ncuenta mucho.\012Nunca se sabe\nqué POKéMON\011va a aparecer.",
  ["6a:5aa5"] = "¡Hola, chico! ¡Me\nacabo de tomar un\012café doble y estoy\ncomo una moto!\012¡Tengo que hablar\ncon alguien, así\011que te toca a ti!\012Puede que ahora no\nlo parezca, pero\012yo era un experto\natrapando POKéMON.\012¿Me crees?",
  ["1a:740f"] = "SAM: Te envidio.\nEsta vez no\011lo he conseguido.",
  ["6a:59be"] = "RUTA 46\nCAMINO MONTAÑA",
  ["1a:7440"] = "SAM: ¿Has usado\nPOKéMON grandes?",
  ["6a:5927"] = "Auuuu… ¡Pierdo\nsiempre! ¡Sólo\012tengo que seguir\nintentándolo!\012Bueno, gracias por\nluchar conmigo una\012y otra vez. Toma\neste regalo de la\011última vez.",
  ["1a:7462"] = "NANO: ¡Eso es!\nVoy a entrenar\012mejor a mis\nPOKéMON.",
  ["6a:58c6"] = "He estado en\nmuchos GIMNASIOS,\012pero mi favorito\nes el de TRIGAL.\012¡Está lleno de\npreciosas flores!",
  ["1a:7496"] = "NANO: Quizá ganes\nmás puntos por\012un POKéMON de\nun color inusual.",
  ["6a:58bb"] = "¡Oh, narices!",
  ["1a:74da"] = "GUILLE: ¿Eres el\nganador? ¿Qué\011has atrapado?",
  ["6a:588f"] = "¡Yo también\nentreno POKéMON!\012¿Quieres luchar\ncontra mí?",
  ["1a:750a"] = "GUILLE: Me alegra\nhaber atrapado\012el POKéMON\nque quería.",
  ["1c:52c7"] = "Una máquina\nexpendedora con\012una ruleta de\npremios…\012Nunca verás\nnada igual.",
  ["1a:754e"] = "TINO: Enhorabuena.\n¡Te has ganado mi\011respeto!",
  ["1c:5310"] = "¡Auu! ¡Aquí no\nhay juegos!\012¡Quería jugar…!",
  ["1a:757c"] = "TINO: He atrapado\nun SCYTHER,\011pero he perdido.",
  ["1c:533e"] = "ÚLTIMO PISO\nEXPENDEDORAS",
  ["1a:75b0"] = "BENITO: El POKéMON\nque has atrapado…\011es impresionante.",
  ["1c:5416"] = "Mis queridos\nPOKéMON me hacen\012compañía, así que\nnunca estoy sola.\012MEOWTH hasta trae\ndinero a casa.",
  ["1a:75dd"] = "BENITO: Es más\nfácil ganar con\012un POKéMON bicho\nde nivel alto.\012Pero creo que\ntambién cuentan\011otros aspectos.",
  ["1c:5470"] = "MEOWTH: ¡Meow!",
  ["1a:764b"] = "CINDY: ¿Ganaste?\n¡Qué bien!\012¿Te apetece buscar\nPOKéMON bicho\011conmigo?",
  ["1c:547f"] = "CLEFAIRY: ¡Clef\ncleff!",
  ["1a:7698"] = "CINDY: ¡Adoro\nlos POKéMON bicho!",
  ["1c:5496"] = "NIDORAN: ¡Nido\nnido!",
  ["1a:76b8"] = "KAI: ¡No…!\nNo me puedo creer\011que haya perdido.",
  ["1c:54ab"] = "DESPACHO DEL JEFE\nDE MANSIÓN AZULONA",
  ["1a:76e9"] = "KAI: ¡Dicen que\nalguien ha ganado\011con un CATERPIE!",
  ["1c:5539"] = "{PLAYER} encendió\nel PC.\012…\012Alguien estaba\nescribiendo\011un e-mail.\012Espero que\nvengas a KANTO.\012Te sorprenderás de\ncuánto han\012cambiado las\ncosas por aquí.\012También verás\nmuchos POKéMON\012que no son nativos\nde JOHTO.\012Al PRODUCTOR\012…",
  ["1a:771b"] = "SAMUEL: La próxima\nvez ganaré yo.",
  ["1c:562c"] = "SALA DE REUNIONES\nDE GAME FREAK",
  ["1a:7740"] = "SAMUEL: Vaya,\ncreí que obtendría\011más puntos…",
  ["1c:56ce"] = "¡Hola!\012¡Soy el DISEÑADOR\nDEL JUEGO!\012Te costará\ncompletar tu\012POKéDEX, pero\n¡no te rindas!",
  ["1a:776f"] = "KOLDO: ¿Me das\nalgún consejo?\012Quiero estudiar\ntu estilo.",
  ["1c:5725"] = "¡Uau! ¡Excelente!\n¡Has completado tu\011POKéDEX!\012¡Enhorabuena!",
  ["1a:77af"] = "KOLDO: He\nestudiado mucho,\012pero eso no vale\npara ganar.",
  ["1c:5760"] = "…",
  ["1c:5763"] = "El ARTISTA GRÁFICO\nte imprimirá un\011DIPLOMA.\012Deberías presumir\nde ello.",
  ["6a:5851"] = "Hice lo que pude\npero no sirvió.\012No hay excusa que\nvalga. He perdido.",
  ["1a:797f"] = "¿{PLAYER}?\012Aquí tienes el\npremio que te\011guardábamos.",
  ["6a:584a"] = "¿Qué…?",
  ["1c:57d8"] = "Soy el ARTISTA\nGRÁFICO.\012¿Has completado\ntu POKéDEX?\012¿Quieres imprimir\ntu DIPLOMA?",
  ["6b:449f"] = "CUEVA DIGLETT",
  ["1b:40be"] = "¡Lo…, lo siento!",
  ["6b:447a"] = "RUTA 2\012CIUDAD VERDE -\nCIUDAD PLATEADA",
  ["1c:5895"] = "¿Quién? ¿Yo? Soy\nel PROGRAMADOR.\012¡Juega a las\ntragaperras!",
  ["6b:4423"] = "Los POKéMON bicho\nparecen muñecos\012de goma cuando les\naprietas la tripa.\012¡Me encanta\ntocarlos!",
  ["1b:40f4"] = "Los polis han\ncerrado la VÍA\012SUBTERRÁNEA. ¡Qué\nfastidio!",
  ["6b:4419"] = "¡Muy mal!",
  ["1c:590b"] = "SALA DE DESARROLLO\nDE GAME FREAK",
  ["6b:43fa"] = "¿Por qué a las\nchicas no les\012gustan los\nPOKéMON bicho?",
  ["1b:4143"] = "Destruido por\nun gamberro\011de JOHTO…",
  ["6b:43cf"] = "Seguro que te\npican si te\011bañas.",
  ["1c:5952"] = "Es el programa\ndel juego. ¡No lo\012toques! ¡Podrías\nestropearlo!",
  ["6b:43bc"] = "¡Au, au, au!",
  ["1b:4194"] = "¡Vaya! ¡Perdona!",
  ["6b:4376"] = "Si caminas por la\nhierba alta con\012pantalones cortos,\n¿no te arañas?",
  ["27:4086"] = "Hay una persona en\nCIUDAD ORQUÍDEA,\011cruzando el mar.\012¡Dicen que\npresume de sus\011raros POKéMON!",
  ["6b:434d"] = "Voy a buscar\nPOKéMON bichos\011más fuertes.",
  ["1b:41d0"] = "¿Cómo funciona\nel MAGNETOTRÉN?",
  ["1b:56cf"] = "Esta máquina está\ncausando todos\011los problemas.\012Pero no veo ningún\ninterruptor…\012No tenemos\nelección. Hay que\012debilitar a todos\nlos ELECTRODE.\012Eso impedirá que\nesta máquina siga\012transmitiendo esa\nextraña señal.\012Los POKéMON no\ntienen la culpa\012y por eso yo me\nsiento culpable.\012{PLAYER}, mejor\nque nos dividamos\011la tarea.",
  ["27:42bb"] = "Eres mejor\nentrenador que yo,\012tanto en habilidad\ncomo en simpatía.\012De acuerdo con las\nnormas de la LIGA,\012te concedo esta\nMEDALLA.",
  ["1b:5809"] = "LANCE: Por fin\nha parado esa\011extraña señal.\012El LAGO vuelve a\nla normalidad.\012¡Eres un héroe!\nMuchas gracias\012en nombre de\ntodos los POKéMON.\012¡Ah, sí! Toma\nesto.\012Lo encontré aquí,\npero yo no lo\011necesito.",
  ["1b:4219"] = "¡El poder de los\nimanes es inmenso!",
  ["1a:5b83"] = "Éste es un buen\nsitio para pescar.\012¿Has visto a\ngente pescando?\011¿Y tú?\012¿Quieres una\nde mis CAÑAS?",
  ["27:4354"] = "La MEDALLA MINERAL\naumenta la DEFENSA\011de los POKéMON.\012¡Eh…! Toma\nesto también…",
  ["1a:5997"] = "Los POKéMON que\nse intercambian\011crecen rápido.\012Pero si no tienes\nla MEDALLA\012adecuada, podrían\ndesobedecerte.",
  ["1b:425d"] = "Tal y como pensé…\n¡Eres fuerte!",
  ["1a:5712"] = "{PLAYER},\n¿quieres el HUEVO?",
  ["27:43d1"] = "¡Eh…! No sé\ncómo decirlo, pero\011buena suerte…",
  ["1a:5555"] = "¡{PLAYER}, cuánto\ntiempo sin verte!\012El PROF. ELM te\nestá buscando.\012Quiere pedirte\notro favor.\012¿Puedes llevar el\nHUEVO POKéMON?",
  ["1b:42aa"] = "Está cerrada…",
  ["1a:5287"] = "Quienes atrapan\nPOKéMON y los usan\012para luchar son\nentrenadores.\012Su misión es ir\na los GIMNASIOS\012y vencer a otros\nentrenadores.\012La hoja siguiente\nestá… ¡vacía!\012Niño: ¡Eh, eh…!\012No he escrito\nnada más…",
  ["27:4451"] = "Ha sido increíble.\012¿El tipo acero,\neh?\012¡Ha sido un gran\ncombate de un\011tipo desconocido!",
  ["1a:50cb"] = "Si tu POKéMON está\ncongelado, no\011podrá hacer nada.\012Seguirá congelado\ntras el combate.\012Descongélalo con\nANTIHIELO.",
  ["1b:446b"] = "¡Arrg…!\nHas encontrado la\011escalera secreta.",
  ["1a:4efe"] = "Si un POKéMON\nes envenenado,\011perderá PS.\012El envenenamiento\ncontinúa tras el\012combate y al\ncaminar seguirá\011perdiendo PS.\012Para curarlo,\nusa ANTÍDOTO.",
  ["27:45a2"] = "Cuando mis POKéMON\nenfermaron, el\012FARMACÉUTICO de\nCIUDAD IRIS me\011dio una medicina.",
  ["66:4f5b"] = "¡El mundo es un\ncamino de bicis!\011TIENDA DE BICIS",
  ["27:45f0"] = "RHYDON: ¡Rhydo!",
  ["66:4f29"] = "CIUDAD TRIGAL\012La alegre ciudad\nde rico encanto",
  ["27:4643"] = "De camino a CIUDAD\nORQUÍDEA, hay\012cuatro islas\ndesiertas.\012¡A los niños malos\nlos llevan a\012las islas como\ncastigo!",
  ["6a:50fc"] = "DOMINGO: Mis\nhermanos son\011LUNA, MARTA,\011MIGUEL, JOSUÉ,\011VICKY y SABINO.\012¡Son todos\nmayores que yo!",
  ["27:46b1"] = "Cuando me meto en\nlíos, papá siempre\011se enfada.",
  ["6a:516e"] = "DOMINGO: ¿Hoy no\nes domingo?\011¡Um…! ¡Lo olvidé!",
  ["27:4749"] = "¡CIUDAD OLIVO está\njunto al mar!\012¡Y si está junto\nal mar, tiene que\011haber peces!\012Llevo 30 años\npescando aquí.\012¿Quieres mirar\nal mar y\011pescar?",
  ["6a:5197"] = "RUTA 37",
  ["27:47db"] = "¡Ah, ja, ja!\n¡Ya tenemos un\011nuevo pescador!",
  ["6a:535f"] = "¡Déjame que te\nenseñe el poder de\011mis POKéMON!",
  ["27:4807"] = "No sólo hay peces\nen el mar. Puedes\012encontrarlos allí\ndonde haya agua.",
  ["6a:5393"] = "¿Qué? Eso no está\nbien.",
  ["27:484c"] = "¿Quééé? ¿¡No te\ngusta pescar!?\011¡Incomprensible!",
  ["6a:53ab"] = "Quiero convertirme\nen un CAMPEÓN\012con los POKéMON\nque he atrapado.\012¡Eso es lo mejor\nde la pesca!",
  ["27:487f"] = "¿Qué tal va todo?\n¿Pica el grande?",
  ["6a:5408"] = "¡Ah! ¡Qué bien\nestar fuera! ¡Me\011siento tan libre!",
  ["27:48df"] = "¡Ja! ¡Tus POKéMON\nparecen ser muy\011enclenques!\012No tienen el poder\npara desplazar\011rocas.\012Mira, ¡usa esto y\nenséñales FUERZA!",
  ["6a:5435"] = "¡Gahahah!",
  ["27:4965"] = "¡En el mar sólo\npuedes confiar\011en ti mismo!\012¡Y yo estoy en\nplena forma!",
  ["6a:543f"] = "¡Perder no tiene\nimportancia si lo\012comparas con el\ninmenso cielo!",
  ["1b:4c0b"] = "Lo tengo…",
  ["6a:547c"] = "¡OYE!\012¡Éste es mi lugar\nsecreto! ¡Fuera de\011aquí, intruso!",
  ["27:4a09"] = "Cuando estoy de\npaso, siempre\012visito el CAFÉ\nOLIVO.\012Todo lo del menú\nme hace sentir más\012fuerte. ¡No puedo\nparar de comer!",
  ["1c:654f"] = "Aquí hay un\nencendedor.",
  ["27:4ad4"] = "¿Tus POKéMON saben\nun movimiento para\012llevar personas\npor el agua?",
  ["1c:6567"] = "¡Un refresco!\012Alguien se lo\nhabrá dejado…\012¿Uh? ¡Está vacío!",
  ["27:4b16"] = "Mi BUTTERFREE ha\nestado con mi\011novio.\012Y me ha traído\nuna CARTA suya.\012¿Quieres saber\nlo que dice?\012Veamos… ¡No!\n¡Es un secreto!",
  ["1c:68b8"] = "Quería un PORYGON,\npero sólo tenía\011100 fichas…",
  ["27:4bda"] = "¿De dónde has\ndicho que eras?\012¿De PUEBLO\nPRIMAVERA?\012El PROF. ELM vive\npor allí, ¿no?\012Has recorrido un\nlargo camino.",
  ["1c:68e9"] = "¡Uauu…!\012Debo permanecer\ntranquilo…\012No puedo perder\nla cabeza o\011perderé todo…",
  ["27:4d2e"] = "MUU-MUU está\nenferma…\012Necesita muchas\nBAYAS.",
  ["1c:693e"] = "¡Bienvenido!\012¡Aquí te cambiamos\ntus fichas por\011premios fabulosos!",
  ["27:4d5a"] = "¡Estamos dando de\ncomer a MUU-MUU!",
  ["1c:6974"] = "¿Qué premio\nquieres?",
  ["1c:6991"] = "De acuerdo,\n¿{STRBUF}?",
  ["6a:54b3"] = "Debí haber usado\nmi PIEDRA LUNAR…",
  ["1c:69ad"] = "¡Aquí tienes!",
  ["1c:69bb"] = "No tienes\nbastantes fichas.",
  ["27:4d92"] = "MUU-MUU: ¡Muu!",
  ["1c:69d8"] = "No tienes espacio\nsuficiente.",
  ["27:4da2"] = "¿Dar una BAYA a\nMUU-MUU?",
  ["1c:69f2"] = "¡Vuelve cuando\ntengas fichas!",
  ["27:4dbc"] = "{PLAYER} dio una\nBAYA a MUU-MUU.",
  ["1c:6a14"] = "¡Vaya! No tienes\nun MONEDERO.",
  ["1b:545c"] = "¡Uau! Eres muy\nfuerte.\012¡Qué lástima!\012Si te unieras al\nTEAM ROCKET,\012podrías llegar a\nser un EJECUTIVO.",
  ["6a:54d6"] = "¿Tienes una\nPOKéDEX?\012¡Uau, habrás visto\nPOKéMON muy\011raros!\012¿Puedo verla,\npor favor?",
  ["27:4dfc"] = "¡MUU-MUU está\nmucho mejor!",
  ["6a:5537"] = "RUTA 42\012CIUDAD IRIS -\nPUEBLO CAOBA",
  ["27:4e1b"] = "¡MUU-MUU se ha\nrecuperado!",
  ["6a:555f"] = "MONTE MORTERO\012CUEVA CASCADA\nInterior",
  ["27:4e3c"] = "{PLAYER} no tiene\nBAYAS…",
  ["6a:5580"] = "MONTE MORTERO\012CUEVA CASCADA\nInterior",
  ["27:4e4f"] = "{PLAYER} no le\nda una BAYA.\012MUU-MUU parece\ntriste.",
  ["6a:5793"] = "De acuerdo. ¡Te\nenseñaré el poder\012de los POKéMON\nde montaña!",
  ["27:4f38"] = "Mi MUU-MUU ya no\nme da leche.\012La leche de esta\nGRANJA es famosa.\012Casi todos\nquieren probarla.\012Supongo que si le\ndoy muchas BAYAS\012me dará mucha\nleche.",
  ["6a:57c6"] = "¡Me has demostrado\ntu poder!",
  ["27:4fe1"] = "¿Te gusta mi LECHE\nMU-MU?\012Es mi orgullo y mi\nalegría.\012¡Dásela a los\nPOKéMON para\011restaurar sus PS!\012Tuya es por sólo\n500¥.",
  ["6a:57e8"] = "Se acabó. Pero no\nme importa. \012Los MONTAÑEROS\nsomos así.",
  ["27:505d"] = "¡Toma! ¡Bébetela\ny disfruta!",
  ["6a:5819"] = "¡Yo también\nentreno POKéMON!\012¿Quieres luchar\ncontra mí?",
  ["27:507c"] = "Lo siento.\n¡Si no hay dinero,\011no hay trato!",
  ["61:4ef3"] = "¡Mi cerebro sí\nque es brillante!",
  ["27:509d"] = "Vaya, tu MOCHILA\nestá llena.",
  ["61:4f12"] = "¡Que haya luz\nen tus viajes!",
  ["27:50b7"] = "¿No la quieres?\nVuelve otro día.",
  ["61:4f37"] = "Es un bonito\ncuadro de un\011BELLSPROUT.",
  ["27:50dc"] = "Mejor que me vaya\na ordeñar.",
  ["61:4f61"] = "Estatua POKéMON…\012Parece muy\nilustre.",
  ["27:50f6"] = "Nuestra leche\nllega hasta KANTO.\012Así que si nuestra\nMUU-MUU no nos da\012leche, tendremos\nproblemas.",
  ["63:4a8b"] = "¿Eh? No tienes\nsitio para esto.\012Me vuelvo al\nGIMNASIO, así que\012haz hueco y ven a\nverme allí.",
  ["27:5156"] = "Has curado a\nnuestra MUU-MUU.\012Ya vuelve a dar\nLECHE MU-MU.\012Aquí tienes algo\nque te ayudará.",
  ["63:4af1"] = "",
  ["27:51c7"] = "Esto es\nRONQUIDO.\012Es un movimiento\nraro que sólo\012funciona cuando el\nPOKéMON duerme.\012Mejor que pienses\ncómo vas a\011utilizarlo.",
  ["63:4c2e"] = "SANTUARIO DRAGÓN\012Erigido en honor\nde los POKéMON\012dragón de la\nGUARIDA DRAGÓN",
  ["1b:5c09"] = "Sabía que\nperdería…",
  ["63:4c83"] = "…\n¿Qué? ¿{PLAYER}?\012No, no lucharé\ncontra ti…\012Mis POKéMON no\npueden ganarte.\012Y ahora no puedo\npresionarles.\012La disciplina es\nclave para ser el\012mejor entrenador\nPOKéMON.",
  ["1b:5c1a"] = "En mi última\nmisión también fui\012derrotado por\nun niño.\012Cuando estábamos\nsecuestrando unos\012POKéMON, un\nchico pelirrojo y\012de extraña mirada\nme machacó…",
  ["63:4d2d"] = "…\012¡Vaya…!\012Aprende a no\ncruzarte en\011mi camino.",
  ["27:541b"] = "{PLAYER} recibió\nun POKéMON.",
  ["63:4d53"] = "¡Tú! ¿Cómo te\natreves a entrar\012sin que te hayan\ninvitado?",
  ["27:542f"] = "No puedes llevar\nmás POKéMON.",
  ["63:4d77"] = "¡Qué fuerte!",
  ["27:5449"] = "¡Oh, no…!\n¿Y qué hago\011si vuelve?",
  ["63:4d82"] = "El SANTUARIO de\nahí delante es el\012hogar del MAESTRO\ndel clan de los\011dragones.\012¡No te está\npermitido pasar!",
  ["27:5470"] = "¡Hola! ¿Cómo está\nmi POKéMON?\012Creo que ya\npasó el peligro.\011¿Me lo devuelves?",
  ["63:4de4"] = "¡No deberías estar\naquí!",
  ["27:54b1"] = "¡Gracias!",
  ["63:4dfe"] = "¡Oh, maldición!\n¡Perdí!",
  ["27:54bd"] = "¡Oye! ¡No llevas\na mi POKéMON\011contigo!",
  ["63:4e11"] = "Pronto conseguiré\nel permiso del\012MAESTRO para poder\nusar dragones.\012Cuando lo tenga,\nseré una admirable\012entrenadora de\ndragones y ganaré\012la aprobación del\nMAESTRO.",
  ["27:54e3"] = "Mi POKéMON te\nha tomado cariño.\012¡Vale! ¡Quédatelo,\npero prométeme\012que serás bueno\ncon él!",
  ["63:4eab"] = "Es alguien que no\nconocemos.",
  ["27:553f"] = "¡Oh, no, no…!\nEs como si me\011hubieran robado.",
  ["63:4ec9"] = "Ayyyy…",
  ["61:5d9b"] = "¡Bah!\012¡Por eso no me\ngusta luchar\012contra memos!\n¡Son tan malos!",
  ["63:4ed3"] = "Fue como tener que\nluchar con LANCE.",
  ["61:5de2"] = "¡Que más da!\012Jamás podrías\natrapar un\012POKéMON\nlegendario.",
  ["63:4ef8"] = "¿Quién eres tú?",
  ["61:5e2c"] = "¡Bah!\012¡Por eso no me\ngusta luchar\012contra memos! ¡Qué\npérdida de tiempo!",
  ["63:4f06"] = "Qué cutre.",
  ["61:5e75"] = "¡Bah!\012¿Qué haces\ncayéndote por un\012agujero? ¿No ibas\nde inteligente?\012¡Te está bien\nempleado!",
  ["63:4f0f"] = "Te lo avisamos.\012El MAESTRO se\nenfadará contigo.",
  ["61:5ecc"] = "EUSINE: Me llamo\nEUSINE.\012Estoy tras la\npista de un\012POKéMON llamado\nSUICUNE.\012¿Y tú eres…?\012¿{PLAYER}?\n¡Encantado\011de conocerte!\012He oído rumores de\nque SUICUNE está\012en TORRE QUEMADA,\nasí que he venido\011a mirar.\012¿Pero dónde puede\nestar exactamente?",
  ["63:4f41"] = "{PLAYER} encontró\n{STRBUF}.",
  ["61:5f99"] = "EUSINE: He oído\nrumores de que\012SUICUNE está en\nTORRE QUEMADA, así\012que he venido a\nmirar.\012¿Pero dónde puede\nestar exactamente?",
  ["6b:4583"] = "Luchar es lo\nprimero que hacen\012los entrenadores\nsi se encuentran.",
  ["61:6002"] = "MORTI: El LÍDER de\nGIMNASIO de CIUDAD\012IRIS tenía que\nestudiar lo que se\012dice de los\nPOKéMON legenda-\011rios: SUICUNE,\011ENTEI y RAIKOU.\012EUSINE está aquí,\nasí que he decidi-\011do investigar\011la TORRE con él.",
  ["6b:45b7"] = "Tengo el récord de\ncombates perdidos.",
  ["61:626a"] = "EUSINE: También\nexcavé un hoyo\011aquí…\012¡Me quedé\nimpresionado!\012¡SUICUNE salió\ncorriendo como un\012rayo, ante mis\npropios ojos!\012Tras diez años de\nperseguir a\012SUICUNE, por fin\nhe podido verle.\012¡Estaba alucinado!\012¡{PLAYER}, todo\nte lo debo a ti!\012¡Gracias!\012He oído que los\nPOKéMON legenda-\011rios de CIUDAD\011IRIS probaron a\012ciertos humanos\npermitiéndoles\011acercarse.\012Voy a seguir a\nSUICUNE.\012¡{PLAYER}, nos\nveremos de nuevo!\012¡Adiós!",
  ["6b:45d7"] = "Es obvio que los\nentrenadores\012luchemos cuando\nnos encontremos.",
  ["62:4005"] = "¿Coleccionas las\nMEDALLAS DE KANTO?",
  ["6b:4615"] = "¡Estás ahí!\n¿Quieres luchar?",
  ["62:405a"] = "Dicen que hay\nun tipo sospechoso\011merodeando.\012Si resulta ser\nel ladrón, le\011detendré.",
  ["6b:4631"] = "He perdido…",
  ["62:40c3"] = "Ya nos atracaron\nantes.",
  ["6b:4640"] = "Eres fuerte.\012Seguro que te has\nentrenado mucho.",
  ["62:40e7"] = "DIGLETT: Dig, dig.",
  ["6b:4675"] = "RUTA 1\012PUEBLO PALETA -\nCIUDAD VERDE",
  ["62:414d"] = "Mi marido vive\nfeliz con los\012POKéMON que ha\nintercambiado.",
  ["6b:46e7"] = "Yo también entreno\nPOKéMON. Son\012mis guardaespaldas\npersonales.",
  ["62:418a"] = "Soy tan feliz…",
  ["6b:4720"] = "¡La tecnología es\nincreíble!\012Ahora puedes\ncambiar POKéMON\012con el pasado,\ncomo un e-mail.",
  ["62:419c"] = "KANGASKHAN: Kangas\nkangas.",
  ["6b:476b"] = "PUEBLO PALETA\012Un tranquilo lugar\nde paz y pureza",
  ["62:41b5"] = "ZUBAT: Zuba zubaa.",
  ["6b:479d"] = "CASA DE ROJO",
  ["62:4221"] = "En los combates yo\nprefiero usar\012POKéMON que he\nentrenado, aunque\012sean más débiles\nque los POKéMON\011recién capturados.",
  ["6b:47aa"] = "LABORATORIO DE\nINVESTIGACIÓN\011POKéMON DE OAK",
  ["62:428c"] = "¿Combates por\nteléfono móvil?\012Si el tiempo se\nacaba durante la\012lucha, la espera\npara ver al\012ganador es\ndesesperante.",
  ["6b:47c1"] = "CASA DE AZUL",
  ["62:42ff"] = "El MAGNETOTRÉN\nviaja a unos\n550 Km/h. Puede\nllevarte de\012KANTO a JOHTO en\npocos segundos.\012Hace que sea muy\nfácil ir a JOHTO.",
  ["6b:4850"] = "Tierra a la vista.\n¡Sigamos adelante!",
  ["62:44fb"] = "¡Uups! ¡Yo sentir!\nTú no hacer daño,\011¿de acuerdo?\012Yo muy ocupado.\nNo tener tiempo\012para hablar\ncontigo. No poder\011verme nadie.",
  ["6b:486c"] = "¡Glup…!",
  ["62:4574"] = "¡Oh, no! ¡Tú\nverme! ¡Yo cometer\011gran error!",
  ["6b:4873"] = "Ese chico tan\narrogante estaba\012en el volcán de\nISLA CANELA.",
  ["62:45a5"] = "¡Oye! Tú olvidar\nque me has visto,\012¿vale? Tú ver, oír\ny saber nada, ¿de\012acuerdo?\n¡Adiós, chico!\012¡Hasta la vista!",
  ["6b:48a0"] = "¡Si gano, tienes\nque ayudarme con\011la loción solar!",
  ["62:4610"] = "Lo siento, estaré\nfuera un tiempo.\012MISTY, LÍDER del\nGIMNASIO",
  ["6b:48d6"] = "No quiero\nquemarme…",
  ["62:4642"] = "Como MISTY ha\nsalido, nosotros\012tampoco estaremos.\nLos ENTRENADORES",
  ["6b:48f1"] = "Debería tener\ncuidado con las\012manchas causadas\npor el sol.",
  ["62:4674"] = "MISTY: Te estaba\nesperando,\011pesado.\012Puede que tengas\nmuchas MEDALLAS de\012JOHTO, pero será\nmejor que me tomes\011en serio.\012¡Mis POKéMON de\nagua son fuertes!",
  ["6b:4927"] = "Estoy aburrido de\npescar. ¡Luchemos!",
  ["62:470c"] = "MISTY: Eres\nrealmente bueno…\012Reconozco que eres\nun experto…\012Aquí tienes la\nMEDALLA CASCADA.",
  ["6b:494c"] = "Un fracaso…",
  ["62:4768"] = "{PLAYER} recibió\nMEDALLA CASCADA.",
  ["6b:495c"] = "Seguiré\npescando…",
  ["62:4782"] = "MISTY: ¿Hay muchos\nentrenadores\012fuertes en JOHTO?\nComo tú, digo.\012Un día viajaré y\nlucharé contra\012entrenadores\nexpertos.",
  ["6b:49d2"] = "¿Quién eres tú?\012Es evidente\nque eres un\011entrenador…\012Me llamo AZUL.\012Y una vez fui el\nCAMPEÓN, pero sólo\012durante poco\ntiempo…\012El entrometido de\nROJO me ganó…\012¡Pero qué más da!\n¿Y tú qué quieres?\012¿Has venido a\ndesafiarme?\012Lo siento, pero\nno, ahora no\012tengo ganas\nde luchar.\012Echa un vistazo a\ntu alrededor…\012Un volcán entra\nen erupción y una\012ciudad entera\ndesaparece.\012En POKéMON se\npuede ganar y\012perder, pero si\nse tuercen las\012cosas, se puede\nperder enseguida.\012…\012Así son las\ncosas…\012Sin embargo, sigo\nsiendo entrenador.\012Y encontrarme con\nun rival fuerte me\011anima a luchar.\012Si quieres luchar\ncontra mí, ven\012al GIMNASIO de\nla CIUDAD VERDE.\012Y aceptaré\ntu desafío…",
  ["62:480a"] = "Siento haber\nestado fuera.\011¡A lo nuestro!",
  ["6b:4c73"] = "Aquí hay una\nnota…\012El GIMNASIO DE\nISLA CANELA se ha\012trasladado a ISLAS\nESPUMA.\012BLAINE",
  ["62:4838"] = "¡Me rindo! ¡Has\nganado!",
  ["6b:4cc2"] = "ISLA CANELA\012La abrasadora isla\ndel ardiente deseo",
  ["62:4856"] = "Estaré nadando\ntranquilamente.",
  ["6b:4d68"] = "Me siento más\nligera en el agua.",
  ["62:4870"] = "No te desanimes\npor mi elegante\011forma de nadar.",
  ["6b:4d8a"] = "¡Oh, no!",
  ["62:489f"] = "¡Ooh! Has acabado\nconmigo…",
  ["6b:4d93"] = "La natación\nfortalece todo el\012cuerpo. ¡Es muy\nbuena!",
  ["62:48c0"] = "No fardes tanto de\nhaberme vencido.\012MISTY acabará\ncontigo si te\011confías demasiado.",
  ["6b:4dd0"] = "¡Vaya colección\nde MEDALLAS\012de GIMNASIO!\n¡Luchemos!",
  ["62:4912"] = "¡Glup…!\012¡Soy el primero!\n¡Ven a por mí!",
  ["6b:4e10"] = "¡No!",
  ["62:4934"] = "No puede ser…",
  ["6b:4e15"] = "SURF ya no es el\núnico movimiento\012que se utiliza\nen el agua.",
  ["62:4943"] = "MISTY ha mejorado\nmucho en los\011últimos años.\012¡No bajes la\nguardia o acabarás\011machacado!",
  ["6b:4e4b"] = "Supongo que es\nimposible ir\012nadando hasta\nJOHTO.",
  ["62:49a7"] = "¡Hola, futuro\nCAMPEÓN!\012Como MISTY no\nestaba, salí\012a divertirme un\nrato. ¡Je, je, je!",
  ["6b:4e83"] = "¡Aiyaa!",
  ["62:49fa"] = "¡Uauu! ¡Qué\nfuerte eres!\012¡Como siempre, ha\nsido un combate\011realmente bueno!",
  ["6b:4e8b"] = "Además de nadar\nen el mar, puedo\012nadar en estanques\ny ríos.",
  ["62:4acd"] = "Encontrarás muchos\nentrenadores de\012camino hacia\nCABO CELESTE.\012Quieren saber cómo\nson en comparación\012con otros\nentrenadores.",
  ["6b:4ec2"] = "¿Qué pone en\neste letrero?\012LÍDER del GIMNASIO\nde ISLA CANELA:\011BLAINE",
  ["62:4b46"] = "MISTY es casi la\núnica persona de\012la ciudad capaz de\nvencer a los\012ENTRENADORES de\nCABO CELESTE.",
  ["6b:4f5c"] = "Si estás buscando\nPOKéMON, mira\012en las zonas de\nhierba alta.",
  ["62:4bf1"] = "¿Un CENTRO POKéMON\njunto a una cueva?\012¡Qué bien!\n",
  ["6a:55a1"] = "RUTA 42\012CIUDAD IRIS -\nPUEBLO CAOBA",
  ["62:4c26"] = "El DIRECTOR de la\nC. ENERGÍA busca\012a un entrenador\nPOKéMON fuerte.\012Necesita ayuda\npara recuperar\012algo que le\nrobaron.",
  ["6b:4fa5"] = "Siendo tan fuerte,\ndebe de ser muy\011divertido luchar.",
  ["62:4c9e"] = "Dicen que el TEAM\nROCKET se reunió\012en JOHTO, pero se\nvolvió a separar.\012No tenía ni idea\nde eso.",
  ["6b:4fd7"] = "El CAMINO BICIS es\nun atajo a CIUDAD\011AZULONA.",
  ["62:4d0c"] = "Cuando salgas,\nverás el tejado\012de un edificio\nmuy grande.\012Eso es la CENTRAL\nde ENERGÍA.",
  ["63:604d"] = "Aquí no hay SÚPER\nBALL. Tendrás que\012conformarte con\nlas POKé BALL.\012¡Ojalá me pudiera\nfabricar CÉSAR\011alguna BALL!",
  ["62:4ee0"] = "Entró un ladrón en\nla C. ENERGÍA…\012¿Adónde vamos a\nir a parar?",
  ["63:60b6"] = "Mejor una SÚPER\nBALL para capturar\012POKéMON que una\nPOKé BALL.\012Pero a veces,\nlas de CÉSAR\011son mejores.",
  ["62:4f22"] = "Tengo noticias de\nCIUDAD CELESTE.\012Parece que ha\nestado merodeando\012por allí un hombre\nmuy sospechoso.",
  ["63:6473"] = "¿Quién eres?\012{PLAYER},\n¿quieres que haga\011alguna BALL?\012Lo siento, pero\ndeberás esperar.\012¿Conoces al TEAM\nROCKET? ¡Bah!\012No importa. Yo\nte lo contaré.\012Se trata de una\nbanda malvada que\012usa POKéMON para\nel trabajo sucio.\012Se supone que se\ndisolvieron hace\011tres años.\012¡Pero están en el\nPOZO cortando\012COLAS de SLOWPOKE\npara venderlas!\012¡Así que voy a\nir allí a darles\011una lección!\012¡Resistid,\nSLOWPOKE!\011¡CÉSAR os ayudará!",
  ["62:4f7f"] = "¿Puedo pedirte\nayuda?",
  ["63:6615"] = "CÉSAR: ¡{PLAYER}!\012Te has portado\ncomo un auténtico\011héroe en el POZO.\012¡Tienes estilo!\012Sería un honor\nhacer alguna BALL\012para un entrenador\ncomo tú.\012Ahora sólo tengo\nésta. Tuya es.",
  ["62:4fa2"] = "Tendremos que\nreforzar nuestra\011seguridad.",
  ["63:66c9"] = "CÉSAR: Fabrico\nlas BALL de\011los BONGURI.\012Recógelos de\nlos árboles\011y traémelos.\012Los usaré para\nhacer las BALL.",
  ["62:4fcf"] = "Alguien ha robado\nuna pieza que\012necesitamos para\nel generador.\012¡Sin ella, el\nnuevo generador no\011sirve para nada!",
  ["63:6736"] = "CÉSAR: ¿Tienes\nun BONGURI?\012¡Vale! Te haré\nuna BALL.",
  ["62:5038"] = "El generador ya\nfunciona y está\012generando mucha\nelectricidad.",
  ["63:6779"] = "CÉSAR: Tardaré un\ndía en fabricar\012una BALL. Vuelve\nmañana a por ella.",
  ["62:5079"] = "Esta CENTRAL de\nENERGÍA había\012sido abandonada\nhace mucho tiempo.\012Volvimos a ponerla\nen funcionamiento\012para poder usar\nel MAGNETOTRÉN.",
  ["63:67bc"] = "CÉSAR: ¡Oh…!\n¡Qué decepción!",
  ["62:50ef"] = "¡El generador\nya funciona!",
  ["63:67d8"] = "CÉSAR: ¡Estoy\ntrabajando! ¡Vete!",
  ["62:510e"] = "El DIRECTOR de la\nCENTRAL ENERGÍA\011está ahí delante.\012Pero está triste y\nenfadado porque\012alguien ha\nestropeado el\011generador…",
  ["63:67fb"] = "CÉSAR: ¡{PLAYER}!\nAcabo de terminar\011tu BALL. Tuya es.",
  ["62:517f"] = "El DIRECTOR está\ncontento porque\012el generador ya\nestá arreglado.",
  ["63:682a"] = "CÉSAR: Ha salido\nmuy bien.\012Intenta capturar\nPOKéMON con ella.",
  ["62:51c2"] = "El MAGNETOTRÉN\nconsume mucha\011electricidad.\012No se puede mover\nsi el nuevo\012generador no\nfunciona.",
  ["63:6863"] = "CÉSAR: Ahora que\nmi nieta me ayuda,\012puedo trabajar\nmucho más rápido.",
  ["62:5225"] = "¡Muy bien!\nEl MAGNETOTRÉN\012puede volver a\nfuncionar.",
  ["63:68ab"] = "",
  ["62:5264"] = "DIRECTOR: ¡Me voy\na enfadar con\011alguien!\012¿Quién ha roto mi\ngenerador?\012¡Con el tiempo que\nle he dedicado!\012¡Como lo atrape,\nva a saber lo\012que es mi\nELECTROCAÑÓN!",
  ["63:6934"] = "Estoy viéndolo.",
  ["62:5308"] = "DIRECTOR: ¡Nunca\nle perdonaré!\012Aunque el culpable\nllore y suplique\012perdón, ¡le\nmachacaré!\012¡Ja, ja, ja!",
  ["63:6949"] = "¡Ajá! ¡Ya veo!\nEntonces…",
  ["62:536e"] = "DIRECTOR: ¡Sí!\012¡Ésa es la pieza\nque le faltaba a\012mi generador! ¿La\nencontraste tú?",
  ["63:695c"] = "¡{PLAYER}!\012Esta BALL comenzó\na agitarse cuando\011la examinaba.\012¡Tiene que haber\nalgo!",
  ["62:53c4"] = "¡Yuju! ¡Gracias!\012¡Toma esta MT\ncomo recompensa!",
  ["63:69b5"] = "Los SLOWPOKE se\nhan ido…\012¿Se los ha llevado\nla gente mala?",
  ["62:53f4"] = "DIRECTOR: La MT07\nes mi ELECTRO-\012CAÑÓN. ¡Es muy\npotente!\012Aunque presenta\nel inconveniente\012de no ser muy\nprecisa.",
  ["63:69f1"] = "El abuelo se fue.\nEstoy tan sola…",
  ["62:5475"] = "DIRECTOR: ¡Mi\nquerido generador!\012¡Sigue generando\nelectricidad!",
  ["63:6a0f"] = "¡El SLOWPOKE que\nme regaló mi padre\011ha vuelto!\012¡Y su COLA vuelve\na crecer!",
  ["62:56ce"] = "¿Conoces a BILL?\nEs mi nieto.\012Está en JOHTO\ntrabajando con\012los PC. Yo le\ncuido la casa.",
  ["63:6a55"] = "Papá trabaja en\nSILPH y estudia\011las POKé BALL.\012Tengo que quedarme\nen casa con el\011abuelo y SLOWPOKE.",
  ["6a:5e99"] = "CASA DE ENTRENADOR\012Club de Mejores\nEntrenadores",
  ["63:6ab2"] = "¡Estoy ayudando al\nabuelo!\012¡Haremos buenas\nBALL para ti, así\011que espera!",
  ["6a:5f7d"] = "Este POLIWRATH es\nmi compañero.\012Me pregunto si\nalgún día\012evolucionará en\nuna rana POKéMON.",
  ["63:6afc"] = "¡Hacer BALL es\ndivertido!",
  ["6a:5fcb"] = "POLIWRATH: ¡Polii!",
  ["63:6b14"] = "El abuelo está\nexaminando una\011BALL.\012Estoy esperando\na que termine.",
  ["6a:5fde"] = "Volví a perder en\nlas tragaperras.\012Las chicas también\njugamos a las\012tragaperras.\nPrueba tú también.",
  ["63:6b56"] = "SLOWPOKE: ¡Mmm!\n(Bostezo).",
  ["6a:6043"] = "Últimamente han\naparecido GRIMER.\012¿Ves esa charca\nque hay delante de\012la casa? Ahí\nviven GRIMER.\012¿De dónde han\nvenido? Es un\011grave problema…",
  ["63:6b69"] = "¿Un joven\nPROF. OAK?",
  ["6a:60dc"] = "¡Bravo! ¡Este\nGIMNASIO es\012genial! ¡Es sólo\npara chicas!",
  ["63:6b7e"] = "Es una estatua\ndel guardián\011del encinar.",
  ["6a:6115"] = "¿Te cuento\nun secreto?\012La MANSIÓN AZULONA\ntiene una puerta\011trasera secreta.",
  ["63:6d0b"] = "¡Soy ANTÓN!\nSoy invencible\012con los\nPOKéMON bicho.\012¡Mis estudios me\nvan a convertir en\012una autoridad de\nlos POKéMON bicho!\012Te enseñaré lo\nque he aprendido.",
  ["64:7591"] = "Estableciendo\nconexión…",
  ["63:6dae"] = "¡Uauu, increíble!\n¡Eres un experto\011en POKéMON!\012Mi investigación\naún no ha acabado.\012Vale, tú ganas.\nToma esta MEDALLA.",
  ["64:7626"] = "Estableciendo\nconexión…",
  ["63:6e14"] = "{PLAYER}\nrecibió la\011MEDALLA COLMENA.",
  ["6a:6306"] = "Me he mareado de\nir mirando al\012suelo mientras\ncaminaba.",
  ["63:6e2b"] = "¿Conoces las\nventajas de la\011MEDALLA COLMENA?\012Si la tienes, los\nPOKéMON hasta N.30\011te obedecerán.\012Y los POKéMON\nque sepan CORTE\012podrán usarlo\nfuera del combate.\012Mira, también te\ndaré esto.",
  ["6a:6340"] = "CIUDAD AZULONA\012La ciudad de los\nsueños de arcoiris",
  ["63:6efa"] = "MT49 contiene\nCORTEFURIA.\012Si no fallas, se\nhace cada vez\011más fuerte.\012Cuanto más dure\nel combate, más\011fuerte será.\012¿No es genial?\n¡Lo descubrí yo!",
  ["6a:6369"] = "LÍDER DEL GIMNASIO\nPOKéMON DE\012CIUDAD AZULONA:\nERIKA\012La princesa amante\nde la naturaleza",
  ["63:6f98"] = "Los POKéMON bicho\nson muy complejos.\012Quedan muchos\nmisterios por\011resolver.\012Estudia a fondo\ntus favoritos.",
  ["6a:63a9"] = "¡Encuentra lo que\nnecesitas en el\012CENTRO COMERCIAL\nDE CIUDAD AZULONA!",
  ["63:6ff8"] = "Los POKéMON bicho\nevolucionan pronto\012y se hacen fuertes\nmucho antes.",
  ["6a:63d4"] = "MANSIÓN AZULONA",
  ["63:7037"] = "¡No se trata sólo\nde evolucionar!",
  ["6a:63e5"] = "CASINO DE CIUDAD\nAZULONA: Zona de\011juego para todos",
  ["63:7053"] = "Los POKéMON se\nhacen más fuertes\011si evolucionan.",
  ["6a:6418"] = "PISTAS ENTRENADOR\012PROTEC. ESP\nprotege a los\012POKéMON de\nataques ESPECIALES\011como fuego y agua.\012¡Consigue los\nobjetos en el\012CENTRO COMERCIAL\nde CIUDAD AZULONA!",
  ["63:7081"] = "¡Los POKéMON bicho\nson buenos y muy\012fuertes! ¡Te lo\ndemostraré!",
  ["6a:65e6"] = "¿Has olvidado\nalgo?",
  ["63:70b4"] = "Has demostrado lo\nfuerte que eres…",
  ["6a:6604"] = "¡Kiaaa!",
  ["63:70d3"] = "Son geniales,\npero la mayoría de\012las chicas odian\nlos POKéMON bicho.\012No sé por qué…",
  ["6a:660d"] = "Antes de ser\nmaestra, solía\012olvidarme de\nmuchas cosas.",
  ["63:7118"] = "¿Has salvado a los\nSLOWPOKE? ¡Uauu!\011¡Eres muy fuerte!\012¡Pero mis\nPOKéMON\012entrenados también\nson muy fuertes!",
  ["6a:664b"] = "Creo que si hace\nsol, los niños\012deberían estar\njugando en el\012patio en lugar\nde estar en clase.",
  ["63:7174"] = "¡Urrggg!",
  ["6a:66b3"] = "No quería\nperder…",
  ["63:717e"] = "Supongo que\ndebería enseñarles\011mejores ataques…",
  ["6a:66ca"] = "Es importante\nestudiar, pero\012hacer deporte\ntambién.",
  ["63:71a9"] = "AMY: ¿Vas a\ndesafiar al LÍDER?\011¡Ni lo sueñes!",
  ["6a:6703"] = "Espera. Tengo que\nllamar a mamá.",
  ["63:71db"] = "AMY-MAY: ¡Oh,\ndoble bondad!",
  ["6a:6725"] = "¡Lo siento, mamá!\n¡Me han vencido!",
  ["63:71fc"] = "AMY: ¡Eres\nmuy fuerte!",
  ["6a:6740"] = "Mi madre se\npreocupa mucho por\012mí, tengo que\nllamarla siempre.",
  ["63:7217"] = "MAY: ¿Quieres ver\nal LÍDER?\012¡Pues nosotras\nvamos primero!",
  ["6a:6784"] = "Luchemos.\n¡No perderé!",
  ["63:7248"] = "AMY-MAY: ¡Oh,\ndoble bondad!",
  ["63:7269"] = "MAY: Han perdido\nnuestros POKéMON.\011¡Qué lástima!",
  ["65:482d"] = "Toma. Coge\nesto.",
  ["63:7296"] = "¡Hola, valiente!\012ANTÓN es joven,\npero conoce muy\012bien a los POKéMON\nbicho.\012Y sin mis consejos\nte resultaría aún\011más duro.\012Veamos… A los\nPOKéMON bicho no\011les va el fuego.\012Y los ataques de\ntipo volador son\011muy efectivos.",
  ["65:4847"] = "JOSUÉ: Debería\nusarlo un POKéMON\012con habilidades\nde tipo roca.\012Mejora los ataques\nde tipo roca.",
  ["63:7359"] = "¡Eso es! Ha sido\nun gran encuentro\012entre jóvenes\ncon talento.\012Con gente como tú,\n¡el futuro de los\012POKéMON será\nmaravilloso!",
  ["65:48aa"] = "JOSUÉ: Soy JOSUÉ,\npor jueves. Soy\012el segundo de\nsiete hermanos.",
  ["64:40b0"] = "¿Qué tal, joven?\012Veo que no eres de\nCIUDAD CAOBA.\012¡Por no ser de\naquí, deberías\012probar el CARAMELO\nFURIA!\012¡Puede ser tuyo\npor sólo 300¥!\011¿Quieres uno?",
  ["65:48f3"] = "JOSUÉ: Hoy no\nes jueves. ¡Qué\011desilusión!",
  ["64:414a"] = "¡Bien! ¡Saboréalo!",
  ["65:4924"] = "RUTA 36",
  ["64:415b"] = "No tienes\nbastante dinero.",
  ["65:492e"] = "RUINAS ALFA\nENTRADA NORTE",
  ["64:4178"] = "¡Oh, de acuerdo…!",
  ["65:494c"] = "PISTAS ENTRENADOR\012Las habilidades de\nlos POKéMON varían\012incluso dentro de\nuna misma especie.\012Al principio, sus\nhabilidades pueden\011parecerse.\012Sin embargo, las\ndiferencias surgen\012a medida que el\nPOKéMON crece.",
  ["64:4188"] = "No tienes\nespacio para esto.",
  ["65:49ee"] = "PISTAS ENTRENADOR\012Usa EXCAVAR para\nvolver a la\011entrada.\012Es útil para\nexplorar cuevas\012y otros\nlugares.",
  ["64:41a6"] = "CARAMELOS FURIA\nagotados.\012Estoy haciendo las\nmaletas. No me\011molestes, joven.",
  ["65:4b45"] = "Un miembro del\nALTO MANDO era el\012LÍDER del GIMNASIO\nde CIUDAD FUCSIA.",
  ["64:41e5"] = "¿Vas al LAGO a ver\na los violentos\011GYARADOS?",
  ["65:4b83"] = "La hija de KOGA le\nha sucedido como\012LÍDER del GIMNASIO\ncuando él se unió\011al ALTO MANDO.",
  ["64:421d"] = "MAGIKARP ha\nvuelto al LAGO\011DE LA FURIA.\012Son buenas\nnoticias para\011los pescadores.",
  ["65:4bd3"] = "La ZONA SAFARI\nestá cerrada. Da\012pena, ya que es\nla mayor atracción\011de CIUDAD FUCSIA.",
  ["64:4276"] = "Has venido de muy\nlejos. Tómate\012tiempo para ver\nel paisaje.\012Deberías ir hacia\nel Norte y ver lo\012que pasa en el\nLAGO DE LA FURIA.",
  ["65:4c22"] = "CIUDAD FUCSIA\012¡Mirad la CIUDAD\nFUCSIA! ¡La pasión\011rosa!",
  ["64:42f2"] = "Visita la tienda\nde la Abuela. Hay\012cosas que sólo\nella tiene.",
  ["65:4c4a"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\011FUCSIA: SACHIKO\012La venenosa\nmaestra ninja.",
  ["64:432e"] = "PUEBLO CAOBA\012Bienvenido al\nhogar de los Ninja",
  ["65:4c8b"] = "Aquí hay una\nnota…\012El PUESTO GUARDA\nDE LA ZONA SAFARI\012está cerrado hasta\nnuevo aviso.",
  ["64:435e"] = "¡Si visitas PUEBLO\nCAOBA, prueba un\011CARAMELO FURIA!",
  ["65:4cd5"] = "CASA DEL GUARDA\nDE LA ZONA SAFARI",
  ["64:4391"] = "LÍDER DEL GIMNASIO\nPOKéMON DE PUEBLO\011CAOBA: FREDO\012El maestro del\ncrudo invierno",
  ["65:4cf0"] = "El GUARDA está\nde viaje. Ésa es\012la razón por la\nque la ZONA SAFARI\011está cerrada.",
  ["64:4790"] = "¡Espera!\n¿Por qué corres?",
  ["65:4d37"] = "No ensuciar.\012Por favor, no\ntirar basura.",
  ["6a:6c2b"] = "¿Has conseguido ya\nalguna MEDALLA de\011GIMNASIO de KANTO?\012¿A que los\nentrenadores\012de KANTO son\nmuy fuertes?",
  ["65:4efa"] = "Soy DÉBORA.\012Soy la mejor\nmaestra dragón del\011mundo.\012Puedo enfrentarme\nincluso al ALTO\012MANDO de la LIGA\nPOKéMON.\012¿Todavía quieres\nenfrentarte a mí?\012Bien…\n¡Adelante!\012¡Como LÍDER de\nGIMNASIO, usaré\012toda mi fuerza\ncontra mi\011oponente!",
  ["6a:6c88"] = "Supongo que pronto\nhabrás conseguido\012todas las MEDALLAS\nde KANTO.\012Cuando tengas\nlas ocho MEDALLAS,\011dímelo.",
  ["65:4fd6"] = "¿He perdido?\012No puedo creerlo.\nHa debido de haber\011algún error…",
  ["6a:6cf3"] = "¡Enhorabuena!\012Tienes todas las\nMEDALLAS de KANTO.\012Te recompensaré\npor tu esfuerzo.",
  ["65:500e"] = "Me niego a\naceptarlo.\012He podido perder,\npero todavía no\012podrás con la LIGA\nPOKéMON.\012Ya sé. Deberías\nenfrentarte al\011desafío dragón.\012Tras este GIMNASIO\nexiste un lugar\012llamado GUARIDA\nDRAGÓN.\012Hay un pequeño\nsantuario en su\012centro.\nVe allí.\012¡Si pruebas tu\nvalía, reconoceré\012que te mereces la\nMEDALLA del\011GIMNASIO!",
  ["6a:6d4a"] = "Llevar distintos\ntipos de POKéMON\012te debería ayudar\nen el combate.\012Seguro que las\nMEDALLAS de KANTO\011te ayudarán.",
  ["65:5162"] = "¿Qué pasa?\012¿Es demasiado\npara ti?",
  ["6a:6db9"] = "CIUDAD CARMÍN\012El puerto de los\nocasos exquisitos",
  ["65:5196"] = "¡Me has hecho\nesperar!\012¡Ven! ¡Coge esto!",
  ["6a:6de7"] = "LÍDER DEL GIMNASIO\nPOKéMON DE LA\012CIUDAD CARMÍN:\nLT. SURGE\012El Rayo\nAmericano",
  ["65:51bf"] = "{PLAYER} recibió\nMT24.",
  ["65:51d1"] = "Esta MT contiene\nDRAGOALIENTO.\012No, no tiene\nnada que ver\011con mi aliento.\012Si no la quieres,\nno es necesario\011que la aceptes.",
  ["65:524f"] = "¿Qué pasa? ¿No te\nqueda espacio?",
  ["6a:6e4e"] = "CUEVA DIGLETT",
  ["65:5272"] = "",
  ["6a:6e5e"] = "ENTRADA AL PUERTO\nCARMÍN",
  ["65:5396"] = "¿Tu primer combate\ncontra dragones?\012¡Te mostraré lo\nfuertes que son!",
  ["6a:6fa5"] = "He venido a\nexplorar el\011TÚNEL ROCA.",
  ["65:53db"] = "¿Han perdido mis\nPOKéMON dragón?",
  ["6a:6fc5"] = "¡Uau! Peligro.",
  ["65:53f1"] = "¿LANCE te dijo que\nquería verte de\012nuevo?\n¡Ni por asomo!",
  ["6a:6fd9"] = "Hirieron a mis\nPOKéMON antes\012de entrar al\nTÚNEL ROCA.\012Será mejor que los\nlleve ahora mismo\012a un CENTRO\nPOKéMON.",
  ["65:542f"] = "¿Mis posibilidades\nde perder? ¡Ni el\011uno por ciento!",
  ["6a:703f"] = "¿Has ido alguna\nvez de picnic?\012¡Es muy\ndivertido!",
  ["65:545b"] = "Es extraño.",
  ["6a:7074"] = "¡Ohhhh!",
  ["65:5467"] = "Ahora sé cuál es\nmi punto débil.\012¡Gracias por\nenseñármelo!",
  ["6a:707c"] = "Hacemos dulces y\nlos repartimos\012entre todos. ¡Son\ndeliciosos!",
  ["65:549d"] = "Los dragones son\nPOKéMON sagrados.\012Están llenos de\nenergía vital.\012Si no eres\nserio, no\012podrás acabar\ncon ellos.",
  ["6a:70c2"] = "¡Eh, tú!\n¡No tires basura!",
  ["65:550a"] = "¡Adelante!",
  ["6a:70da"] = "Sólo estaba\ndiciendo que…",
  ["65:5516"] = "Los dragones son\ndébiles contra los\012movimientos del\ntipo dragón.",
  ["6a:70f6"] = "Perdón. No estabas\ntirando basura. Me\011he equivocado.",
  ["65:5544"] = "¡Hola, futuro\ncampeón!\012¡Ha sido un largo\nviaje, pero casi\012hemos acabado!\n¡Confía en mí!\012DÉBORA usa los\nmíticos y sagrados\012POKéMON de tipo\ndragón.\012No son fáciles\nde dañar.\012Pero se supone\nque son débiles\012contra los ataques\ndel tipo hielo.",
  ["6a:7127"] = "La gente no\ndebería dejar la\011basura por ahí.",
  ["65:5632"] = "¡Genial! ¡Has\nvencido a DÉBORA!\012Sólo te queda el\ndesafío de la\011LIGA POKéMON.\012¡Vas a convertirte\nen el CAMPEÓN\011POKéMON!",
  ["6a:7151"] = "¡Ohh…! Perdí…",
  ["65:5789"] = "No todos nosotros\nusamos POKéMON\011del tipo dragón.",
  ["6a:715f"] = "Es importante\nahorrar energía,\012pues el entorno es\naún más vital.",
  ["65:57b6"] = "¡Maldición!\n¡Ojalá tuviera un\011dragón!",
  ["6a:71a8"] = "Ella se desviará\npor MT. PLATEADO\011cuando venga…\012MT. PLATEADO está\nen JOHTO, ¿verdad?",
  ["65:57d5"] = "Los miembros del\nclan de los drago-\011nes sólo pueden\011usar POKéMON del\012tipo dragón si el\nMAESTRO se lo\011permite.",
  ["6a:71f7"] = "Estaba ocupado\ncantando…",
  ["65:582b"] = "¡No puedo permitir\nque alguien como\011tú pase de aquí!\012¡DÉBORA se enfa-\ndará si te dejo!",
  ["6a:7210"] = "Los combates son\ncuestión de\011concentración.",
  ["65:5874"] = "Auuuu… Perdí…",
  ["6a:7232"] = "Te contaré un\nsecreto.\012Pero primero,\n¡luchemos!",
  ["65:5883"] = "Oh, oh… DÉBORA\nse va a enfadar…",
  ["6a:7260"] = "¡Caray!\nHe perdido…",
  ["1f:4842"] = "¿No?\n¡Qué lástima!",
  ["6a:7278"] = "La CENTRAL ENERGÍA\nestá al otro lado\011de un riachuelo.",
  ["1f:485b"] = "No te queda\nmucho dinero.",
  ["6a:72a2"] = "RUTA 9\012CIUDAD CELESTE -\nTÚNEL ROCA",
  ["1f:487b"] = "Sólo corto el pelo\nuna vez al día.\012Perdona, pero hoy\nno trabajo más.",
  ["6a:7335"] = "Parece que BLAINE,\ndel GIMNASIO de\012ISLA CANELA, vive\nsolo en la cueva\011de ISLAS ESPUMA…",
  ["1f:48bf"] = "{STRBUF}\nparece un poco\011más feliz.",
  ["6a:737f"] = "El volcán hizo\nerupción hace\011un año.",
  ["1f:48dc"] = "{STRBUF}\nparece feliz.",
  ["6a:740a"] = "El volcán de ISLA\nCANELA ha entrado\011en erupción.\012Y ha lanzado rocas\nque han cortado la\012RUTA 19 hasta\nnuevo aviso.\012Me pregunto si la\ngente de ISLA\012CANELA estará\nbien…",
  ["1f:48ee"] = "¡{STRBUF}\nestá encantado!",
  ["6a:748a"] = "Nadie en ISLA\nCANELA resultó\012herido por la\nerupción. ¡Bien!",
  ["1f:4904"] = "Lo siento,\nhemos cerrado.",
  ["6a:7548"] = "BLAINE: ¡Buaaa!\012Mi GIMNASIO de\nISLA CANELA se ha\011quemado.\012El volcán nos ha\ndejado sin casa a\012mis POKéMON\ncomefuego y a mí.\012¡Buaaaa!\012Pero sigo haciendo\nmi trabajo de\012LÍDER de GIMNASIO\nen esta cueva.\012Si me vences,\nte daré una\011MEDALLA.\012¡Ja! Espero que\ntengas ANTIQUEMAR.",
  ["1f:491a"] = "PROHIBIDO PASAR\nDE ESTE PUNTO",
  ["6a:7646"] = "BLAINE: Increíble.\nMe consumí…\012¡Has ganado la\nMEDALLA VOLCÁN!",
  ["1f:4e9d"] = "¡Alto ahí!\012Te he visto y te\nhe seguido.\012No quiero verte\ncerca mientras\012me ocupo del TEAM\nROCKET.\012Espera un segundo.\nMe venciste antes,\011¿verdad?\012¡Tuviste mucha\nsuerte!\012¡Pero yo pago\nmis deudas!",
  ["6a:7683"] = "{PLAYER} recibió\nla MED. VOLCÁN.",
  ["1f:4f5d"] = "¿Por qué? ¿Cómo\nhe podido perder?\012He usado a mis\nmejores POKéMON.\012No he bajado la\nguardia.\012¿Cómo he perdido?",
  ["6a:769d"] = "BLAINE: Esta vez\nhe perdido, pero\012la próxima te\nganaré.\012Cuando reconstruya\nmi GIMNASIO de I.\012CANELA, tendremos\nla revancha.",
  ["1f:4fc2"] = "No lo\nentiendo…\012¿Es verdad lo que\ndijo ese LANCE?\012¿Qué no cuido bien\na mis POKéMON?\012Amor…\012Confianza…\012¿Es eso lo que\nme falta?\012¿Es eso lo que me\nimpide ganar?\012Yo… No lo\nentiendo.\012Pero esto no\nacaba aquí.\012Ahora no. No por\nesta razón.\012¡No renunciaré a\nmi sueño de ser el\012mejor entrenador\nPOKéMON del mundo!",
  ["6a:771c"] = "BLAINE: Mis\nPOKéMON de fuego\012serán más fuertes.\n¡Ya lo verás!",
  ["1f:5102"] = "¡Bah! ¡Mira\nqué fuerte soy!\012Destruiré al\nTEAM ROCKET.\012Y machacaré a\nese tal LANCE.",
  ["6a:7759"] = "¡Vaya!\012¿Eh…?\n¿Ya ha acabado?\012¡Lo siento!\012El GIMNASIO de\nISLA CANELA ya no\012existe y no sabía\ndónde encontrarte.\012Pero eres fuerte\nhasta sin mis\012consejos. ¡Sabía\nque ganarías!",
  ["1f:5176"] = "Me desafiaron a\nun combate en el\011piso de abajo.\012Ahí abajo son muy\nduros. Mejor que\011tengas cuidado.",
  ["66:4fae"] = "INSPECTOR DE MOTES\012Evalúa los motes\nde tus POKéMON",
  ["1f:51d0"] = "Abajo hay algunas\ntiendas…\012Pero también hay\nentrenadores.\012Me da miedo\nbajar ahí.",
  ["66:4fee"] = "ENTRADA\nSUBTERRÁNEA",
  ["1f:522b"] = "Una puerta se abre\ny otra se cierra.\012¡Seguro que no\nconsigues llegar!",
  ["5d:64eb"] = "¡Escucha, escucha!\012¿Conoces la LECHE\nMU-MU?\012Puedes comprarla\nen la GRANJA\011MUU-MUU.\012Se supone que es\nbuena para la\012salud y el cutis.\nQuiero probarla.\012¡Seguro que es\ndeliciosa!",
  ["1f:526f"] = "¡Caramba! ¡Perdí\npor mi indecisión!",
  ["6a:4f65"] = "He perdido. ¡Qué\npena…!",
  ["1f:5290"] = "Tampoco lo sé…\nPrimero hay que\012pulsar el último\nbotón, pero…",
  ["6a:4f1b"] = "Los POKéMON no\npueden hacer nada\011dormidos.\012¡Yo te enseñaré el\nmiedo que da eso!",
  ["1f:52d8"] = "¡Ajajaja!\012¿Confundido con\ntanta llave?\012¡Te contaré un\nsecreto si logras\011vencerme!",
  ["6a:4eec"] = "ANY: Sentimos\nlo mismo que\011nuestros POKéMON.",
  ["1f:5335"] = "¡Ohhh…!\nFallé.",
  ["66:540d"] = "La COPIONA parecía\nmuy triste.\012Había perdido\nsu POKé MUÑECO\011CLEFAIRY favorito.",
  ["1f:5347"] = "Bien. ¡Una pista!\012Cambia el orden al\npulsar botones.\012Y cambiará la\nforma en que se\012abren y se cierran\nlas puertas.",
  ["66:5460"] = "¿Eres de\nJOHTO?\012Si funcionara el\nMAGNETOTRÉN, no\012tardarías nada en\nvolver a casa.",
  ["1f:53ae"] = "¡Paga tus\ndeudas!",
  ["66:54ae"] = "¿Eres de\nJOHTO?\012Con el MAGNETOTRÉN\nenseguida estarás\011en casa.",
  ["1f:53c7"] = "¡Misericordia!",
  ["66:54fe"] = "Iba al GIMNASIO\na luchar contra\011entrenadores…\012Y acabé en el\nviejo GIMNASIO\012que hay\nal lado.\012¡Chico, qué\nvergüenza pasé!",
  ["1f:53cf"] = "¡Robar y vender!\n¡La base de todo\011acto criminal!",
  ["6a:4e12"] = "ANA: ¡ANY y yo\nestamos en esto\011juntas!",
  ["1f:53fb"] = "Abandonaron este\nproyecto antes\011de terminarlo.\012Estoy buscando\nrestos.",
  ["6a:4c99"] = "HACIA LA TORRE\nBATALLA\011¡Ya hemos abierto!",
  ["1f:544c"] = "¡Por encima!",
  ["6a:4c60"] = "FARO DE OLIVO\nTambién conocido\012como el FARO\nBRILLANTE",
  ["1f:545b"] = "¿Al ALMACÉN\nSUBTERRÁNEO?\012¿Para qué quieres\nir ahí?\012Ahí abajo no\nhay nada.",
  ["6a:4c1d"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\011OLIVO: YASMINA\012La chica\nde acero",
  ["1f:54b2"] = "¡Qué me importa si\nte has perdido!\012Apareciste aquí,\n¡eres sólo una\011víctima!",
  ["6a:4c00"] = "PUERTO OLIVO\nMUELLE DEL FERRY",
  ["1f:54fc"] = "¡Seguro! Te crees\ngenial, ¿verdad?",
  ["6a:4bd0"] = "CIUDAD OLIVO\012El puerto a\ntierras lejanas",
  ["1f:551f"] = "Debes de tener\nhielo en las venas\012para enfrentarte\nal TEAM ROCKET.",
  ["6a:4b71"] = "¡El mar es dulce!\012¡Los atardeceres\nen el mar son\011maravillosos!\012¡Canta conmigo!\n¡La, la, la…!",
  ["1f:5554"] = "Viene marcado\ncomo BOTÓN 1.",
  ["6a:4b41"] = "¡Uauu, tienes una\nPOKéDEX! Es\012realmente\nincreíble.",
  ["1f:556b"] = "¿Estás perdido?\nNo, es imposible.\012No pareces\nasustado.\012¡Te daré algo\nque te\011asustará!",
  ["6a:4b04"] = "Eso que tienes\nes un POKéGEAR,\012¿verdad? ¡Uauu!\n¡Es genial!",
  ["1f:55d6"] = "¿Cómo ha sido?",
  ["6a:4a58"] = "Las calles oscuras\nson muy peligrosas\011por la noche.\012Pero si es noche\ncerrada, ¡el mar\012es aún más\ntraicionero!\012Si no les guiara\nla luz del FARO,\012los barcos no\npodrían navegar.",
  ["1f:55e6"] = "¡Ve a donde\nquieras! ¡Lárgate!\011¡No me importa!",
  ["6a:48fa"] = "…\012¿Tú otra vez?\012¿Y a mí qué me\nimporta? No me\012asustan los\ncanijos como tú.\012Y hablando de\ndebiluchos, la\012LÍDER del GIMNASIO\nno está aquí.\012Se supone que está\ncuidando a un\012POKéMON enfermo\nen el FARO.\012¡Buuuu! ¡Fuera\nlos POKéMON\011enfermos!\012¡Los POKéMON que\nno pueden luchar\011son unos inútiles!\012¿Por qué no vas\na entrenar al\011FARO?\012¿Quién sabe?\n¡A lo mejor\011te refuerza!",
  ["1f:5617"] = "Está APAGADO.\n¿ENCENDERLO?",
  ["6a:474d"] = "ACADEMIA POKéMON\nDE PRIMO",
  ["1f:562d"] = "Está ENCENDIDO.\n¿APAGARLO?",
  ["6a:4724"] = "TORRE BELLSPROUT\012Vive la vida\nPOKéMON",
  ["1f:5643"] = "Viene marcado\ncomo BOTÓN 2.",
  ["6a:46dc"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\011MALVA: PEGASO\012El elegante\nmaestro de los\011POKéMON voladores",
  ["1f:565a"] = "Viene marcado\ncomo BOTÓN 3.",
  ["6a:46b2"] = "CIUDAD MALVA\012La ciudad de los\naromas nostálgicos",
  ["1f:5671"] = "Viene marcado\ncomo EMERGENCIA.",
  ["6a:4665"] = "¡He visto un árbol\nque se mueve!\012¡Si lo tocas,\nse retuerce y\011baila! ¡Es genial!",
  ["1f:57cb"] = "¡Eh, tú! ¡Estás\ninterrumpiéndonos!\012¡Tenemos por\ncostumbre trabajar\012sin que nadie\nnos vea!",
  ["6a:45ef"] = "¡PEGASO, del\nGIMNASIO POKéMON\012de CIUDAD MALVA,\nes magnífico!\012Heredó el\ngimnasio de su\012padre y ha hecho\nun gran trabajo.",
  ["1f:582c"] = "Pierdo las ganas\nde trabajar si hay\011alguien mirando.\012¡Venga, chaval,\nfuera de aquí!",
  ["6a:4593"] = "¿Eres entrenador\nPOKéMON?\012¡Si ganas a este\nLÍDER de GIMNASIO,\012estarás en el\ncamino del éxito!",
  ["1f:5875"] = "¡Oohah! ¡Oohah!\012Hay cosas tiradas\npor el suelo.\012¡Recógelas si\nquieres!",
  ["6a:4529"] = "Dicen que en la\nTORRE BELLSPROUT\011hay fantasmas.\012Y dicen que los\nPOKéMON normales\012no afectan\na los fantasmas.",
  ["1f:58bb"] = "MACHOKE: ¡Machok!",
  ["6a:44f9"] = "El profesor soy\nyo. ¡Bien está\011que aquí estudies!",
  ["1f:59ea"] = "¿Cómo has llegado\nhasta aquí?\012Supongo que no\npudieron evitarlo.\011¡Acabaré contigo!",
  ["6a:44cb"] = "¿Es verdad? ¡Pues\ntú estudiarás!\011¡Sígueme!",
  ["1f:5a34"] = "Acabó conmigo…",
  ["6a:44ac"] = "¡Oh la la!\n¡Muy bien!",
  ["1f:5a48"] = "El TEAM ROCKET\nseguirá esperando\012el regreso de\nGIOVANNI.\012Haremos lo que\nsea necesario.",
  ["6a:4473"] = "¡Hola! ¿Eres un\nentrenador? ¿Has\012ganado al LÍDER\ndel GIMNASIO?",
  ["1f:5aa7"] = "¡No vas a ir\nmás lejos!\012¡Soy implacable\ncon mis enemigos\012y con cualquier\nmocoso!",
  ["6a:4340"] = "CASA DE ELM",
  ["1f:5af6"] = "¡Maldición!",
  ["6a:4332"] = "LABORATORIO DE ELM",
  ["1f:5b01"] = "He perdido…\012¡Perdóname,\nGIOVANNI!",
  ["6a:4328"] = "CASA DE {PLAYER}",
  ["1f:5b27"] = "¡Ji, ji, ji!\n¡Te recuerdo!\012¡Me diste bien\nen la guarida!",
  ["6a:42e8"] = "PUEBLO PRIMAVERA\012El pueblo donde\nsoplan vientos de\011un nuevo amanecer",
  ["1f:5b6b"] = "¡Ji, ji, ji!\n¿Así funcionas?",
  ["6a:42cd"] = "¿Qué estás\nmirando?",
  ["1f:5b8e"] = "¡Ji, ji, ji!\n¡Vaya combate!\011¡No te olvidaré!",
  ["6a:42a6"] = "……\012Así que éste es el\nfamoso LABORATORIO\011POKéMON de ELM…",
  ["1f:5bc6"] = "DIRECTOR: ¿Quién?\n¿Qué? ¿Has venido\011a rescatarme?\012¡Gracias!\012La TORRE de RADIO.\012¿Qué está pasando\nahí dentro?\012¿Invadida por el\nTEAM ROCKET?\012Mira. Toma esta\nLLAVE MAGNÉTICA.",
  ["6a:4274"] = "¡Hola, {PLAYER}!\012Dicen que el PROF.\nELM ha descubierto\011nuevos POKéMON.",
  ["1f:5c5b"] = "DIRECTOR: Úsala\npara abrir las\011puertas de la P2.",
  ["6a:4236"] = "Llama a tu madre\ncon la POKéGEAR\012y cuéntale cómo\nte va.",
  ["1f:5c8d"] = "Te ruego que\nme ayudes.\012¡Quién sabe lo\nque harían si se\012apoderaran de la\nemisora!\012¡Podrían hasta\ncontrolar a los\012POKéMON usando una\nseñal especial!\012Sólo tú puedes\nayudarme.\012Salva la TORRE\nde RADIO…\012¡Y a todos los\nPOKéMON del mundo!",
  ["6a:41f2"] = "¡Hola, {PLAYER}!\n¿Te vas otra vez?\012Deberías decirle\na tu madre que\011te vas.",
  ["1f:5e8d"] = "¡No perderé esta\nvez!",
  ["6a:41c4"] = "¡Oh, tu POKéMON es\nadorable! ¡Ojalá\011tuviera yo uno!",
  ["1f:5ea7"] = "¿He perdido…?",
  ["6a:415e"] = "¡Es peligroso\nsalir sin\011un POKéMON!\012De camino hacia la\nsiguiente ciudad\012te encontrarás\nPOKéMON salvajes.",
  ["1f:5ebd"] = "Hace un rato, este\nKARATEKA quería\011luchar.\012Era increíblemente\nbueno.\012Nos machacó.\012Nos dijo que sólo\nse estaba\012entrenando.\n¿Cómo será?",
  ["6a:413e"] = "¿Qué crees que\nestás haciendo?",
  ["1f:5f6a"] = "¡Hey! ¡UFF!",
  ["6a:4134"] = "¡Espera, {PLAYER}!",
  ["1f:5f76"] = "Te confundí con\notra persona…",
  ["6a:40f7"] = "¡Uau! ¡Tu POKéGEAR\nes impresionante!\012¿Te la ha dado\ntu madre?",
  ["1f:5f97"] = "Vine a explorar el\nMT. MORTERO, pero\012me separé de mi\ncompañero…\012¿Te has encontrado\ncon un entrenador\012que usa a un\nSEADRA que conoce\011CASCADA?",
  ["66:5745"] = "Nuestra ciudad\nsalió en un\011programa de radio.\012Está bien oír\nalabanzas sobre tu\012ciudad, pero\ntambién da un poco\011de vergüenza.",
  ["1f:60ed"] = "¡Eh! ¡MARC!",
  ["66:57b7"] = "CIUDAD AZAFRÁN\012La brillante y\ndorada tierra del\011comercio",
  ["1f:60fa"] = "Lo siento.\nMe equivoqué.",
  ["66:57e6"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\011AZAFRÁN: SABRINA\012Maestra de los\nPOKéMON psíquicos",
  ["1f:610e"] = "Estoy investigando\nMT. MORTERO, pero\012mi compañero ha\ndesaparecido.\012¿Has visto a un\nentrenador que\012tiene un SLOWPOKE\nque puede usar\011FUERZA?",
  ["66:5829"] = "¡Bienvenidos!\nDOJO-KARATE",
  ["1f:624d"] = "¡Hola!\012¡Soy el REY\ndel KARATE!\012¡Me entreno solo\nen la oscuridad!\012¡Tú!\n¡Lucha conmigo!\012¡Uaaarggh!",
  ["66:584a"] = "EDIFICIO-OFICINAS\nSILPH S.A.",
  ["1f:62a9"] = "¡Aaaargg!\n¡He perdido!",
  ["66:5865"] = "CASA DEL\nSR. PSÍQUICO",
  ["1f:62c0"] = "He… perdido…\012Tendré que seguir\nentrenándome…\012Pero una derrota\nes una derrota.\012Como prueba de tu\nvictoria, te voy\012a dar un raro\nPOKéMON de lucha.",
  ["66:5879"] = "ESTACIÓN DEL\nMAGNETOTRÉN DE\011CIUDAD AZAFRÁN",
  ["1f:6355"] = "{PLAYER} recibió\na TYROGUE.",
  ["66:599c"] = "Dicen que ha\naparecido un\012GYARADOS rojo\nen el LAGO.\012¡Qué raro, porque\nen el lago no son\012frecuentes ni los\nGYARADOS comunes!",
  ["1f:636a"] = "TYROGUE es del\ntipo lucha.\012Evoluciona en\nun POKéMON\011más fuerte.\012Sigue así.\nYo también seguiré\011entrenándome.\012¡Adiós!",
  ["66:5a0e"] = "¿Mi programa de\nradio favorito? La\011MÚSICA POKéMON.",
  ["1f:63df"] = "¡No tienes sitio\nen tu equipo!",
  ["66:5a3d"] = "He estado oyendo\nrisas en la\012radio… Es\nespeluznante.",
  ["1f:6512"] = "La piedra cayó\npor el agujero.",
  ["66:5b8d"] = "Los POKéMON viven\ntodo tipo de\011experiencias.\012Yo también he\nvisto y sufrido\011mucho en mi vida.\012Soy más mayor, así\nque te enseñaré lo\011que quiero decir.\012He estado con los\nPOKéMON desde\012antes de que tú\nnacieras.\012Y no pierdo\nfácilmente.\012¡Yo, FREDO, el\nentrenador del\012invierno, te\nmostraré mi poder!",
  ["1f:65ad"] = "Está empotrado\nen el hielo.",
  ["61:564a"] = "En marcha.",
  ["1f:66bd"] = "Al norte de\nPUEBLO LAVANDA\012está el TÚNEL\nROCA. Crúzalo\012para llegar a\nla CENTRAL\011de ENERGÍA.",
  ["61:55ee"] = "¡Parece que HO-OH\nse ha posado\012sobre la TORRE\nHOJALATA!",
  ["1f:6710"] = "Hay un programa\nde radio que\012pone música de\nPOKé FLAUTA.\012Necesitas una\nTARJETA EXPN para\011sintonizarlo.",
  ["61:5433"] = "Se dice que,\ncuando la TORRE\012LATÓN se quemó,\ntres POKéMON anó-\011nimos perecieron.\011Fue una tragedia.\012Sin embargo…\012Un POKéMON con los\ncolores del arco\011iris…\012En otras palabras…\012HO-OH descendió\ndesde el cielo y\012devolvió la vida a\nlos tres POKéMON.\012Son…\012SUICUNE, ENTEI y\nRAIKOU.\012Eso es lo que\ndicen…",
  ["1f:6779"] = "Si la CENTRAL\nENERGÍA no está en\012funcionamiento, el\nMAGNETOTRÉN\011tampoco lo estará…\012Y eso significa\nque la ESTACIÓN de\012RADIO no podrá\nemitir…",
  ["61:5203"] = "EUSINE: ¡Genial!\n¡Impresionante!\012Nunca había visto\nuna batalla igual.\012Verla ha sido\ninspirador.\012SUICUNE fue duro,\npero has estado\012increíble,\n{PLAYER}.\012He oído que los\npoderes místicos\012de SUICUNE invocan\na un POKéMON\012con los colores\ndel arco iris.\012Lo que ha ocurrido\nhoy quizás haga\012que ese POKéMON\naparezca.\012Voy a estudiar más\nlas leyendas.\012Gracias por\ndejarme asistir a\012esta fantástica\nbatalla.\012¡Hasta luego,\n{PLAYER}!",
  ["1f:67ed"] = "El DIRECTOR de\nla EMISORA estaba\011muy contento.\012Dijo que han\nvuelto a emitir\012porque la CENTRAL\nde ENERGÍA ya\011funciona.",
  ["1b:4b28"] = "¡Vaya…! Fallé…",
  ["1f:68f1"] = "El SR. FUJI vive\naquí, pero ahora\011no está en casa.\012Debe de estar en\nel CEMENTERIO.",
  ["1d:5937"] = "Me rindo.\nNo tienes por qué\012buscarlo.\n¡Olvídalo!",
  ["1f:6940"] = "Algunas personas\nson tan crueles\012que abandonan a\nsus POKéMON.\012El abuelo recoge a\nlos POKéMON que\012no tienen hogar\ny los cuida.",
  ["1d:5bbd"] = "Ooooh, guau.\n¡Qué fuerte!",
  ["1f:69b6"] = "PSYDUCK: ¿Psyay?",
  ["1e:56cd"] = "ELM: {PLAYER},\n¡qué horror…!\012¡Ah, sí! ¿Cuál\nera el gran\012descubrimiento del\nSR. POKéMON?",
  ["1f:69c9"] = "NIDORINO: ¡Nido!",
  ["1e:5c65"] = "(Suspiro…). El\nPOKéMON robado.\012Me pregunto\ncómo estará.\012Dicen que los\nPOKéMON educados\012por malas personas\nse vuelven malos.",
  ["1f:69da"] = "PIDGEY: ¡Pijji!",
  ["1e:609a"] = "Atrapa POKéMON\npara completar\011tu POKéDEX.\012Atrapa POKéMON\nsalvajes usando\011las POKé BALL.",
  ["1f:6a4d"] = "El PUEBLO LAVANDA\nes un pequeño y\012apacible lugar,\nal pie de las\011montañas.\012Desde que se\nconstruyó la TORRE\012de RADIO, acude\nalgo más de gente.",
  ["1d:574b"] = "LILA es buena pero\nROSA es la mejor.\012¡Me encantaría\nescuchar las\011emisoras de JOHTO!",
  ["1f:6b29"] = "Si vas a explorar\nuna cueva, debes\012llevar siempre\nREPELENTE.\012Aunque me gusta la\nexploración, aún\012no he explorado\ntodas las cuevas.",
  ["1b:4b39"] = "¡Me toca a mí!\n¡No puedes huir!",
  ["1f:6bac"] = "He oído hablar de\nun artesano que\012fabrica POKé BALL\na medida en PUEBLO\012AZALEA, en JOHTO.\n¡Yo quiero una!",
  ["1b:6548"] = "No puedo dejar\nque me afecte.\012Tengo que informar\na los otros…",
  ["1f:6c53"] = "SR. FUJI: ¡Hola!\012¡Mmm…! Parece que\nestás educando a\012tus POKéMON con\nmucho cariño.\012Los amantes de los\nPOKéMON vienen a\012rendir homenaje a\nPOKéMON muertos.\012Por favor, muestra\ntu condolencia por\012las almas POKéMON\nque han partido.\012Seguro que eso\nles hará felices.",
  ["1b:6802"] = "Un error táctico\nacabó conmigo…",
  ["1f:6d4d"] = "Creo que aquí hay\notras tumbas de\011POKéMON.\012Hay muchas cámaras\nen las que sólo\012puede entrar\nel SR. FUJI.",
  ["69:6c7f"] = "Dicen que hay un\ngran POKéMON\012bajo las\nISLAS REMOLINO.\012Me pregunto\ncómo será…",
  ["1f:6db1"] = "He venido con mi\nmadre a visitar\012las tumbas de los\nPOKéMON…",
  ["69:6c67"] = "¿Así es como\nlo haces?",
  ["1f:6ddb"] = "A los POKéMON que\nvivían conmigo…\012los quería como a\nmis nietos…",
  ["69:6c24"] = "Voy hacia las\nISLAS REMOLINO.\012Voy a explorarlas\ncon unos amigos.",
  ["1f:6ebf"] = "¡Bienvenido!\nMira por donde\012quieras en este\npiso.",
  ["69:6bed"] = "Un secreto sobre\nISLAS REMOLINO…\012¡Dentro está muy\noscuro!",
  ["1f:6efa"] = "Lo siento, pero\nsólo puedes dar\012una vuelta por la\nplanta baja.\012Desde que una\nbanda criminal\012asaltó la TORRE de\nRADIO, tuvimos\012que incrementar\nnuestra seguridad.",
  ["69:6bcc"] = "¡Ooh, tienes una\ngran resistencia!",
  ["1f:6f90"] = "En la TORRE de\nRADIO hay mucha\012gente que trabaja\nduramente.\012Seguro que están\nhaciendo todo lo\012posible por emitir\nbuenos programas.",
  ["69:6b9d"] = "¿Estás buscando\nel secreto de las\011ISLAS REMOLINO?",
  ["1f:6ffb"] = "¡Oh, no, no, no!\012No hemos emitido\ndesde que cerró la\012CENTRAL de\nENERGÍA.\012Si no emitimos, de\nnada servirá el\012esfuerzo realizado\npor la emisora.\012¡Me arruinaré!",
  ["69:6b6c"] = "La corriente me\nimpide llegar\011a las islas.",
  ["1f:70a1"] = "¿Eres tú\n{PLAYER}? ¿El que\012arregló la CENTRAL\nde ENERGÍA?\012Gracias a ti, no\nperdí mi empleo.\012¡Sin duda, tú eres\nmi salvador!\012Toma esto como\nagradecimiento.",
  ["69:6b62"] = "¡Me has vencido!",
  ["1f:7141"] = "Con eso podrás\nsintonizar los\012programas de\nradio de KANTO.\012¡Jajajaja!",
  ["69:6b26"] = "Aquí hay mucho\noleaje.\012Cuesta mucho\nnadar.",
  ["1f:7193"] = "",
  ["69:6aa4"] = "Era de noche\ny llovía…\012Vi un POKéMON\ngigante volando\011desde las islas.\012Dejaba caer las\nplumas de sus\011alas plateadas.",
  ["1f:7248"] = "¡Oye, joven!\012¡Soy el DIRECTOR\nde MÚSICA!\012Soy el encargado\nde las fantásticas\012melodías que se\nemiten aquí.\012No seas anticuado.\n¡Atrapa la música\011de las ondas!",
  ["69:6a80"] = "¿Cuál es tu\nsecreto?",
  ["1f:72e3"] = "PB RECEPCIÓN\nP1 VENTAS\011P2 PERSONAL\011P3 PRODUCCIÓN\011P4 DESPACHO DEL\011   DIRECTOR",
  ["1f:732d"] = "Anima a los POKé-\nMON con la melodía\012de la POKé FLAUTA\ndel CANAL 20",
  ["69:6429"] = "Aunque no se ve\ndesde aquí, CIUDAD\012ORQUÍDEA está al\notro lado del mar.",
  ["1f:7419"] = "¿Has estado en\nPUEBLO LAVANDA?\012Hay una TORRE\nde RADIO muy alta.",
  ["69:63f5"] = "Mientras flote\nasí, las olas\011me llevarán.",
  ["1f:74af"] = "Soy el hermano\npequeño del GURÚ\011PESCADOR.\012Veo que te gusta\npescar. ¡No\012tengo ninguna\nduda!\012Sé que tengo\nrazón.",
  ["69:63dd"] = "¡Ooh, estoy\nmareada!",
  ["1f:752f"] = "Sí, sí. ¡Justo lo\nque pensaba!\012¡Aquí tienes!\nToma esto. Es\011una SÚPER CAÑA.",
  ["69:63a9"] = "Yo no necesito\nflotador.\012¡Voy agarrada a\nun POKéMON de mar!",
  ["1f:757c"] = "Intenta pescar\nallí donde veas\011agua.\012Recuerda: puedes\ncapturar POKéMON\012diferentes usando\ndistintas CAÑAS.",
  ["69:637b"] = "Creo que nado\nmejor que tú.\011¡Sin duda!",
  ["1f:75ec"] = "¿Eh? ¿Me engañan\nmis ojos?",
  ["69:6369"] = "¡He perdido!",
  ["21:652c"] = "¡Nuevo Hall Fama!",
  ["69:632d"] = "¿Vas a CIUDAD\nORQUÍDEA?\012¿Te apetece luchar\nantes?",
  ["21:66fc"] = "¡Maestro HdF!",
  ["69:62fa"] = "La natación\nfortalece tu\011cuerpo. Es sana.",
  ["21:670c"] = "    vez/veces HdF",
  ["69:62ea"] = "¡Oh, he perdido…!",
  ["24:423c"] = "¿Eh? Perdona,\nnº equivocado.",
  ["69:62b4"] = "¡Eres joven y\nestás en forma!\012¡No vayas sobre tu\nPOKéMON! ¡Nada!",
  ["24:465b"] = "Ese número no es\nde esta zona.",
  ["64:5e29"] = "Si alguno alardea,\nhazlo tú también.",
  ["24:4664"] = "¡Habla con esa\npersona!",
  ["67:6d45"] = "A saber cuánto se\ntardaría en mover\011esta roca…",
  ["26:40d1"] = "Sin la MEDALLA\ndel GIMNASIO de\012CIUDAD IRIS, no se\nentra en la TORRE\012HOJALATA. ¡Vaya,\ntendrás que irte!",
  ["67:6caf"] = "Lo siento. La\ncarretera está\011cortada por obras.\012Si quieres llegar\na ISLA CANELA, ve\012por el Sur, desde\nPUEBLO PALETA.",
  ["67:6c66"] = "Creía que podía\nganar.",
  ["67:6bad"] = "No hay que nadar\nmucho desde CIUDAD\012FUCSIA a las ISLAS\nESPUMA…\012¡Mi novio es un\ngrandullón!\012¡Qué canijo!",
  ["1b:72de"] = "Hay tantos árboles\nen el ENCINAR que\012no se ve ni\nel cielo.\012Por favor, busca\nobjetos que puedan\011haber caído.",
  ["1b:7358"] = "SANTUARIO del\nENCINAR…\012Construido en\nhonor del guardián\011del encinar…",
  ["69:4a27"] = "SABINO: …\012Es sábado…\012Soy SABINO, por\nsábado…",
  ["1e:6c55"] = "¡EL CANAL POKéMON!",
  ["69:4a6b"] = "SABINO: …\012HECHIZO…\012Mejora los\nmovimientos de\011tipo fantasma.\012Te voy a\nasustar…",
  ["1e:6c64"] = "¡Soy la DJ ROSA,\nla presentadora!",
  ["69:4b00"] = "SABINO: Hoy no\nes sábado…",
  ["1e:6c84"] = "¡POKéMON!\nCANAL POKéMON…",
  ["69:4b67"] = "CIUDAD ENDRINO\012Un tranquilo\nrefugio de montaña",
  ["1e:6d2f"] = "PIKACHU es un\nPOKéMON\011evolucionado.\012Los hallazgos del\nPROF. ELM me\011sorprendieron.\012Es famoso por\nsus estudios\012sobre la evolución\nde los POKéMON.\012(Suspiro…).\012Me gustaría ser\nuna investigadora\011como él…",
  ["69:4bd9"] = "CASA DEL\nQUITA-MOVIMIENTOS",
  ["1e:6dd4"] = "Mi hija está\nempeñada en\012convertirse en la\nayudante del PROF.\011ELM.\012¡Le encantan los\nPOKéMON!\012¡Y a mí también!",
  ["69:4c03"] = "PISTAS ENTRENADOR\012Todo POKéMON que\nvaya equipado con\012una BAYA MILAGRO\nse curará a sí\011mismo en combate.",
  ["1e:6e3b"] = "¡La HORA POKéMON\ndel PROF. OAK!\012¡Sintonízanos la\npróxima vez!",
  ["1e:6e6c"] = "¡EL CANAL POKéMON!",
  ["1e:6e7b"] = "¡Soy la DJ ROSA,\nla presentadora!",
  ["1e:6e9b"] = "¡POKéMON!\nCANAL POKéMON…",
  ["1e:6ef7"] = "¡Hola, {PLAYER}!\nMi marido siempre\012está muy ocupado.\n¡Ojalá esté bien!\012Cuando estudia\na los POKéMON,\012se olvida hasta\nde comer.",
  ["69:4efc"] = "¡Caramba!",
  ["1e:6f6b"] = "¡Cuando sea mayor,\nayudaré a mi\011padre!\012¡Voy a ser un gran\nprofesor POKéMON!",
  ["69:4f97"] = "Es en estos duros\ncombates donde\011ganas más poder.",
  ["1e:701b"] = "Los POKéMON.\n¿De dónde vienen?\012¿Adónde van?\012¿Por qué no ha\npresenciado nadie\012el nacimiento de\nun POKéMON?\012¡Quiero saber!\n¡Quiero dedicar mi\012vida al estudio de\nlos POKéMON!\012…\012Son algunos\npapeles del\011PROF. ELM.",
  ["69:5d9d"] = "No me importa\nperder.",
  ["1e:714d"] = "Tus POKéMON\nparecen cansados.\012Deberías dejarlos\ndescansar un poco.",
  ["69:5d5b"] = "¡Qué POKéMON\nmás encantadores!\012Enseñemos nuestros\nPOKéMON al\011mismo tiempo.",
  ["1e:718b"] = "¡Vaya! ¡Tus\nPOKéMON tienen\011buen aspecto!\012¡Sigue así!",
  ["69:5cf8"] = "¡No te estoy\nescuchando!\012¡Los POKéFANS\ntenemos la norma\012de no escuchar a\nlos presumidos!",
  ["1e:71f9"] = "Aquí hay algo\nescrito.\012¿Quieres leerlo?",
  ["69:5cd4"] = "No tuve tiempo de\npresumir de mi\011PIKACHU…",
  ["1e:7222"] = "A mis hermanos y\nhermanas:\012Nos orgullece\nayudar a los\012entrenadores\nPOKéMON.\012Cuando habléis con\nlos entrenadores,\011dadles algo útil.\012Besos,\nLUNA\012¿Seguir leyendo?",
  ["69:5ca5"] = "¡Es buen momento\npara alardear de\011mi PIKACHU!",
  ["1e:72b9"] = "Lunes, LUNA\nRUTA 40\012Martes, MARTA\nRUTA 29\012Miércoles, MIGUEL\nLAGO DE LA FURIA\012Jueves, JOSUÉ\nRUTA 36\012Viernes, VICKI\nRUTA 32\012Sábado, SABINO\nCIUDAD ENDRINO\012Domingo, DOMINGO\nRUTA 37",
  ["69:5c4d"] = "Mis POKéMON han\nsido atrapados y\012entrenados en el\nextranjero.\012Son mis compañeros\nde esos largos\011viajes.",
  ["1e:73c6"] = "¿A dónde vas con\nlos POKéMON?\012¿A la LIGA\nPOKéMON?\012¿Son tus POKéMON\nlo bastante\012fieles como para\npemitirte ganar?\012Déjame ver…",
  ["69:5c42"] = "¡Awaaargh!",
  ["1e:742b"] = "¡Ah! Tus POKéMON\nconfían mucho\011en ti.\012Da gusto ver a un\nbuen entrenador.\012Toma. Un regalo\npara el viaje.",
  ["69:5c09"] = "Acabo de volver\nde CIUDAD OLIVO.\012¿Te apetece luchar\ncon los POKéMON?",
  ["1e:748f"] = "MT37 contiene\nTORMENTA ARENA.\012Este movimiento\ndaña a ambos\011combatientes.\012Es para entrenado-\nres avanzados.\012Úsala si te\natreves. ¡Suerte!",
  ["69:5204"] = "¡Uau! ¡Cuántas\nMEDALLAS! Estoy\011impresionado.\012Pero no te basta\nsólo con\012coleccionarlas,\n¿verdad?",
  ["1e:751f"] = "Si no confían\nmás en ti,\012tendrás problemas\npara ganar.\012La confianza es el\nvínculo entre los\012POKéMON y sus\nentrenadores.",
  ["69:526a"] = "¡Buena batalla!",
  ["1e:75c1"] = "No puedes cruzar\nsetos.\012Pero puedes saltar\npor encima de\011ellos para atajar.",
  ["69:5278"] = "Las personas y los\nPOKéMON se\012enriquecen con la\nexperiencia.\012No seas vago\ny conformista.",
  ["1e:760d"] = "Más adelante\naparecen muchos\012tipos de\nPOKéMON.\012Si quieres hacerte\ncon todos, tendrás\012que buscar por\ntodas partes.",
  ["69:52c4"] = "¡Hoy me siento\nmuy bien!\012¡Siento que podría\nvencer hasta al\011CAMPEÓN de LIGA!",
  ["1f:4005"] = "LIGA POKéMON\012ENTRADA A\nCALLE VICTORIA",
  ["69:530d"] = "¡No! ¡En esta\nbatalla, no!",
  ["1f:4314"] = "Me echaron\ndel CASINO.\012Intentaba hacer\ntrampas usando\011mis POKéMON…",
  ["69:5326"] = "Como en la pesca,\ncon los POKéMON\012todo está perdido\nsi te rindes.",
  ["1f:4361"] = "¡Caray…!",
  ["69:5364"] = "RUTA 26\012RECEPCIÓN DE LA\nLIGA POKéMON",
  ["1f:436c"] = "Supongo que\ndebería actuar\011honradamente…",
  ["69:5413"] = "RUTA 28",
  ["1f:439a"] = "¿Tienes en cuenta\nlos tipos durante\011el combate?\012Si conoces bien\nlos distintos\012tipos, rendirás\nmás en combate.",
  ["69:55ff"] = "CUEVA OSCURA…\012Si los POKéMON\npudieran\012iluminarla,\nla exploraría.",
  ["1f:4403"] = "¡Oo, oo, oo!",
  ["69:5635"] = "He atrapado un\nmontón de POKéMON.\011¡Luchemos!",
  ["1f:4410"] = "Conozco mis tipos\nde POKéMON.\012Pero sólo uso un\ntipo de POKéMON.",
  ["26:4131"] = "Sin la MEDALLA\nde CIUDAD IRIS,\012no se entra en\nTORRE HOJALATA.\012¡Ah!\012¡La MEDALLA de\nla CIUDAD IRIS!\011Puedes pasar.",
  ["1f:4452"] = "¡Les corté el pelo\na mis POKéMON!\012¡Ahora verás lo\nfuertes que son!",
  ["26:41a4"] = "Ha ocurrido un\nhecho importante.\012Perdóname, pero\ntengo que pedirte\011que te vayas.\012Lo que alivia el\nalma…\012El TRÍO DE SABIOS\ndice cosas muy\012difíciles de\nentender…",
  ["1f:448e"] = "¡Ayyyy!",
  ["26:4250"] = "",
  ["1f:4498"] = "Los POKéMON serán\nmás amigos tuyos\012si los llevas a\ncortar el pelo.",
  ["26:437e"] = "Sigue adelante.",
  ["1f:44d1"] = "Creo que tienes\nalgunos POKéMON\011muy raros.\012¡Déjame verlos!",
  ["26:4391"] = "El sonido de la\ncampana muestra el\011alma del portador.\012Tú…\012Puedes entrar en\nla TORRE HOJALATA.\012Sigue adelante.",
  ["1f:450d"] = "¡Bah! ¡He perdido!\n¡Qué rabia me da!",
  ["26:440b"] = "La TORRE HOJALATA\nes una espléndida\012torre de nueve\npisos.\012Alivia el alma de\ntodos los que la\011miran.",
  ["1f:452f"] = "¿Tienes una\nPOKéDEX? Pues te\011daré una pista.\012El MONTAÑERO de\nla RUTA 33, LUIS,\011es un buen chico.\012Te telefoneará\nsi ve algún\011POKéMON raro.",
  ["26:446f"] = "¡La TORRE HOJALATA\nse ha movido! ¡Se\012habrá posado un\nPOKéMON arriba!",
  ["1f:45b0"] = "Puerta cerrada…",
  ["26:44ab"] = "Dos torres…\nDos POKéMON…\012Pero cuando una\nse quemó, los dos\012POKéMON huyeron\ny nunca volvieron.",
  ["1f:45c3"] = "Puerta abierta.",
  ["26:462b"] = "Asombroso…\012SUICUNE, ENTEI y\nRAIKOU han salido\011de su letargo…\012¿Se hará realidad\nla leyenda?",
  ["1f:45d6"] = "Puerta abierta con\nLLAVE del SÓTANO.",
  ["26:468b"] = "Nos entrenamos en\nTORRE QUEMADA,\012pero nunca oímos\nhablar de que\012hubiera ningún\nagujero.\012Alguien lo debió\nde hacer a\011propósito.",
  ["1f:45f9"] = "¡Hola! ¡Yo dirijo\012la PELUQUERÍA\nPOKéMON!\012Soy el mayor y\nel mejor de los\012dos HERMANOS\nPELUQUEROS.\012Puedo poner guapos\na tus POKéMON por\011sólo 500¥.\012¿Quieres que les\ncorte el pelo?",
  ["26:4712"] = "Sólo pueden entrar\nen la TORRE\012HOJALATA aquellos\nque lleven la\012MEDALLA del\nGIMNASIO IRIS.\012¡Aunque, ahora que\nSUICUNE, RAIKOU\012y ENTEI han des-\npertado, te pido\012que te abstengas\nde entrar!",
  ["1f:469a"] = "¿A qué POKéMON\nle corto el pelo?",
  ["26:47af"] = "Nosotros, el TRÍO\nDE SABIOS, somos\012los protectores\ndel POKéMON\011legendario.",
  ["1f:46b8"] = "¡Vale! ¡Verás lo\nbien que queda!",
  ["26:47ed"] = "Cuenta la leyenda\nque cuando resurja\012un entrenador con\nla capacidad de\012tocar las almas de\nlos POKéMON, un\012POKéMON aparecerá\npara retar al\012entrenador en la\nTORRE HOJALATA.\012¡La leyenda se ha\nhecho realidad!\012¡SUICUNE, el\nPOKéMON legenda-\011rio, ha llegado!\012¡Nosotros, el TRÍO\nDE SABIOS, vamos a\012probarte antes de\nque entres!",
  ["1f:46d8"] = "¡Bien! ¡Ya está!",
  ["26:4914"] = "¿Más fuerte que\nnosotros? Quizá…",
  ["1f:46ea"] = "¿De verdad?\n¡Qué vergüenza!",
  ["26:4938"] = "Ah, entonces tú\neres quien dice\012haber visto a\nSUICUNE, ENTEI y\012RAIKOU mientras\ndormían…\012¡Increíble!\012La leyenda cuenta\nque no se pueden\012ver mientras\nduermen…",
  ["1f:4709"] = "Necesitarás más\ndinero.",
  ["26:49d2"] = "¿Mereces conocer\nla verdad?\012Debo averiguar tu\nvalía.",
  ["1f:472b"] = "Sólo corto el pelo\nuna vez al día.\011Ya vale por hoy.",
  ["26:4a18"] = "Te contaré la\nverdad…",
  ["69:5668"] = "¡Auuuu…!",
  ["26:4a35"] = "En el pasado, aquí\nse alzaban dos\012torres de nueve\npisos.\012La TORRE LATÓN, de\nla cual se decía\012despertaba a los\nPOKéMON, y la\012TORRE HOJALATA,\nen la que dormían\012los POKéMON,\nsegún parece.\012La vista desde las\nTORRES debía\011ser magnífica.\012Se dice que, por\naquel entonces, un\012inmenso POKéMON\nplateado hizo su\012nido sobre la\nTORRE LATÓN.\012Pero…\012Hace unos 150\naños, un rayo\012destruyó una de\nlas TORRES.\012La envolvió en\nferoces llamas\012durante tres días\ny tres noches.\012Un aguacero\nrepentino acabó\011con el fuego.\012Y así es como pasó\na ser la TORRE\011QUEMADA.",
  ["69:5761"] = "Zzzz… ¿Eh?\012¿Qué es eso? ¿Una\nCARTA para mí?",
  ["26:4c42"] = "¡Déjame ver tu\npoder!",
  ["69:56d9"] = "¡Arg…! ¿Eh?\012Hoy he caminado\nmucho buscando\011POKéMON.\012Me duelen los pies\ny tengo sueño…\012Si fuera un\nPOKéMON salvaje,\012sería fácil\natraparme…\012¡Zzzz…!",
  ["26:4c5a"] = "¡Muy fuerte!\n¿Por qué?",
  ["69:5671"] = "Puedes atrapar\nPOKéMON aunque\012ya lleves seis\ncontigo.\012Si atrapas alguno\nmás, será enviado\011a la CAJA.",
  ["26:4c6c"] = "Tú… ¿Era a ti\na quien esperaba\012el POKéMON legen-\ndario?",
  ["69:5790"] = "{PLAYER} entregó\nel POKéMON que\011lleva la CARTA.",
  ["26:4cac"] = "Ya veo…\012Nosotros, el TRÍO\nDE SABIOS, tenemos\012la responsabilidad\nde proteger al\012POKéMON legenda-\nrio. Sólo podemos\012dejar pasar a\naquellos que\012posean el poder y\nun alma pura.\012Por favor, sigue\nadelante hacia la\011TORRE HOJALATA.\012SUICUNE te pondrá\na prueba.",
  ["69:57ba"] = "Veamos…\012La C. OSCURA lleva\na otro camino.\012Es bueno saberlo.\012Gracias por\ntraerme esto.\012Mi amigo es un\nbuen chico.\012¡Tú también eres\nincreíble!\012¡Me gustaría\ndevolverte el\011favor!\012¡Ya sé!\n¡Toma esto!",
  ["26:4db5"] = "Adelante.\012SUICUNE te pondrá\na prueba.",
  ["69:5896"] = "MT50 es PESADILLA.\012Es un movimiento\nterrible que\012reduce los PS de\nun rival dormido.\012¡Ooooh…!\n¡Qué miedo…!\012No me gustan las\npesadillas.",
  ["26:4ed8"] = "Hola, soy BILL.\n¿Quién eres tú?\012¿Eh? {PLAYER}.\n¡Has llegado\011justo a tiempo!",
  ["69:5921"] = "Esta CARTA no\nes para mí.",
  ["26:4f22"] = "Ya he terminado de\najustar la CÁPSULA\011del TIEMPO.\012Sabes que puedes\ncambiar POKéMON,\011¿verdad?\012Mi CÁPSULA del\nTIEMPO sirve para\012cambiar POKéMON\ncon el pasado.\012Pero no podrás\nenviar nada que\012no existiera en\nel pasado.\012Si lo haces, el PC\ndel pasado podría\011estropearse.\012Así que debes\neliminar cualquier\012cosa que no\nexistiera antes.\012Esto es, no envíes\nnuevos movimientos\012o nuevos POKéMON\na esta CÁPSULA.\012No te preocupes.\nYa he acabado\011de ajustarla.\012Mañana funcionarán\ntodas las CÁPSULAS\012del TIEMPO de los\nCENTROS POKéMON.\012Debo volver pronto\na CIUDAD TRIGAL.\011Mi familia espera.\012¡Hasta luego!",
  ["69:5939"] = "¿Por qué es espe-\ncial este POKéMON?\012No tiene ninguna\nCARTA.",
  ["26:5155"] = "Las CHICAS KIMONO\nson unas geniales\012bailarinas, además\nde magníficas\011con sus POKéMON.",
  ["69:5972"] = "¿Qué? ¿No\nquieres nada?",
  ["26:51aa"] = "Seguro que esperas\nluchar con más\012gente, ¿verdad?\nParece que hay un\012sitio en el que se\nreúnen los\011entrenadores.\012Te preguntarás\ndónde.\012Es pasando CIUDAD\nOLIVO.",
  ["69:5991"] = "Si te quito ese\nPOKéMON, ¿qué\012vas a usar en los\ncombates?",
  ["26:5240"] = "MORTI, el LÍDER\ndel GIMNASIO, es\011muy bueno.\012Y sus POKéMON\nson muy fuertes.",
  ["69:59d5"] = "He encontrado un\nbuen POKéMON en\011la CUEVA OSCURA.\012Voy a criarlo\npara enfrentarme\011a PEGASO.\012Es el líder del\nGIM. de C. MALVA.",
  ["26:5286"] = "LAGO DE LA FURIA.\012Un montón de\nGYARADOS…\012¡Esto huele a\nconspiración!",
  ["69:5a45"] = "RUTA 31\012CIUDAD MALVA -\nCIUDAD CEREZO",
  ["26:533d"] = "Sucedió cuando\nera joven.\012El cielo se\noscureció de\012repente. Un enorme\nPOKéMON estaba\011tapando el sol.\012Me pregunto qué\nsería ese POKéMON,\012mezcla de pájaro\ny dragón.",
  ["69:5a6e"] = "CUEVA OSCURA",
  ["26:53ec"] = "¿Existe un POKéMON\ntan grande? Si\012existe, debe de\nser muy fuerte.",
  ["69:5bf9"] = "MUU-MUU: ¡Muu!",
  ["26:552e"] = "Tus POKéMON son\nencantadores.\011¿Cómo luchan?",
  ["69:51d9"] = "Los POKéMON son\nvaliosos amigos\011para toda la vida.",
  ["26:555f"] = "¡Oh! ¡Eres muy\nfuerte!",
  ["69:51bf"] = "Los POKéMON no son\narmas de guerra.",
  ["26:5579"] = "Me ha gustado el\ncombate. Espero\011volver a verte.",
  ["69:5136"] = "He perdido contra\n{RIVAL}.\012Era realmente\nfuerte, pero…\012Parecía como si\ntuviera que ganar\011a toda costa.\012Me dieron pena\nsus POKéMON.",
  ["26:55ae"] = "Yo siempre bailo\ncon mis POKéMON.\012Y también los\nentreno, claro.",
  ["69:50d7"] = "Como había vencido\na ocho LÍDERES\012de GIMNASIO, me\nconfié demasiado.\012Tendré que\nesforzarme más.",
  ["26:55ea"] = "¡Estuve cerca!\nPor poco te venzo.",
  ["69:50bd"] = "¡No! ¡No puedo\ncreerlo!",
  ["26:560b"] = "El ritmo es muy\nimportante para\012la danza y para\nlos POKéMON.",
  ["69:505c"] = "Si has llegado tan\nlejos, debes de\011ser muy bueno.\012¡Voy a dar todo\nlo que tengo en\011este combate!",
  ["26:563f"] = "¿Te gusta\nmi pasador?\012¡Ah! ¿Un combate\nPOKéMON?",
  ["69:4fe4"] = "Para llegar a la\nLIGA POKéMON,\012hay que pasar por\nla CALLE VICTORIA.\012Pero la CALLE\nVICTORIA es dura.\012¡No va allí\ncasi nadie!",
  ["26:566c"] = "No me queda ningún\nPOKéMON…",
  ["69:4fc7"] = "¡La vida es\naún más dura!",
  ["69:5db2"] = "¿Sabes algo sobre\nlos POKéMON bebés?\012¡Seguro que\nson adorables!",
  ["69:4f08"] = "Va a ser difícil\nganar en la\011LIGA.\012Tengo que\nentrenar más.\012Dicen que el ALTO\nMANDO es más duro\012que los LÍDERES\nde GIMNASIO.",
  ["69:5dec"] = "¡PIKACHU es lo\nmás! ¿No crees?",
  ["69:4ec6"] = "Estoy haciendo\nlos últimos\012preparativos para\nla LIGA POKéMON.",
  ["69:5e0c"] = "Déjame ver de qué\nson capaces tus\011POKéMON.",
  ["69:4bef"] = "HACIA LA GUARIDA\nDEL DRAGÓN",
  ["69:5e37"] = "¡Ooh! Tus POKéMON\ntienen potencial.",
  ["69:4b91"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\011ENDRINO: DÉBORA\012La gran experta en\nPOKéMON dragón",
  ["69:5e57"] = "¿Sabes que\nlos POKéMON\012tienen distintas\nhabilidades?\012Son como las\npersonas. Cada\012uno tiene su\npropio potencial.",
  ["69:4b1e"] = "¡Uau! ¿Has venido\npor la RUTA\011HELADA?\012¡Debes de ser un\nentrenador genial!",
  ["69:5ec4"] = "Ufufufu… Espero\nque oscurezca\011pronto.",
  ["69:4ab6"] = "SABINO: …\012Nos vemos otro\nsábado…\012Pero ya no tendré\nmás regalos…",
  ["69:5ee8"] = "Llegas justo a\ntiempo.\012Luchemos.",
  ["69:4a57"] = "Toma esto…",
  ["69:5f17"] = "Oh, qué\ndecepcionante…",
  ["1d:5643"] = "Voy a KANTO a\nponerme a prueba.",
  ["69:5f31"] = "Encontré mi MEOWTH\naquí por la noche,\011en la RUTA 39.\012No estoy segura,\npero parece que\012le gusta que me\nentrene aquí.\012Cuando estamos por\nesta zona, se\012vuelve más cari-\nñoso.",
  ["1d:548d"] = "El FERRY S.S. AQUA\nha llegado a\011CIUDAD OLIVO.",
  ["69:5fe3"] = "RUTA 39\012CIUDAD OLIVO -\nCIUDAD IRIS",
  ["1d:5412"] = "¡Auuu! Perdóname.\n¡Tengo prisa!\012¡Mi nieta ha\ndesaparecido!\012Es muy pequeña.\n¡Si la ves, por\012favor, házmelo\nsaber!",
  ["69:600a"] = "GRANJA MUU-MUU\012Prueba nuestra\nrica leche fresca",
  ["67:6c19"] = "Soy malísimo\nnadando.\012Sólo estoy\nchapoteando por\012estas aguas poco\nprofundas.",
  ["69:6036"] = "PISTAS ENTRENADOR\012Usa GOLPE CABEZA\nen los árboles\012para que salgan\nPOKéMON.\012De los árboles\npueden caer varios\011tipos de POKéMON.",
  ["67:6c7e"] = "Puede que no nade\nmuy bien, pero me\011encanta el mar.",
  ["69:622f"] = "Debes calentar\nantes de entrar\011en el agua.\012Es imprescindible.",
  ["67:6d24"] = "Estoy sudando.\n¡Voy a bañarme!",
  ["69:626e"] = "¡Vale! ¡Me rindo!",
  ["67:6d7d"] = "Las obras de la\ncarretera ya han\011terminado.\012Ya puedo volver a\npescar.",
  ["69:6282"] = "CIUDAD ORQUÍDEA\nestá bastante\011lejos de aquí.",
  ["16:5ac1"] = "Es una réplica\nde un antiguo\011POKéMON.",
  ["16:5c0b"] = "¿Te diriges a\nPUEBLO AZALEA?\012Demuestra a\nmis POKéMON que\011vales para luchar.",
  ["64:5de9"] = "BAYLEEF: ¡Li liif!",
  ["16:5c5f"] = "¡Oh, oh, oh!",
  ["64:5d73"] = "¡Mira mi precioso\nBAYLEEF!\012¡Lleva una hoja\ntan mona!",
  ["16:5c6c"] = "¡Muy bien!\nYa lo he decidido.\012¡No me iré hasta\nque mis POKéMON\011se fortalezcan!",
  ["64:5d1e"] = "¡Ya verás! Voy\na hacerme amigo\012de un auténtico\nCLEFAIRY.",
  ["16:5cb5"] = "Merodeo por todas\npartes en busca\011de POKéMON.\012¿También tú vas en\nbusca de POKéMON?\012¡Pues entonces\neres mi rival\011coleccionista!",
  ["64:5c5a"] = "¡Ah, entiendo! La\nniña que perdió el\012POKé MUÑECO\nestá triste…\012Vale. ¿Podrías\ndevolverle este\012POKé MUÑECO a\nesa pobre niña?\012Un día me haré\namigo de un\012CLEFAIRY real.\n¡No te preocupes!",
  ["16:5d1b"] = "¡Ugh! Mis pobres\nPOKéMON…",
  ["64:5ba0"] = "Me encanta el\nmodo en que\012CLEFAIRY mueve el\ndedo para usar\012METRÓNOMO. ¡Es\ntan adorable!",
  ["16:5d31"] = "Todos los viernes\nse escucha a un\012POKéMON que ruge\nen la cueva.",
  ["64:5b38"] = "¡Qué pena…!\012¡Vuelve cuando\nquieras!",
  ["16:5d73"] = "¡Uauu!\n¡Qué sorpresa!\012¡No esperaba\nver a nadie!",
  ["69:41db"] = "Voy a practicar en\nel TEATRO de\012DANZA. ¿Vienes\nconmigo?",
  ["16:5dae"] = "¡Uauu! ¡Me\nhan machacado!",
  ["69:4147"] = "¡Ah, tú!\n¿Has aprendido a\012bailar como las\nCHICAS KIMONO?\012Si vas a su TEATRO\nde DANZA, un raro\012anciano te dará\nalgo bonito.\012Eso me han dicho.",
  ["16:5dc9"] = "Me obligaron a\ncomprar una COLA\011de SLOWPOKE.\012Lo siento por\nel pobre POKéMON.",
  ["69:4105"] = "En CIUDAD IRIS\nhabía dos torres:\012una en el Este y\notra en el Oeste.",
  ["1d:6e6f"] = "En las RUINAS\nALFA hay unas\012extrañas piezas\nde piedra.",
  ["68:705f"] = "Me gusta dormirme\ncon la radio en…\011¡Zzzz…!",
  ["1d:6ea6"] = "¡Estoy agotado!",
  ["68:6f75"] = "Casi todos los\nPOKéMON se duermen\012al oír cantar a\nJIGGLYPUFF.\012Cuando un POKéMON\nestá dormido sólo\012se pueden usar\nciertos ataques.",
  ["1d:6eb6"] = "He leído que hay\ncuatro piezas de\011piedra como ésas.",
  ["68:6f5d"] = "JIGGLYPUFF: Puff,\npuff.",
  ["1d:6faf"] = "El FERRY S.S. AQUA\nnavega hasta KANTO\012los lunes y\nlos viernes.",
  ["68:6f01"] = "¡Sí! Ya no hay\nGIMNASIO en la\012ISLA CANELA. Me\nquedé de piedra.\012¿Sí? Estoy al\nteléfono. ¡Fuera!",
  ["1d:701d"] = "El FERRY sale\nsiempre los\012miércoles y\nlos domingos.",
  ["68:6e3a"] = "Había una vez\nun anciano muy\012raro que vendía\nMAGIKARP.\012Decía que\nlos MAGIKARP del\012LAGO DE LA FURIA\neran excelentes.",
  ["1d:713b"] = "PLAZA MT. MOON\nNo tirar basura",
  ["68:6dd8"] = "¡Hola! ¡Mira mi\nGYARADOS!\012Procede de un\nMAGIKARP. No me\012puedo creer lo\nfuerte que es.",
  ["1d:71b3"] = "Cuando el sol se\npone, CLEFAIRY\011sale a jugar.",
  ["68:6d07"] = "¡Hola, futuro\nCAMPEÓN! Este\012GIMNASIO no te\nha costado mucho.\012Tu forma de atacar\nha sido realmente\012increíble. Lo\ndigo en serio.",
  ["1d:7260"] = "¡Shaoooh!",
  ["68:6c6e"] = "¡Eh, futuro\nCAMPEÓN! Eres\012realmente temible.\n¿Vas a enfrentarte\012a los LÍDERES DE\nGIMNASIO de KANTO?\012Son fuertes y\nentregados, igual\012que los LÍDERES de\nGIMNASIO de JOHTO.",
  ["1e:433d"] = "¡Aquí es donde\nentreno!",
  ["68:6c0f"] = "¡Eh, tú! ¡Chico\nde JOHTO! BROCK\012es muy duro. Te\ncastigará si no\012le tomas en\nserio.",
  ["1e:435e"] = "¡Me han\nderrotado!",
  ["68:6bf1"] = "Tengo que ganar\nestos combates…",
  ["1e:43d8"] = "Voy a entrenar\nmás aún.\012Estoy intentado\nconvertirme en un\011LÍDER de GIMNASIO.",
  ["68:6b62"] = "Los entrenadores\nde este GIMNASIO\011usan POKéMON roca.\012Los de roca tienen\nmayor DEFENSA.\012Los combates\npueden durar mucho\012tiempo. ¿Estás\npreparado?",
  ["1e:4425"] = "Soy el mejor de mi\nclase en POKéMON.",
  ["68:6ada"] = "BROCK: El mundo es\nenorme. Hay muchos\012entrenadores tan\nfuertes como tú.\012Espera y verás.\nYo también me voy\012a hacer más\nfuerte.",
  ["1e:4447"] = "¡No! Hay mejores\nentrenadores…",
  ["68:6a57"] = "BROCK: Gracias,\n{PLAYER}. Me gustó\012luchar contigo,\naunque estoy un\011poco triste.\012La MEDALLA ROCA\nhará que tus\012POKéMON sean aún\nmás fuertes.",
  ["1e:4469"] = "Estoy esforzándome\npara ser el mejor\011de mi clase.",
  ["68:6a3d"] = "{PLAYER} recibió\nla MEDALLA ROCA.",
  ["1e:449b"] = "Confío en mi\ncapacidad para\011criar POKéMON.\012¿Quieres verlo?",
  ["68:69bb"] = "BROCK: Mi dura\ndefensa no soportó\012los ataques de\ntus POKéMON…\012Eres más fuerte de\nlo que pensaba…\012Toma. Coge\nesta MEDALLA.",
  ["1e:44d3"] = "¿He fallado en mi\nentrenamiento?",
  ["68:68d0"] = "BROCK: ¡Uau! No\ntodos los días\012nos desafía\nalguien de JOHTO.\012Soy BROCK, LÍDER\ndel GIM. de C.\012PLATEADA y experto\nen POKéMON roca.\012Mis POKéMON son\ninsensibles a la\012mayoría de ataques\nfísicos. Te será\012muy difícil\nhacerles daño.\012¡Venga!",
  ["1e:44f0"] = "Quizá deba llevar\na un POKéMON a la\012GUARDERÍA, o quizá\nusar objetos…",
  ["68:6825"] = "NIDORAN: ¡Nidoo!",
  ["1e:4532"] = "¡De compras al\naire libre!\012Se está tan bien\nen la azotea…",
  ["68:6814"] = "¡NIDORAN, agítate!",
  ["1e:456d"] = "¿Eres entrenador?\012Libremos un\ncombate de prueba.",
  ["68:677d"] = "HACIA EL NORTE\nAL PUEBLO LAVANDA\012HACIA EL OESTE\nA CIUDAD FUCSIA",
  ["1e:459e"] = "¡Oh, no! No\npuedo ganar…",
  ["68:675b"] = "RUTA 13 HACIA EL\nNORTE AL PUENTE\011SILENCIO",
  ["1e:45b8"] = "Eres demasiado\nfuerte para\011practicar conmigo.",
  ["68:671c"] = "PISTAS ENTRENADOR\012¡Mira! Allí, a\nla izquierda\011del poste.",
  ["1e:45e4"] = "¿Quién anda ahí?\n¿Qué es lo que\011quieres?",
  ["68:66c2"] = "Parece que las\nformas geológicas\011no cambian.\012Pero sí que\ncambian, aunque\011poco a poco.",
  ["1e:4609"] = "Eres muy fuerte.",
  ["68:66b9"] = "He perdido…",
  ["1e:4624"] = "Hoy no veo\nnada malo. Sé\012bueno y no te\nmetas en líos.",
  ["68:6686"] = "Debería ir al\nTÚNEL ROCA para\011conseguir un ONIX.",
  ["1e:466a"] = "Estoy buscando\nindividuos\011sospechosos.",
  ["68:6662"] = "Los POKéMON son\nfelices si los\011pones guapos.",
  ["1e:4696"] = "Acabo de recoger\nmi POKéMON de la\011GUARDERÍA.\012¡Veamos lo fuerte\nque es ahora!",
  ["68:6649"] = "¡Vaya! ¡No soy lo\nbastante bueno!",
  ["1e:46e1"] = "¿Por qué acaba\nasí?",
  ["68:6604"] = "Mira mis\nPOKéMON. Fíjate\012en su color y\nen su plumaje.",
  ["1e:46fc"] = "Mi POKéMON sabía\nmovimientos que yo\011desconocía.\012¡Eso me confundió\nmuchísimo!",
  ["68:65db"] = "Tus POKéMON\nestán muy bien\011entrenados.",
  ["1e:4743"] = "MAR: ¡Kiaaa! ¡Nos\nhan encontrado!",
  ["68:65bd"] = "Me venciste con\ntu velocidad…",
  ["1e:4765"] = "MAR: ¡Ohhh!\n¡Demasiado fuerte!",
  ["68:6591"] = "La agilidad es\nla clave de los\011POKéMON pájaro.",
  ["1e:477f"] = "MAR: ¡Mi hermana\nLISA te lo hará\011pagar!",
  ["68:654f"] = "Parece que tienes\nmuchos POKéMON,\012pero PIKACHU es\nel mejor.",
  ["1e:47ad"] = "MAR: ¿No te parece\nuna playa genial?\012¡Es nuestro\npequeño refugio!",
  ["68:6542"] = "¡PI, PIKACHU!",
  ["1e:47eb"] = "ILDA: ¡No puedes\nvencer a MAR e\011irte sin más!",
  ["68:650f"] = "¡Jijiji! ¿Quieres\nluchar contra mi\011grupo de PIKACHU?",
  ["1e:4819"] = "ILDA: ¡Lo siento\nmucho, MAR!",
  ["68:64e3"] = "¿Acaso no quiere\nser rey todo\011el mundo?",
  ["1e:4836"] = "ILDA: ¡No seas\nchulo! ¡Mi hermana\011LISA es fuerte!",
  ["68:64c2"] = "¿Qué? ¡Te burlas\nde la realeza!",
  ["1e:4866"] = "ILDA: El sol\nfortalece tu\011cuerpo.",
  ["68:64a2"] = "¡Arrodíllate ante\nmi regio POKéMON!",
  ["1e:4890"] = "LISA: ¡Seguro que\nhas sido malo con\011mis hermanitas!",
  ["68:6324"] = "PISTAS ENTRENADOR\012Si un POKéMON\nva a evolucionar,\011puedes pararlo.\012Pulsa el Botón B\nmientras intenta\011evolucionar.\012Esto asusta al\nPOKéMON y detiene\011su evolución.",
  ["1e:48c0"] = "LISA: ¡He perdido!\n¡Increíble!",
  ["68:62fd"] = "RUTA 38\012CIUDAD OLIVO -\nCIUDAD IRIS",
  ["1e:48e2"] = "LISA: Eres muy\nfuerte. No pude\011hacer nada.\012Toma. Te lo\nmereces.",
  ["68:629a"] = "La LECHE MU-MU\nembellece y es\012saludable, pero es\nuna pena que sólo\012vendan una botella\ncada vez.",
  ["1e:492b"] = "LISA: Sentimos\nhaberte atacado.\012Pensábamos que\naquí nadie nos\012encontraría. ¡Nos\nhas sorprendido!",
  ["68:6279"] = "Bebemos LECHE\nMU-MU a diario.",
  ["1e:49a8"] = "RUTA 34\012CIUDAD TRIGAL -\nPUEBLO AZALEA\012EL ENCINAR\nEntre medias",
  ["68:624c"] = "¿No crees que mis\nPOKéMON y yo\011somos bonitos?",
  ["1e:49ed"] = "PISTAS ENTRENADOR\012Todos los días\ncrecen BAYAS en\011los árboles.\012Toma nota de los\ntipos de BAYAS que\011tiene cada árbol",
  ["68:620c"] = "Gentes de todo el\nmundo viven\012felices con\nlos POKéMON.",
  ["1e:4a52"] = "GUARDERÍA\012¡Déjanos criar a\ntu POKéMON por ti!",
  ["68:61f0"] = "¡Tu destreza es de\ncategoría mundial!",
  ["1e:4fb6"] = "ELM: ¡{PLAYER}!\n¡Aquí estás!\012Tengo que pedirte\nun favor.\012Estoy llevando una\nnueva investiga-\011ción POKéMON en\011este momento.\012Me preguntaba si\npodrías ayudarme,\011{PLAYER}.\012Mira…\012Estoy preparando\nel discurso que\012daré en una\nconferencia.\012Pero hay algunas\ncosas que todavía\012no llego a\ncomprender.\012¡Bueno!\012Necesito que\ncuides de un\012POKéMON que\ncapturé hace poco.",
  ["68:61b7"] = "He estado en el\nextranjero. ¡Así\012que conozco todo\ntipo de POKéMON!",
  ["1e:50fa"] = "¡Gracias,\n{PLAYER}!\012¡No sabes cuánto\nte lo agradezco!",
  ["68:6185"] = "Cuando veo\nPOKéMON me\011tranquilizo.",
  ["1e:511a"] = "Pero… ¡por\nfavor, ayúdame!",
  ["68:6164"] = "Encantada de\nhaber visto\011a tus POKéMON.",
  ["1e:513a"] = "Cuando haga públi-\ncos mis hallazgos,\012habremos ahondado\nun poco más en los\012misterios que\nrodean a los\011POKéMON.\012¡Con toda\nseguridad!",
  ["68:6130"] = "¡Hola! ¡Eres\nmuy guapo!\012¿Me dejas ver a\ntus POKéMON?",
  ["1e:51ae"] = "",
  ["68:60ec"] = "¡Tengo una buena\nnoticia!\012La leche de la\nGRANJA MUU-MUU\012es famosa por\nsu sabor.",
  ["1e:51df"] = "Eh, escucha.\012Conozco a\nalguien llamado\011SR. POKéMON.\012Investiga cosas\nextrañas y le\012entusiasman sus\ndescubrimientos.\012Bueno, pues me ha\nenviado un e-mail\012diciendo que\nestá pasando algo.\012Es intrigante,\npero estamos\012ocupados con la\ninvestigación…\012¡Espera!\012¡Ya sé!\012{PLAYER},\n¿puedes ir por\011nosotros?",
  ["68:60c8"] = "Ya veo. De modo\nque luchas así.",
  ["1e:52ff"] = "Quiero que cuides\nde uno de los\012POKéMON que hay\ndentro de las\011BALL.\012¡Estos POKéMON\nnunca han tenido\012un compañero,\n{PLAYER}!\012Venga. ¡Elige!",
  ["68:607d"] = "Parece que sabes\nde POKéMON.\012Si es así, ¿por\nqué no me das\011algún consejo?",
  ["1e:5375"] = "Si aparece un\nPOKéMON salvaje,\012haz que tu POKéMON\nluche contra él.",
  ["68:600e"] = "Tengo que hacer\nmuchos exámenes y\012no tengo tiempo\npara los POKéMON.\012Así que, cuando\npuedo jugar, me\011concentro mucho.",
  ["1e:53a7"] = "ELM: ¡Espera!\n¿Adónde vas?",
  ["68:5fee"] = "Creo que no\nestudié bastante.",
  ["1e:53c8"] = "ELM: ¿Quieres a\nCYNDAQUIL, el\011POKéMON de fuego?",
  ["68:5fc5"] = "Déjame probar\nalgo que he\011aprendido hoy.",
  ["26:56c0"] = "¡Oh! ¡Eres\ntan mono!\011¿Quieres luchar?",
  ["68:5f86"] = "Pienso entrenarme\nen CIUDAD ORQUÍDEA\012y enseñar a volar\na mis POKéMON.",
  ["26:56f5"] = "Eres más fuerte de\nlo que pareces.",
  ["68:5f63"] = "¡Me apetece salir\nvolando ahora!",
  ["26:5714"] = "He entrenado mucho\ny creía que tenía\012posibilidades,\npero no.",
  ["68:5f35"] = "¡Vuela alto hacia\nel cielo, querido\011pájaro POKéMON!",
  ["1e:5487"] = "ELM: ¡Yo también\ncreo que es un\011POKéMON genial!",
  ["68:5bc0"] = "Perdí otra vez…\n¡Eres fuerte!\012Oh. Casi olvido\nque tenía que\011darte esto.\012Úsalo para hacerte\naún más fuerte,\011¿vale?\012Yo también seré\nmás fuerte.",
  ["26:578a"] = "¡Oh! ¡Tú también\neres bueno!",
  ["68:5b66"] = "PISTAS ENTRENADOR\012¡No robes los\nPOKéMON de otros!\012¡Las POKé BALL\nsólo se lanzan a\011POKéMON salvajes!",
  ["26:57a8"] = "Sigo bailando\nporque hay gente\012a la que le gusta\nlo que hago.\012Mis POKéMON\nme animan.",
  ["68:5b55"] = "CASA SR. POKéMON",
  ["26:580a"] = "Las CHICAS KIMONO\nno sólo bailan.\012También son\nextraordinarias\011con los POKéMON.\012Yo siempre las\ndesafío pero nunca\012les he hecho\nni un rasguño…",
  ["68:5b34"] = "CASA SR. POKéMON\n¡Todo recto!",
  ["1e:55db"] = "¡{PLAYER}, cuento\ncontigo!",
  ["68:5b0b"] = "RUTA 30\012CIUDAD MALVA -\nCIUDAD CEREZO",
  ["26:58d4"] = "Chica, si vences a\ntodas las CHICAS\012KIMONO, te daré un\nregalo.",
  ["68:5ac4"] = "No soy una\nentrenadora.\012Pero si miras a\nuno a los ojos,\012prepárate\na luchar.",
  ["26:591a"] = "Verte luchar ha\nsido como ver\011una danza.\012¡Ha sido un\nextraño combate!\012Me gustaría darte\nesto. Adelante,\011¡tuyo es!",
  ["68:5a94"] = "¡Todo el mundo se\ndivierte luchando!\012¡Tú también\ndeberías hacerlo!",
  ["26:599b"] = "Es SURF.\012Un movimiento\nque permite nadar\011a los POKéMON.",
  ["68:5a6a"] = "¿La casa del SR.\nPOKéMON? Está un\011poco más adelante.",
  ["1e:5690"] = "Me pregunto qué\nserá esto.",
  ["68:5a1c"] = "Me quedé sin\nPOKé BALL mientras\011atrapaba POKéMON.\012Debería haber\ncomprado más…",
  ["26:5a0a"] = "RHYDON: ¡Rhydo,\nrhydo!",
  ["68:5a03"] = "¡Arg! ¡Eres\nmuy fuerte!",
  ["26:5a24"] = "Ese hombre siempre\nva con su RHYDON.\012Dice que quiere un\nPOKéMON que baile\011y haga SURF.\012¿Intenta crear\nun POKéMON que\012haga natación\nsincronizada?",
  ["68:59d8"] = "¡En lugar de un\nPOKéMON bicho,\012he encontrado\nun entrenador!",
  ["26:5aaa"] = "Las CHICAS KIMONO\nson tan guapas…\012Pero tienen que\nentrenar mucho.\012Y deben aprender\nlos distintos\012bailes antes\nde actuar.\012Pero si te gusta\nalgo, todo\011es posible.",
  ["68:597d"] = "Es muy duro llegar\na ser un buen\011entrenador.\012Tengo que luchar\ncontra más gente\011para mejorar.",
  ["15:5f08"] = "Me encantan los\nPOKéMON fuertes.\012Les doy PROTEÍNAS\npara mejorar su\011ATAQUE.",
  ["68:595f"] = "¡Qué extraño!\n¡Creí que ganaría!",
  ["15:5f52"] = "El HIERRO mejora\nsu DEFENSA.",
  ["68:5928"] = "Eres un entrenador\nPOKéMON, ¿verdad?\012¡Pues entonces\nluchemos!",
  ["26:5cd5"] = "Si usas REVIVIR,\nel POKéMON\012debilitado se\nreanimará.",
  ["68:58c2"] = "¿Debo tener más\nPOKéMON para poder\011luchar mejor?\012¡No! ¡Continuaré\nsólo con éste,\011pase lo que pase!",
  ["26:5e65"] = "Me alegro de que\nhayas venido.\012Aquí en IRIS, los\nPOKéMON son\011venerados.\012Se dice que un\nPOKéMON de los\012colores del arco\niris aparecerá\012ante un verdadero\nentrenador.\012Yo creo en esa\nhistoria y, por\012eso, llevo entre-\nnándome aquí toda\011mi vida.\012Así que ahora\npuedo ver cosas\011que otros no ven.\012Sólo un poco más…\012Con un poco más,\npodría ser yo\012quien viera al\nPOKéMON de los\012colores del arco\niris.\012¡Ayúdame a alcan-\nzar ese nivel!",
  ["68:58a2"] = "¡Argh! ¡He perdido\nde nuevo!",
  ["15:6143"] = "Hola. ¡Oh, tus\nPOKéMON…!",
  ["68:5849"] = "Acabo de perder\ny estoy buscando\011más POKéMON.\012¡Espera! ¡Pareces\ndébil! ¡Venga,\011luchemos!",
  ["15:615a"] = "Están muy unidos\na ti.\012Este movimiento\nsería perfecto\011para vosotros.",
  ["68:581c"] = "¿Qué? ¡Es un\ngran combate!\011¡Déjame en paz!",
  ["17:438f"] = "La pegatina de la\nPOKéDEX del otro\012chico será mía,\nsi gano.",
  ["68:5806"] = "¡Ve, RATTATA!\012¡PLACAJE!",
  ["15:61d8"] = "Parece malvado.\n¿Qué te parece\011esta MT para él?",
  ["68:55b9"] = "RUTA 29\012CIUDAD CEREZO -\nPUEBLO PRIMAVERA",
  ["17:4416"] = "PERSIAN: ¡Persiia!",
  ["68:558e"] = "RUTA 29\012CIUDAD CEREZO -\nPUEBLO PRIMAVERA",
  ["15:6241"] = "REGALO MISTERIOSO.\012Con un simple\nbeep, recibes\012un regalo. Búscalo\nen el menú.",
  ["68:5559"] = "MARTA: Hoy no es\nmartes. ¡Qué\011pena…!",
  ["17:447e"] = "El mundo POKéMON\nes muy amplio.\012Y sigue habiendo\nmuchas cosas que\011ignoramos.\012¡Pero yo sé\nmás que tú!",
  ["68:54e7"] = "MARTA: ¿Has visto\na LUNA, mi hermana\011mayor?\012¿O a mi hermano\npequeño, MIGUEL?\012Soy la segunda de\nsiete hermanos.",
  ["15:62ad"] = "Los domingos viene\nuna señora a\011examinar POKéMON.\012¡Regala\nhasta las MT!",
  ["68:546f"] = "MARTA: ¿No\ncrees que es\011adorable?\012Fortalece los\nataques normales.\012Seguro que te\nserá muy útil.",
  ["1e:5b8d"] = "Eso es una\nPIEDRAETERNA.\012Algunos POKéMON\nevolucionan al\012alcanzar ciertos\nniveles.\012Si un POKéMON\nva equipado con la\012PIEDRAETERNA,\nno evolucionará.\012Dásela al POKéMON\n\nque no quieras que\011evolucione.",
  ["66:437b"] = "Entrar ahí es muy\npeligroso, por eso\011estoy de guardia.\012¿A que soy un\nbuen samaritano?",
  ["1e:5c37"] = "ELM: {PLAYER},\nsi surge algo,\011te llamaré.",
  ["66:43c7"] = "¿Sabes algo sobre\nlas COLASLOWPOKE?\012¡Dicen que son\nmuy sabrosas!\012¿Contento de que\nte lo haya dicho?",
  ["15:64cb"] = "¡Una máquina\nexpendedora!",
  ["66:441b"] = "Los SLOWPOKE han\ndesaparecido del\011pueblo…\012Dicen que venden\nsus COLAS en algún\011lugar.",
  ["15:64ef"] = "¡Clang! ¡Salió\nuna lata de\011{STRBUF}!",
  ["66:4473"] = "Los SLOWPOKE\nhan vuelto.\012Conociéndolos,\nquizá han estado\012remoloneando en\nalgún lugar.",
  ["15:6512"] = "¡Uups! No tienes\nbastante dinero.",
  ["68:52d9"] = "Quería descansar\nun poco, así que\012guardé la\npartida.",
  ["15:652b"] = "No hay sitio\npara nada más.",
  ["68:526c"] = "¿Ves esos setos?\nDa miedo\011saltarlos.\012Pero puedes ir a\nPUEBLO PRIMAVERA\012sin pasar por\nla hierba.",
  ["15:654b"] = "¿Escuchas el CANAL\nde la SUERTE?\012Si quieres ganar,\ncambia POKéMON\012con mucha gente\npara conseguir\011muchos números ID.",
  ["68:5214"] = "¿Cómo están tus\nPOKéMON?\012Si están débiles y\nno pueden luchar,\012no entres en\nla hierba.",
  ["15:65ca"] = "Si estás cansado,\nprueba las bebidas\011de las máquinas.\012A tus POKéMON\nles gustarán.",
  ["68:51e3"] = "¿Qué? ¿Quieres que\nte enseñe a\011atrapar POKéMON?",
  ["15:661a"] = "¡Descansa de las\ncompras!\012P5 PLAZA TRANQUILA",
  ["68:5197"] = "¡Ah! ¡Muy bien!\012Pero si quieres\natrapar POKéMON,\012tendrás que\ncaminar mucho.",
  ["15:677f"] = "Uf, estoy cansada.\nA veces vengo a la\012azotea a tomarme\nun respiro.",
  ["68:514d"] = "Así es como\nse hace.\012Si los debilitas,\nlos POKéMON\012son más fáciles\nde atrapar.",
  ["15:67d2"] = "¿Perdona? ¿Quién\ndijo que un adulto\012no podía meterse\nen esto?\012¡Voy a volver\ntodos los días\012para coleccionar\ntodos los muñecos!",
  ["68:50df"] = "Te he visto un par\nde veces. ¿Cuántos\012POKéMON has\natrapado?\012¿Quieres que te\nenseñe a atrapar\011POKéMON?",
  ["15:6839"] = "Aquí suelen tener\ngangas a menudo.",
  ["68:50a7"] = "Los POKéMON se\nesconden en la\012hierba. Nadie sabe\ncuando salen…",
  ["15:6867"] = "¡Oh, uau!",
  ["68:4e7f"] = "CATARATAS TOHJO\012La conexión entre\nKANTO y JOHTO",
  ["15:6871"] = "¿Vas a dejarme\nen paz?",
  ["5d:4ec5"] = "¡Volvamos a luchar\nalgún otro día!",
  ["15:688e"] = "Hay algo que\nquiero realmente,\012pero no tengo el\ndinero suficiente…\012Es posible que\nvenda las BAYAS\011que he recogido…",
  ["1e:624c"] = "{PLAYER} abrió\nun libro.\012Pista de viaje 1:\012Pulsa START para\nabrir el MENÚ.",
  ["15:6901"] = "¡Oh, todo está tan\nbarato!\012¡Compré tanto que\nmi MOCHILA está\011abarrotada!",
  ["1b:5bca"] = "¡Oh! ¿Un niño?\nNo me gusta,\012pero debo\neliminarte.",
  ["15:6942"] = "Mis POKéMON quedan\nparalizados o\012envenenados cuando\nmenos lo esperas…\012Así que vine a\ncomprar CURA\011TOTAL.\012Me pregunto si\naún quedará…",
  ["1b:5b79"] = "¿Qué? ¿He perdido?",
  ["15:69c3"] = "Con estos\nbinoculares puedo\011ver muy lejos.\012Puede que vea mi\npropia casa.\012¿No es ésa del\ntejado verde?",
  ["1b:5af7"] = "LANCE: {PLAYER},\ntenemos que hacer\012todo lo posible\npor los POKéMON.",
  ["15:6a2b"] = "¡Eh! ¡Hay unos\nentrenadores\012combatiendo en el\ncamino!\012¡Un POKéMON lanzó\nuna ráfaga de\011hojas!\012¡Me están entrando\nunas ganas de\011luchar increíbles!",
  ["1b:5994"] = "{PLAYER}…\012El viaje para ser\nun MAESTRO\012POKéMON es largo\ny difícil.\012Y ya que lo sabes,\n¿quieres seguir?\012…\012Entiendo. No,\ntienes razón.\012Si te rindieras\ntan fácilmente,\012jamás habrías\nperseguido este\012maravilloso\nsueño.\012¡Espero volver\na verte!",
  ["15:6aa6"] = "Un PESCADOR atrapó\nun montón de\011MAGIKARP…\012¡Están SALPICANDO\ntodos a la vez!\012¡Mira, están\nsalpicándolo todo!",
  ["1a:4c51"] = "¿Quieres saber\ncómo educar bien\011a los POKéMON?",
  ["15:6b11"] = "¿Una máquina\nexpendedora de\011muñecos POKéMON?\012Echa dinero y\nmueve la manivela…\012Pero, si está casi\nvacía…",
  ["1a:4dda"] = "He cambiado a mis\nmejores POKéMON\011con mi compañero.",
  ["15:6e50"] = "¡Bienvenido!\012¡Aquí cambiamos\ntus fichas por\011premios fabulosos!",
  ["6a:7806"] = "Los GIMNASIOS\nPOKéMON están allí\012donde se encuentre\nsu LÍDER.\012No es necesario\nun edificio.",
  ["15:6e8b"] = "¿Qué premio\nquieres?",
  ["6b:40ec"] = "Crucé el túnel\ny todavía me\012queda mucha\nenergía.",
  ["15:6ea8"] = "{STRBUF}.\n¿De acuerdo?",
  ["6b:4130"] = "¡Guau! ¡Tienes más\nfuerza que yo!",
  ["15:6ebd"] = "¡Aquí tienes!",
  ["6b:4153"] = "Los MONTAÑEROS\nsomos felices en\011las montañas.",
  ["15:6ecb"] = "¡Vaya! ¡Necesitas\nmás fichas!",
  ["6b:4180"] = "¿Conseguiste un\nDUNSPARCE?\012Yo también.\012Míralo a la luz.\n¡Pone una cara muy\011divertida!",
  ["15:6ee8"] = "Lo siento. No\ntienes más sitio.",
  ["6b:41e7"] = "Uff, uff…\012Por fin he atrave-\nsado esa cueva.\012Era más grande de\nlo que esperaba.\012Estaba tan cansada\nde explorarla, que\011he salido fuera.",
  ["15:6f09"] = "Vale. ¡Guarda tus\nfichas y vuelve\011cuando quieras!",
  ["6b:4279"] = "RUTA 33",
  ["15:6f35"] = "¡Vaya! No tienes\nun MONEDERO.",
  ["6b:4314"] = "Mis POKéMON bicho\nson muy fuertes.\012¡Prepárate para\nperder!",
  ["15:6f55"] = "Yo siempre juego\nen esta máquina.\012Gano más fichas\nque en otras.",
  ["6b:433d"] = "Me vencieron…",
  ["15:6f9e"] = "Me encanta esta\nnueva tragaperras.\012Es más difícil\nque las de\011CIUDAD AZULONA.",
  ["66:5022"] = "Un bello florecer\nFLORISTERÍA",
  ["15:6ff4"] = "Vivir es un juego,\ny yo jugaré hasta\011que no pueda más.",
  ["66:5042"] = "Si quieres, puedo\nenseñar increíbles\012movimientos a tus\nPOKéMON.\012¿Le enseño un\nnuevo movimiento?",
  ["15:702b"] = "Las cartas…\012Las prefiero a las\ntragaperras porque\012son más fáciles\nde acertar.\012Pero se gana\nmucho menos.",
  ["66:5090"] = "Te costará 4000\nfichas. ¿Vale?",
  ["15:7097"] = "¡No pararé hasta\nque gane!",
  ["66:50b4"] = "Auu… Pero\nson increíbles…",
  ["15:70b1"] = "Enseñé VENTISCA a\nmi POKéMON.\012Ha sido difícil\nganar bastantes\012fichas pero ha\nmerecido la pena.",
  ["66:50ce"] = "¡Uajajaja! ¡No lo\nlamentarás!\012¿Qué movimiento\ndebo enseñar?",
  ["15:710d"] = "No gané en las\ntragaperras y\012lo perdí todo en\nlas cartas…\012Me enfadé tanto\nque tiré mi\012MONEDERO al\nSUBTERRÁNEO.",
  ["66:5107"] = "Mm, qué mal.\nTendré que coger\012algo de dinero de\ncasa…",
  ["15:718a"] = "¡Uajaja! ¡Más fi-\nchas, más fichas!",
  ["66:513a"] = "Si comprendes lo\nincreíble de este\012movimiento, tu\nentrenamiento será\011de alto nivel.",
  ["15:71af"] = "Alguien se dejó la\nbebida.\012Huele dulce.",
  ["1b:55d8"] = "LANCE: Funcionó.\nHemos derrotado\012a todos estos\nROCKETS.\012Pero me preocupa\nese joven contra\011el que luché…",
  ["16:40c7"] = "¿Eh? Es una\nPOKéDEX, ¿verdad?\011¿Puedo verla?\012Hay muchos tipos\nde POKéMON.\012¿Y esto qué es?\012¿Cuál es este\nPOKéMON?\012Se parece a las\nraras escrituras\012de las paredes\nde las RUINAS.\012Si esos dibujos\nson POKéMON,\012debería haber\nmuchos más.\012¡Ya sé! Voy a\nactualizar tu\011POKéDEX. Sígueme.",
  ["1b:4c16"] = "Bien. Te contaré\nun secreto sobre\011nuestra guarida.\012Eso que hay en\nel suelo es un\011panel deslizante.\012Si te colocas\nencima, te\012llevará de vuelta\na la entrada.",
  ["16:42eb"] = "¡Mmm…! ¡Qué\nlugar tan extraño!",
  ["1b:4494"] = "El experimento\nfuncionó a las mil\011maravillas.\012Los MAGIKARP no\nvalen nada, pero\012los GYARADOS son\nmuy productivos.",
  ["16:430b"] = "…",
  ["1b:427e"] = "Las MEDALLAS de\nGIMNASIO te dan\012ventaja en los\ncombates.",
  ["16:430e"] = "Me gusta pensar\naquí.",
  ["1b:41f3"] = "Quiero ver el\nMAGNETOTRÉN…",
  ["16:4325"] = "SALA DEL PANEL DE\nPIEDRA MISTERIOSO",
  ["1b:4167"] = "Somos la\nFEDERACIÓN\012POKéMON de KANTO.\n¡Allá vamos!",
  ["16:4342"] = "RUINAS ALFA\n¡Bienvenidos!",
  ["1b:40c8"] = "¡Viva la\nFEDERACIÓN\011POKéMON de KANTO!",
  ["16:4362"] = "C. INVESTIGACIÓN\nDE LAS RUINAS ALFA\012La Autoridad en\nlas RUINAS ALFA",
  ["1a:405a"] = "No se puede hacer\ntrampa en POKéMON.\012¡Que quede bien\nclaro!",
  ["16:43a4"] = "Mientras explorá-\nbamos las RUINAS,\012de repente notamos\nuna extraña\011presencia.\012Nos asustamos y\nhuimos.\012Tu también debes\ntener cuidado.",
  ["15:6364"] = "Personaliza a tus\nPOKéMON\012P4 TIENDA DE MT",
  ["16:4420"] = "¡Las RUINAS\nesconden un gran\011secreto!\012Creo…",
  ["19:71a4"] = "Y, y…\n¡Acabo de derrotar\011a {STRBUF}!\012¡He entrenado bien\na mis POKéMON!",
  ["16:4449"] = "Hay muchas clases\nde UNOWN, así que\012los utilizamos\ncomo nuestro\011código secreto.",
  ["63:49bf"] = "DÉBORA: Siento\ntodo esto.\012Toma esto en señal\nde disculpa.",
  ["16:448e"] = "A… D… E… L…\nA… N… T… E…\011Mmmmmm…\012¿Qué?\012¡Estoy decodifi-\ncando el mensaje!",
  ["63:4a0d"] = "Esta MT contiene\nDRAGOALIENTO.\012No, no tiene\nnada que ver\011con mi aliento.\012Si no la quieres,\nno es necesario\011que la aceptes.",
  ["16:4612"] = "Aparecieron\ndibujos en las\011paredes…",
  ["63:52ea"] = "Mmm… Encantado\nde verte.\012No necesitas\nexplicarme por qué\011has venido.\012DÉBORA te envía,\n¿verdad?\012Esa chica es muy\ntraviesa…\012Lo siento, pero\ndebo probarte.\012No te preocupes.\nSólo deberás\012contestar unas\npocas preguntas.\012¿Ya?",
  ["16:4644"] = "Aparecieron\ndibujos en las\011paredes…",
  ["16:4665"] = "¡Hay un gran agu-\njero en la pared!",
  ["66:74c8"] = "Si pasas por aquí,\nespero que vengas\011a visitarme.",
  ["16:4685"] = "Es una réplica\nde un antiguo\011POKéMON.",
  ["66:74fc"] = "OAK: ¡Uau!\n¡Excelente!\012Has conseguido las\nMEDALLAS de todos\012los GIMNASIOS de\nKANTO. ¡Muy bien!\012Sabía que\neras bueno.\012¿Sabes qué,\n{PLAYER}? Arreglaré\012todo para que\npuedas ir a MONTE\011PLATEADO.\012MONTE PLATEADO es\nuna gran montaña\012llena de\nPOKéMON salvajes.\012Es muy peligroso\npara un entrenador\012normal, así que\nestá prohibido ir.\012Pero en tu caso,\n{PLAYER}, haremos\011una excepción.\012Sube hasta la\nMESETA AÑIL. Desde\012allí puedes llegar\na MONTE PLATEADO.",
  ["16:46aa"] = "Un POKéMON que\nvuela elegante,\012con alas de color\narcoiris.",
  ["66:76a2"] = "OAK: ¿Cómo? ¿No\nhas conseguido las\011MEDALLAS DE KANTO?\012Los LÍDERES de los\nGIMNASIOS de KANTO\012son tan fuertes\ncomo los de JOHTO.\012Te aconsejo que\nte enfrentes a\011ellos.",
  ["16:4800"] = "Bienvenidos a esta\ncámara.\012Hay paneles móvi-\nles que muestran\012a un POKéMON\ndibujado por los\011antepasados.\012Mueve los paneles\npara formar el\011dibujo.\012A la derecha hay\nuna descripción\011del POKéMON.\012El científico\ndel fondo está\012examinando unos\ndibujos nuevos.",
  ["66:773c"] = "OAK: ¿Quieres\nconseguir las\011MEDALLAS DE KANTO?\012No será fácil,\npero la\012experiencia\ntambién cuenta.\012Ven a verme cuando\nlas tengas todas.\011Te haré un regalo.\012¡Sigue así,\n{PLAYER}!",
  ["16:48f5"] = "Recientemente,\nunos misteriosos\012dibujos han\naparecido.\012Es raro. Hace un\nrato no estaban\011aquí…\012Debes echar un ojo\na las paredes.",
  ["66:77fb"] = "El programa de\nla HORA POKéMON\012del PROF. OAK\nno se emite aquí,\011en KANTO.\012¡Qué pena! ¡Me\ngustaría oírlo!",
  ["16:497c"] = "¡Ah! ¡Hay otro\ngran agujero!\012¡Es tan grande que\nse puede pasar por\011él!",
  ["66:7859"] = "Gracias a tu\ntrabajo en la\012POKéDEX, la\ninvestigación del\011PROF. ha avanzado.",
  ["16:49b8"] = "¡Ese temblor me\nasustó mucho!\012Pero me preocupa\nmucho más este\011muro de aquí…",
  ["66:78a7"] = "No se lo digas a\nnadie, pero la\012HORA DE OAK\nno es en directo.",
  ["16:4aa7"] = "Aparecieron\ndibujos en las\011paredes…",
  ["16:4ad9"] = "Aparecieron\ndibujos en las\011paredes…",
  ["16:4afa"] = "¡Hay un gran agu-\njero en la pared!",
  ["16:4b1a"] = "Es una réplica\nde un antiguo\011POKéMON.",
  ["16:4b3f"] = "Un POKéMON que se\noculta en el mar.\012Con sus ojos\nexplora la zona.",
  ["66:7945"] = "Aquí dentro no\nhay nada…",
  ["16:4c8e"] = "Aparecieron\ndibujos en las\011paredes…",
  ["16:4cc0"] = "Aparecieron\ndibujos en las\011paredes…",
  ["16:4ce1"] = "¡Hay un gran agu-\njero en la pared!",
  ["16:4d01"] = "Es una réplica\nde un antiguo\011POKéMON.",
  ["16:4d26"] = "Este POKéMON\nflota a la deriva\012moviendo sus\ndiez tentáculos.",
  ["67:426f"] = "¡De acuerdo!\n¡Sígueme!",
  ["16:4e4f"] = "Aparecieron\ndibujos en las\011paredes…",
  ["16:4e81"] = "Aparecieron\ndibujos en las\011paredes…",
  ["16:4ea2"] = "¡Hay un gran agu-\njero en la pared!",
  ["16:4ec2"] = "Es una réplica\nde un antiguo\011POKéMON.",
  ["16:4ee7"] = "Este POKéMON\nvolador ataca a\012su presa con sus\nfuertes colmillos.",
  ["67:4359"] = "La RUTA 30 está\npor aquí.\012En ella luchan\nlos entrenadores\012con sus queridos\nPOKéMON.",
  ["16:4f89"] = "Siento una\nrara presencia…",
  ["67:43a7"] = "Como puedes ver,\nesto es el mar.\012Algunos POKéMON\nsólo viven en\011el agua.",
  ["16:4fac"] = "Esta habitación es\nmuy grande, pero\011aquí no hay nada.",
  ["67:43ec"] = "Y…\012¡Ésta es mi casa!\nGracias por\011acompañarme.\012Déjame darte\nun regalito.",
  ["16:4fda"] = "Este lugar está\nimpregnado de\011misticismo.\012Parece hasta\netéreo.",
  ["67:4438"] = "¡Ahora el POKéGEAR\nde {PLAYER}\011tiene un MAPA!",
  ["16:5024"] = "Los edificios\nantiguos suelen\012ser tumbas\nde reyes.\012Como por ejemplo,\nlas pirámides.",
  ["67:4451"] = "El POKéGEAR será\nmás útil cuando\011añadas TARJETAS.\012¡Mucha suerte\nen tu aventura!",
  ["16:5072"] = "Es una réplica\nde un antiguo\011POKéMON.",
  ["16:5278"] = "¡Ya está!\012He modificado\ntu POKéDEX.\012Añadí una\nPOKéDEX opcional\012para guardar los\ndatos de UNOWN.\012Los registra en\nel orden en que\011son atrapados.",
  ["68:42df"] = "Si usas VUELO,\npodrás volver a\012CIUDAD OLIVO\nenseguida.",
  ["16:52fa"] = "Mejorada POKéDEX\nde {PLAYER}.",
  ["68:4277"] = "Mi marido perdió\ncontra ti. Debería\011entrenarse más.\012Menos mal, porque\nya estaba\011engordando.",
  ["16:5311"] = "Todos los UNOWN\nque atrapes serán\011registrados aquí.\012A ver cuántos\ntipos existen.",
  ["68:421d"] = "Enseña VUELO a\ntus POKéMON.\012En un instante\npodrás VOLAR a\012cualquier lugar al\nque ya hayas ido.",
  ["16:535f"] = "¿Atrapaste a todos\nlos UNOWN?\012¡Es un gran\nlogro!\012He ajustado la\nimpresora para\011UNOWN.\012Puedes usarla\ncuando quieras.",
  ["68:41e3"] = "¡Es la MEDALLA de\nCIUDAD ORQUÍDEA!\012¡Toma esta\nMO!",
  ["16:53ed"] = "Las RUINAS datan\nde hace unos\t1.500 años.\012Pero ignoramos\npor qué o por\012quién fueron\nconstruidas.",
  ["68:4163"] = "Pero no puedes\nusar VUELO sin la\012MEDALLA de esta\nciudad.\012Si vences al LÍDER\nde este GIMNASIO,\011ven a verme.\012Te daré un\nbonito regalo.",
  ["16:5445"] = "¿Cuántos tipos de\nPOKéMON habrá\011en las RUINAS?",
  ["67:4650"] = "¿Has hablado con\nel anciano que\012está cerca del\nCENTRO POKéMON?\012Te dará un MAPA\nde JOHTO para tu\011POKéGEAR.",
  ["16:5478"] = "¿Hay POKéMON\nen las RUINAS?\012¡Qué noticia\ntan increíble!\012Tendremos que\ninvestigarlo.",
  ["67:46a8"] = "Cuando vas con los\nPOKéMON, cualquier\011sitio está bien.",
  ["16:54cb"] = "Nuestra investiga-\nción, con tu\012ayuda, nos está\nreportando infor-\011mación acerca de\011las RUINAS.\012Las RUINAS parecen\nhaber sido cons-\011truidas como un\011hábitat para\011POKéMON.",
  ["67:46d6"] = "La casa del SR.\nPOKéMON está\011más adelante.",
  ["16:554f"] = "En las paredes de\nlas RUINAS hay\012unos dibujos\nmuy raros.\012Son la clave\npara resolver\012el misterio\nde las RUINAS.",
  ["67:4701"] = "He luchado contra\nlos entrenadores\011del camino.\012Mis POKéMON han\nperdido. ¡Están\012fatal! Los llevaré\nal CENTRO POKéMON.",
  ["16:55cb"] = "¿Los POKéMON\nraros que viste\011en las RUINAS?\012Son muy parecidos\na los dibujos de\012esas paredes\nde ahí.\012¡Mmm…!\012Debe de significar\nque hay muchos\011tipos diferentes…",
  ["67:4766"] = "Atrapé un POKéMON\ncon un objeto.\012Creo que es\nAGUA MÍSTICA.\012No lo necesito,\n¿lo quieres?",
  ["16:5769"] = "¿Por qué estos\nantiguos dibujos\012aparecen ahora en\nel muro?\012Esto es cada vez\nmás misterioso…",
  ["67:47c1"] = "Pues yo me\nvoy a pescar.",
  ["16:57b6"] = "RUINAS ALFA\n10 Años\nde Exploración",
  ["67:47e0"] = "CIUDAD CEREZO\012La ciudad de las\nflores bonitas y\011fragantes",
  ["16:57d9"] = "Nombre de POKéMON\nmisterioso: UNOWN\012Encontrados un\ntotal de 26 tipos.",
  ["67:4815"] = "CASA DEL GUÍA",
  ["16:580e"] = "Parece que esto\naún no funciona.",
  ["67:4a80"] = "He estado cogiendo\ndatos de POKéMON\012de mi radio. Creo\nque soy bueno.",
  ["16:582d"] = "Se puede imprimir\nUNOWN.",
  ["67:4abb"] = "¡Me rindo!",
  ["16:5886"] = "Hay muchos libros\nacadémicos.\012Ruinas Antiguas…\nLos Misterios de\011los Antiguos…",
  ["67:4ac4"] = "La música de la\nradio cambia el\012ánimo de los\nPOKéMON salvajes.",
  ["16:5923"] = "Es una réplica\nde un antiguo\011POKéMON.",
  ["16:59ad"] = "Es una réplica\nde un antiguo\011POKéMON.",
  ["16:5a37"] = "Es una réplica\nde un antiguo\011POKéMON.",
  ["67:4b23"] = "Ojalá hubieras\nperdido por mí…",
  ["68:40f1"] = "¿Has cruzado el\nmar para llegar\012hasta aquí? ¡Habrá\nsido duro!\012Todo sería mucho\nmás fácil si tus\012POKéMON supieran\nVUELO…",
  ["67:4b47"] = "Me humillaste\ndelante de mi\011novia…",
  ["67:7567"] = "CASA DEL MAR\nCASA DE BILL",
  ["67:4b74"] = "Mi novio es débil.\nAsí que no puedo\011confiar en él.",
  ["67:7520"] = "¡Ha sido\nfantástico!\012Tus POKéMON y tú\nsois realmente\011buenos.",
  ["67:4ba0"] = "¡Cielos! ¡Eres tan\nfuerte!",
  ["67:74fd"] = "¡Nunca había visto\nnada igual!",
  ["67:4bba"] = "Confío más en\nmis POKéMON\011que en mi novio.",
  ["67:749d"] = "Pero después de\nverte luchar, me\012gustaría saber\ncómo me iría a mí.\012Déjame luchar\ncontra ti.",
  ["67:4bea"] = "¿Vas al GIMNASIO?\n¡Yo también!",
  ["64:4f49"] = "En la hierba hay\ncosas pegajosas.",
  ["67:4c0d"] = "¡Vaya! No pude\nganar…",
  ["64:4f8c"] = "¡Mmmm! ¡Qué\ndecepción!",
  ["67:4c21"] = "Me gustan las\nMEDALLAS de\012los GIMNASIOS.\nLas colecciono.",
  ["64:4fdf"] = "Sí. Y sabes\nque…\012¿Luchar? ¡Estoy\nal teléfono!\012Vale. Pero que\nsea rápido.",
  ["67:4c4d"] = "¿Qué tipo de\nPOKé BALL usas?",
  ["64:5060"] = "Yo también estaba\ncharlando.",
  ["67:4c6e"] = "¡Vaya! ¡No lo\nbastante rápido!",
  ["64:507f"] = "¡Esa MEDALLA! ¡Es\nde CIUDAD MALVA!\012¿Ganaste a PEGASO?",
  ["67:4c87"] = "Algunos POKéMON\nhuyen enseguida.\012Intenta atraparlos\ncon la RAPID BALL\011de CÉSAR.\012Cuando encuentro\nun BONGURI BLA, se\011lo llevo a CÉSAR.\012Él lo convierte en\nuna POKé BALL.",
  ["64:50d4"] = "Debería volver a\nentrenarme en el\012GIMNASIO de\nCIUDAD MALVA.",
  ["67:4d1e"] = "¡Observa cómo uso\nlas POKé BALL!",
  ["64:518c"] = "¡GRRR!\n¡ES RUGIDO! HASTA\012LOS POKéMON HUYEN\nCON UN RUGIDO.",
  ["67:4d42"] = "¡Uauuu! ¡Vaya\nsacudida!",
  ["64:51c1"] = "VICKI: ¡Yuju!\n¡Es viernes!\012Soy VICKI, por\nviernes.\012¡Mucho gusto!",
  ["67:4d5a"] = "Quería\nimpresionarte con\011mi premio POKéMON.\012¡Pero tu habilidad\nme ha electrizado!",
  ["64:5222"] = "VICKI: Dásela a un\nPOKéMON de tipo\011veneno.\012¡Oh!\012¡Es terrible!\012¡Te sorprenderá\nver cómo mejora\012los movimientos\nde tipo veneno!",
  ["67:4daa"] = "Iré a cualquier\nlugar donde haya\011POKéMON bicho.",
  ["64:52ff"] = "VICKI: ¿Hoy no\nes viernes?\012¡Me aburro cuando\nno lo es!",
  ["67:4dd5"] = "¿Eh? No debería\nhaber perdido…",
  ["64:533a"] = "RUTA 32\012CIUDAD MALVA -\nPUEBLO AZALEA",
  ["67:4df6"] = "Mi VENONAT ganó\nel Concurso de\012Captura de Bichos\ndel PARQUE\011NACIONAL.",
  ["64:537b"] = "Hacia la\nCUEVA UNIÓN",
  ["67:4e38"] = "Uauu… ¡Mira todos\nesos YANMA!\012Estoy tan\nalucinado, que no\011me puedo mover.",
  ["64:55a3"] = "Es una foto de\ngente pescando…\012Lo están pasando\nmuy bien…",
  ["67:4e76"] = "Practico mi\naliento de fuego.",
  ["64:5620"] = "Hay un POKéMON\ndormido delante de\011la CUEVA DIGLETT.\012¡El momento ideal\npara atraparlo!\012¿Pero cómo\ndespertarlo?",
  ["17:44f3"] = "Hay muchas cosas\nque aprender.\012Por ejemplo…\012Hay 50 tipos de\nMT.\012Los POKéMON\nintercambiados\012suben antes de\nnivel.",
  ["64:56fe"] = "El FERRY es un\nbuen lugar para\012conocer y luchar\ncon entrenadores.",
  ["17:4552"] = "Mis POKéMON son\nencantadores.\012Déjame mostrarte\nlo orgullosa que\011estoy de ellos.",
  ["64:5881"] = "Soy el PRESIDENTE\ndel CLUB de FANS\011de POKéMON.\012He curado a más\nde 150 POKéMON.\012Soy muy exigente\ncuando se trata de\011POKéMON.\012¿Has venido\npara saber\011de mis POKéMON?",
  ["17:459e"] = "Puedo derrotarte,\npero…",
  ["64:5911"] = "¡Muy bien!\n¡Pues escucha!\012Mi… preferido\nes RAPIDASH…\012Es… gracioso…\ncariñoso… veloz\011e increíble…\011¿No crees…? Es\011sorprendente…\011simpático…\011¡Y lo quiero!\012Si lo abrazas…\ncuando duerme…\011es tan cálido…\011y mimoso… Es\011espectacular…\011encantador…\011¡Uuups! ¡Mira qué\011hora es! ¡Hablo\011demasiado!",
  ["17:45bd"] = "Debo decirte que\ntus POKéMON son\011bonitos también.",
  ["64:5a72"] = "Es un CARAMELORARO\nque fortalece a\011los POKéMON.\012Prefiero que mis\nPOKéMON luchen\012para fortalecerse.\n¡Así que toma!",
  ["17:45e9"] = "Queremos a\nnuestros POKéMON,\012aunque ellos\nno nos quieran.\012Eso significa ser\nun FAN POKéMON.",
  ["69:421a"] = "La torre que\nhabía aquí…\012Mi abuela me dijo\nque era mucho\011más alta.",
  ["17:4639"] = "¡M-mi POKéMON!",
  ["69:4269"] = "Tres POKéMON\nhuyeron en tres\012direcciones.\n¿Qué eran?",
  ["17:4645"] = "Perdí el combate,\npero mis POKéMON\012son más adorables\nque los tuyos.",
  ["69:42ac"] = "He oído un rumor\nsobre el FARO\011OLIVO.\012El POKéMON que\nusan como luz\012ha caído enfermo.\nParece que tienen\011problemas.",
  ["17:468a"] = "¡Mi amigo tiene un\nMARILL!\012Los encuentro muy\nsimpáticos.\012Oh, deseo tener un\nMARILL propio…",
  ["69:4325"] = "El POKéMON de\nFARO OLIVO se\011ha curado.\012Los barcos pueden\nvolver a navegar\011seguros de noche.",
  ["17:46e4"] = "¿Hola?\n¿Y tú que miras?\012¿Quieres luchar?",
  ["69:4386"] = "Los POKéMON están\ncausando estragos\012en el LAGO DE\nLA FURIA. Me\011encantaría verlo.",
  ["17:4715"] = "¡Mmmm…!",
  ["69:43cb"] = "Hace mucho, mucho\ntiempo…\012Esta torre ardió\npor el fuego. Tres\012POKéMON descono-\ncidos perecieron\011en ella.\012Un POKéMON con los\ncolores del arco\012iris bajó del\ncielo y los\011resucitó…\012Es una leyenda que\nha ido pasando de\012LÍDER a LÍDER en\nel GIMNASIO IRIS.\012¿Yo?\012Yo sólo soy un\nentrenador.\011¡Jo, jo, jo!",
  ["17:471d"] = "¡Pensaba que me\nestabas mirando\011porque soy bonita!",
  ["69:44d1"] = "CIUDAD IRIS\nUna ciudad donde\012conviven el pasado\ny el presente",
  ["17:4750"] = "PLAZA DEL DESCANSO\nPARQUE NACIONAL",
  ["69:4513"] = "TORRE HOJALATA\012Aquí duerme un\nPOKéMON\011legendario.",
  ["17:4771"] = "¿Qué dice\neste cartel?\012Por favor, lucha\nsólo en la hierba.\012PUESTO DEL GUARDA\nPARQUE NACIONAL",
  ["69:4548"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\011IRIS: MORTI\012El místico adivino\ndel futuro",
  ["17:47c6"] = "PISTAS ENTRENADOR\012Imprime una CARTA\nabriéndola y\011pulsando START.",
  ["69:458c"] = "TEATRO DE DANZA\nDE CIUDAD IRIS",
  ["17:494c"] = "RAFA: ¡Voy a\nganar! No me\011molestes.",
  ["69:45a4"] = "TORRE QUEMADA\012Destruida por\nun misterioso\011incendio.\012¡Atención!\n¡Peligro!",
  ["17:4973"] = "SAM: Mi PARASECT\nduerme a los\012POKéMON con\nESPORA.",
  ["69:477a"] = "Lo siento.\012DÉBORA, la LÍDER\ndel GIMNASIO, está\012en la GUARIDA\nDRAGÓN, detrás del\011GIMNASIO.\012No tengo ni idea\nde cuándo volverá\011nuestra LÍDER.",
  ["17:49a3"] = "NANO: Entreno a\nPOKéMON rápidos\011para luchar.",
  ["69:47f3"] = "DÉBORA, la LÍDER\ndel GIMNASIO, te\011espera.\012Aunque, a alguien\ncomo tú le será\011imposible ganar.",
  ["17:49cc"] = "GUILLE: No me\nimporta ganar.\012Sólo busco\nPOKéMON raros.",
  ["69:4865"] = "¿Has vencido a\nDÉBORA?\012¡Impresionante!\012Nunca oí que\nperdiera contra\012nadie, excepto\ncontra LANCE.",
  ["17:4a15"] = "TINO: ¡Ssh! Vas a\nasustar a SCYTHER.\012Hablaré contigo\ndespués.",
  ["69:48c3"] = "No. Sólo los\nelegidos pueden\012entrenarse aquí.\nPor favor, vete.",
  ["17:4a52"] = "BENITO: Debilita a\nlos POKéMON bicho\012y lánzales una\nPARQUE BALL.",
  ["69:48fb"] = "Si DÉBORA lo\npermite, su\012abuelo, nuestro\nMAESTRO, también.\012Puedes entrar.",
  ["17:4a8f"] = "CINDY: Me gustan\nlos POKéMON bicho.\012Seguro que a ti\ntambién.",
  ["69:494a"] = "¿Mi radio está\nrota? Sólo recibo\011esta rara señal.",
  ["17:4ac8"] = "KAI: Colecciono\nPOKéMON bicho\012desde que era\nsólo un niño.\012¡Es imposible\nque pueda perder!",
  ["69:4983"] = "¡Auu! ¡Voces en\nmi cabeza! ¿Cómo?\012¡Estoy escuchando\nla radio!",
  ["17:4b25"] = "SAMUEL: Si tienes\ntiempo para\012conversar, busca\nPOKéMON bicho.",
  ["69:49bd"] = "¿Quieres que\ntus POKéMON\012olviden algún\nmovimiento?",
  ["17:4b64"] = "KOLDO: Soy un gran\nestudioso de los\011POKéMON bicho.\012Seguro que\ngano.",
  ["69:49f1"] = "Todos los expertos\nen dragones vienen\011de CIUDAD ENDRINO.",
  ["17:4ba7"] = "PLAZA DEL DESCANSO\nPARQUE NACIONAL",
  ["17:4bc8"] = "¿Qué dice\neste cartel?\012Por favor, lucha\nsólo en la hierba.\012PUESTO DEL GUARDA\nPARQUE NACIONAL",
  ["17:4c1d"] = "PISTAS ENTRENADOR\012Imprime una CARTA\nabriéndola y\011pulsando START.",
  ["17:4e77"] = "¡Bienvenido!",
  ["64:4acf"] = "¡Vaya! Pensaba que\nlos niños de hoy\012en día estaban\nforrados…",
  ["17:4e81"] = "Hola. Lo siento\npero hoy no\012se admiten\nvisitas.",
  ["64:4afc"] = "¿No la quieres?\nPues lárgate.",
  ["17:4eba"] = "¿Quieres probar\nen el NÚMERO DE\011LA SUERTE?\012¿Compruebo los\nnúmeros ID de\011tus POKéMON?\012Si tienes suerte,\nganarás un premio.",
  ["64:4b21"] = "¡Vaya!\012¡Se me escapó ese\npez por tu culpa!",
  ["17:4f3a"] = "El número de esta\nsemana es {STRBUF}.",
  ["64:4b44"] = "¡Splash!",
  ["17:4f5a"] = "A ver si coincide\ncon tu número.",
  ["64:4b4e"] = "Paciencia… La\nbase de la pesca\012y de los POKéMON\nes la misma.",
  ["17:4f79"] = "……\n……",
  ["64:4b8f"] = "Soy muy bueno,\ntanto pescando\012como con los\nPOKéMON.\012¡No voy a perder\ncon alguien tan\011joven!",
  ["17:4f7e"] = "Vuelve la próxima\nsemana y participa\012otra vez en el\nNº DE LA SUERTE.",
  ["64:4bda"] = "Intenté acelerar\nlas cosas…",
  ["17:4fb5"] = "¡Uauu! ¡Tus cinco\nnúmeros coinciden!\012¡Ya tenemos un\nganador!\012¡Has ganado una\nMASTER BALL!",
  ["64:4bf8"] = "¡Pescar es una\npasión eterna y\012los POKéMON son\namigos eternos!",
  ["17:5023"] = "¡Oye! ¡Tus tres\núltimos números\011coinciden!\012¡Ganaste el\nsegundo premio:\011REPARTIR EXP!",
  ["64:4c37"] = "Uno, dos, tres…\n¡Jajajajaja!\012¡Qué gran botín!\012¡Vale! ¡Sigue y\natrapa tantos como\011puedas!",
  ["17:5076"] = "¡Ooh! ¡Tus dos\núltimos números\011coinciden!\012Ganaste el tercer\npremio: MÁS PP.",
  ["64:4dcf"] = "¿Mi POKéMON?\n¡Recién pescado!",
  ["17:50c0"] = "¡No! Tus números\nID no coinciden.",
  ["64:4de9"] = "¡Splash!",
  ["17:50e6"] = "No tienes sitio\npara tu premio.\012Hazle sitio y\nvuelve enseguida.",
  ["64:4df2"] = "Los POKéMON\nrecién atrapados\012no son comparables\ncon los criados.",
  ["17:512d"] = "Ahora tenemos\nuna promoción\011especial.\012Acierta estas 5\npreguntas y gana\011una TARJETA RADIO.\012Introdúcela en tu\nPOKéGEAR para oír\012la radio siempre\nque quieras.\012¿Quieres\nparticipar?",
  ["64:4e2e"] = "No te había\nvisto antes.\012¿Te crees\nmuy duro?",
  ["17:51f2"] = "1a Pregunta:\012¿Hay POKéMON que\nsólo aparecen por\011la mañana?",
  ["64:4e73"] = "¡Eres fuerte!",
  ["17:5231"] = "¡Correcto!\n2a Pregunta:\012¿Es verdad que no\npuedes comprar una\012BAYA en una\nTIENDA?",
  ["1b:7394"] = "SANTUARIO del\nENCINAR…\012Construido en\nhonor del guardián\011del bosque…\012¿Oh? ¿Qué es esto?\012Es un agujero.\nParece que la\012GS BALL cabe\ndentro.\012¿Quieres colocar\nla GS BALL aquí?",
  ["17:5282"] = "¡Acertaste!\n3a Pregunta:\012¿Contiene la MO01\nel movimiento\011DESTELLO?",
  ["1b:743b"] = "{PLAYER} coloca la\nGS BALL.",
  ["17:52bc"] = "¡Vas bien!\n4a Pregunta:\012¿PEGASO, el LÍDER\nde GIMNASIO de\012CIUDAD MALVA usa\nPOKéMON pájaro?",
  ["1b:7452"] = "¡Fiuuu, increíble!\012{PLAYER}, ha sido\nfantástico.\011¡Gracias!\012Las leyendas sobre\neste SANTUARIO\012eran ciertas\ndespués de todo.\012Me ha inspirado\nlo que acabo de\011ver.\012¡Me motiva para\nhacer mejores\011BALL!\012¡Voy a ello!",
  ["17:530e"] = "¡Guau! ¡Correcto!\nÉsta es la última\011pregunta:\012¿Sale CHARMANDER\nen las máquinas\012del CASINO de\nCIUDAD TRIGAL?",
  ["1b:7515"] = "¡No me des estos\nsustos!\012¡Un POKéMON ha\nescapado asustado!",
  ["17:537b"] = "¡Bingo!\n¡Enhorabuena!\012Éste es tu premio:\n¡la TARJETA RADIO!",
  ["67:68bb"] = "¿Has estado en la\nTORRE BATALLA?\012Nunca llegué a\nperder allí, pero…",
  ["17:53c0"] = "¡El POKéGEAR de\n{PLAYER} se puede\011usar como radio!",
  ["67:6899"] = "Era fuerte en la\nTORRE BATALLA…",
  ["17:53e5"] = "Sintoniza nuestros\nprogramas.",
  ["67:687f"] = "¡Soy muy, muy\nfuerte!",
  ["17:5409"] = "Lo siento mucho,\npero te has\012equivocado.\n¡Vuelve a probar!",
  ["67:67d1"] = "No soy partidaria\nde los ataques\011demasiado fuertes.\012Quiero ganar, pero\nno quiero herir\011a los POKéMON.",
  ["17:5443"] = "¡Ah! Entiendo.\nVuelve a probar si\011cambias de idea.",
  ["67:67c2"] = "Vale. He perdido.",
  ["17:5476"] = "NARDO es un DJ\nfabuloso.\012¡Su dulce voz\nme derrite!",
  ["67:676f"] = "¿Cuál es tu\nestrategia?\012Es de tontos usar\nataques fuertes\012de forma\nindiscriminada.",
  ["17:54ac"] = "Me gusta ROSA, de\nla HORA POKéMON.\012Aunque sólo\nconozca su voz.",
  ["67:670d"] = "Veo que estás\neducando a tus\012POKéMON\ncon cariño.\012El vínculo que\nos une os salvará\012en las situaciones\ndifíciles.",
  ["17:54f4"] = "¡Por fin nos hemos\napoderado de la\011TORRE de RADIO!\012¡Ahora todos\nexperimentarán el\012verdadero terror\ndel TEAM ROCKET!\012¡Ya veréis qué\nhorribles somos!",
  ["67:66f6"] = "Te has ganado\nmi respeto.",
  ["17:5582"] = "¡Demasiado fuerte!\nTe vigilaremos…",
  ["67:66cb"] = "¿Qué piensas sobre\nla educación\011de los POKéMON?",
  ["17:55a2"] = "Eres muy fuerte.\012Arruinarías\nnuestros planes.\012Mejor alertar a\nlos otros…",
  ["67:666c"] = "¡Descansamos mucho\ndurante la comida,\012así que ya estamos\ntodos listos!\012¡Volvemos al\nentrenamiento!",
  ["17:55e7"] = "PB RECEPCIÓN\nP1 VENTAS\011P2 PERSONAL\011P3 PRODUCCIÓN\011P4 DESPACHO DEL\011   DIRECTOR",
  ["67:6634"] = "Voy a entrenar un\npoco más antes de\011parar a comer.",
  ["17:5631"] = "¡CANAL SUERTE!\012¡Gana con los ID\nde los POKéMON!\012¡Cambia POKéMON\ny reúne diferentes\011números ID!",
  ["67:65e2"] = "Debo tomar\nmedidas extremas.\012Debo ir a los\nmontes y entrenar\011allí, en soledad.",
  ["17:5924"] = "Puedes escuchar la\nradio en cualquier\011lugar. ¡Sintoniza!",
  ["67:65d7"] = "¡Waaaargh!",
  ["17:5956"] = "Las nanas de la\nradio duermen\011a los POKéMON.",
  ["67:659c"] = "Estaba entrenando\naquí solo.\012¡Observa el fruto\nde mi trabajo!",
  ["17:5983"] = "¿Por qué querrían\napoderarse de la\011TORRE de RADIO?",
  ["67:652c"] = "¡No encuentro la\nmanera de ganar!\012¡Sigue así!\012Oh, y toma esto:\nes el regalo que\012no pudiste llevar\nla última vez.",
  ["17:59b6"] = "JIGGLYPUFF:\nJiggly…",
  ["67:64f1"] = "Lo mejor que me ha\npasado nunca fue\012descubrir a los\nPOKéMON.",
  ["17:59cb"] = "¡Aviso!\nProhibido entrar\011sin autorización.\012Antes no\nera así.\012Debe de haber\nalgún problema con\011el DIRECTOR…",
  ["67:64d6"] = "Las derrotas…\n¡También están!",
  ["17:5a44"] = "Puedes mirar por\ntodas partes.\012El DIRECTOR ya\nno está enfadado.",
  ["67:647a"] = "¿Que por qué\nescalo montañas?\012Porque están\nahí.\012¿Que por qué\nentreno POKéMON?\012¡Porque están\nahí!",
  ["17:5a9b"] = "Hace tres años, el\nTEAM ROCKET tuvo\011que separarse.\012¡Pero nos estamos\nvolviendo a\011reunir aquí!",
  ["67:6434"] = "No se me da muy\nbien pensar.\012¡Así que utilizo\nsólo la fuerza!",
  ["17:5af1"] = "¡Bah! ¡No te\nhagas el chulo!",
  ["67:6418"] = "¡Buaaaaa! ¡Soy un\nperdedor!",
  ["17:5b07"] = "¡No permitiremos\nque arruines\011nuestros planes!",
  ["67:63fd"] = "¡Mis POKéMON son\nmuy poderosos!",
  ["17:5b39"] = "¡Somos el\nTEAM ROCKET,\012explotadores de\nlos POKéMON!\012¡Nos gusta ser\nmalos! ¿Asustado?",
  ["67:63b1"] = "¡Cómo me gusta\nMÁS PS! ¡Mmmm!\012¡Me bebo la de mis\nPOKéMON!\012No puedo evitarlo.",
  ["17:5b80"] = "¿Te crees\nun héroe?",
  ["67:6392"] = "¡A mis POKéMON les\nfaltaron agallas!",
  ["17:5b99"] = "No siempre somos\nmalos. Hacemos\011lo que queremos.",
  ["67:633d"] = "¡Eres valiente!\nPero…\012¿Sabes qué?\nPara valiente,\011¡yo!",
  ["17:5bcd"] = "¡Oye! ¡Fuera de\nnuestro camino!",
  ["1d:4ca2"] = "En KANTO hay\nmuchos POKéMON.\012¡Ojalá pudiera ir!",
  ["17:5bed"] = "¡Argg! Me rindo.",
  ["1d:4cd7"] = "No queremos que te\ncaigas al mar\012y por eso no\npuedes entrar.",
  ["17:5c00"] = "Nuestros\nEJECUTIVOS\012quieren hacerse\ncon este lugar.\012Tienen grandes\nplanes. ¿Cuáles\011serán?",
  ["1d:4f06"] = "El barco va a\nzarpar. Por favor,\011suba a bordo.",
  ["17:5c64"] = "¡Jajaja!\012¡Qué aburrimiento!\n¡Fue tan sencillo\012apoderarse de\neste lugar!\012¡Venga,\nentretenme!",
  ["1d:4f4d"] = "Bienvenido al\nFERRY S.S. AQUA.\012¿Vas a embarcar\nhoy?",
  ["17:5cbf"] = "¿Quién eres tú?",
  ["1d:4fa7"] = "Siempre a su\nservicio.",
  ["17:5cd0"] = "¡Me venciste y no\npienso olvidarlo!",
  ["1d:4ff2"] = "{PLAYER} intentó\nenseñar el TICKET\011BARCO…\012¡Pero no lo tiene!\012¡Lo siento!\nSólo puedes subir\012si tienes un\nTICKET BARCO.",
  ["17:5cf4"] = "BUENA: ¡Hola!\n¡Soy BUENA!\012¿Conoces un\nprograma de radio\011llamado CÓDIGO?\012Si puedes decirme\nel código del\012programa, ganarás\npuntos.\012¡Acumula puntos y\ncámbiaselos a esa\012dulce jovencita de\nahí para recibir\011regalos!\012¡Allá vamos!\012¡Es tu propia\ntarjeta de puntos!",
  ["67:6301"] = "Volveré a la RUTA\nHELADA de CIUDAD\012ENDRINO y seguiré\nentrenándome.",
  ["17:5e10"] = "BUENA: ¡Sintoniza\nmi SHOW CÓDIGO!",
  ["67:62ef"] = "¡Oh, he perdido!",
  ["17:5e35"] = "BUENA: ¡Hola!\n¿Sintonizaste mi\011programa de radio?\012¿Recuerdas el\ncódigo de hoy?",
  ["67:62a1"] = "¡Prepárate para\ncualquier cosa!\012¡Déjame ver si\nhas entrenado bien\011a tus POKéMON!",
  ["17:5e84"] = "BUENA: ¡Oh, guau!\n¡Gracias!\012¿Cómo decías que\nte llamabas?\012…\n¡{PLAYER}, vale!\012Venga, {PLAYER}.\nÚnete al show.",
  ["67:5fcc"] = "RUTA 44\012PUEBLO CAOBA -\nCIUDAD ENDRINO",
  ["17:5edd"] = "BUENA: ¿Todos\npreparados?\012¡Quiero oírte\ndecir el código\012de hoy, {PLAYER}!",
  ["67:5fb3"] = "RUTA 44\nHACIA RUTA HELADA",
  ["17:5f29"] = "BUENA: Vuelve\ntras escuchar mi\012show, ¿vale?\n¡Hasta luego!",
  ["67:5f4d"] = "Todos mejoramos\nluchando\011muchas veces.\012He luchado mucho\npara llegar a ser\012lo que soy hoy:\nuna campeona.",
  ["17:5f6c"] = "BUENA: Lo siento…\012Sólo tienes una\noportunidad por\011día.\012¡Vuelve mañana\npara otro intento!",
  ["67:5f31"] = "¡No! Esto no\nservirá para nada.",
  ["17:5fc1"] = "BUENA: ¡YUUUUPI!\n¡Correcto!\012¡Me habías oído!\n¡Estoy muy feliz!\012¡Ganaste un punto!\n¡Felicidades!",
  ["67:5eed"] = "Pareces fuerte.\012Los buenos\nentrenadores\012siempre buscan\nbuenos rivales.",
  ["17:601c"] = "BUENA: Ooooh…\nIncorrecto…\012¿Has olvidado el\ncódigo?",
  ["67:5e66"] = "¡Uauu! Tienes\nmuchas MEDALLAS.\012No me extraña que\nseas tan fuerte.\012Me pregunto si\nMORTI, de GIMNASIO\012IRIS, estará\naún entrenándose.\012Él sí que me\ndio una paliza.",
  ["17:6054"] = "BUENA: Hemos\nconcursado con\012{PLAYER}. ¡Gracias\npor venir!\012¡Espero que todos\nlos oyentes vengan\012también!\n¡Estaré esperando!",
  ["67:5e43"] = "¡Vaya! Ha sido una\nauténtica derrota.",
  ["17:60c2"] = "BUENA: ¿Eh?\n¿El código de hoy?\012¡AYUDA,\npor supuesto!",
  ["67:5ddc"] = "Con sólo mirarte\nsé si eres un\011buen entrenador.\012Yo soy bueno con\nlos POKéMON y veo\011que tú también.",
  ["17:60f1"] = "BUENA: Tu TARJETA\nAZUL está llena.\012¡Consigue algún\npremio fabuloso!",
  ["67:5d7e"] = "Los POKéMON\nde colores\012poco habituales\ntienen más valor.\012¿Qué? ¿Insinúas\nque no es cierto?",
  ["17:6131"] = "BUENA: ¡Sintoniza\ncon CÓDIGO todos\012los días desde las\nseis de la tarde\011hasta medianoche!\012¡Sintoniza y luego\nven a visitarnos!",
  ["67:5d5b"] = "Oooh, tus POKéMON\nson muy bonitos.",
  ["17:6192"] = "BUENA: ¿Eh?\n¿Olvidaste traer\011tu TARJETA AZUL?\012No puedo darte\npuntos si no la\011tienes.",
  ["67:5d2c"] = "¡Haré lo que sea\npara conseguir\011POKéMON raros!",
  ["17:61ee"] = "BUENA: ¡Oh! ¡Tu\nTARJETA AZUL ha\012llegado hoy hasta\nlos 30 puntos!\011¡Increíble!\012Mmm… No hay ningún\npremio por llegar\012a los 30 puntos,\npero…\012Has venido muy a\nmenudo, {PLAYER}.\012¡Te ofreceré algo\nespecial!\012¿Quieres mi número\nde teléfono?",
  ["67:5cfc"] = "Es importante\ntener confianza\011en uno mismo.",
  ["17:62bf"] = "BUENA: {PLAYER},\n¿quieres registrar\012mi número de\nteléfono?",
  ["67:5cdd"] = "¡Arrgh…! No\nesperaba perder.",
  ["17:62f3"] = "{PLAYER} registró\nel número de\011teléfono de BUENA.",
  ["67:5cc4"] = "¡Voy a ganar!\n¡Seguro!",
  ["17:6310"] = "BUENA: ¡Llámame\ncuando quieras!",
  ["67:5c67"] = "¿Por qué no\npude vencerte?\012Ah, sí, aquí\ntienes. Es el\012regalo que no te\npude dar antes.",
  ["17:633c"] = "BUENA: Ooh… Es un\npremio especial…",
  ["67:5bf3"] = "ARTICUNO, ZAPDOS y\nMOLTRES son los\012pájaros POKéMON\nlegendarios.\012Aunque dicen que\nhay otros pájaros\011legendarios.",
  ["17:635e"] = "BUENA: {PLAYER}, no\nqueda espacio en\012tu agenda para mi\nnúmero…",
  ["67:5bdb"] = "¡Uauu! Eres un\nhacha.",
  ["17:6392"] = "¡Puedes cambiar\nlos puntos guarda-\011dos por el premio\011de tu elección!",
  ["67:5baf"] = "¿Sabes algo sobre\nel POKéMON\011pájaro legendario?",
  ["17:63d8"] = "No puedes cambiar\npuntos sin tu\011TARJETA AZUL.\012¡No olvides tu\nTARJETA AZUL!",
  ["67:5b6f"] = "Son 100 victorias\ny 101 derrotas.\012No lucharé\nen un rato.",
  ["17:6426"] = "P1 VENTAS",
  ["67:5b55"] = "¡Mmmmm…!\nEso no está bien.",
  ["17:6430"] = "La HORA POKéMON\ndel PROF. OAK.\012¡El mejor programa\nde la radio!",
  ["67:5af7"] = "Pesco hasta que\nno puedo más.\012Y lucho hasta\ndesfallecer.\012Ésta es la\nrelación que tengo\011con mis POKéMON.",
  ["17:6463"] = "Radio POKéMON.\nA cualquier hora\011y en todas partes.",
  ["67:5aa8"] = "Ese POLIWAG que\nescapó…\011Era enorme.\012¡Juraría que medía\nunos 5 metros!",
  ["17:6621"] = "Hemos grabado los\ngritos de todos\012los POKéMON\ndescubiertos.\012Debemos de tener\nunos 200 tipos.",
  ["67:5a91"] = "¡Simplemente,\nolvídalo!",
  ["17:6682"] = "Los POKéMON son\nmuy queridos por\011sus entrenadores.\012Es horrible ver\ncómo trata el\012TEAM ROCKET\na los POKéMON.",
  ["67:5a4b"] = "¡Me has hecho\nperder a POLIWAG!\012¿Qué vas a hacer\npara remediarlo?",
  ["17:66eb"] = "Emitimos programas\nde entretenimiento\012las 24 horas\ndel día.\012¡Intentaremos\nhacerlo lo mejor\011posible!",
  ["67:56c9"] = "PISTAS ENTRENADOR\012Todos los POKéMON\ntienen ventajas y\012desventajas según\nel tipo.\012Entre dos POKéMON\nde distinto tipo,\012puede perder el\nde nivel superior.\012Aprende qué tipos\nson fuertes o\012débiles contra tu\ntipo de POKéMON.",
  ["17:6754"] = "El jefe del TEAM\nROCKET se ha\011encerrado.\012Pero el DIRECTOR\npuede abrirle.\012Está en el\ncuarto piso.\012¡Sálvale!",
  ["67:56a2"] = "RUTA 43\012LAGO DE LA FURIA -\nPUEBLO CAOBA",
  ["17:67cb"] = "¿Está a salvo\nel DIRECTOR?",
  ["67:567b"] = "RUTA 43\012LAGO DE LA FURIA -\nPUEBLO CAOBA",
  ["17:67e2"] = "¡Gracias!\n¡Eres mi héroe!\012Toma esto como\nagradecimiento.",
  ["67:564b"] = "¿No es mi CLEFAIRY\nlo más bonito del\011mundo?",
  ["17:6821"] = "¡Es DÍA SOLEADO!\nMejora movimientos\012del tipo fuego\ndurante un tiempo.",
  ["67:5618"] = "Voy a ir de picnic\ncon mis POKéMON.\012¿No te vienes?",
  ["17:685c"] = "¡Estuviste\ngenial!",
  ["67:5604"] = "¡He jugado mucho!",
  ["17:6878"] = "He recibido\nórdenes.\012¡Aplastaré a todo\naquél que desafíe\011al TEAM ROCKET!",
  ["67:55c1"] = "¿Tú también vas al\nLAGO DE LA FURIA?\012¡Juguemos un\nratito!",
  ["17:68c8"] = "¿¡Qué!?",
  ["67:557e"] = "¿Qué ocurre en el\nLAGO DE LA FURIA?\012Teníamos pensado\nacampar aquí.",
  ["17:68d0"] = "No he cumplido\ncon mi deber…\012Y me van a\nbajar el sueldo…",
  ["67:5565"] = "Perder no es nada\ndivertido…",
  ["17:6904"] = "Me encanta ordenar\na los POKéMON que\011cometan delitos.",
  ["67:5535"] = "Puedo hacer muchas\ncosas con mis\012POKéMON.\n¡Es muy divertido!",
  ["1d:5bd5"] = "Encontrarás muchos\nPOKéMON en los\011árboles de JOHTO.",
  ["67:54d3"] = "Las CEBO BALL de\nCÉSAR son las\012mejores para\npescar POKéMON.\012Son mucho más\nefectivas que las\011ULTRA BALL.",
  ["1d:5c07"] = "Intento olvidar a\nmis enemigos.\011¡Luchemos!",
  ["67:54b0"] = "He perdido, pero\nme siento mejor.",
  ["1d:5c32"] = "Estoy desolada…",
  ["67:5461"] = "No estoy de racha.\012Quizá sea por el\nequipo que uso.\012Luchemos. A ver si\ncambia mi suerte.",
  ["1d:5c43"] = "Lo mejor para\ncurar las penas\012es hacer un\nviaje en barco.\012Pero los viajes\nen FERRY son\012demasiado\ncortos.",
  ["67:53f8"] = "Es bueno que a la\ngente le gusten\012distintos tipos de\nPOKéMON.\012No sólo se trata\nde tener el\011más fuerte.",
  ["1d:5ca6"] = "Voy a una audición\nde mis canciones\012en la EMISORA de\nCIUDAD TRIGAL.",
  ["67:53d6"] = "¡Mi NIDOKING lo\nha hecho muy bien!",
  ["1d:5ce4"] = "¡Uauu!\n¡Distorsión total!",
  ["67:5386"] = "¿Te lo puedes\ncreer?\012¡{RIVAL} se ha\nburlado de mi\011POKéMON!\012¡Maldición! ¡Mi\nPOKéMON es genial!",
  ["1d:5cfe"] = "Iba a hacer mi\ndebut en la\011TORRE BATALLA…\012Debo regresar a\nCIUDAD CARMÍN para\011volver a entrenar…",
  ["67:5359"] = "Sería feliz con\nsólo tener un\011POKéMON raro.",
  ["1d:5d65"] = "Hablando de la\nEMISORA, ¿cuál es\012nº de la suerte\nde esta semana?",
  ["67:533a"] = "¡Oh, mis pobres\nPOKéMON!",
  ["1d:5da4"] = "¡Una buena cama!\nA dormir…",
  ["67:5319"] = "¡Eh! ¿Tienes algún\nPOKéMON raro?",
  ["1d:5dc1"] = "¡Ah! Me siento\ncomo nuevo.",
  ["67:52d2"] = "¿Que qué me gusta\nademás de los\011POKéMON?\012Oír a ROSA en la\nradio. ¡Seguro que\011es muy guapa!",
  ["1d:5dde"] = "El FERRY S.S. AQUA\nha llegado a\011CIUDAD OLIVO.",
  ["1d:5e0f"] = "El FERRY S.S. AQUA\nha llegado a\011CIUDAD CARMÍN.",
  ["1d:6012"] = "¡Ah! Gracias por\nvenir.\012Estoy agotado\nde entretener\011a esa niña.",
  ["67:52b4"] = "¿Cómo me has\npodido hacer esto?",
  ["1d:6064"] = "¿Te gusta viajar\nen el S.S. AQUA?\012Prácticamente\nvuela por encima\011de las olas.",
  ["67:526a"] = "¡Me encantan\nlos POKéMON!\012¡Ésa es la razón\npor la que empecé\012a coleccionar\nPOKéMON!",
  ["1d:60ae"] = "Oh, hola…\012Todavía no he\npodido encontrar\011a mi nieta.\012Si está en el\nbarco, no hay\011problema.\012Es una niña muy\ntraviesa, así que\012estará molestando\na alguien.\011Me preocupa…",
  ["67:4f94"] = "RUTA 35",
  ["1d:6143"] = "{PLAYER}, ¿verdad?\nMe han dicho que\012has entretenido a\nmi nieta.\012Quiero darte\nlas gracias.",
  ["67:4f56"] = "Tus POKéMON son\nbastante fuertes.\012Estarás seguro en\ncualquier parte.",
  ["1d:619b"] = "¡Me gustaría que\ntuvieras esto!",
  ["67:4f0f"] = "Ya sabes, la noche\nes divertida a su\011manera.\012Pero no te pases,\n¿vale?",
  ["1d:61be"] = "Estamos viajando\npor todo el mundo.",
  ["67:4f06"] = "¡Uy!",
  ["1d:61e0"] = "CAPITÁN, venga,\njuegue conmigo.\012¡Me aburro! Quiero\njugar más.",
  ["67:4eea"] = "¡El peligro acecha\npor la noche!",
  ["1d:621f"] = "¡Hola! ¿Quieres\njugar conmigo?\012¿Qué…?\012¿Que mi abuelo\nestá preocupado?\012¡Debería irme!\012¡Tengo que buscar\nal abuelo!",
  ["67:4ebc"] = "La Marcha POKéMON\nde la radio atrae\011POKéMON salvajes.",
  ["1d:6284"] = "¡Hola, abuelo!\nEstaba jugando\012con el CAPITÁN y\neste chico.",
  ["67:4e98"] = "¡Me he quemado la\npunta de la nariz!",
  ["1d:62c6"] = "¡Hola, abuelo!\nEstaba jugando\012con el CAPITÁN y\nesta chica.",
  ["67:4af8"] = "Le voy a demostrar\na mi novia lo\011bueno que soy.",
  ["1d:630d"] = "¡Me he divertido\nmucho jugando!",
  ["67:4608"] = "",
  ["1d:6329"] = "¡Hola, peque!\n¿Quieres luchar?",
  ["67:45e6"] = "¡Vaya pérdida\nde tiempo!",
  ["1d:634c"] = "¡Eres fuerte!",
  ["67:459e"] = "",
  ["1d:635b"] = "¿Viajas\nsolo?\012¿Tu madre no está\npreocupada?",
  ["67:457f"] = "¿Estás contento\nde haber ganado?",
  ["1d:638e"] = "¿Crees que soy\nuna nena?\011¡No es justo!",
  ["67:44e2"] = "",
  ["1d:63b4"] = "¡Oh! ¡Perdimos!",
  ["67:449f"] = "¡Oh…! Me\ngusta hacerlo…\012Vale. Ven a verme\ncuando quieras.",
  ["1d:63c2"] = "¡No deberías\nllamar nenas a\011las chicas!",
  ["67:4304"] = "Esto es una TIENDA\nPOKéMON.\012Hay POKé BALL para\ncapturar POKéMON\012salvajes y otras\nmuchas cosas.",
  ["1d:63e9"] = "¡No soy una nena!\012¡Y no deberías\nllamar así a\012una dama!",
  ["67:4285"] = "Esto es un\nCENTRO POKéMON.\012Aquí curan a\ntus POKéMON.\012Vas a necesitar\nmucho de ellos,\012así que mejor\nconocerlos.",
  ["1d:641a"] = "¡Oh! ¡Perdimos!",
  ["1d:6428"] = "A veces, los niños\nson más listos que\011los adultos.",
  ["67:41e3"] = "Eres un entrenador\nnovato, ¿verdad?\011¡Estoy seguro!\012¡Está bien! ¡Todo\nel mundo es novato\011alguna vez!\012Si quieres, te\npuedo enseñar\011algunas cosas.",
  ["1d:6455"] = "¡Ssh! ¡Mi cerebro\nestá captando\011señales de radio!",
  ["66:795e"] = "Hay un e-mail en\nel PC.\012…\012PROF. OAK, ¿cómo\nsiguen sus\011investigaciones?\012Yo sigo perseve-\nrando en lo mío.\012He oído rumores\nde que {PLAYER}\012se está labrando\nbuena reputación.\012Estoy encantado\nde oír eso.\012ELM, de PUEBLO\nPRIMAVERA 8-)",
  ["1d:6481"] = "¡Escucho\nalgo…!",
  ["66:7909"] = "La opción GUARDAR\nestá en el MENÚ.\012Utilízala con\nfrecuencia.",
  ["1d:6497"] = "Entiendo. Puedes\noír la radio de\011JOHTO en el FERRY.",
  ["66:78ea"] = "Pulsa START para\nacceder al MENÚ.",
  ["1d:64ce"] = "¿Qué opinas? Mis\nPOKéMON son\011bonitos, ¿verdad?",
  ["66:74a2"] = "¿Qué tal va tu\nPOKéDEX?\012Veamos…",
  ["1d:64fe"] = "¡Oh, no! ¡Mis\npreciosos POKéMON!",
  ["66:7427"] = "OAK: ¡Ah, {PLAYER}!\nMe alegro de\012que hayas venido\nhasta KANTO.\012¿Qué opinas de los\nentrenadores que\012hay por aquí? Son\nfuertes, ¿verdad?",
  ["1d:651c"] = "¡Debo ir a la\nPELUQUERÍA POKéMON\012para ponerlos\nguapos!",
  ["66:7377"] = "DALIA: Lo siento.\nNo puedo\011limpiar un HUEVO.",
  ["1d:654f"] = "Me voy de compras\nal C. COMERCIAL\011y luego…",
  ["66:7334"] = "DALIA: ¿No quieres\nque te limpie un\012POKéMON? Vale, tan\nsólo tomaremos té.",
  ["1d:657d"] = "¿Qué es lo que\niba a hacer?",
  ["66:72fa"] = "DALIA: Siempre\ntomo té a esta\012hora. Ven cuando\nquieras.",
  ["1d:6596"] = "¡Ah, sí! Tengo que\nir a buscar a mis\012POKéMON a la\nGUARDERÍA.",
  ["66:72aa"] = "DALIA: ¡Ya está!\n¡Listo!\012¿Qué? ¿Tiene buen\naspecto o no?\012¡Qué POKéMON\nmás mono!",
  ["1d:65c7"] = "¿Qué tipos de\nPOKé BALL llevas\011contigo?",
  ["66:7296"] = "{STRBUF}\nparece contento.",
  ["1d:65f4"] = "¡Espera! ¡Detente!\n¡No, por favor!",
  ["66:7266"] = "DALIA: Vale, haré\nque mejore su\011aspecto enseguida.",
  ["1d:660f"] = "Deberías usar las\nBALL adecuadas\012para cada\nsituación.",
  ["66:7244"] = "DALIA: ¿Qué\nPOKéMON limpio?",
  ["1d:6645"] = "El FERRY S.S. AQUA\nha llegado a\011CIUDAD CARMÍN.",
  ["1d:687b"] = "¡Eh! ¿Podrías\nbuscar a mi\011compañero?\012¡Está haciendo de\nlas suyas en algún\012sitio!\n¡El muy vago!\012Me gustaría ir a\nbuscarle, pero\011estoy de servicio.",
  ["66:71b6"] = "DALIA: ¡Llegas\na tiempo! Iba a\011tomar un té.\012¿Quieres\ntomarte uno?\012Tus POKéMON están\nun poco sucios.\012¿Quieres que\nlimpie a uno?",
  ["1d:6907"] = "¡Oh…!\012El CAPITÁN se\npondrá furioso…",
  ["66:7130"] = "DALIA: ¡Hola! Mi\nhermano es LÍDER\012del GIMNASIO de\nCIUDAD VERDE.\012Pero sale tanto de\nla ciudad que trae\012problemas a los\nentrenadores.",
  ["1d:692e"] = "¡Gracias, joven!\n¡Le he echado una\012buena bronca y se\nha tranquilizado!",
  ["66:7087"] = "Parece que nadie\nlo ha usado en\011mucho tiempo…",
  ["1d:696d"] = "¿Una niña pequeña?\012Puede que la haya\nvisto por aquí.",
  ["66:7050"] = "{PLAYER} jugó\na la N64.\012Mejor irse. No hay\ntiempo que perder.",
  ["1d:699d"] = "El comedor está\nahí delante.\012Las escaleras del\nfondo conducen al\012camarote del\nCAPITÁN.",
  ["66:6fe8"] = "Tienen programas\nque no se emiten\011en JOHTO…",
  ["1d:69ed"] = "No hay nada mejor\nque un combate\012en mi tiempo\nlibre.",
  ["66:6f81"] = "Me preocupa que\nROJO esté herido o\012enfermo, pero es\nun chico. Estoy\012orgullosa de que\nesté haciendo\012lo que quiere.",
  ["1d:6a1a"] = "¡Gane o pierda, se\nacabó el descanso!",
  ["66:6ec0"] = "¡Hola!\012ROJO lleva fuera\nmucho tiempo.\012Tampoco ha\nllamado, así que\012no sé dónde está,\nni lo que ha\011estado haciendo.\012Dicen que si no\nhay noticias es\012que todo va bien,\npero estoy\011preocupada por él.",
  ["1d:6a38"] = "Supongo que no\nganaré si no me\011lo tomo en serio.",
  ["66:6e2d"] = "Usa esta puerta\npara no andar\011por la hierba.",
  ["1d:6a63"] = "Me aburro tanto.\n¿Quieres luchar?",
  ["66:6d9b"] = "Esos gamberros de\nnegro me echaron\011de mi puesto.\012Se dejaron\nesto.\012Me molesta.\n¿Podrías\011llevártelo?",
  ["1d:6a81"] = "¡Uau! ¡Eres\ndemasiado fuerte!",
  ["66:6d41"] = "¡Je, je! Nos\nestamos forrando.\012Todo el mundo\nquiere ver lo que\012ocurre en el LAGO\nDE LA FURIA.",
  ["1d:6a99"] = "AZAFRÁN…\nAZULONA…\012Dicen que hay\nmuchas ciudades\011grandes en KANTO.",
  ["66:6d20"] = "Entonces paga\nlo que tengas.",
  ["1d:6ad7"] = "¡Urrf…!\n¡Estoy mareado!",
  ["66:6d0a"] = "¡Gracias, joven!",
  ["1d:6aea"] = "No me puedo\nmover…",
  ["66:6cd2"] = "¡Alto ahí, joven!\012El precio por\npasar es 1.000¥.",
  ["1d:6b02"] = "No vuelvo a ir en\nbarco. La próxima\012vez viajaré en el\nMAGNETOTRÉN.",
  ["1b:423d"] = "Mmm… Tienes muchas\nMEDALLAS de\011GIMNASIO.",
  ["1d:6b40"] = "¡Aquí es donde\ntrabajamos!",
  ["1b:42b7"] = "El cartel\nestá roto.\012Es imposible\nleerlo…",
  ["1d:6b60"] = "He perdido en mi\npropio campo…",
  ["1b:4b59"] = "En las estatuas de\nlos POKéMON hay\012cámaras de\nvigilancia.\012Seguiremos\napareciendo hasta\012que pulses un\nbotón secreto.",
  ["1d:6b7a"] = "Llevamos a muchos\npasajeros desde\012CIUDAD CARMÍN a\nCIUDAD OLIVO.",
  ["1b:54c6"] = "Esta guarida\nse acabó…\012Pero no importa.\nEl experimento de\012emisión fue\ntodo un éxito.\012Qué más da lo que\npase ahora con\011esta guarida.\012Tenemos planes más\nimportantes.\012Muy pronto\nconocerás el\012verdadero poder\ndel TEAM ROCKET.\012Disfruta mientras\npuedas…\012¡Fufufufu…!",
  ["1d:6bbc"] = "¡Aunque estemos en\nel mar, no puedo\011pescar!\012¡Qué aburrido!\n¡Luchemos!",
  ["1b:564e"] = "Perdona, {PLAYER}.\nComo lo estabas\012haciendo tan bien,\nme retiré.\012Lo único que hay\nque hacer ahora es\012apagar esa extraña\nseñal radiofónica.",
  ["1d:6c08"] = "Ya… Ya no\nme aburro…",
  ["1b:57ea"] = "LANCE: Déjame\neste lado.",
  ["1d:6c22"] = "Voy a pescar en\nlos muelles de\011CIUDAD CARMÍN.",
  ["1a:5c1b"] = "¡Pescar es genial!\012Si ves agua, ya\nsea el mar o un\012río, utiliza\ntu CAÑA.",
  ["1d:6c47"] = "¡Fortalezco mis\npiernas nadando\012en la estela\ndel barco!",
  ["1a:5a81"] = "¿Estás estudiando\nlas RUINAS?\012Eres un científico\nen potencia.",
  ["1d:6c85"] = "¡Bailemos el Rock\nand Roll!",
  ["1a:583c"] = "Fue hace unos\ntres años.\012El TEAM ROCKET\nquería hacer daño\011a los POKéMON.\012Pero prevaleció la\njusticia y un niño\011acabó con ellos.",
  ["1d:6c9e"] = "No pude encontrar\nal REY del KARATE\011en JOHTO.\012Dicen que se está\nentrenando en\011alguna cueva.",
  ["1a:5693"] = "¡Oh, no! No puedes\nllevar más\011POKéMON.\012Esperaré aquí a\nque le hagas\011sitio al HUEVO.",
  ["1d:6cf9"] = "¡Soy marinero!\012Pero entreno\nPOKéMON para\011ser el CAMPEÓN.",
  ["1a:545e"] = "¡A mi PIDGEY le\nllamo FRESITA!",
  ["1d:6d3c"] = "Me falta\nentrenamiento…",
  ["1a:5197"] = "Antes de lanzar la\nPOKé BALL, debes\011debilitarlo.\012Atrapar un\nPOKéMON quemado\012o envenenado es\nmucho más fácil.\012¿Seguir leyendo?",
  ["1d:6d5f"] = "¡Ocho MEDALLAS!\nEso demuestra que\012has vencido a los\nLÍDERES de GIM.\012¡No me extraña que\nseas tan bueno!",
  ["1a:4fe2"] = "Si tu POKéMON\nse queda dormido\012no podrá realizar\nningún movimiento.\012Un POKéMON dormido\nno se despierta\011tras el combate.\012Despiértalo con\nDESPERTAR.",
  ["1d:6db6"] = "¡No toques a\nmis alumnos!",
  ["1a:4e39"] = "Si un POKéMON va\nequipado con una\012BAYA, se curará él\nsolo en combate.\012Los POKéMON pueden\nir equipados con\011muchos objetos…\012Es muy duro\ntomar apuntes…",
  ["1d:6dd9"] = "¡Aaah!",
  ["1a:4d31"] = "¡Oh! ¡Un alumno\nlisto eres! ¡Nada\011más quieres saber!\012¡Bueno en POKéMON\ndebes de ser!",
  ["1d:6de1"] = "Vamos de excursión\na las RUINAS de\012las afueras de\nCIUDAD MALVA.",
  ["1b:58f8"] = "Es TORBELLINO.\nEnséñasela a\012un POKéMON y\npodrá cruzar\011torbellinos.\012Pero recuerda\nque…\012Sólo podrás usarla\nfuera de los\012combates con la\nMEDALLA del\011GIMNASIO CAOBA.",
  ["1d:6e14"] = "¿Conoces las\nRUINAS ALFA?",
  ["1b:5a97"] = "LANCE: ¿Estás\nbien?\012Tus POKéMON están\nheridos, cansados.\012Toma, dales un\npoco de mi\011medicina.",
  ["1d:6e34"] = "¡Aarg!",
  ["1b:5b22"] = "¿No se abre\nla puerta?\012Bueno, necesitas\nuna contraseña que\012sólo conoce el\nTEAM ROCKET.",
  ["1d:6e3d"] = "Las radios captan\nseñales extrañas\011en las RUINAS.",
  ["1b:5b88"] = "¿Qué? Soy sólo\nun SOLDADO.\012Y no conozco la\ncontraseña. Lo\011siento por ti.",
  ["1e:6315"] = "{PLAYER} abrió\nun libro.\012Pista de viaje 4:\012Mira los ataques\nde tus POKéMON.\012Pulsa A para\ncambiar de ataque.",
  ["1e:60f0"] = "Dicen que han\nrobado un POKéMON.\012Y acabo de recibir\ncierta información\011del PROF. ELM.\012Parece que fue un\njoven pelirrojo,\011de pelo largo.\012¿Qué?\012¿Que tú te has\nenfrentado a un\011entrenador así?\012¿Y sabes cómo\nse llama?",
  ["1e:6370"] = "Dentro está el\nenvoltorio del\012tentempié que se\ntomó el PROF. ELM.",
  ["1d:5716"] = "¿Conoces a LILA?\nEs una DJ muy\011buena de KANTO.",
  ["1e:63a6"] = "OBSERVACIONES DE\nEVOLUCIÓN POKéMON\012Es lo que pone\nen la pantalla…",
  ["5d:4f2f"] = "Escucha, el puerro\nde mi {STRBUF}\012tiene un aroma\ndelicioso.\012¡Ese aroma me abre\nel apetito!",
  ["1e:6604"] = "¡Ah, {PLAYER}…!\nNuestro vecino,\012el PROF. ELM, te\nestaba buscando.\012Dijo que quería\nque le hicieras\011un favor.\012¡Ah! ¡Casi se me\nolvida! Ya han\012traído tu POKéGEAR\ndel taller.\012¡Aquí tienes!",
  ["5d:5106"] = "¡Hasta la vista!",
  ["1e:66bd"] = "El POKéMON GEAR o\nsólo POKéGEAR.\012Es básico si\nquieres ser un\011buen entrenador.\012¡Ah! Falta el día\nde la semana.\012¡No olvides\nponerlo!",
  ["1b:7141"] = "Es la MO CORTE.\n¡Enséñasela a un\012POKéMON para\ncortar arbustos!\012Pero necesitarás\nla MEDALLA del\012GIMNASIO AZALEA\npara usarla.",
  ["1e:6742"] = "¿Es horario\nde verano?",
  ["1b:7086"] = "FARFETCH'D: ¡Farf!",
  ["1e:6763"] = "Vuelve a casa\npara cambiar de\011hora el reloj.\012Por cierto,\n¿sabes cómo usar\011el TELÉFONO?",
  ["1b:6f5c"] = "¡Vaya…! Mi jefe\nse va a poner\011furioso…\012Se me escapó el\nFARFETCH'D que\012CORTA árboles para\nconseguir carbón.\012No puedo ir a\nbuscarlo al\011ENCINAR.\012Demasiado grande y\noscuro para mí…",
  ["1e:67cb"] = "¿Recuerdas que\nhay que encender\012el POKéGEAR\ny elegir el\011TELÉFONO?",
  ["69:6d04"] = "He perdido.",
  ["1e:6807"] = "Te leeré las\ninstrucciones.\012Enciende el\nPOKéGEAR y elige\011el TELÉFONO.",
  ["69:6d11"] = "¿No había una\ncanción famosa\012sobre un niño que\nmontaba un LAPRAS?",
  ["1e:6850"] = "Los números están\nen la memoria.\012Elige el nombre\nque quieras.\012¿No te parece\nestupendo?",
  ["69:6d46"] = "¡Hace muy buen\ndía! ¡Estoy\011aturdida!",
  ["1e:68b5"] = "El PROF. ELM te\nestá esperando.\012¡Date prisa!",
  ["69:6d72"] = "¡Ohhh!",
  ["1e:68e5"] = "¿Qué quería\nel PROF. ELM?\012…\012Parece muy\ndíficil.\012Deberías estar\norgulloso de\012que la gente\nconfíe en ti.",
  ["69:6d79"] = "El sol es muy malo\npara la piel.\012Pero yo no uso\nprotección solar.\012No quiero\nensuciar el agua.",
  ["1e:6957"] = "¡Vamos, {PLAYER}!\012¡Cuentas con\ntoda mi ayuda!",
  ["69:6dd0"] = "Si necesitas\ndescansar, ve por\011el agua.\012El viento te\nempujará y podrás\012seguir siendo\nfuerte.",
  ["1e:697d"] = "¡Buenos días,\n{PLAYER}!\012¡Estoy de visita!",
  ["69:6e33"] = "¡Oh! Tienes más\nenergía que yo.",
  ["1e:699c"] = "¡Hola, {PLAYER}!\n¡Estoy de visita!",
  ["69:6e58"] = "He oído rugidos\nprocedentes de\011las ISLAS.",
  ["1e:69b4"] = "¡Buenas tardes,\n{PLAYER}!\012¡Estoy de visita!",
  ["69:6e85"] = "Por la noche,\nlos STARYU se\012reúnen cerca de la\nsuperficie.",
  ["1e:69d3"] = "{PLAYER}, ¿lo\nhas oído?\012Mi hija está\nempeñada en\012convertirse en\nayudante del PROF.\011ELM.\012¡Le encantan\nlos POKéMON!",
  ["69:6eb7"] = "¡Oh, querido…!",
  ["1e:6a3a"] = "¡La especialidad\nde mi madre!\012¡HAMBURGUESA\nVOLCÁN CANELA!",
  ["69:6ec2"] = "Los grupos de\nSTARYU se iluminan\011al mismo tiempo.\012Es muy bonito,\npero da miedo.",
  ["1e:6a64"] = "El fregadero está\nimpecable. A mamá\011le gusta limpio.",
  ["69:7012"] = "La paciencia es la\nclave para pescar\011y criar POKéMON.",
  ["1e:6a91"] = "Veamos qué hay\nen la nevera…\012¡AGUA FRESCA y una\nsabrosa LIMONADA!",
  ["69:7043"] = "¡Guaaa!",
  ["1e:6ad0"] = "Una peli en TV:\ndos niños suben\012a un tren bajo un\ncielo estrellado.\012¡Mejor que yo\ntambién me vaya!",
  ["69:704c"] = "No tengo paciencia\npara la pesca…",
  ["1e:6c24"] = "¡La HORA POKéMON\ndel PROF. OAK!\012¡Sintonízanos la\npróxima vez!",
  ["69:706b"] = "Me gusta pescar\nmientras escucho\012canciones por\nla radio.",
  ["64:5fca"] = "Estoy pensando en\nir a comprar a\011CIUDAD AZAFRÁN.",
  ["69:70b4"] = "¡Mi estúpida radio\nme ha distraído!",
  ["64:6034"] = "Durante años,\nDIGLETT ha estado\012excavando un gran\ntúnel.\012El túnel lleva a\nuna ciudad lejana.",
  ["69:70d4"] = "¿Conoces las\nemisoras de\012radio de KANTO?\nTenemos muchas.",
  ["64:6142"] = "SURGE: ¡Eh, tú,\njoven!\012Tengo que recono-\ncerlo. No es que\012sea inteligente\ndesafiarme, ¡pero\011requiere agallas!\012Cuando se trata de\nPOKéMON\012eléctricos, ¡soy\nel número uno!\012Nunca he perdido\nen la batalla.\012¡Te electrocutaré\ncomo hice con el\012enemigo en la\nguerra!",
  ["69:711d"] = "¿Qué es lo más\nimportante en\011nuestras vidas?",
  ["64:6238"] = "SURGE: ¡Arrrgh!\n¡Eres fuerte!\012Vale, joven. ¡Toma\nla MEDALLA TRUENO!",
  ["69:714e"] = "¡La respuesta\nvendrá luego!",
  ["64:6277"] = "{PLAYER} recibió\nla MEDALLA TRUENO.",
  ["69:716d"] = "Creo que la\nelectricidad es lo\012más importante en\nnuestras vidas.\012Si no lo fuera, no\nse habría montado\012tanto follón\ncuando se estropeó\012la CENTRAL\nde ENERGÍA.",
  ["64:6291"] = "SURGE: La MEDALLA\nTRUENO aumenta la\012velocidad de los\nPOKéMON.\012Te la mereces por\nhaberme vencido.\012Llévala con\norgullo, ¿me oyes?",
  ["69:7214"] = "¿Te acuerdas?",
  ["64:6303"] = "SURGE: ¡Eh, tú!\n¿Todavía estás\012molestando por\naquí?\012¡Mis POKéMON y yo\nseguimos en ello!",
  ["69:7226"] = "Te acuerdas, ¿no?",
  ["64:6356"] = "¿Vienes a derrotar\nal LT. SURGE?\012¡No, si yo\npuedo impedirlo!",
  ["69:7238"] = "El tirón de la\nCAÑA cuando ha\012picado un\nPOKéMON…\012Ésa es la mejor\nsensación para un\011pescador como yo.",
  ["64:638c"] = "¡Cuánto siento\nhaberle fallado,\011LT. SURGE!",
  ["69:72a0"] = "RUTA 12\012PUEBLO LAVANDA\nHACIA EL NORTE",
  ["64:63b0"] = "Cuando aún estaba\nen el ejército, el\012LT. SURGE me salvó\nla vida.",
  ["69:72c1"] = "COTO DE PESCA",
  ["64:63e8"] = "El LT. SURGE\nreconoció mi\012potencial con\nlos POKéMON\011eléctricos.\012¿Crees que puedes\nvencerme?",
  ["1c:6faf"] = "No ganamos…",
  ["64:6437"] = "¡Ooh! ¡Increíble!",
  ["1c:6fc0"] = "¡ERIKA es mucho,\nmucho más fuerte!",
  ["64:644b"] = "Si funcionaran las\ntrampas del\012GIMNASIO, no lo\nhabrías logrado.",
  ["1c:70de"] = "¡Hola!\012Estamos celebrando\nun concurso\011de tragones.\012Perdona. Ahora no\npodemos atenderte.",
  ["64:6487"] = "¡Voy a acabar\ncontigo! ¡Vas\011a echar chispas!",
  ["1c:7129"] = "¡Ñam, ñam…!",
  ["64:64ba"] = "¡Vaya! Me has\nvencido…",
  ["1c:713a"] = "¡No me hables!\012¡Me vas a\ndesconcentrar!",
  ["64:64d6"] = "No te relajes\npor haberme\012vencido… LT.\nSURGE es fuerte.",
  ["1c:716a"] = "¡Glup…! ¡Ñam…!",
  ["64:6517"] = "¡Hola, futuro\nCAMPEÓN!\012Esta vez no\ntendrás tanta\011suerte.\012El LT. SURGE es\nmuy prudente. Ha\012puesto trampas por\ntodo el GIMNASIO.\012Pero (risas),\nlas trampas no\011están activadas.\012Te será fácil\nencontrar al\011LT. SURGE.",
  ["1c:7178"] = "¡Mejor cantidad\nque calidad!\012¡Si estoy lleno,\nestoy feliz!",
  ["64:65df"] = "¡Vaya combate más\nelectrizante!\012¡Me has puesto\nmuy nervioso!",
  ["1c:71ae"] = "¡Ñam, ñam…!",
  ["64:661e"] = "¡Bah! Aquí sólo\nhay basura.",
  ["1c:71bd"] = "La comida de aquí\nes buena, pero\012en CIUDAD TRIGAL\nes aún mejor.",
  ["64:66fe"] = "¡Bienvenido a\nCIUDAD AZAFRÁN,\012hogar del\nMAGNETOTRÉN!\012Eso es lo que\nsuelo decir, pero\012el MAGNETOTRÉN no\nfunciona ahora.\012No recibe\nelectricidad\012porque hay un\nproblema en la\012CENTRAL de\nENERGÍA.",
  ["1c:7201"] = "¡Ñam… Ñam…!",
  ["64:67cb"] = "El MAGNETOTRÉN\nes lo más\012famoso de\nCIUDAD AZAFRÁN.",
  ["1c:7212"] = "Aquí nadie te va\na dar un MONEDERO.\012Mejor que lo\nbusques en JOHTO.",
  ["64:6d39"] = "¿Quieres luchar\npor el cable GAME\012LINK o por\nteléfono móvil?",
  ["1c:7254"] = "¡Ñam… ñam…!\012¡Sigo comiendo!",
  ["64:6d7e"] = "¿Quieres cambiar\npor cable GAME\012LINK o por\nteléfono móvil?",
  ["1c:7278"] = "¡Más, JEFE!",
  ["64:6de0"] = "Bienvenido al\nCOLISEO DEL\011CLUB CABLE.\012Aquí puedes luchar\ncontra un amigo.\012¿Quieres\nluchar?",
  ["1c:7285"] = "¡Concurso de\ntragones! ¡Sin\012tiempo! ¡Una lucha\nsin fin! ¡El mayor\012tragón podrá\ncomer gratis!",
  ["64:6e3a"] = "Éste es el CENTRO\nDE CAMBIO del CLUB\011DEL CABLE.\012Puedes cambiar un\nPOKéMON aquí\011con un/a amigo/a.\012¿Quieres\nintercambiar?",
  ["1c:72e7"] = "{PLAYER} encontró\n{STRBUF}.",
  ["64:6e9f"] = "Bienvenido a la\nCÁPSULA DEL TIEMPO\011DEL CLUB CABLE.\012Puedes viajar al\npasado y cambiar\011tus POKéMON.\012¿Quieres viajar al\npasado?",
  ["1c:72f7"] = "Pero {PLAYER} no\ntiene espacio…",
  ["64:6f19"] = "Tu amigo no\nestá preparado.",
  ["1c:7379"] = "Si bajas por el\nCAMINO BICIS,\012llegarás a\nCIUDAD FUCSIA.",
  ["64:6f34"] = "Antes de conectar\nlas consolas,\011guarda el juego.",
  ["1c:7408"] = "Aquí empieza el\nCAMINO BICIS.\012Es todo cuesta\nabajo. Es muy\011emocionante.\012Es una sensación\nque no se\012experimenta en\nbarco o en tren.",
  ["64:6f67"] = "Espera, por favor.",
  ["1c:7496"] = "¡Eh! ¡Alto!\012No puedes pasar\npor el CAMINO\012BICIS si no vas\nen BICICLETA.",
  ["64:6f75"] = "La conexión se ha\ninterrumpido por\011inactividad.\012Habla con tu\namigo y vuelve\011cuando quieras.",
  ["1c:752c"] = "¿Has oído lo del\naccidente de la\011CENTRAL ENERGÍA?\012Se encuentra al\nEste, cerca de\011PUEBLO LAVANDA.",
  ["64:6fd1"] = "Vuelve algún día.",
  ["1c:7592"] = "Me tomo muy en\nserio mi trabajo\011de GUARDA.\012¡Eh! Tienes una\nPOKéDEX.\012Vale. Puedes\npasar.",
  ["64:7029"] = "No puedes\nconectarte con\011el pasado aquí.",
  ["1c:762c"] = "CAMINO BICIS\nA partir de aquí,\011es cuesta arriba.",
  ["64:704a"] = "Tu amigo/a eligió\nuna sala distinta.",
  ["1c:764d"] = "¡Alto! ¿No tienes\nuna BICI?\012Aquí empieza el\nCAMINO BICIS.\012Necesitas una\nBICI para seguir.",
  ["64:706b"] = "Entra, por favor.",
  ["1d:4008"] = "Del suelo salieron\nun montón de\012DIGLETT.\n¡Qué susto!",
  ["64:708b"] = "Perdona. No\npuedes llevar a\011{STRBUF}.",
  ["1d:4105"] = "…… …… ……\012¡Cuánto tiempo,\n{PLAYER}!\012Tras haber sido\nderrotado por\012ti, estuve\npensando en mis\011POKéMON…\012Y llegué a una\nconclusión.\012¡Ahora verás,\n{PLAYER}!",
  ["64:70a8"] = "No puedes llevar a\n{STRBUF} con\011{STRBUF}.",
  ["1d:419d"] = "…… …… ……\012Creía haber\nentrenado muy\012bien a mis\nPOKéMON…\012Pero estaba\nequivocado…",
  ["64:70cf"] = "No puedes llevarte\na {STRBUF}\011con la CARTA.",
  ["1d:41fa"] = "…… …… ……\012Has ganado\njustamente.\012Lo admito. Pero\nesto no termina\011aquí.\012Voy a ser el mejor\nentrenador POKéMON\011del mundo.\012Ya que estos\nchicos me apoyan.\012Mira, {PLAYER}.\012Uno de estos días\nte demostraré lo\012bueno que soy,\nderrotándote.",
  ["64:7100"] = "Lo siento. Estamos\narreglando la\011CÁPSULA DE TIEMPO.",
  ["1d:42e0"] = "…… …… ……\012Ya te he pagado\nmi deuda.\012Con mis POKéMON\nganaré al CAMPEÓN\012y seré el mejor\nentrenador\011del mundo.",
  ["64:712f"] = "Lo siento. Estamos\najustando la\011MÁQUINA DE CAMBIO.",
  ["1d:455f"] = "Espera.\012¿Vas a\nparticipar en la\011LIGA POKéMON?\012No me hagas reír.\nEres mucho más\012débil que yo,\nporque ya no\012soy el mismo\nde antes.\012¡Ahora tengo los\nPOKéMON mejores\012y más fuertes!\n¡Soy invencible!\012¡{PLAYER}!\n¡Yo te desafío!",
  ["64:715f"] = "Lo siento. Estamos\najustando la\011MÁQUINA DE LUCHA.",
  ["1d:463d"] = "He perdido…\012Hice todo lo\nque pude…\012Lo que tú tienes\ny yo no tengo…\012Empiezo a entender\nlo que me dijo\012aquel maestro\nde dragones…",
  ["64:7190"] = "¡Hola! Tú eres\n{PLAYER}, ¿no?\012¿Quieres recoger\nlo que tengo\011para ti?",
  ["1d:46ce"] = "Sigo queriendo\nser el mejor\011entrenador…\012Descubriré por qué\nno puedo ganar\012y ser más\nfuerte…\012Te desafiaré en\ncuanto lo sepa.\012Y te aplastaré\ncon todo\011mi poder.\012Hasta entonces,\n¡sigue entrenando!",
  ["64:71c4"] = "¡Aquí tienes!",
  ["1d:47aa"] = "¡Bah!\012Después de todo,\nnada mejor que\011el poder.\012No necesito\nnada más.",
  ["66:56e5"] = "En CIUDAD VERDE\nhay un lugar\012llamado la CASA\ndel ENTRENADOR,\012donde se reúne\ngente de todas\011partes.",
  ["1d:4a55"] = "El barco va a\nzarpar. Por favor,\011suba a bordo.",
  ["66:56a5"] = "Entrar por primera\nvez en un callejón\012me pone un\npoco nervioso.",
  ["1d:4a80"] = "Lo siento. No\npuedes embarcar.",
  ["66:564b"] = "¡Ñam… ñam…!\012Dicen que hay\nproblemas en la\011CENTRAL ENERGÍA.\012¡Ñam… ñam…!\n¡Estoy lleno!",
  ["1d:4a9c"] = "Bienvenido al\nFERRY S.S. AQUA.\012¿Vas a embarcar\nhoy?",
  ["66:55fc"] = "¡Ñam… ñam…!\012Dicen que en la\nCENTRAL de ENERGÍA\012tienen muchos\nproblemas.\012¡Ñam… ñam…!",
  ["1d:4ada"] = "¿Puedo ver tu\nTICKET BARCO?",
  ["66:558e"] = "Es SILPH S.A.,\nfamosa por sus\011artículos POKéMON.\012En el pasado, el\nTEAM ROCKET quiso\012hacerse con esta\ncompañía por esa\011misma razón.",
  ["1d:4af6"] = "Siempre a su\nservicio.",
  ["1d:4b11"] = "{PLAYER} enseña\nel TICKET BARCO.\012Muy bien.\n¡Gracias, joven!",
  ["6a:4e3b"] = "ANA-ANY: Nnn…\nDemasiado fuerte.",
  ["1d:4b41"] = "{PLAYER} intentó\nenseñar el TICKET\011BARCO…\012¡Pero no lo tiene!\012¡Lo siento!\nSólo puedes subir\012si tienes un\nTICKET BARCO.",
  ["6a:4e62"] = "ANA: Sé lo que\nestán pensando\012mi hermana y mis\nPOKéMON.",
  ["1d:4ba8"] = "El FERRY zarpará\nel próximo lunes.",
  ["6a:4e9c"] = "ANY: ¡ANA y yo\nestamos en esto\011juntas!",
  ["1d:4bce"] = "El FERRY zarpará\nel viernes.",
  ["6a:4ec5"] = "ANA-ANY: Nnn…\nDemasiado fuerte.",
  ["1d:4bf4"] = "Aquí es fácil\natrapar SHELLDER.\012En otros sitios\nson raros.",
  ["66:538d"] = "Aquí vive una niña\nque es experta en\012imitar a la\ngente.\012Imita incluso a\nla gente con\012la que habla,\ny te confunde.",
  ["1d:4c35"] = "¿Cuántas CAÑAS\ntienes?\012Las distintas\nCAÑAS sirven para\012atrapar distintos\nPOKéMON.",
  ["1d:4f31"] = "Lo siento. No\npuedes embarcar.",
  ["1d:4c76"] = "¡El S.S. AQUA usa\npropulsores para\011surcar las olas!",
  ["1b:7099"] = "¡Mi FARFETCH'D!\012¡Genial! ¡Lo has\nencontrado!\012Sin él no podíamos\nCORTAR árboles\012para conseguir\ncarbón.\012¡Gracias, chico!\012¿Cómo podría\nagradecértelo…?\012¡Ya sé! Toma\nesto.",
  ["6a:4f80"] = "Dormir o paralizar\na los POKéMON\012son buenas\ntécnicas de lucha.",
  ["5d:4ffd"] = "Me encontré con un\n{STRBUF}\011…\012Intenté cogerlo,\npero salió volando\012más rápido de lo\nque pensaba.\012Me decepcionó un\npoco.",
  ["6a:4fc8"] = "DOMINGO: ¡Hola!\012Soy DOMINGO, por\nel día. Es decir,\011¡hoy es domingo!",
  ["66:4fd8"] = "ENTRADA\nSUBTERRÁNEA",
  ["6a:5004"] = "¡Me dijeron que\nte diera esto si\011te veía!",
  ["66:4f81"] = "¡Tu zona de juego!\012CASINO DE\nCIUDAD TRIGAL",
  ["6a:502f"] = "¡Me dijeron que\nte diera esto si\011te veía!",
  ["6a:505a"] = "DOMINGO: Eso…\012¡Um…!\012¿Qué era…?\012…\012¡Ah! ¡Ahora lo\nrecuerdo!\012Debería llevarlo\nun POKéMON\012con habilidades\neléctricas.\012¡Mi hermana LUNA\ndice que mejora\012las habilidades\neléctricas!",
  ["66:4ee4"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\011TRIGAL: BLANCA\012¡La increíble y\nbella señorita!",
  ["18:63fb"] = "¡Llevas mucho peso\nen la mochila!\012¡Oye! ¿No tendrás\nalgo llamado\011CARTA EÓN?\012Mi hija está\nbuscando una.\012Puedes darme una,\n¿verdad?",
  ["66:4eab"] = "¡Una gran gama de\nartículos POKéMON!\012CENTRO COMERCIAL\nDE CIUDAD TRIGAL",
  ["18:648c"] = "¿Entregas una\nCARTA EÓN?",
  ["66:4e8f"] = "TORRE DE RADIO\nDE CIUDAD TRIGAL",
  ["18:64a4"] = "¡Oh, genial!\n¡Gracias, cariño!\012¡Toma esto en\nagradecimiento!",
  ["66:4e77"] = "ESTACIÓN DE\nCIUDAD TRIGAL",
  ["18:64e9"] = "¡A mi hija le\nencantará!",
  ["66:4e4b"] = "¡Prueba el\nverdadero terror\011del TEAM ROCKET!",
  ["18:6509"] = "¿Oh? ¿No tienes?\nQué lástima…",
  ["66:4e1f"] = "¡Eh, mocoso! ¡Tú\nno eres de aquí!\011¡Lárgate!",
  ["18:652a"] = "Oh… Bueno, en otra\nocasión será.",
  ["66:4de2"] = "Nuestro sueño se\ncumplirá pronto…\012Ha sido una lucha\ntan larga…",
  ["18:6549"] = "{PLAYER} entrega\nla CARTA EÓN.",
  ["66:4daa"] = "¿Los POKéMON?\n¡Sólo son\012herramientas para\nganar dinero!",
  ["18:6674"] = "",
  ["66:4d6d"] = "Asaltemos la\nTORRE de RADIO…\012¿Qué? ¡Y a ti\nqué te importa!",
  ["18:66f9"] = "Cuando enlazaste\ncon alguien por\012teléfono móvil por\nprimera vez, ¿no\011te impresionó?\012¡La primera vez\nme impresionó\012tanto que me puse\na temblar!",
  ["66:4d4e"] = "¡Fuera de mi\ncamino! ¡Pesado!",
  ["18:6795"] = "Fueron capaces de\nconstruir este\012gran edificio\ngracias a los\012avances en\ntecnología\011inalámbrica.",
  ["66:4d2a"] = "¿Qué quieres,\npesado? ¡Fuera!",
  ["18:67ee"] = "Es una nota sobre\ndónde deben usarse\012los ADAPTADORES de\nMÓVIL…",
  ["66:4d0d"] = "Así que ésta es la\nTORRE de RADIO…",
  ["18:6828"] = "",
  ["66:4ccf"] = "¡Uau! Esta ciudad\nes muy grande.\012No sé dónde\nestá nada.",
  ["18:68f4"] = "Para usar el\nCENTRO DE CAMBIO o\012leer las NOTICIAS\nPOKéMON, necesitas\012llamar al CENTRO\nMÓVIL.\012Debes inscribirte\nen el CENTRO MÓVIL\012antes de poder\nconectarte.",
  ["66:4c83"] = "El hombre de esa\ncasa evalúa los\012nombres de\ntus POKéMON.\012Y puede renombrar\na tus POKéMON.",
  ["18:6989"] = "Es una nota sobre\ncómo usar el\011teléfono…",
  ["66:4c36"] = "¡Eh, eh, eh…!\012Me he metido en\nlíos por jugar en\012el sótano del\nCENTRO COMERCIAL.",
  ["18:69ae"] = "Asegúrate de que\ntu teléfono y el\012ADAPTADOR de MÓVIL\nestán bien\011conectados.\012Cuida que haya\nbuena cobertura en\011tu móvil.\012No toques ni\ncuelgues el móvil\011mientras conecta.",
  ["66:4c14"] = "¡Oh, tu POKéGEAR\nsirve de radio!",
  ["18:6a5a"] = "Si el servidor\nestá ocupado, no\012será posible\nconectar.\012Inténtalo más\ntarde.\012Si no consigues\nconectar o no\012comprendes los\nmensajes de error,\012llama a Atención\nal Cliente o lee\011las instrucciones.",
  ["66:4b73"] = "La TORRE de RADIO\nde CIUDAD TRIGAL\011es muy importante.\012Ahora están en\nuna campaña\011promocional.\012Modificarán tu\nPOKéGEAR para\012que te sirva\ntambién de radio.",
  ["18:6b26"] = "",
  ["66:4b2d"] = "¿Pertenecía ese\nhombre de negro\012al TEAM ROCKET?\n¡Es increíble!",
  ["18:6c80"] = "El ENCINAR es muy\ngrande. ¡Cuidado!\011No te pierdas.",
  ["66:4ae6"] = "¿Ese hombre de\nnegro se ha\012vestido como uno\ndel TEAM ROCKET?\011¡Qué tonto!",
  ["18:6cb0"] = "El ENCINAR está\nvigilado por su\011guardián.\012¡No hagas\nnada malo!",
  ["66:4aa9"] = "Sé que hay una\nnueva TIENDA de\012BICIS, pero no\nla encuentro.",
  ["29:6200"] = "Bien… Eres\nmuy especial.\012Si hubiera empeza-\ndo con los POKéMON\011cuando era joven…\012Quiero que te\nesfuerces por los\012dos, así que coge\nesto… ¿Vale?",
  ["66:4a69"] = "Han construido una\nTORRE RADIO nueva\012que sustituye a\nla antigua.",
  ["29:6295"] = "Me enfada bastante\nperder. Tendré que\012entrenarme mucho\nmás…\012Éste es mi número.\nSoy ELISA. ¡No lo\012olvides! ¿Quieres\nluchar de nuevo?",
  ["66:479c"] = "EL ENCINAR\012Entra por la\npuerta",
  ["29:6316"] = "Quiero luchar\ncontigo otra vez.\012¿Quieres que\nintercambiemos\012nuestros números\nde teléfono?",
  ["66:478d"] = "CASA DEL CARBONERO",
  ["29:6359"] = "¡Me acordaré de\nllamarte cuando\011quiera luchar!",
  ["66:46e7"] = "POZO SLOWPOKE\012Conocido también\ncomo POZO LLUVIA.\012Los nativos creen\nque el bostezo de\012SLOWPOKE invoca\nla lluvia.\012Hace 400 años\nun bostezo de\012SLOWPOKE acabó\ncon una sequía.",
  ["29:638c"] = "Oh… Estoy triste…\nSi quieres luchar,\012ven a verme…\n¡Soy ELISA!",
  ["66:46a1"] = "LÍDER DEL GIMNASIO\nPOKéMON DE PUEBLO\011AZALEA: ANTÓN\012La enciclopedia\nandante de los\011POKéMON bicho",
  ["29:63cc"] = "Oh, no. No admite\nmás números.",
  ["66:4693"] = "CASA DE CÉSAR",
  ["29:63f1"] = "¡Ajá! ¡Te\nesperaba!\011¡Comencemos!",
  ["66:465a"] = "PUEBLO AZALEA\nDonde la gente y\012los POKéMON viven\nen feliz armonía",
  ["29:6411"] = "¡Qué mal!\nNo tienes sitio…\012Te lo daré en\notra ocasión.",
  ["66:4628"] = "¿Puedes ir a ver\npor qué el ENCINAR\011está tan inquieto?",
  ["29:6454"] = "Oh… ¡He perdido\notra vez!\012Me gustaría saber\ncuántas veces va a\011repetirse…\012¡Gracias! ¡Coge\neste regalo!",
  ["66:460b"] = "¡{PLAYER}, aquí\ntienes tu GS BALL!",
  ["5d:4000"] = "¡Hola, {PLAYER}!\n¡Las ventas de\012BICIS han subido\nespectacularmente!\012Y todo gracias a\nla publicidad\012que has hecho\ncon nuestra BICI.\012Quédate con esa\nBICI como\012agradecimiento.\n¡Gracias de nuevo!",
  ["66:45df"] = "¡El ENCINAR está\ninquieto!\012¿Qué está pasando?",
  ["5d:40c0"] = "La inteligencia de\nmi {STRBUF}\012sigue creciendo.\n¡Va a ser más lis-\011to que los tuyos!",
  ["66:45c3"] = "(bostezo)……",
  ["5d:4106"] = "El otro día,\nderroté a\011{STRBUF}.\012Creo que cambiar\ntrucos contigo\012está empezando a\ndar sus frutos.",
  ["66:45b0"] = "SLOWPOKE: …\012…… …… ……",
  ["5d:4165"] = "Oh… y escucha…\nIntenté atrapar un\012{STRBUF}, pero\nfallé muy poco.\012Si hubiera estado\nun poco mejor\012informado, seguro\nque sería mío…",
  ["66:451a"] = "Ataja por PUEBLO\nAZALEA y llegarás\011al ENCINAR.\012Pero estos\narbolitos te\011impiden pasar.\012Los POKéMON del\nCARBONERO pueden\011CORTAR árboles.",
  ["5d:41e1"] = "¿Quieres luchar?\nTe enseñaré como\011luchar con lógica.\012Estaré en\n{STRBUF}.\012Avísame si estás\nen las cercanías.",
  ["66:44ce"] = "¿Viste a CÉSAR\npara que te diera\011algunas BALL?\012Muchas personas\nlo hacen.",
  ["5d:4251"] = "¡Hasta luego!",
  ["5d:4261"] = "¿Sabías qué…?\012Cuando llueve, el\nataque TRUENO\011siempre golpea.",
  ["19:41e8"] = "¡Lo sé, lo sé,\nlo sé!\012¡Me he enterado de\ntu heroica libera-\011ción de la TORRE\011RADIO!\011¡Eres genial!",
  ["5d:429d"] = "¿Sabías qué…?\012Si usas RIZO\nDEFENSA, sube la\012potencia de\nDESENROLLAR.",
  ["19:4247"] = "¡Lo vi, lo vi!\012¡Vi como entrabas\nen la GUARIDA\011DRAGÓN!\012¡Sabía que\npodrías hacerlo!\012¡No hace falta\ntanta modestia!\012¡No podías fallar!",
  ["5d:42ee"] = "¿Sabías qué…?\012Si el sol es\nabrasador, no hay\012que cargar RAYO\nSOLAR.",
  ["19:42bb"] = "Ayer fui a PUEBLO\nPRIMAVERA.\012Había una señora\nque se parecía\012mucho a ti,\n{PLAYER}.\012¿Qué? ¿Esa señora\nera tu madre?\012¡Debería haberme\npresentado!\012Seguro que tu\nmadre está muy\012orgullosa de lo\nque has hecho.\012Míralo de este\nmodo. Yo también\012lo estaría si\nfuera tu madre.\011¡Créeme!",
  ["5d:4340"] = "¿Sabías qué…?\012Si el rival usa\nREDUCCIÓN, tu\012PISOTÓN será mucho\nmás potente.",
  ["19:43d4"] = "¡Lo vi, lo vi,\nlo vi!\012¡Subiste a un\nbarco, {PLAYER}!\012¡No puedes ni\nimaginar lo bien\012que te queda el\nmar de fondo!",
  ["5d:4391"] = "¿Sabías qué…?\012Si tu rival usa\nVUELO, tu TORNADO\012será mucho más\npotente.",
  ["19:4448"] = "¡Ya sé, ya sé!\012¡Tienes un PASE\npara el\011MAGNETOTRÉN!\012Cuando te vi par-\ntir en el barco,\012me sentí muy\ntriste porque no\012te podría ver en\ncierto tiempo.\012¡Pero, como tienes\nese PASE, puedes\012regresar en un\ninstante!\011¡Qué alivio!\012¿Qué? ¿Puedes\nVOLAR de vuelta en\011cualquier momento?\012¿Qué quieres decir\ncon VOLAR?",
  ["5d:43e3"] = "¿Sabías qué…?\012Si tu rival usa\nVUELO, tu CICLÓN\012será mucho más\npotente.",
  ["19:455b"] = "¡Lo vi, lo vi!\012¡Despertaste a\nSNORLAX!\012Te estaba mirando\nde lejos, así que\012no sabría decir lo\nque hiciste\011exactamente.\012¿Tocaste una\nflauta para\011despertarle?\012¡Uau! ¡Como por\narte de magia!",
  ["5d:4433"] = "¿Sabías qué…?\012Si tu rival usa\nEXCAVAR, tu\012TERREMOTO será\nmás potente.",
  ["19:45ff"] = "He oído rumores\nacerca de ti por\011todo el lugar.\012Me da envidia,\n{PLAYER}.\012¿Cómo puedes ser\ntan fuerte?\012¡Ve a por el\ncampeonato del\011mundo ahora!\012¡Siempre te estaré\nanimando!",
  ["5d:4485"] = "¿Sabías qué…?\012Si tu rival usa\nEXCAVAR, tu\012MAGNITUD será\nmás potente.",
  ["19:46a3"] = "¡Je, je, acabo de\nllamar!\012¡Creo que podemos\nser buenos amigos!",
  ["5d:44d6"] = "¿Sabías qué…?\012Los tipos roca,\ntierra y acero no\012pueden ser dañados\npor TORM. ARENA.",
  ["19:46df"] = "¡Lo vi, lo oí!\012¡Derrotaste a\nMORTI del GIMNASIO\011de CIUDAD IRIS!\012¡Eso es increíble!\012En realidad, fui a\nla entrada del\012GIMNASIO a\nanimarte.\011¿Lo sabías?\012Pero todo el mundo\nflotaba y había\012fantasmas por todo\nel lugar. Así que\012me asusté y me fui\na casa…",
  ["5d:4522"] = "¿Sabías qué…?\012Si el sol es\nabrasador, los\012ataques de agua\nson más débiles.",
  ["19:47d8"] = "¡{PLAYER}, lo oí!\012¡Organizaste un\nbuen jaleo en\012KANTO!\n¡Qué glorioso\012espectáculo tuvo\nque ser!\012¡Cómo molas!",
  ["5d:4571"] = "¿Sabías qué…?\012Cuando llueve, los\nataques de fuego\012son más débiles de\nlo habitual.",
  ["19:4846"] = "¡Oír lo de tus\naventuras me\012alegra el alma!\n¡Te lo aseguro!",
  ["5d:45c2"] = "Mi amigo ha oído\nalgunos trucos\011geniales.\012Me va a enseñar\nalgunos.\012Cuando me los\ndiga, te llamaré\011para contártelos.",
  ["19:4881"] = "¡Me encanta que\nhayas llamado!\012¡Estaba a punto de\nllamarte yo!\012¡Creo que podemos\nllevarnos bien!",
  ["5d:4638"] = "¡Eh, {PLAYER}!\012¿Recuerdas tu\npromesa?\012¡Tenemos que\nluchar pronto!\012Estaré en\n{STRBUF}.",
  ["19:48dc"] = "¿Cómo estás?\012¿Qué estás\nhaciendo?\012¿Dónde estás?\012¿Cuántas MEDALLAS\nhas conseguido?\012¿Cuánto dinero has\nahorrado?\012¿Cómo está tu\nmadre?\012¿Tienes muchos\nPOKéMON?\012¿Va a hacer sol\nmañana?\012Arrgh… ¡Hay\ntantas cosas de\012las que quiero\nhablar! ¡Esto no\012lleva a ninguna\nparte!",
  ["5d:4688"] = "¡He arreglado a\nmi {STRBUF} y\012está más guapo que\nnunca!",
  ["19:49dc"] = "¡Siempre estoy con\nmi {STRBUF}!\012¡Es tan mono!\n¡Me encanta!",
  ["5d:46c3"] = "Hace poco me\nencontré con un\011SNUBBULL salvaje.\012Te puedo asegurar\nque mi SNUBBULL\012es mucho más guapo\nque el salvaje.",
  ["19:4a13"] = "Cambiando de tema,\nhe visto a un\012{STRBUF} por\nprimera vez.\012La verdad, fue\nfácil vencerlo.",
  ["5d:4734"] = "Hace poco me\nencontré con un\012MARILL salvaje.\nO eso pensaba.\012Mirándolo más de\ncerca vi que era\012un {STRBUF}.\nMe disgusté mucho.",
  ["19:4a71"] = "Me pregunto…\n¿tienes algún\011{STRBUF}?\012No consigo atrapar\nninguno. ¿Cuál\012será su punto\ndébil?",
  ["68:534c"] = "Estoy esperando a\nlos POKéMON\012que aparecen sólo\npor la noche.",
  ["19:4ada"] = "¡Enfrentemos a\nnuestros POKéMON!\012¡No me vencerás ni\nen combate ni en\012el Concurso de\nCaptura de Bichos!\012¡Estaré en\n{STRBUF}!",
  ["68:537c"] = "Estoy esperando a\nlos POKéMON\012que aparecen sólo\npor la mañana.",
  ["19:4b48"] = "Volvemos a hablar\npronto, ¿vale?",
  ["68:53b2"] = "MARTA: Creo que\nes la primera\012vez que nos\nvemos.\012Déjame que me\npresente. Soy\012MARTA, por\nmartes.",
  ["19:4b5f"] = "¡Qué bien que te\nlocalizo!\012¡Hay un montón de\n{STRBUF} por\012los alrededores de\n{STRBUF}!\012¡No te lo puedes\nperder!",
  ["68:542f"] = "Como presentación,\npor favor, toma\012este regalo:\nun LAZO ROSA.",
  ["19:4bc6"] = "Últimamente no he\ntenido suerte para\011ver POKéMON raros…\012¡Pero sé que están\nahí fuera!",
  ["66:435b"] = "¡Ja! Sabía\nque mentías.",
  ["19:4c13"] = "Eh, ¿dónde estás?\012Luchemos. ¡Te\nestaré esperando\011en {STRBUF}!",
  ["66:4233"] = "Odio a los\ndébiles.\012Ya sean POKéMON\no entrenadores. Da\011igual quién o qué.\012Seré fuerte\ny acabaré con los\011enclenques.\012Eso también va por\nel TEAM ROCKET.\012Son fuertes cuando\nestán en grupo,\012pero si están\nsolos, son unos\011cobardes.\012¡Cuánto les odio!\012¡Fuera de mi\nvista! ¡Eres tan\012insignificante\ncomo el resto!",
  ["19:4c5a"] = "¿Hola? ¿Vienes o\nqué?\012¡Te vas a perder\na YANMA!\012¡Ven a la RUTA 35\ninmediatamente!",
  ["66:41e6"] = "¡Vaya!\n¡Inútiles POKéMON!\012¡Escúchame! ¡Has\nganado porque\012mis POKéMON\neran débiles!",
  ["19:4cbd"] = "Mi {STRBUF} está\ncada vez más\012fuerte, ¡justo\ncomo calculé!",
  ["66:414d"] = "Dime una\ncosa…\012¿Es cierto que\nel TEAM ROCKET\011ha vuelto?\012¿Qué? ¿Los has\nderrotado? ¡Anda!\011¡No me mientas!\012¿Bromeas?\nPues a ver lo\011bueno que eres.",
  ["19:4cf3"] = "Por cierto, el\notro día noqueamos\012a un {STRBUF}\nsalvaje.\012¡Estudiar\nfunciona!",
  ["65:7661"] = "Estoy demasiado\nlejos. ¡Mejor que\011llame a casa!",
  ["19:4d4f"] = "Por cierto, ayer\nse me escapó un\012{STRBUF}\nsalvaje.\012Ha sido un error\nde cálculo mío…",
  ["65:763a"] = "¡Hola!\n¿Has visitado la\011TORRE BELLSPROUT?",
  ["19:4da4"] = "¡He estado\nestudiando este\012tiempo y he\nmejorado mucho!\012Estoy en\n{STRBUF}.\012¿Te puedes pasar\npara luchar?",
  ["65:75ac"] = "¡Un montón de\nmonedas extrañas!\012Quizá sean de\notro país…",
  ["19:4e1f"] = "¡Hasta luego!",
  ["65:7584"] = "Es un ordenador\nenorme. ¡Mmm!\011Está estropeado.",
  ["19:4e2f"] = "¡Je, je, he cogido\nalgo interesante!\012¡Es tuyo!\n¿Por qué no vienes\012a {STRBUF}\ny te lo llevas?",
  ["65:7543"] = "Lleno de revistas\nextranjeras.\012Ni siquiera puedo\nleer los títulos.",
  ["19:4e90"] = "Todavía no he\ncogido nada.\012Te llamaré si\nencuentro algo.",
  ["65:750d"] = "Es una pena.\nEs realmente\011raro.",
  ["19:4ed4"] = "¡Si no luchamos\npronto, olvidaré\011mis estrategias!\012¡Te espero en\n{STRBUF}!",
  ["65:7476"] = "¿Mmm? ¡Esa ESCAMA!\n¿De qué es? ¿De\011un GYARADOS rojo?\012¡Es muy rara!\nQuiero tenerla…\012{PLAYER}, ¿quieres\nintercambiarla?\012Yo te ofrezco\nREPARTIR EXP.\012Me lo dio\nel PROF. OAK.",
  ["19:4f1a"] = "Tengo que hacer\nlos deberes,\012¿vienes ahora a\npor tu regalo?\012¡Te espero en\n{STRBUF}!",
  ["65:73de"] = "Busca muchos\ntipos de POKéMON\012y completa esa\nPOKéDEX.\012Ahora tengo\nque irme.\012Me esperan en\nCIUDAD TRIGAL para\012presentar mi\nprograma de radio.\012¡{PLAYER}, cuento\ncontigo!",
  ["19:4f74"] = "¡Mi {STRBUF}\nestá precioso!\012¡Le he hecho un\nmontón de fotos!",
  ["65:73cc"] = "¡{PLAYER} recibió\nla POKéDEX!",
  ["19:4fb2"] = "Acabé con un\n{STRBUF} salvaje\011en un segundo.\012Debe de ser porque\nla última vez me\012diste consejos\nde combate.",
  ["65:7185"] = "OAK: ¡Así que tú\neres {PLAYER}!\012¡Yo soy OAK!\n¡Un científico\011POKéMON!\012Estaba visitando a\nmi viejo amigo el\011SR. POKéMON.\012Y como me dijo que\ntenías algo para\012el PROF. ELM,\ndecidí esperarte.\012¡Oh! ¿Qué es esto?\n¡Un POKéMON raro!\012Veamos…\012¡Mmm, ya veo!\012Ahora entiendo por\nqué el PROF. ELM\012te confió un\nPOKéMON.\012Para científicos\ncomo el PROF. ELM\012y yo, los POKéMON\nson amigos.\012Sabía que\ntratarías a tus\012POKéMON con\nmucho cariño.\012¡Ah!\012Pareces ser de\nconfianza.\012¿Te gustaría\nayudarme?\012Mira. Ésta es la\núltima versión de\011la POKéDEX.\012Registra los datos\nde los POKéMON\012que has atrapado\no que has visto.\012¡Es una moderna\nenciclopedia!",
  ["19:501c"] = "¿Sabes una cosa?\nSe me ha vuelto a\012escapar un\n{STRBUF}\011salvaje.\012¡Estuvo tan cerca!\nEn serio, un poco\011más y hubiera…",
  ["65:714a"] = "¡La vida es\ngenial! ¡Siempre\012quedan cosas por\ndescubrir!",
  ["65:7134"] = "¡Confío\nen ti!",
  ["65:70ed"] = "¿Vas a ir a ver\nal PROF. ELM?\012Toma. Tus POKéMON\ndeberían descansar\011un poco.",
  ["65:70b7"] = "Si tengo razón,\nel PROF. ELM lo\011sabrá.",
  ["65:7092"] = "Hasta el PROF. OAK\nlo reconoce.",
  ["65:6feb"] = "Conozco a una\npareja que tiene\012una GUARDERÍA\nPOKéMON.\012Ellos me dieron\nese HUEVO.\012Como me intrigaba,\nle mandé una carta\011al PROF. ELM.\012El PROF. ELM es la\nmáxima autoridad\012en evolución de\nlos POKéMON.",
  ["65:6fd2"] = "{PLAYER} recibió\nun HUEVO MIST.",
  ["65:6fa8"] = "Esto es lo que\nquiero que\012examine el\nPROF. ELM.",
  ["65:6f66"] = "¡Hola! Debes de\nser {PLAYER}.\012El PROF. ELM dijo\nque vendrías.",
  ["65:6dec"] = "Busca BAYAS\nen los árboles.\012Son muy fáciles\nde encontrar.",
  ["65:6d82"] = "Los POKéMON\ncomen BAYAS.\012Mi POKéMON se\ncuró comiendo\011una BAYA.\012Toma. ¡Te daré\nuna!",
  ["65:6cfc"] = "¿Se transforman?\012¡Alucinaría si\nlo viera!",
  ["65:6cc3"] = "Luchando, los\nPOKéMON ganan\012experiencia y se\ntransforman.",
  ["65:6c0d"] = "¡Cuando era niño,\nera un brillante\011entrenador!\012Éste es mi\nconsejo: ¡Atrapa\011muchos POKéMON!\012¡Y trátalos con\nmucho cariño!",
  ["65:6b65"] = "¡Cuando sea mayor,\nvoy a ser un LÍDER\011de GIMNASIO!\012¡Hago luchar a mis\nPOKéMON con los\012de mi amigo para\nfortalecerlos!",
  ["65:6aea"] = "¿Quieres saber lo\nbueno que eres\012como entrenador\nPOKéMON?\012Pues vete a los\nGIMNASIOS POKéMON\012de JOHTO y gana\nmuchas MEDALLAS.",
  ["65:6a46"] = "El CENTRO de\nCOMUNICACIONES de\012arriba está recién\nconstruido.\012¡Yo ya he cambiado\nPOKéMON en él!",
  ["65:69f1"] = "El CENTRO de\nCOMUNICACIONES de\012arriba está recién\nconstruido.\012Pero aún no está\nterminado.",
  ["65:69c8"] = "Ese PC puede ser\nusado por todo\011entrenador.",
  ["65:698a"] = "¡Es genial! Puedo\nguardar a todos\012los POKéMON que\nquiera, ¡y gratis!",
  ["65:68a0"] = "Cuando iba por la\nhierba, un POKéMON\012bicho envenenó\na mis POKéMON.\012Yo seguí andando,\npero mi POKéMON\011se debilitó.\012Deberías llevar un\nANTÍDOTO contigo.",
  ["65:6873"] = "¡Tengo POKé BALL\nde reserva! ¡Puedo\011atrapar POKéMON!",
  ["65:6834"] = "¡Se han quedado\nsin POKé BALL!\012¿Cuándo\nconseguirán más?",
  ["65:67a1"] = "¿Estás trabajando\nen una POKéDEX?\012Es muy importante.\n¡No te rindas!",
  ["65:6726"] = "Es una foto de una\nextensa pradera\012llena de POKéMON\nraros jugando.",
  ["65:66ea"] = "Es una foto de un\nanciano sonriente\012rodeado de\nPOKéMON.",
  ["65:6691"] = "Mucha gente se\nenfadó cuando\012cerraron la ZONA\nSAFARI, pero el\011abuelo es terco.",
  ["65:65e6"] = "Mi abuelo es el\nGUARDA de la ZONA\011SAFARI.\012Al menos lo era…\012Decidió irse de\nvacaciones y se\012fue al extranjero\nél solo.\012Así fue como dejó\nde ocuparse de\011la ZONA SAFARI.",
  ["65:654e"] = "¿Has visto? ¡Ahora\nsoy como ella!",
  ["65:652e"] = "¡Soy SACHIKO!\nAbracadabra…",
  ["65:64dc"] = "Me sorprendió\nmucho el GIMNASIO.\012Había tres chicas\nque parecían\011idénticas.",
  ["65:6494"] = "¡Anda! Tienes un\nnuevo tipo de\011POKéDEX.\012¿Te la ha dado\nel PROF. OAK?",
  ["65:63f9"] = "He visto a unos\nlentos y raros\012POKéMON en el\nCAMINO DE BICIS.",
  ["65:63c3"] = "Mi abuelo está en\ncasa de mi hermano\012BILL, en CABO\nCELESTE.",
  ["65:6325"] = "¡Qué bien luchas,\nentrenador\011de JOHTO!",
  ["65:6299"] = "¡Hola, futuro\nCAMPEÓN!\012Echa un vistazo a\ntu alrededor.\012Todos los\nentrenadores se\011parecen a SACHIKO.\012¿Cuál será la\nauténtica SACHIKO?",
  ["65:626b"] = "¡Eh, tú!\n¿No era bueno mi\011disfraz?",
  ["65:624a"] = "¿A que era bueno\nmi disfraz?",
  ["65:6228"] = "¡Uajajaja!\012Acertaste, joven.\n¡Yo soy SACHIKO!",
  ["65:620c"] = "Debes de estar\ncansado.",
  ["65:61f1"] = "¡Maldición!\n¡Quería ganar!",
  ["65:61bb"] = "¡Soy SACHIKO!\012¿Cómo has sabido\nque no era yo?\012¡Luchemos!",
  ["65:6199"] = "¿Qué? ¿Mi disfraz\nno era perfecto?",
  ["65:617b"] = "¡Oh…! He perdido…\nNo eres débil…",
  ["65:6166"] = "¡Te he engañado!\n¡Ja ja ja!",
  ["65:6139"] = "¿Cómo reconocerás\na la auténtica\011LÍDER?",
  ["65:6126"] = "Te he engañado…",
  ["65:60e6"] = "¡Fufufu! ¡Soy\nSACHIKO, la LÍDER\011del GIMNASIO!\012¡No, no soy yo!\n¡Qué tonto eres!",
  ["65:6074"] = "SACHIKO: Voy a\nesforzarme por\012mejorar mis\nhabilidades.\012¡Quiero llegar a\nser mejor que mi\011padre y que tú!",
  ["65:6002"] = "SACHIKO: ¡Eres tan\nfuerte! ¡Tengo un\011regalo para ti!\012Es TÓXICO, un\npotente veneno que\012va agotando los\nPS de la víctima.",
  ["65:5feb"] = "{PLAYER} recibió\nla MEDALLA ALMA.",
  ["65:5fa1"] = "SACHIKO: Eres un\ntipo duro. ¡Y, sin\011duda, has ganado!\012Aquí tienes la\nMEDALLA ALMA.",
  ["65:5f35"] = "¡Fufufufu…!\012Lo siento\nmucho…\012¡Sólo bromeaba!\012¡Soy la auténtica!\012Soy SACHIKO, del\nGIMNASIO FUCSIA.\011¡La original!",
  ["65:5d36"] = "La nieta del\nGUARDA de la ZONA\012SAFARI vive en la\nciudad.",
  ["65:5cf5"] = "Esperaba comprar\nalgunos souvenirs\012en la ZONA SAFARI,\npero está cerrada.",
  ["65:5bfd"] = "Tenía un\nmovimiento que\012quería enseñar\na mi POKéMON.\012Así que usé el\nQUITA-MOVIMIENTOS\011y eliminé una MO.",
  ["65:5b85"] = "En el corazón de\nla remota MESETA\012AÑIL se celebra la\nLIGA POKéMON.\012Dicen que allí se\nreúnen los mejores\012entrenadores de\ntodo el país.",
  ["65:5ae9"] = "MÁX. REPEL evita\nque se acerquen\011POKéMON débiles.\012Es el repelente\nmás duradero\011de todos.",
  ["65:5a6a"] = "No puedes comprar\nMÁX. REVIVIR. Pero\012éste reanima\na un POKéMON\011debilitado.\012Atención: No\nrestaura los PP o\012PUNTOS de PODER de\nlos movimientos.",
  ["65:59ee"] = "DRATINI: ¡Draa!",
  ["65:595c"] = "En CIUDAD ENDRINO\nvive un clan que\012puede controlar a\nlos dragones\011a su antojo.\012Por ello, hay\nmuchas leyendas\012acerca de dragones\nen esta ciudad.",
  ["65:58a5"] = "¡La piedra cayó\npor el agujero!",
  ["65:4800"] = "JOSUÉ: ¿Quién\neres tú?\012Soy JOSUÉ, por\njueves.",
  ["65:47aa"] = "Yo también estudio\n5 horas al día.\012Leyendo libros\npuedes aprender\011muchas cosas.",
  ["65:4790"] = "¡Uups! ¿Error de\ncálculo?",
  ["65:4760"] = "¡Gracias a mis\nestudios, estoy\012preparado para\ncualquier POKéMON!",
  ["65:471e"] = "Sería fuerte si\npudiera saber lo\012que está pensando\nmi rival.",
  ["65:470e"] = "¡Te malinterpreté!",
  ["65:46ed"] = "¡Te voy a leer\nel pensamiento!",
  ["65:469e"] = "Ese árbol extraño\ndesapareció sin\011dejar rastro.\012¡Oh! ¿Ese árbol\nera un POKéMON?",
  ["65:4626"] = "Un árbol extraño\nbloquea el camino\011a CIUDAD TRIGAL.\012No me permite\nir de compras.\012Habría que hacer\nalgo.",
  ["65:452c"] = "Se trata del\nGOLPE ROCA.\012Puedes destrozar\nrocas con un\012simple golpe bien\ndirigido.\012Si encuentras una\nroca en tu camino,\011¡destrózala!",
  ["65:44d0"] = "¿Quitaste ese\npobre árbol?\012¡Estoy\nimpresionado! Toma\011esto.",
  ["65:446f"] = "¡Cielos!\012Iba a quitar\nese árbol con\012un gran\nderechazo.\012Pero no pude.\n¡Soy un fracaso!",
  ["65:43ed"] = "Cuando le hablé a\nmi hermana de ese\012árbol, me dijo que\nera peligroso.\012Si venzo a BLANCA,\nquizás me preste\011su REGADERA…",
  ["65:42f1"] = "¡Soy FLORA, de\nla FLORISTERÍA!\012¡Escucha!\012¡Cuando le eché\nagua a ese árbol\012extraño, saltó\nhacia atrás!\012Debe de tratarse\nde un POKéMON.\012¡Apuesto a que\nle sacarías del\012disfraz si lo\nmojaras!\012¡Ya sé! ¡Le\npediré a mi\012hermana su\nREGADERA!",
  ["65:42aa"] = "¡Al árbol extraño\nno le gusta la\011REGADERA!\012¡El árbol extraño\natacó!",
  ["65:4290"] = "{PLAYER} usó\nla REGADERA.",
  ["65:426b"] = "Un árbol extraño.\n¿Usar REGADERA?",
  ["64:7644"] = "Tus POKéMON serán\ncurados totalmente\011antes del combate.",
  ["64:7521"] = "Tu amigo está\npreparado.",
  ["64:74a0"] = "Tu amigo está\npreparado.",
  ["64:72bc"] = "¡Perdona!\012Según las reglas\nde ESTADIO, trae\012seis POKéMON, que\nno sean HUEVOS.\012Los 6 POKéMON\ndeben ser\011diferentes.\012Además, no pueden\nllevar objetos\011idénticos.\012Vuelve cuando todo\nesté listo.",
  ["64:729a"] = "¿Qué te parece\neste estilo?",
  ["64:7278"] = "Debemos cambiar\nel aspecto…",
  ["64:7266"] = "Oh, espera.",
  ["64:724d"] = "¿No? Es muy\nextraño…",
  ["64:71ef"] = "¡Oh! No tienes\nespacio para esto.\012Para en cualquier\nCENTRO POKéMON\012del país y podrás\nrecogerlo.",
  ["64:71d2"] = "Esperamos poder\nayudarte de nuevo.",
  ["64:5f8b"] = "El TEAM ROCKET ya\nno está en KANTO.\012Eso hace que\nme sienta mejor.",
  ["64:5f16"] = "Quiero ir a CIUDAD\nAZAFRÁN para ver\011el MAGNETOTRÉN.",
  ["64:5ec0"] = "¿Has oído hablar\ndel MAGNETOTRÉN?\012Es un tren que\nva hasta CIUDAD\011TRIGAL, en JOHTO.",
  ["67:6dbc"] = "RUTA 19\012CIUDAD FUCSIA -\nISLAS ESPUMA",
  ["64:5dfc"] = "Escuchemos\natentamente a\011los entrenadores.",
  ["67:6de5"] = "Por favor, ten\ncuidado si vas\012nadando hasta las\nISLAS ESPUMA\012POLICÍA C. FUCSIA",
  ["64:5db1"] = "¡Es un CLEFAIRY!\n¿Verdad?\012¡No! Es un\nPOKé MUÑECO\011CLEFAIRY.",
  ["67:7006"] = "MISTY: ¡Eh!\n¿Por qué\012has venido a\nmolestarnos ahora?\012¿Sabes cómo llaman\na la gente\011como tú?\012¡Pesados! Me has\noído bien, pesado.\012…\012¡Oh! Esas\nMEDALLAS… ¿Son\012de los GIMNASIOS\nde JOHTO?\012Si tienes ocho,\nserás muy bueno.\012De acuerdo. Ven\nal GIMNASIO de\011CIUDAD CELESTE.\012Me enfrentaré a\nti encantada.\012Soy MISTY, la\nLÍDER del GIMNASIO\011de CIUDAD CELESTE.",
  ["64:5d58"] = "Tu MOCHILA está\nrepleta.",
  ["67:714d"] = "¡Véncenos a los\nseis para ganar\012un fantástico\npremio!\012¿Lo conseguirás?",
  ["64:5d0a"] = "{PLAYER} recibió\nPOKé MUÑECO.",
  ["67:71a2"] = "¡Uau! Muy bien.",
  ["64:5bff"] = "Me gusta CLEFAIRY,\npero jamás podría\012atrapar uno.\nPor eso me\012conformo con este\nPOKé MUÑECO\011que he encontrado.",
  ["67:71b5"] = "Hice lo que pude.\nNo me arrepiento.",
  ["64:5b6d"] = "Al PRESIDENTE\nle encanta hablar\012cuando se trata de\nPOKéMON…",
  ["67:71d8"] = "Ahora me toca a\nmí. ¡En guardia!",
  ["64:5ae0"] = "¡Hola, {PLAYER}!\012¿Has vuelto para\nsaber más cosas\011sobre mis POKéMON?\012¿No? Pues tengo\nmás historias…",
  ["67:71f5"] = "¿Cómo he\npodido perder?",
  ["64:5a3d"] = "¡Gracias por\nescucharme!\011¡Toma esto!",
  ["67:7208"] = "Hice lo que pude.\nNo me arrepiento.",
  ["67:722b"] = "¡Soy el tercero!\nY no será fácil.",
  ["64:573b"] = "Tienes algunas\nMEDALLAS que no\011había visto nunca.\012¡Claro! Las has\nganado en JOHTO.",
  ["67:7249"] = "¡Au! ¡Se acabó!",
  ["64:5698"] = "Antes había un\nPOKéMON durmiendo\012delante de la\nCUEVA de DIGLETT.\012Pero parece que\nha desaparecido.",
  ["67:725c"] = "Hice lo que pude.\nNo me arrepiento.",
  ["67:727f"] = "¡Yo soy la cuarta!\n¿Cansado?",
  ["64:5496"] = "Soy el TÍO PESCA-\nDOR, el mayor de\012los HERMANOS\nPESCADORES.\012¿Conoces al GURÚ\nPESCADOR del LAGO\011DE LA FURIA?\012Sueña con ver el\nMAGIKARP más\011grande del mundo.\012Si no te importa,\n¿podrías mostrarle\012todos los MAGIKARP\nque captures?\012Quién sabe,\npodrías capturar\012el MAGIKARP de sus\nsueños.",
  ["67:7299"] = "He perdido…",
  ["64:535e"] = "RUINAS ALFA\nENTRADA ESTE",
  ["67:72a6"] = "Hice lo que pude.\nNo me arrepiento.",
  ["67:72c9"] = "Yo soy el quinto.\n¡Te machacaré!",
  ["64:529a"] = "VICKI: ¡Hola! ¿Qué\ndía prefieres?\012A mí me gusta el\nviernes. Sin duda.\012¿No crees que\nes genial?",
  ["67:72e7"] = "¡Uau! Demasiado.",
  ["64:5204"] = "¡Toma una FLECHA\nVENENOSA!",
  ["67:72f8"] = "Hice lo que pude.\nNo me arrepiento.",
  ["67:731b"] = "Y por último yo,\npero te lo aviso,\011¡soy la mejor!",
  ["64:5133"] = "¡GRRR!\n¡TODOS HUYEN\012CUANDO RUJO! ¡PERO\nTÚ HAS VENIDO!\012¡ESO ME GUSTA!\n¡TOMA ESTO!",
  ["67:734b"] = "¿Estás bromeando?",
  ["64:50b4"] = "Conozco mis\ndebilidades.",
  ["67:735b"] = "Hice lo que pude.\nNo me arrepiento.",
  ["67:737e"] = "¡Mufufufu…!\012No tengo nada que\nver con los otros\011seis entrenadores.\012Pero he esperado a\nque estés cansado\012de tanto pelear\npara vencerte.",
  ["64:503e"] = "¡Oh! ¡Tengo que\naliviar mi enfado!",
  ["67:7401"] = "¿No estás\ncansado?",
  ["64:4faa"] = "Si no quieres\nluchar, evita el\011contacto visual.",
  ["67:741a"] = "Lo siento… No\nharé más trampas.",
  ["64:4f6e"] = "Esa mirada…\nMe intriga.",
  ["67:743b"] = "Tuviste que\nluchar una\012vez más, pero\nganaste.\012Como te prometí,\nel premio es tuyo.",
  ["64:4f2b"] = "¡Maldición! Creía\nque podía ganar.",
  ["64:4ee8"] = "¡He encontrado\nPOKéMON muy buenos\011en la hierba!\012¡Creo que me\nservirán!",
  ["64:4e82"] = "Intentaré ser el\nmejor con mis\011favoritos.\012No uso los mismos\nPOKéMON que\011todo el mundo.",
  ["64:4a59"] = "¿Te gustaría tener\nesta sabrosa y\012nutritiva\nCOLASLOWPOKE?\012¡Sólo te costará\n1.000.000¥!\012¡Te gustará!",
  ["64:4a15"] = "Tu experiencia en\nCIUDAD MALVA\012debería ayudarte\nen tu viaje.",
  ["64:4925"] = "Tienes POKéMON\nmuy buenos.\012Seguro que es por\nhaberlos entrenado\012en los alrededores\nde CIUDAD MALVA.\012El entrenamiento\nen el GIMNASIO ha\012debido de ser de\ngran ayuda.\012Toma esto como\nrecuerdo de\011CIUDAD MALVA.\012Aumenta el poder\nde los movimientos\011de tipo planta.",
  ["64:48b0"] = "¿Has ido al\nGIMNASIO POKéMON?\012Allí puedes probar\na tus POKéMON\011y a ti mismo.\012¡Es un rito para\ntodos los\011entrenadores!",
  ["64:47ab"] = "{PLAYER}, ¿verdad?\nUn tipo con\012gafas te estaba\nbuscando.\012Compruébalo tú\nmismo. Te está\012esperando en el\nCENTRO POKéMON.",
  ["63:5fe5"] = "FARFETCH'D: ¡Farf!",
  ["63:5f93"] = "Los SLOWPOKE han\nvuelto, hasta\011FARFETCH'D.\012¡Eres el mejor,\ntío!",
  ["63:5f25"] = "Lo siento. Olvidé\ndarte las gracias.\012Éste es el CARBÓN\nque he fabricado.\012A los POKéMON de\nfuego les gustará\011llevarlo.",
  ["63:5ee0"] = "¿Adónde han ido\nlos SLOWPOKE?\012¿Están jugando\nfuera?",
  ["63:5e73"] = "¿Expulsaste al\nTEAM ROCKET y\012fuiste solo al\nENCINAR?\012¡Qué valiente! Me\ngustas. Entrena\011con nosotros.",
  ["63:5dfd"] = "Los SLOWPOKE han\nvuelto…\012Pero mi APRENDIZ\nno ha vuelto del\011ENCINAR.\012¿Dónde demonios\nestá ese vago?",
  ["63:5d74"] = "Todos los SLOWPOKE\ndel pueblo\011han desaparecido.\012Quizá el guardián\ndel ENCINAR esté\011enfadado…\012Puede ser un mal\npresagio. Mejor\011no salir.",
  ["63:5c19"] = "¿Sabes algo sobre\nlos BONGURI?\012Abre uno, vacíalo\ny rellénalo con\012un aparato\nespecial.\012Así podrás atrapar\nPOKéMON.\012Antes de que se\ninventaran las\012POKé BALL, todos\nusaban BONGURI.",
  ["63:5bee"] = "En el PC de BILL\nse almacenan 20\011POKéMON por CAJA.",
  ["63:5b34"] = "¿Tus POKéMON saben\nmovimientos MO?\012Se pueden usar\nestos movimientos\012aunque el POKéMON\nesté debilitado.",
  ["63:5ab4"] = "",
  ["63:5a0b"] = "La MEDALLA DRAGÓN\npermite que tus\012POKéMON puedan\nusar el movimiento\012para subir\ncascadas.\012Además, todos los\nPOKéMON te\012reconocerán y obe-\ndecerán cualquier\012orden sin hacer\npreguntas.",
  ["63:59f2"] = "{PLAYER} recibió\nla MEDALLA DRAGÓN.",
  ["63:59bf"] = "Toma. Ésta es la\nMEDALLA DRAGÓN…\012¡Deprisa! ¡Cógela!",
  ["63:59ae"] = "En… entiendo…",
  ["63:5983"] = "¡Estás mintiendo!\012¡Ni siquiera yo he\nconseguido la\011aprobación!",
  ["63:5974"] = "¡No es posible!",
  ["63:5916"] = "",
  ["63:58b1"] = "¿Conoces al joven\nMaestro LANCE?\012Se parece bastante\na nuestro MAESTRO\011cuando era joven.\012Lo llevan en la\nsangre.",
  ["63:5840"] = "Ha pasado bastante\ntiempo desde la\012última vez que un\nentrenador obtuvo\012la aprobación de\nnuestro MAESTRO.\012De hecho, nadie\nlo ha conseguido\012desde que el Maes-\ntro LANCE la ganó.",
  ["63:582d"] = "Oh, ya entiendo…",
  ["63:5816"] = "¿Qué has dicho?",
  ["63:57f6"] = "¿Eh? No lo he\nentendido…",
  ["63:5782"] = "Un chico de tu\nedad está aquí\011entrenándose.\012Es como DÉBORA\ncuando era joven.\012Es algo\ninquietante…",
  ["63:5724"] = "Parece que DÉBORA\nha aprendido de ti\012una lección\ninestimable.\012Te lo agradezco\ncomo abuelo suyo\011que soy.",
  ["63:56ca"] = "Los POKéMON dragón\nson el símbolo de\011nuestro clan.\012Has demostrado que\npodemos darte uno.",
  ["63:56ac"] = "¿Mmm? Tu equipo\nPOKéMON está\011lleno.",
  ["63:5697"] = "¡{PLAYER} recibió\na DRATINI!",
  ["63:5604"] = "Mmmm… Encantado\nde verte.\012Tu llegada es más\nque afortunada.\012Tengo algo para\nti.\012Coge este DRATINI\ncomo prueba de\012que reconozco tu\nesfuerzo.",
  ["63:55e5"] = "Ven de nuevo, si\nasí lo deseas.",
  ["63:55a3"] = "DÉBORA…\012Medita acerca de\nlo que tiene y\011tú careces…",
  ["63:5520"] = "¡DÉBORA!\012¡Esta persona es\nadmirable en todos\011los sentidos!\012¡Admite la derrota\ny dale la MEDALLA\011DRAGÓN!\012¿O debo informar a\nLANCE de esto…?",
  ["63:547c"] = "Mmm… Ya veo…\012Cuidas mucho de\nlos POKéMON.\012Muy encomiable.\012¡La convicción es\nlo más importante!\012{PLAYER}, no pier-\ndas la confianza.\012La necesitarás en\nla LIGA POKéMON.",
  ["63:544a"] = "POKéMON fuertes.\nPOKéMON débiles.\012¿Cuáles son más\nimportantes?",
  ["63:5420"] = "¿Qué es lo más\nimportante para\011mejorar POKéMON?",
  ["63:53f3"] = "¿Contra qué clase\nde entrenador\011prefieres luchar?",
  ["63:53d3"] = "¿Qué te ayuda a\nvencer combates?",
  ["63:53bc"] = "¿Qué son los POKé-\nMON para ti?",
  ["68:4319"] = "Las piedras del\nnorte del pueblo\011se pueden romper.\012Quizá escondan\nalgo.\012Tus POKéMON pueden\nusar el GOLPE ROCA\011para romperlas.",
  ["63:4f51"] = "Pero {PLAYER} no\npuede llevar\011más cosas.",
  ["68:4394"] = "ANÍBAL, el LÍDER\ndel GIMNASIO,\012pelea con sus\nPOKéMON de lucha.",
  ["63:49fb"] = "{PLAYER} recibió\nMT24.",
  ["68:4433"] = "EUSINE: Hola,\n{PLAYER}.\012¿No se trataba\nde SUICUNE?\012Sólo pude fijarme\nun poco, pero creí\012haber visto a un\nSUICUNE corriendo\011sobre las olas.\012SUICUNE es bello\ny grandioso.\012Corre por los\npueblos y caminos\012a unas velocidades\nincreíbles.\012Es maravilloso…\012Quiero ver un\nSUICUNE de cerca…\012Estoy decidido.\012¡Lucharé contra ti\npara ganarme el\012respeto de\nSUICUNE!\012Venga, {PLAYER}.\n¡Luchemos!",
  ["63:49b8"] = "¡Espera!",
  ["68:45a1"] = "Odio admitirlo,\npero ganaste.",
  ["19:722e"] = "¿Luchamos de\nnuevo?\012¡Esta vez no\nperderé!\012¡Te espero en\n{STRBUF}!",
  ["68:45c3"] = "¡Eres increíble,\n{PLAYER}!\012¡Ahora entiendo\npor qué los\012POKéMON te quieren\ntanto!\012Ya lo cojo.\012Voy a seguir\nbuscando a\011SUICUNE.\012Estoy seguro de\nque nos volveremos\011a ver.\012¡Hasta la vista!",
  ["19:7294"] = "¡Trabajo duro para\nentrenar a mis\011POKéMON!\012¡Vuelve para\nluchar de nuevo!",
  ["68:4660"] = "CIUDAD ORQUÍDEA\012Un puerto rodeado\nde agitadas aguas",
  ["1a:7910"] = "¡Vaya…! Tu MOCHILA\nestá llena.\012Guardaremos\ntu premio, pero\011sólo hoy.\012Haz sitio en ella\ny ven a verme.",
  ["68:468f"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\012ORQUÍDEA: ANÍBAL\012Sus puños\nhablan por él",
  ["62:5732"] = "Si tienes ese\nPOKéMON, ¿me\011dejas verlo?",
  ["68:46d6"] = "500 años de\ntradición\012FARMACIA DE\nCIUDAD ORQUÍDEA\012Aceptamos\npedidos",
  ["62:5760"] = "¿Me lo dejas ver?\n¡Qué amable eres!",
  ["68:4725"] = "ESTUD. FOTOGRÁFICO\nDE CIUDAD ORQUÍDEA\012¡Hazte una foto\nde recuerdo!",
  ["62:5784"] = "¿No lo tienes?\n¡Qué pena…!",
  ["68:4760"] = "",
  ["62:57a6"] = "¡Ah! ¿es ése\n{STRBUF}?\012¡Qué mono!\nEres muy\011simpático.",
  ["68:4a6b"] = "¡Eh!",
  ["62:57e1"] = "¡Gracias!\012Toma esto como\nagradecimiento.",
  ["68:4a71"] = "¿Sabes lo que\nacabas de hacer?\012Acabas de\nentrar en\011KANTO.\012Consulta el MAPA\ndel POKéGEAR.",
  ["62:580e"] = "Vuelve cuando\nquieras.",
  ["68:4ad9"] = "Pareces muy\nfuerte. ¡Déjame\011luchar contigo!",
  ["62:582a"] = "Gracias por\nmostrarme tantos\012POKéMON\nbonitos.\012Me he divertido\nmucho. Me alegro\012de haber vivido\ntantos años.",
  ["68:4b05"] = "¡Yau!",
  ["62:5891"] = "¿Mmm?\012Ése no es el\nPOKéMON del\011que me hablaron.",
  ["68:4b0b"] = "Si continúas por\neste duro camino,\012¡conocerás la\nverdad!\012Lo siento, pero me\napetecía decir\011algo chulo.",
  ["62:58c0"] = "Mi nieto BILL me\ndijo que había un\012POKéMON con una\nlengua muy larga.",
  ["68:4b7c"] = "¿Mmm? Eres bueno,\n¿verdad?",
  ["62:58ff"] = "Mi nieto mencionó\na un POKéMON verde\012y redondo al que\nle crecen hojas en\011la cabeza.",
  ["68:4b98"] = "¡Tal como pensaba!",
  ["62:5953"] = "¿Conoces a un\nPOKéMON de mar que\012tiene una esfera\nroja en el cuerpo?\012Ya sabes, ése\nque tiene forma\011de estrella.\012Dicen que sale\npor la noche.\012Me encantaría\nverlo.",
  ["68:4bac"] = "Un buen entrenador\nsabe reconocer a\012otros buenos\nentrenadores.",
  ["62:59fe"] = "BILL me habló de\nun POKéMON que\012es muy fiel a su\nentrenador.\012Se supone que\nRUGE bien.",
  ["68:4bdf"] = "No deberías\nsubestimar a los\012POKéMON salvajes\nde esta zona.",
  ["62:5a57"] = "He oído hablar de\nun POKéMON que\011tiene seis colas.\012Me gustaría\nabrazar a un\011POKéMON así.",
  ["68:4c19"] = "¡Oh! ¡Qué\nfuerte eres!",
  ["62:5ab1"] = "¿Conoces a ese\nPOKéMON tan\011popular?\012El POKéMON de\ncuerpo amarillo\011y mejillas rojas.\012Me gustaría\nverlo antes\012de que\nevolucione.",
  ["68:4c35"] = "Eres sólo un niño,\npero tampoco\012se te puede\nsubestimar.",
  ["62:5b6c"] = "¡Hola!\012El REY del KARATE,\nel maestro del\012DOJO-KARATE, está\nentrenando en una\011cueva de JOHTO.",
  ["68:4c73"] = "Es raro que venga\nalguien por aquí.\012¿Te estás\nentrenando solo?",
  ["62:5bc0"] = "¡Lo que tenga que\nser será!",
  ["68:4cb4"] = "¡Oh! ¡Eres\nmuy fuerte!",
  ["62:5be0"] = "¡Enemigos por\ntodas partes!",
  ["68:4cce"] = "Estoy investigando\nlos POKéMON antes\012y después de que\nevolucionen.\012Los POKéMON se\nhacen más fuertes\011al evolucionar.\012Pero aprenderán\nnuevos movimientos\012mucho más despacio\nque antes.",
  ["62:5cdf"] = "SABRINA: Sabía\nque vendrías…\012Hace tres años\ntuve una visión\011de tu llegada.\012Tú lo que quieres\nes mi MEDALLA.\012No me gusta\nluchar, pero mi\012deber como LÍDER\nes conceder\012MEDALLAS a todo\naquel que se las\011merezca.\012Como eso es lo que\nquieres, mira mis\011poderes psíquicos.",
  ["68:4d55"] = "¡No digas nada!\012Déjame adivinar lo\nque piensas.\012¡Mmmmmmm…!\012¡Listo! ¡Estás\nen la LIGA\011POKéMON!",
  ["62:5df4"] = "SABRINA: Tu\npoder…\012supera con creces\nlo que esperaba…\012Quizá no se pueda\npredecir del todo\012lo que nos espera\nen el futuro…\012Vale, tú ganas.\nTe has ganado la\011MEDALLA PANTANO.",
  ["68:4dc1"] = "¡Eres demasiado!",
  ["62:5e95"] = "{PLAYER} recibió\nMEDALLA PANTANO.",
  ["68:4dd2"] = "Con tus\nhabilidades,\012te irá bien\nen la LIGA.\012Eso es lo que\npresiento.",
  ["62:5ead"] = "SABRINA: La\nMEDALLA PANTANO\012muestra tus\npoderes ocultos.\012Aunque no supe\npredecir tu poder\012con exactitud,\nsabía que valías\011mucho.\012¡Te convertirás en\nun amado y alabado\011CAMPEÓN!",
  ["68:4e22"] = "¡Pío! ¡Pío!\n¡Píooo!",
  ["62:5f6c"] = "SABRINA: Tu amor\npor tus POKéMON\012supera mi poder\npsíquico…\012Creo que el poder\ndel amor es un\012tipo de poder\npsíquico…",
  ["68:4e3a"] = "¡Pío!",
  ["62:5fe9"] = "¡El poder de todos\nlos que venciste\011está en mí!",
  ["68:4e42"] = "Los ORNITÓLOGOS\nimitan el canto de\012los pájaros para\ncontrolar POKéMON.",
  ["62:601b"] = "Fuerte…\nMuy fuerte…",
  ["66:518b"] = "¡Uajajaja!\n¡Adiós!",
  ["62:6034"] = "¿De dónde proviene\ntu poder?",
  ["66:51a4"] = "Pe… Pero…",
  ["62:6057"] = "El poder psíquico\nes el poder de tu\011alma.",
  ["66:51ac"] = "…No tienes sufi-\ncientes fichas…",
  ["62:6081"] = "¡Tu alma tiene más\npoder que la mía!",
  ["62:60a6"] = "Has fortalecido tu\nalma, no sólo tus\011habilidades.",
  ["1b:690a"] = "Si enviáramos\nnuestra señal de\012radio por todo\nel país…\012¡Me emociono\nsólo de pensarlo!",
  ["62:60dd"] = "¡Fufufufu…!\nLo veo claramente.\012¡Puedo leer\ntu alma!",
  ["1b:6671"] = "¡Je, je, je!\012¿Me desafías a\nun combate? ¡Bah!\012¡Estás loco, pero\ntienes agallas!\012¡Eso me gusta!\012¡Si me vences, te\ndiré la contraseña\012de la oficina\ndel jefe!",
  ["62:6114"] = "A pesar de leerte\nel pensamiento,\011he perdido…",
  ["15:5e74"] = "Para los amantes\nde la victoria\012P2 COLECCIÓN\n   DE COMBATE",
  ["62:6136"] = "¡Maldición! Olvidé\nque predije mi\011derrota contra ti.",
  ["15:5f74"] = "Algunos POKéMON\nsólo evolucionan\012al intercambiarlos\ncon el Game Link.\012Por ejemplo:\nMACHOKE, KADABRA,\012HAUNTER y\nGRAVELER.\012Dicen que hay\notros también.",
  ["62:616c"] = "El DOJO-KARATE era\nel GIMNASIO\011de esta ciudad.",
  ["1e:6231"] = "¡Entró por\naquí!",
  ["62:61a2"] = "¡Eres bueno…!",
  ["1e:5f38"] = "{PLAYER}, toma\nesto por las\011molestias.",
  ["62:61b3"] = "El REY del KARATE,\nel maestro del\012DOJO-KARATE, acaba\nde ser machacado\011por SABRINA.",
  ["1e:5a1b"] = "ELM: ¿Alguna\nnovedad?",
  ["62:6201"] = "¡Hola, futuro\nCAMPEÓN!\012Un entrenador tan\nhabilidoso como tú\012no necesita que le\ndigan cómo luchar\012contra POKéMON\npsíquicos, ¿no?\012¡Espero mucho\nde ti!\012¡Buena suerte!",
  ["1e:54c0"] = "El SR. POKéMON\nvive un poco más\012allá de CEREZO, la\npróxima ciudad.\012Es casi una ruta\ndirecta, así que\011no tiene pérdida.\012Pero por si acaso,\naquí tienes mi\012número de móvil.\n¡Llámame si\011ocurriera algo!",
  ["62:62a0"] = "¡Otro combate\nfantástico!",
  ["1d:5b04"] = "¡Voy a KANTO para\nactuar en un\012espectáculo de\ncomefuegos!",
  ["62:63cc"] = "En PUEBLO LAVANDA\nhay una gran TORRE\011de RADIO.",
  ["1b:5cb0"] = "¡Tú! ¡Pequeño\nparásito podrido!",
  ["62:63f3"] = "Quiero ser más\nfuerte, pero aún\011soy muy mala…\012¿Podrías enseñarme\ncómo algún día?",
  ["1b:45ba"] = "LANCE: {PLAYER},\nseparémonos para\012registrarlo todo.\nYo iré primero.",
  ["62:64a3"] = "¿Cómo son los\nCENTROS POKéMON\011de JOHTO?\012Oh… ya veo.\nAsí que no son tan\012diferentes de los\nde KANTO…\012¡Entonces puedo ir\na JOHTO sin tener\011que preocuparme!",
  ["61:5386"] = "De acuerdo con la\nleyenda…\012Cuando las almas\nde los POKéMON y\012los humanos se\nunan, descenderá\012de los cielos un\nPOKéMON con los\012colores del arco\niris…\012¿Quiere eso decir\nque el POKéMON\012legendario está\nprobando a los\011humanos?",
  ["62:6532"] = "¿Cómo son los\nCENTROS POKéMON\011de JOHTO?\012…Oh, ya veo.\nAsí que permiten\012conectar con gente\nde lejos…\012¡Entonces le diré\na mi amigo de\012JOHTO que capture\nun MARILL y me lo\011cambie!",
  ["61:5544"] = "",
  ["62:65d3"] = "Acabo de cruzar\nel TÚNEL ROCA.\012Pasaba algo en\nla CENTRAL de\011ENERGÍA.",
  ["61:5629"] = "Esto te protegerá.\nCógelo.",
  ["62:662e"] = "Las cuevas suelen\nderrumbarse.\012Últimamente han\ndesaparecido\012varias cuevas,\ncomo la de\011CIUDAD CELESTE.\012Para un MONTAÑERO\nprofesional, eso\011es obvio.",
  ["61:5654"] = "Creo que te están\nprobando.\012Libera tu mente de\nla incertidumbre y\011avanza.",
  ["62:66c5"] = "La OFICINA CENTRAL\nde SILPH S.A. y\012la ESTACIÓN del\nMAGNETOTRÉN son\012los lugares más\nvistos de AZAFRÁN.",
  ["61:56a3"] = "Lo sabía.\012Sabía que conse-\nguirías ver al\012POKéMON de los\ncolores del arco\011iris, {PLAYER}.\012Ha ocurrido tal y\ncomo lo imaginé.\012Debo decir que mi\ninvestigación ha\011sido correcta.\012¡Voy a continuar\nestudiando a los\012POKéMON para\nconvertirme en\012un POKéMANIAC\nfamoso!",
  ["62:6798"] = "…\012…\012…\012¡Lo conseguí!\012¡Tú lo quisiste!",
  ["61:5803"] = "Cuando aparecieron\nlos POKéMON\011legendarios…\012Infundieron el\nterror en aquellos\012que vieron su\nascenso.\012Y…\012Algunos incluso\natacaron en vano.\012Los POKéMON legen-\ndarios, conocedo-\011res de su propio\011poder, huyeron y\012abandonaron a la\ngente, asustada.",
  ["62:67bb"] = "MT29 es PSÍQUICO.\012Puede reducir\nla DEFENSA\012ESPECIAL del\nblanco.",
  ["61:5cd9"] = "",
  ["62:68a9"] = "Lo siento, pero el\nMAGNETOTRÉN no\011funciona ahora.",
  ["61:58d0"] = "De los POKéMON\nlegendarios, se\012dice que SUICUNE\nes el más cercano\011a HO-OH.\012Además, he oído\nque también puede\012haber una conexión\ncon los POKéMON\011UNOWN.\012Los POKéMON UNOWN\ndeben de tener un\012lazo de unión con\nSUICUNE.",
  ["62:68dd"] = "Pronto saldremos\nhacia CIUDAD\011TRIGAL.\012¿Quiere\nsubir?",
  ["61:5765"] = "Se dice que los\nPOKéMON legenda-\011rios encarnan tres\011poderes…\012El rayo que\nalcanzó la TORRE…\012El fuego que\nquemó la TORRE…\012Y la lluvia que\napagó dicho fuego…",
  ["62:6917"] = "Por favor, ¿puedo\nver su PASE?\012Muy bien. Pase por\naquí, por favor.",
  ["62:6956"] = "Lo siento, pero\nno tiene un PASE.",
  ["66:5cb3"] = "¡Ah! Me impresiona\ntu valor.\012Con tu gran\nvoluntad, sé que\012superarás todos\nlos obstáculos.\012¡Te mereces\nesta MEDALLA!",
  ["62:6978"] = "¡Vuelve siempre\nque quieras!",
  ["66:5d3b"] = "{PLAYER}\nrecibió la\011MEDALLA GLACIAR.",
  ["62:6993"] = "Hemos llegado a\nCIUDAD AZAFRÁN.\012Siempre a\nsu servicio.",
  ["66:5d55"] = "Esta MEDALLA sube\nlas habilidades\012ESPECIALES de los\nPOKéMON.\012Y tus POKéMON\nusarán TORBELLINO\012para pasar los\ntorbellinos.\012¡Además, te voy\na hacer un regalo!",
  ["62:69ca"] = "El MAGNETOTRÉN es\nun tren ultra-\012moderno, accionado\npor electricidad\012e imanes. Su\nvelocidad es\011increíble.\012Sin embargo,\nsi no hay\011electricidad…",
  ["66:5def"] = "Esta MT contiene\nVIENTO HIELO.\012Causa daño y baja\nla velocidad.\012Demuestra la\ndureza del\011invierno.",
  ["62:6a61"] = "¡Caramba…!\012¡Cuántas veces he\nido de KANTO a\012JOHTO y de JOHTO\na KANTO!",
  ["66:5e59"] = "La primavera llega\ncuando se derrite\012el hielo y la\nnieve.\012Tú y tus POKéMON\npasaréis juntos\011muchos años.\012¡Pasadlo\nbien!",
  ["62:6aab"] = "Antes de que se\nconstruyera la\012ESTACIÓN, ahí\nhabía una casa.\012Y en ella vivía\nuna niña\011llamada COPIONA.",
  ["66:5ee1"] = "¡Congelaré a tus\nPOKéMON! ¡No\011podrás hacer nada!",
  ["62:6b20"] = "Hola. ¿Tienes un\nPASE? Yo sí. Toda\012la gente de CIUDAD\nAZAFRÁN que usa el\012MAGNETOTRÉN tiene\nun PASE.",
  ["66:5f10"] = "Maldición. No\npude hacer nada.",
  ["62:6c03"] = "Bienvenido a la\nOFICINA CENTRAL\011de SILPH S.A.",
  ["66:5f2d"] = "Hay un movimiento\nque se puede usar\012cuando el POKéMON\nestá congelado.",
  ["62:6c36"] = "Al piso de arriba\nsólo pueden subir\011los empleados.\012Pero como has\nvenido desde tan\012lejos, toma este\npequeño recuerdo.",
  ["66:5f65"] = "Este GIMNASIO\ntiene un suelo\012resbaladizo. ¿A\nque es divertido?\012¡Pero oye, aquí\nno estamos\011jugando!",
  ["62:6ca8"] = "Es lo último de\nSILPH S.A. Aún\012no se encuentra\na la venta.",
  ["66:5fbd"] = "¿Ves lo serios\nque somos?",
  ["62:6d34"] = "A mi hija le gusta\nimitar a la gente.\012Y por eso la\nllaman la\011COPIONA.",
  ["66:5fdd"] = "Este GIMNASIO es\ngenial. ¡Me\012encanta patinar\ncon mis POKéMON!",
  ["62:6d95"] = "Mi hija es muy\nintrovertida…\012Tiene muy\npocos amigos.",
  ["66:600f"] = "Conozco el secreto\nde FREDO.",
  ["62:6dd3"] = "Acaba de perder\nel POKé MUÑECO que\012le regaló un niño\nhace tres años.\012Desde entonces,\nimita a la gente\011mucho mejor…",
  ["66:6026"] = "Te contaré el\nsecreto de FREDO.",
  ["62:6e4b"] = "BLISSEY: ¡Bliisii!",
  ["66:6047"] = "El secreto del\npoder de FREDO…\012Medita todos los\ndías bajo una\012cascada para\nmejorar su cuerpo\011y su mente.",
  ["62:6fda"] = "{PLAYER}: ¿Te gusta\nPOKéMON?\012{PLAYER}: No, yo\nsólo preguntaba.\012{PLAYER}: ¿Eh?\n¡Eres muy rara!",
  ["66:60ae"] = "Para vencer a\nFREDO, el LÍDER\012del GIM., piensa\nantes de patinar.",
  ["62:7028"] = "COPIONA: ¿Cómo?\n¿Que no imite?\012¡Pero si es mi\nhobby favorito!",
  ["66:60f4"] = "¡No perderé ante\nti esquiando!",
  ["62:7064"] = "{PLAYER}: ¡Hola!\nDicen que has\012perdido tu POKé\nMUÑECO favorito.\012{PLAYER}: Si lo\nencuentro, ¿me\011darás un PASE?\012{PLAYER}: Iré\na buscarlo.\012¿Crees que lo\nperdiste en\011CIUDAD CARMÍN?",
  ["66:6116"] = "Si no patinas con\nprecisión, no\012lograrás nada en\neste GIMNASIO.",
  ["62:7116"] = "COPIONA: ¿Perdona?\012¿No tendría que\ndecirte yo lo\011que debes hacer?\012Estoy preocupada.\n¿Y si alguien\011lo encuentra?",
  ["66:6157"] = "¡Mira qué bien\nesquío!",
  ["62:717f"] = "COPIONA: ¡Sí! ¡Ése\nes mi POKé MUÑECO\011CLEFAIRY!\012¿Ves el descosido\nque tiene en la\012pata derecha?\n¡Ésa es la prueba!",
  ["66:6174"] = "¡No! ¡He perdido!",
  ["62:71e2"] = "Está bien. ¡Aquí\ntienes el PASE del\012MAGNETOTRÉN que\nte prometí!",
  ["66:618f"] = "No debería haber\npresumido sobre mi\011forma de esquiar.",
  ["62:7214"] = "COPIONA: Ése es\nel PASE para el\011MAGNETOTRÉN.\012La empresa de\nferrocarriles me\012lo dio cuando\nderribaron nuestra\012casa para edificar\nla ESTACIÓN.",
  ["66:61bf"] = "FREDO es veterano.\nLleva entrenando\012POKéMON desde\nhace 50 años.\012Dicen que es bueno\ncongelando a sus\012rivales con los\nataques de hielo.\012¡Eso quiere decir\nque deberías\012derretirle con tu\nardiente ambición!",
  ["62:7298"] = "{PLAYER}: ¡Hola!\nMuchas gracias por\011el PASE de tren.\012{PLAYER}: ¿Perdona?\012{PLAYER}: ¿Tanto\nte divierte imitar\011todo lo que hago?",
  ["66:6275"] = "¡FREDO es bueno,\npero tú eres\011aún mejor!\012¡Ha sido un gran\ncombate que acortó\012distancias entre\ngeneraciones!",
  ["62:72f5"] = "COPIONA: ¿Apuestas\nalgo? ¡Es genial!",
  ["66:6362"] = "¿Qué pasa?\n¿Ha vuelto el\011TEAM ROCKET?\012He visto hombres\nde negro en el\011LAGO DE LA FURIA.",
  ["62:7316"] = "{PLAYER}: Hola.\nTe deben gustar\011los POKéMON.\012{PLAYER}: No, yo\nno. Pregunté yo.\012{PLAYER}: ¿Cómo?\n¡Qué rara eres!",
  ["66:63b3"] = "No permito que\nmis POKéMON\012evolucionen\ndemasiado pronto.\012Antes de dejarles\nevolucionar, les\012enseño algunos\nmovimientos.",
  ["62:7366"] = "",
  ["66:6418"] = "Al evolucionar,\nlos POKéMON se\012fortalecen, pero\ntardan más en\011aprender ataques.",
  ["62:7415"] = "{PLAYER}: ¡Gracias\npor el PASE de\011tren!\012{PLAYER}: …\n¿Perdona?\012{PLAYER}: ¿Es\ntan divertido\012copiar lo que digo\ny hago?",
  ["66:64b8"] = "MONTE MORTERO es\ncomo un laberinto.\012Ten cuidado.\nNo te pierdas.",
  ["62:7476"] = "DODRIO: ¡Dodrii!",
  ["66:654b"] = "Te has\nperdido…\012Aquí he meditado.\nUn nuevo poder se\012ha despertado\ndentro de mí.\012Déjame compartir\nmi poder con tus\012POKéMON.\nToma esto, hijo.",
  ["62:7489"] = "ESPEJITO, ESPEJITO\n¿QUIÉN ES EL MÁS\012GUAPO DE\nTODOS?",
  ["66:65de"] = "¿Lo ves? ¡Es PODER\nOCULTO!\012Saca el poder de\nlos POKéMON para\011atacar.\012Recuerda: su tipo\ny poder dependen\012del POKéMON\nque lo usa.",
  ["62:74c4"] = "¡Qué POKéMON\nmás raro!\012Es un muñeco…",
  ["66:6673"] = "Estoy meditando…",
  ["62:7558"] = "Muchas ciudades de\nJOHTO están llenas\012de historia. ¡Cómo\nme gustaría ir!",
  ["66:672e"] = "El LAGO DE LA\nFURIA es un cráter\012obra de violentos\nGYARADOS.\012El cráter se llenó\nde agua de la\012lluvia y se formó\nel LAGO.\012Esta historia la\ncontó por primera\012vez el tatarabuelo\nde mi abuelo.\012Antes se podían\npescar MAGIKARP\012en el lago,\npero…\012No entiendo lo\nque ocurre ahora.",
  ["62:75bc"] = "Eres de JOHTO,\n¿verdad?\012¿Qué opinas de\nKANTO? Es bonito,\011¿no crees?",
  ["66:684d"] = "En el LAGO pasan\ncosas raras desde\012que llegaron esos\nhombres de negro.",
  ["62:7655"] = "¡Aaaayy!\012Siento que una\nsiniestra sombra\012se cierne\nsobre ti.\012¡Toma esto para\nprotegerte!",
  ["66:6890"] = "La normalidad ha\nvuelto al LAGO DE\012LA FURIA. Vuelve a\nhaber MAGIKARP.\012Quizá se cumpla\nmi sueño de ver\012al MAGIKARP más\ngrande del mundo.\012¿Tienes una CAÑA?\nSi tienes una,\011ayúdame por favor.",
  ["62:76a7"] = "Corrías un peligro\nmortal, pero ahora\011estás protegido.",
  ["66:693e"] = "¡Ah, tienes un\nMAGIKARP! A ver\012lo grande que es\nese bebé.",
  ["62:76de"] = "A mi abuela le\ngusta protegerse\012contra supuestos\nmalos espíritus.\012Perdona si te\nha asustado.",
  ["66:6977"] = "¡Uau! ¡Éste es\nimpresionante!\012¡Me quito el\nsombrero ante ti!\012¡Toma esto como\nrecuerdo!",
  ["63:4042"] = "¿Has ido al GIM.\nde C. PLATEADA?\012El LÍDER utiliza\nPOKéMON roca.",
  ["66:69c3"] = "Lo importante es\nel récord. ¡Piensa\012en él como una\nbonificación!",
  ["63:4080"] = "Por la noche,\nCLEFAIRY sale a\011jugar al MT. MOON.\012Pero no todas\nlas noches.",
  ["66:6a01"] = "¡Uau! ¡Éste es\nimpresionante!\012Ojalá no tuviera\nque decirlo, pero\012he visto uno más\ngrande antes.",
  ["63:40c6"] = "¡Vaya! ¿Vienes\nde JOHTO?\012Me trae muchos\nrecuerdos. Cuando\012era joven, fui a\nJOHTO a entrenar.\012Te pareces\nmucho a mí\012cuando yo\ntenía tu edad.\012Me gustaría darte\neste objeto que\011encontré en JOHTO.",
  ["66:6a5c"] = "¿Qué? ¡Eso no es\nun MAGIKARP!",
  ["63:41aa"] = "Visitar nuevos\nsitios y conocer\011gente nueva…\012Eso es lo\nbueno de viajar.",
  ["66:6a79"] = "¿No tienes ninguno\nbueno para\012enseñármelo? Quizá\nla próxima vez.",
  ["63:41ff"] = "CIUDAD PLATEADA\nLa ciudad de\011piedra grisácea",
  ["66:6b1f"] = "Últimamente sólo\npasaron por aquí\012los que iban al\nLAGO DE LA FURIA.",
  ["63:421e"] = "LÍDER POKéMON\nDEL GIMNASIO DE\011C. PLATEADA: BROCK\012El Entrenador\nPOKéMON más\012fuerte que\nuna roca.",
  ["66:6b65"] = "Ahora nadie\nva al LAGO\011DE LA FURIA.",
  ["63:425e"] = "Aquí hay una\nnota…\012MUSEO DE LA\nCIENCIA DE CIUDAD\012PLATEADA: Cerrado\npor obras…",
  ["63:42a9"] = "Aquí hay una nota…\012¡TIENDA DE REGALOS\nMT. MOON abierta!",
  ["1b:4134"] = "¡Per…, perdóname!",
  ["63:42dc"] = "¡Bienvenidos a\nCIUDAD PLATEADA!",
  ["1b:406e"] = "Somos el grupo de\nentrenadores de la\012FEDERACIÓN POKéMON\nde KANTO.\012¡Te vamos a\narrollar!",
  ["63:4531"] = "¡Gyaaas!",
  ["1a:40b2"] = "He luchado con\nhonor.\012No me\navergüenzo.",
  ["63:4637"] = "……\n……",
  ["63:463c"] = "…",
  ["63:463f"] = "……\n……",
  ["63:473f"] = "¡Uauu! ¡Me has\nasustado!\012Tenía puestas las\nGAFAS DE SOL y\012no me di cuenta\nde tu presencia.\012¿Que qué estoy\nhaciendo aquí?\012No te preocupes\npor eso.\012Te daré unas GAFAS\nDE SOL si olvidas\012que me has\nvisto, ¿vale?",
  ["70:4e6f"] = "No está interesado\nen {STRBUF}.",
  ["63:480c"] = "Las GAFAS DE SOL\naumentan el poder\012de los movimientos\nde tipo siniestro.",
  ["70:4e8d"] = "Está interesado\nen {STRBUF}.",
  ["19:712a"] = "¿No has llegado a\n{STRBUF}?\012¡Esperar aquí no\nestá tan mal, pero\011preferiría luchar!",
  ["70:4eac"] = "Es agradable con\n{STRBUF}.",
  ["19:7106"] = "Volveremos a\nluchar, ¿verdad?",
  ["70:4ec6"] = "Muestra interés\npor {STRBUF}.",
  ["15:6202"] = "Seguro que hay\nMT que serían\012perfectas para\ntus POKéMON.",
  ["70:4ee3"] = "Aquí no hay\nninguna CARTA.",
  ["17:43bc"] = "Doy paseos por\nel PARQUE, pero\012nunca entro en\nla hierba.\012Los entrenadores\nsiempre luchan…",
  ["70:4ef9"] = "La CARTA fue\nenviada.",
  ["19:6fc0"] = "¡Noqueamos a un\n{STRBUF}\011salvaje!\012Estuvo bien, pero\nquería atraparlo…",
  ["70:4f19"] = "¡MOCHILA llena!",
  ["19:6f9f"] = "No hay nada como\nmi {STRBUF}.",
  ["70:4f2c"] = "Perderás el\nmensaje de\011la CARTA. ¿Vale?",
  ["19:6f52"] = "Descansé durante\nla hora de comer.\012¡Ahora toca volver\na entrenarse!\012¡Oooriaa!",
  ["70:4f51"] = "Ya lleva\nun objeto.",
  ["17:422e"] = "Es una CARTA\nde mi hija.\011¡Me da ánimos!",
  ["70:4f71"] = "Un HUEVO no puede\nllevar CARTAS.",
  ["17:41d3"] = "¡Eh! ¡Mira mi\nmochila!\012Imprimí de la\nPOKéDEX mis\012POKéMON favoritos\ny los pegué\011en ella.",
  ["6d:5e25"] = "Buenos días,\n{PLAYER}.\012Soy {STRBUF}.\n¿Dormías?",
  ["16:763c"] = "Cualquiera estaría\npreocupado si sus\012POKéMON estuvieran\nenfermos.\012Rezaré por este\nPOKéMON, para que\012YASMINA regrese\nal GIMNASIO.",
  ["6d:5e59"] = "Hola, {PLAYER}.\nSoy {STRBUF}.\012¿Qué tal te van\nlas cosas?",
  ["16:762b"] = "¡Ay! ¡Mi POKéMON!",
  ["6d:5e8e"] = "Buenas noches,\n{PLAYER}.\012Soy {STRBUF}.\n¿Aún sin dormir?",
  ["16:7584"] = "Hablando de\nenfermedades, hay\012una FARMACIA en\nCIUDAD ORQUÍDEA.",
  ["6d:5ebe"] = "Tenía algo de\ntiempo, así que\011pensé en llamarte.\012De todos modos,\n¿qué tal están tus\011POKéMON?\012Yo llevo a mi\n{STRBUF} al\012CENTRO POKéMON de\nCIUDAD MALVA todos\012los días, así que\nestá fantástico.\012¡Soy amiga de la\nrecepcionista!",
  ["16:7565"] = "Yo tampoco puedo\nsonreír…",
  ["6d:5f7a"] = "Soy {STRBUF}, el\nMONTAÑERO.\012¡Ah, {PLAYER}!",
  ["16:7512"] = "YASMINA debe de\nestar preocupada\011por este POKéMON.\012Ni siquiera\nsonríe.",
  ["6d:5f9e"] = "Soy {STRBUF}, el\nMONTAÑERO.\012¡Ah, {PLAYER}!",
  ["16:7457"] = "YASMINA solía\nutilizar POKéMON\011roca como ONIX.",
  ["6d:5fc9"] = "Soy {STRBUF}, el\nMONTAÑERO.\012¡Ah, {PLAYER}!",
  ["16:73f4"] = "Viajo por el mundo\npara entrenar a\012mis POKéMON.\n¿Quieres luchar?",
  ["6d:5ff6"] = "¿{PLAYER}?\012¡Soy {STRBUF},\nel MONTAÑERO!",
  ["16:7365"] = "Eres fuerte y\nsimpático…",
  ["6d:6017"] = "¿Eres {PLAYER}?\012¡Soy {STRBUF},\nel MONTAÑERO!",
  ["16:72df"] = "¿Cómo diablos\nse sube?\012Quiero visitar\nal POKéMON\012enfermo, pero no\npuedo subir…",
  ["6d:6041"] = "¿No te has acos-\ntado, {PLAYER}?\012¡Soy {STRBUF},\nel MONTAÑERO!",
  ["16:727b"] = "¿Qué haces aquí?\n¿Sólo mirando?\012¡Pues mejor\nque te vayas!",
  ["6d:606f"] = "¿Están tus POKéMON\ntan animados como\011siempre?\012Mi {STRBUF} y\nyo tenemos mucha\012energía. Escalamos\nmontañas todos los\012días a modo de\nentrenamiento.",
  ["16:71b6"] = "¡Ja! ¡Tan\nespecial como\011siempre!\012De todas formas,\naquí está la medi-\011cina que buscabas.",
  ["6d:60f5"] = "¿Sí? Al habla\n{STRBUF}.\012¡Hola, {PLAYER}!",
  ["29:4e4c"] = "¡Hola! ¿Has venido\na por tu regalo?\012¡Esto te alegrará\nel día!",
  ["6d:611b"] = "¿Sí? Al habla\n{STRBUF}.\012Debes de ser\n{PLAYER}.",
  ["29:4e8f"] = "¿Dónde pensabas\nponer esto?\012Lo guardaré, así\nque vuelve luego…",
  ["6d:6149"] = "¿Sí? Al habla\n{STRBUF}.\012Ah, {PLAYER}.",
  ["29:4ed4"] = "",
  ["6d:616e"] = "Hola, soy\n{STRBUF}.\012{PLAYER}, ¿verdad?",
  ["29:4fc8"] = "Por favor, ¿me das\ntu número de\011teléfono?\012Debemos hablar\nacerca del\011PROF. OAK.\012¡Seguro que va a\nser divertidísimo!",
  ["6d:618f"] = "Hola, soy\n{STRBUF}.\012¿{PLAYER}, qué\nestás haciendo?",
  ["29:502e"] = "Debes escuchar la\nHORA POKéMON del\011PROF. OAK, ¿vale?",
  ["6d:61bd"] = "Hola, soy\n{STRBUF}.\012{PLAYER}, siento\nllamar tan tarde.",
  ["29:505f"] = "Oh… Me gustaría\ntener la oportuni-\011dad de conocer al\011PROF. OAK…",
  ["6d:61f2"] = "¿Cómo mejoras a\ntus POKéMON?\012Yo hago toda clase\nde cosas, como\012dejarles en la\nGUARDERÍA y forta-\011lecerlos con\011objetos.",
  ["29:508c"] = "¡Tu agenda de\nteléfonos está\012completamente\nllena!",
  ["6d:626a"] = "¿Hola? Soy\n{STRBUF}…\012¡Oh, {PLAYER}!\n¡Buenos días!",
  ["29:50b1"] = "¡Te esperaba!\n¡Luchemos!",
  ["6d:6296"] = "¿Hola? Soy\n{STRBUF}…\012¡Oh, {PLAYER}!\n¿Qué tal estás?",
  ["29:50d5"] = "¡Oh, guau! ¡Es\nPIKACHU! ¡Es tan\012suave y peludo!\n¡Cómo mola!\012¡Seamos amigos!\n¡Si te gusta\012PIKACHU, no puedes\nser mala gente!\012¡Hablemos acerca\nde PIKACHU!\012¿Me das tu número\nde teléfono?",
  ["6d:62c5"] = "¿Hola? Soy\n{STRBUF}…\012¡Oh, {PLAYER}!\n¡Buenas noches!",
  ["29:5175"] = "¡Hablemos acerca\nde PIKACHU!\012¿Me das tu número\nde teléfono?",
  ["6d:62f1"] = "¿{PLAYER}?\012Soy {STRBUF}.\n¡Buenos días!",
  ["29:51ac"] = "¡PIKACHU es el\nnúmero uno!\012Si pasa algo, te\nllamaré.",
  ["6d:630e"] = "¿{PLAYER}?\012Soy {STRBUF}.\n¿Te pillo en mal\011momento?",
  ["29:51ee"] = "A ti…\012A ti no debe de\ngustarte PIKACHU…",
  ["6d:6331"] = "¿{PLAYER}?\012Soy {STRBUF}.\n¿Tienes tiempo\011para hablar?",
  ["29:5216"] = "¡Espera! ¡Tu\nagenda está llena!",
  ["6d:6352"] = "¿Tus POKéMON son\nduros?\012Yo me entreno\ntodos los días con\011{STRBUF}.",
  ["29:523a"] = "¡Te estaba\nbuscando! Mira…\011¿Lo ves? ¡Eso es!\012¡Estoy seguro de\nque a PIKACHU\012también le gustará\nmi regalo!",
  ["6d:638c"] = "¿Hola? Soy\n{STRBUF}…\012¡Hola, {PLAYER}!",
  ["29:52a0"] = "Oh, oh. Qué mal.\nNo tienes espacio.\012Asegúrate de\nrecogerlo luego.",
  ["6d:63a8"] = "¿Hola? Soy\n{STRBUF}…\012¡Uau, {PLAYER}!",
  ["29:52e2"] = "¿Tú también estás\nintentando ser el\012no va más entre-\nnando POKéMON?\012¡Entonces somos\ncamaradas!\012Si encuentro más\nobjetos en el\012agua, te daré\nalguno.\012Sólo debes darme\ntu número de\011teléfono.",
  ["6d:63c4"] = "¿Hola? Soy\n{STRBUF}…\012¡Yupi, {PLAYER}!",
  ["29:5383"] = "Si encuentro más\nobjetos en el\012agua, te daré\nalguno.\012Sólo debes darme\ntu número de\011teléfono.",
  ["6d:63e3"] = "Eh, hola.\n¿{PLAYER}?\012¡Soy tu amigo,\n{STRBUF}!",
  ["29:53de"] = "Sabrás de mí si\nencuentro algo\011bueno.",
  ["6d:6407"] = "Uh, hola.\n¿{PLAYER}?\012¡Soy tu colega,\n{STRBUF}!",
  ["29:5412"] = "¿Ésas tenemos?\nEntonces tendré\012que usarlos yo\nmismo.",
  ["6d:642c"] = "Uh, hola.\n¿{PLAYER}?\012¡Soy tu camarada,\n{STRBUF}!",
  ["29:5446"] = "Tu agenda de\nteléfonos está\011completa.\012Vuelve si haces\nhueco para mí.",
  ["6d:6454"] = "Sí, hola.\nSoy {STRBUF}.\012Eh… ¿{PLAYER}?",
  ["29:548c"] = "No sólo he estado\npescando desde la\012última vez que nos\nvimos.\012¡Prepárate para\nuna gran sorpresa!",
  ["6d:647e"] = "Sí, hola. Has lla-\nmado a {STRBUF}.\012Huh… ¿{PLAYER}?",
  ["29:54e3"] = "¡Hola!\n¡Has venido!\012¡Aquí está el\nregalo, tal y como\011te prometí!",
  ["6d:64a8"] = "Sí, hola. Has lla-\nmado a {STRBUF}.\012Huh… ¿{PLAYER}?",
  ["29:5513"] = "¿Tienes la MOCHILA\nllena?\012Vuelve luego.\nAquí estaré.",
  ["16:6bcb"] = "Un SLOWPOKE\nsin COLA…\012¿Qué? Tiene una\nCARTA. ¿Leerla?",
  ["29:5545"] = "A propósito, tú\ndebes de adorar a\011los POKéMON…\012Se nota.\nSí, seguro.\012¡Pero tus conoci-\nmientos aún no son\011muy profundos!\012¿Conoces a BILL?\nEs un POKéMANIAC\012increíble.\nLe venero.\012Te enseñaré todo\nlo que sé acerca\012de BILL, así que\ndéjame tu número\011de teléfono.",
  ["19:5eac"] = "Ya lo creo, perdí\nun {STRBUF}\011salvaje.\012Era enorme, así\nde grande.\012Eh, seguro que no\nte lo crees por\011teléfono…",
  ["29:5621"] = "Te enseñaré todo\nlo que sé acerca\012de BILL, así que\ndéjame tu número\011de teléfono.",
  ["16:6b8d"] = "¡Las COLAS de los\nSLOWPOKE se\011regeneran rápido!\012¿Qué hay de malo\nen venderlas?",
  ["29:5666"] = "¡BILL es más que\nasombroso!\012Quiero ser un\nPOKéMANIAC tan\012bueno como él…\nÉse es mi sueño.",
  ["19:5f88"] = "Pesqué una cosita\ninteresante en la\011orilla.\012Como te prometí,\nes tuyo.\012Te espero en\n{STRBUF}.",
  ["29:56b6"] = "Lo vas a lamentar…\nY me dará igual…",
  ["16:6b7b"] = "¡Maldito lambrijo!",
  ["29:56e2"] = "¿Eh? Tu agenda de\nteléfonos está\011llena.\012¡Los POKéMANIACS\ndeberían ser más\011ordenados!",
  ["19:5e42"] = "Ya lo creo, noqueé\na un {STRBUF}\011salvaje.\012Era enorme, así\nde grande.\012Eh, seguro que no\nte lo crees por\011teléfono…",
  ["29:571e"] = "Estaba esperando.\012Mira… ¡Mira mis\nPOKéMON!",
  ["16:6b43"] = "¿No más COLAS?\012¡Claro! ¡Intenta\nvencernos a todos!",
  ["29:574a"] = "¡Hola! ¿También te\ngusta CLEFAIRY?\012Son tan encantado-\nres, ¿verdad?\012¡Creo que podemos\nllevarnos bien!\012¡Quiero saber\ntu número de\011teléfono!\012¡Hablemos sobre\nCLEFAIRY!",
  ["19:6043"] = "Soy ÓSCAR…\012¿{PLAYER}? ¿Cómo?\n¿Te has perdido?\012Nuestro combate\nserá en\011{STRBUF}.",
  ["29:57e3"] = "¡Quiero saber\ntu número de\011teléfono!\012¡Hablemos sobre\nCLEFAIRY!",
  ["6d:663b"] = "¡Hola! ¡Soy yo,\n{STRBUF}!",
  ["29:5820"] = "¿A que mi CLEFAIRY\nes monísimo?",
  ["19:5de4"] = "Mi {STRBUF} ha\nvuelto a crecer.\012Sólo era así de\ngrande cuando lo\012atrapé, pero ahora\nes mucho mayor.",
  ["29:5842"] = "Auuu… Oh, vale.\nBúscame si quieres\012hablar acerca de\nCLEFAIRY.",
  ["16:6adf"] = "Simplemente…\nMuy fuerte…",
  ["29:5881"] = "¿Eh? Tu agenda de\nteléfonos está\011llena.",
  ["6b:6682"] = "¡Pues vaya!\nMe encontraste.\012Por favor, no se\nlo digas a nadie.\012Te daré esto si\nme guardas el\011secreto. ¿Vale?",
  ["29:58a3"] = "¡Allá vamos!\012¡Haz todo lo que\npuedas, CLEFAIRY!",
  ["6b:66f0"] = "Es muy duro\nser famoso.\012Todo el mundo\nme persigue.\012Sólo quiero que me\ndejen en paz…",
  ["29:58d5"] = "Has tardado mucho.\n¿Ves esto?\012¿A que mola?\nEs un LAZO ROSA.",
  ["6b:6752"] = "FEAROW: ¡Fearow!",
  ["29:5914"] = "Oh, oh. Tu MOCHILA\nestá llena.",
  ["6c:4000"] = "¡Bienvenido a\nnuestro CENTRO\011POKéMON!",
  ["29:5937"] = "Oye, eres\nrealmente fuerte.\012Pero no quiero\nescabullirme…\012¡Ya sé! ¿Me das tu\nteléfono?\012¡Luchemos más\nveces!",
  ["6c:402b"] = "¡Hola! ¡Bienvenido\na nuestro CENTRO\011POKéMON!",
  ["29:59bc"] = "¡Quiero luchar con\nentrenadores duros\012tan a menudo como\nsea posible!\012¿Me das tu número\nde teléfono?\012¡Nos veremos en\nmás batallas!",
  ["6c:404f"] = "¡Buenas noches!\nBienvenido a\012nuestro CENTRO\nPOKéMON.",
  ["29:5a28"] = "¡No olvides venir\na verme cuando te\011desafíe!",
  ["6c:408a"] = "",
  ["29:5a5a"] = "Es bueno tener un\namigo que use\011POKéMON pájaro…\012¿No lo\nreconsiderarás?",
  ["6c:40d6"] = "",
  ["29:5aa6"] = "Tu teléfono ya\nno tiene memoria.\012¡Borra algún\nnúmero!",
  ["6c:411b"] = "",
  ["29:5ada"] = "¡Me alegro de\nverte! ¡Perderás!",
  ["6c:417a"] = "Nosotros curamos\na tus POKéMON.\012¿Quieres curar a\ntus POKéMON?",
  ["29:5aff"] = "Oh, qué mal. No\ntienes espacio.\012¡Te lo daré la\npróxima vez!",
  ["6c:41bd"] = "Muy bien, déjame\ntus POKéMON.",
  ["29:5b3f"] = "¡Eres muy, muy\nfuerte!\012Gracias por verme\ntan a menudo. He\012aprendido un\nmontón de ti.\012¡Ya sé! ¡Esto te\ndemostrará mi\011agradecimiento!",
  ["6c:41d7"] = "¡Gracias por\nesperar!\012Tus POKéMON están\nen plena forma.",
  ["29:5bc4"] = "Eh, nuestra lucha\nfue divertida…\012Cuando pesco, a\nveces recojo\012objetos que ha\nperdido la gente.\012¿Los quieres?\n¿Cuál es tu número\011de teléfono?",
  ["6c:420b"] = "¡Vuelve siempre\nque quieras!",
  ["29:5c4b"] = "Si recojo algún\nobjeto mientras\011pesco, es tuyo.\012¿Cuál es tu número\nde teléfono?",
  ["16:6825"] = "¡Maldición! Estaba\nde guardia arriba\012cuando un viejo\nmemo me gritó.\012Me asusté tanto\nque me he caído\011aquí abajo.\012¡Creo que voy\na desahogar mi\012ira luchando\ncontra ti!",
  ["29:5c8e"] = "Si atrapo algo\nbueno, te avisaré.",
  ["19:5c66"] = "¿Recuerdas? Hoy es\nel Concurso de\011Captura de Bichos.\012¿Vas a ir, no?\012Creo que\nparticiparé con\012PIKACHU para que\ntodos lo admiren.",
  ["29:5cc5"] = "Muy bien… Vuelve\nsi cambias de\011opinión.",
  ["16:67ca"] = "CÉSAR: ¡Muy bien,\n{PLAYER}!\012El TEAM ROCKET\nha huido.\012Y yo estoy mejor\nde mi espalda.\011¡Salgamos de aquí!",
  ["29:5cfa"] = "No puedes guardar\nmás números de\011teléfono.",
  ["19:6cf7"] = "(Suspiro…)\nYa no pican en\012{STRBUF}\ncomo antes…\012¡Tienes que venir\na luchar!",
  ["29:5d1d"] = "¡Argh! ¡Has\nasustado a POLIWAG\011y ha huido!",
  ["19:6d45"] = "¿No quieres este\nobjeto?\012¿Cómo? ¿No sabes\ndónde ir?\012{STRBUF}…\n¡Dirígete desde\012PUEBLO CAOBA a\nCIUDAD ENDRINO!",
  ["29:5d4d"] = "Así que has\nvenido.\012¿Lo ves?\nLo he recogido\012hace un rato.\nEs tuyo.",
  ["1b:5d39"] = "La puerta está\ncerrada…\012Requiere una\ncontraseña.",
  ["29:5d9a"] = "¿Tu MOCHILA está\nllena?\012Te lo daré más\ntarde.",
  ["1b:5d6b"] = "La puerta está\ncerrada…\012{PLAYER} introdujo\nla contraseña.\012¡Puerta abierta!",
  ["29:5dc6"] = "¡Nuestro combate\nfue notable!\012¡Deseo algo con\nlo que poder\011recordarte!\012¿Quizás tu número\nde teléfono?\012Mi entrenamiento\nno me permite\011hablar mucho…",
  ["1b:5da7"] = "La emisora de\nradio está\012emitiendo una\nsiniestra señal.\012Está funcionando a\nmáxima capacidad.",
  ["29:5e63"] = "Mi entrenamiento\nno me permite\012hablar mucho, pero\npodrías apuntar mi\011teléfono…",
  ["1b:5e03"] = "Por fin la emisora\nde radio ha dejado\012de transmitir esa\nmaldita señal.",
  ["29:5ea8"] = "¡Debo entrenarme\nmás para ser el\011más fuerte!",
  ["1b:6179"] = "LANCE: Necesitas\ndos contraseñas\012para entrar en el\ncuarto del jefe.\012Y sólo conocen\nesas contraseñas\011algunos ROCKETS.\012Me lo ha contado\nese ROCKET que\011está ahí.\012{PLAYER}, busquemos\nesas contraseñas.",
  ["29:5ed6"] = "Si decides que\nquieres mi número,\011ven a verme.",
  ["1b:6235"] = "¡Urrgg…! El\nchico de la capa\011es muy fuerte…",
  ["29:5f06"] = "Tu teléfono no\nadmite más\011números.\012¡Vuelve más tarde!",
  ["1b:6267"] = "…\012¿No te había\ndicho que iba a\012destruir al TEAM\nROCKET?\012Dime, ¿quién\nera el chico de la\012capa que usaba los\nPOKéMON dragón?\012Mis POKéMON no\npudieron con él.\012No me importa\nperder. Podría\012ganarle con otros\nPOKéMON.\012Lo que me molestó\nes lo que dijo…\012Me dijo que no\namo ni confío\012bastante en mis\nPOKéMON.\012Me enfurece haber\nperdido contra un\011memo como él.\012¡Humph! ¡No tengo\ntiempo para\011gente como tú!",
  ["29:5f37"] = "¡Quiero darte las\ngracias, {PLAYER}!\012He estado entre-\nnándome tan solo…\012Me hizo muy feliz\nque llamases…\012¡Quiero darte\nesto!",
  ["1b:6400"] = "¿Qué? ¿Quién eres?\nÉsta es la oficina\012de nuestro líder,\nGIOVANNI.\012Lleva entrenándose\ndesde que el TEAM\012ROCKET se separó\nhace tres años.\012Pero seguro que\nvolverá algún día\012para retomar el\nmando.\012Por eso estamos\naquí de guardia.\012¡No permitiré que\nnadie perturbe\011este lugar!",
  ["29:5faa"] = "¡No tienes fuerza\npara llevar ni\011una cosa más!\012¡Te guardaré esto\nhasta que aligeres\011tu MOCHILA!",
  ["1b:6511"] = "Yo…, no pude\nevitarlo…\012GIOVANNI,\nperdóname…",
  ["29:600c"] = "¡Fiuu! ¡Esa manera\nde atacar es\012única! ¡Debemos\nvernos de nuevo!\012¿Qué tal si me\ndas tu número de\011teléfono?",
  ["19:7001"] = "Y ayer vimos a\nun {STRBUF}\012salvaje. Nos pre-\nguntábamos si de-\011bíamos atraparlo\011o golpearlo.\012¡Entonces llegó un\nchico y lo atrapó!\011¿Qué te parece?",
  ["29:6076"] = "Así que quieres\ntener mi teléfono\012para una revancha,\n¿verdad?",
  ["1b:6585"] = "MURKROW: La\ncontraseña es…\012VIVA GIOVANNI.",
  ["29:60b5"] = "¡Te llamaré cuando\nme apetezca echar\011un combate!",
  ["19:70eb"] = "Vale, ¡vuelve a\nllamarme!",
  ["29:60e2"] = "¿No? Pues vale.\012¡No parece un no\ndefinitivo!\012Estaré aquí para\ncuando quieras la\011revancha.",
  ["1b:65f1"] = "Muy bien. Espera.\nTe la diré.",
  ["29:6144"] = "¡Oh! No hay sitio\npara registrar mi\012número de\nteléfono.",
  ["1b:6611"] = "La contraseña de\nla oficina del\011jefe es…\012COLASLOWPOKE.\012Pero no te servirá\nde nada si no\011tienes las dos.",
  ["29:6175"] = "¡Eh, aquí llega!\n¡Adelante!\012Aquí llega mi ata-\nque sin cuartel…",
  ["19:717a"] = "El {STRBUF} de\n{STRBUF} está\012mucho más fuerte\nque antes.",
  ["29:61c9"] = "¡Tu MOCHILA parece\nestar llena!\012Ahora no te puedo\ndar esto.",
  ["1b:6717"] = "¡Ji, Ji, Ji!\n¡Eres bueno!",
  ["6c:470d"] = "¡Equipo completo!\nEl POKéMON fue\012enviado a tu CAJA\nen el PC de BILL.",
  ["19:71eb"] = "Pero, pero…\012Se me ha vuelto a\nescapar un\012{STRBUF}\nsalvaje…\012¡No es justo!",
  ["6c:474e"] = "GIMNASIO POKéMON\nDE {STRBUF}",
  ["1b:678d"] = "Trabajaba para\nSILPH, pero ahora\012investigo para el\nTEAM ROCKET.\012Un entrometido\ncomo tú debería\011ser castigado.",
  ["6c:475c"] = "LÍDER: {STRBUF}\012GANADORES:\n{PLAYER}",
  ["19:7281"] = "¡Hasta la vista!",
  ["6c:477f"] = "Bienvenido al\nCASINO.",
  ["1b:6822"] = "Una señal de radio\nque vuelve locos a\011los POKéMON…\012Mi experimento es\ntodo un éxito.\012Mi ascenso está\nasegurado. Esta\012derrota no\nsignifica nada.",
  ["6c:479c"] = "¿Necesitas fichas\nde juego?\012¡Oh! No tienes\nun MONEDERO\011para tus fichas.",
  ["19:72d5"] = "¡Oh, {PLAYER}!\n¡Lucha con ELISA!\012¡Te espero en\n{STRBUF}!",
  ["6c:47e3"] = "¿Necesitas fichas\nde juego?\n50 fichas por\n1000¥. ¿Quieres\011comprar?",
  ["1b:68df"] = "Mi fuerte es\npensar, no pelear.",
  ["6c:4830"] = "¡Gracias! Aquí\ntienes 50 fichas.",
  ["1a:4097"] = "¿Qué? ¿Cómo ha\npodido ocurrir?",
  ["6c:484f"] = "¡Gracias! Aquí\ntienes 500 fichas.",
  ["1b:6970"] = "La puerta está\ncerrada…\012Necesitas dos\ncontraseñas.",
  ["6c:486f"] = "No tienes\nbastante dinero.",
  ["1a:40f3"] = "Cuando llevo\npantalones cortos\012por la hierba, me\npican las piernas.",
  ["16:6488"] = "Seguiré\nentrenándome\011hasta que mejore.",
  ["1a:4131"] = "¡Ayyyy!\n¡Me han pisado!",
  ["19:5a63"] = "¿Recuerdas\nnuestro combate?\012Estoy en\n{STRBUF}.\012Date prisa, te\nespero.",
  ["1a:414a"] = "Voy a capturar\nmás POKéMON en\011la hierba.",
  ["16:6467"] = "No, eres demasiado\nbueno para mí.",
  ["1a:4175"] = "…",
  ["1a:4178"] = "…",
  ["1a:417b"] = "…\012Perdí cuando tenía\nlos ojos cerrados.",
  ["19:5a23"] = "¡Voy a estudiar\nmucho para ser el\012ayudante del\nPROF. OAK!",
  ["1a:41a1"] = "Ya veo…\012Todo lo que hay\nque ver de ti…",
  ["16:6444"] = "Estoy entrenando.\n¿Quieres luchar?",
  ["1a:41cd"] = "No me imaginaba\ntu poder…",
  ["19:5969"] = "¿Sabes una cosa?\nEl PROF. OAK viajó\012por todo el mundo\ncuando era joven.\012Mientras viajaba,\naprendió mucho\012sobre los POKéMON\nsin esfuerzo.\012Le envidio…\nTambién quisiera\012viajar y aprender\ntantas cosas…",
  ["1a:41ec"] = "Fuerza de\nconvicción…\012Eres fuerte porque\nconfías en tus\011POKéMON.",
  ["6c:49fe"] = "¡Tus conocimientos\nimpresionan!\012¡Me gusta!\012¿Quieres intercam-\nbiar consejos de\011batalla?\012Te telefonearé si\nobtengo buena\011información.\012¿Me das tu número\nde teléfono?",
  ["1a:4238"] = "RUTA 11",
  ["6c:4a82"] = "¿Quieres intercam-\nbiar consejos de\011batalla?\012Te telefonearé si\nobtengo buena\011información.\012¿Me das tu número\nde teléfono?",
  ["1a:42a2"] = "Cuando atrapas un\nPOKéMON, puede\011estar débil.\012Pero éste crecerá\ny se hará más\011fuerte.\012Es importante\ntratar a los\012POKéMON con\nmucho cariño.",
  ["6c:4adb"] = "¡Te llamaré si\nescucho algo!",
  ["1a:4323"] = "Los POKéMON pueden\nir equipados con\012objetos como\nPOCIÓN y ANTÍDOTO.\012Pero parece que\nno saben usar los\012objetos hechos\npor el hombre.",
  ["6c:4afd"] = "Oh, vaya. Qué mal…\012Bueno, si quieres\nmi número, ven a\011verme, ¿vale?",
  ["1a:4473"] = "¡Soy PEGASO, líder\ndel GIMNASIO de\011CIUDAD MALVA!\012Dicen que una\nsacudida eléctrica\012puede acabar con\nlas alas de los\011POKéMON voladores.\012¡No permitiré\nque hablen así\011de ellos!\012¡Yo te enseñaré el\nauténtico poder de\012los magníficos\npájaros POKéMON!",
  ["6c:4b42"] = "¿Eh? Tu agenda\nestá llena.\012No puedes guardar\nmi número.",
  ["1a:454a"] = "¡Maldición! Los\nqueridos POKéMON\011de mi padre…\012¡Muy bien!\nToma esto.\012Es la MEDALLA\nCÉFIRO oficial de\011la LIGA POKéMON.",
  ["6c:4b75"] = "Hola. ¡Esperaba\nque vinieras!\012¡Empecemos ya\nmismo!",
  ["1a:45af"] = "{PLAYER} recibió\nla MEDALLA CÉFIRO.",
  ["6c:4bb6"] = "¡Tu MARILL es tan\nadorable!\012¡Quieres a los\nPOKéMON como yo!\012¿Quieres mi número\nde teléfono?\012¡Qué bien! ¡Será\nmuy divertido!",
  ["1a:45c8"] = "La MEDALLA CÉFIRO\nmejora el ataque\011de los POKéMON.\012Y permite que\nlos POKéMON\012usen DESTELLO, si\nlo tienen.\012Toma, también\nte daré esto.",
  ["6c:4c37"] = "¡Tu MARILL es tan\nadorable!\012Debemos hablar.\nSerá divertido.\012¿Me das tu número\nde teléfono?",
  ["1a:4648"] = "Al usar una MT, el\nPOKéMON aprenderá\012inmediatamente un\nnuevo movimiento.\012Piensa antes de\nactuar, ya que las\012MT sólo se pueden\nusar una vez.\012MT31 contiene\nBOFETÓN-LODO.\012Reduce la\nprecisión del\012enemigo y causa\ngrandes daños.\012Es decir, es tanto\ndefensiva como\011ofensiva.",
  ["6c:4c9b"] = "Para ser sinceros,\nquiero un MARILL.\012Pero me conformo\ncon mi SNUBBULL.",
  ["1a:4735"] = "Encontrarás\nGIMNASIOS POKéMON\012en las ciudades\ny en los pueblos.\012Deberías probar\ntus habilidades en\011estos GIMNASIOS.\012¡Yo seguiré\nentrenándome para\012ser el maestro de\nlos pájaros!",
  ["6c:4ce0"] = "Oh…\nQué pena…\012Adiós, MARILL…",
  ["1a:47cd"] = "¡La clave está en\ntener valor!\012Éstos entrenan\nnoche y día para\012convertirse en\nmaestros POKéMON.\012¡Adelante!",
  ["6c:4d0b"] = "¿Eh? La memoria de\ntu teléfono está\011llena.",
  ["1a:482f"] = "¡Aaah!",
  ["6c:4d2c"] = "¿Eh? ¿{PLAYER}?\nTe esperaba.\012Te he traído un\npequeño regalo.",
  ["1a:4837"] = "¡La destreza de\nPEGASO es real!\012¡No te confíes\npor haberme\011vencido!",
  ["6c:4d69"] = "¿Eh? No tienes más\nespacio.\012Por favor, vuelve\nmás tarde.",
  ["1a:487f"] = "¡Demuéstrame que\neres lo bastante\011bueno para PEGASO!",
  ["6c:4d9f"] = "¡Guay! ¡Es la\nprimera vez que\012pierdo desde hace\nmucho!\012Dame tu número de\nteléfono.\012Me lo paso bien\nluchando contigo;\012te llamaré cuando\nsea más fuerte…",
  ["1a:48b3"] = "¡No puede\nser cierto!",
  ["6c:4e2c"] = "Dame tu número de\nteléfono.\012Me lo paso bien\nluchando contigo;\012te llamaré cuando\nsea más fuerte…",
  ["1a:48c7"] = "¡Qué patético!\nHe perdido contra\011un novato…",
  ["6c:4e89"] = "¡Eh, luchemos de\nnuevo!",
  ["1a:48f9"] = "¡Hola! ¡No soy\nentrenador pero te\011puedo aconsejar!\012¡Créeme!\nSi confías, tus\012sueños de triunfo\npodrían cumplirse.\012¿Confías? Pues\nescucha.\012El tipo planta es\ndébil contra el\012tipo volador.\n¡No lo olvides!",
  ["6c:4ea2"] = "Parece que eres\nmuy débil…",
  ["1a:49c8"] = "¡Bonita batalla!\n¡Sigue así y\011serás el CAMPEÓN!",
  ["6c:4ebc"] = "¡Eh! ¡Tu teléfono\nya está lleno!",
  ["1a:4b3b"] = "¡Soy yo, PRIMO!\012¡Fantásticos son\nlos POKéMON!\012¡A ti yo te\nenseñaré a ser un\011entrenador mejor!\012¿Quieres saber\ncómo ser un\011ganador?",
  ["6c:4edc"] = "¡Eh! ¡Estoy harto\nde esperarte!",
  ["1a:4bbd"] = "¡Bien! ¡A ti yo\nte enseñaré!\012¡En combate, los\nprimeros POKéMON\011salen antes!\012¡Quizá sea más\nfácil si cambias\011el orden!\012¿Quieres que te\ncuente más cosas?",
  ["6c:4eff"] = "Oh… Tu MOCHILA\nestá llena. Te lo\011daré más tarde.",
  ["1c:4421"] = "¡Ajaa! ¡Los\nMAGIKARP pican!",
  ["6c:4f2f"] = "¡Ufff! ¡Ha sido\nmuy duro!\012He luchado contra\nti una y otra vez,\012{PLAYER}, pero no\nhe ganado nunca.\012He comprado muchos\nobjetos para\012mejorar a mis\nPOKéMON, pero…\012Los objetos no son\nla solución.\012Ése debe de ser el\nproblema…\012Coge esto,\n{PLAYER}.\012No lo voy a\nnecesitar más…",
  ["1a:4c7b"] = "¡Bien! ¡A ti yo\nte enseñaré!\012Si un POKéMON\nsale al combate,\012aunque brevemente,\ngana puntos EXP.\012¡Pon arriba los\nPOKéMON débiles,\012y cámbialos rápido\nen el combate!\012¡Así se harán más\nfuertes los\011POKéMON débiles!",
  ["6c:502e"] = "Guau, qué duro.\nNo había luchado\012tan en serio desde\nhacía mucho.\012¿Me das tu número\nde teléfono?\012Me gustaría luchar\notra vez cuando\012cure a {STRBUF}\ny al resto.",
  ["1c:44bb"] = "¿Me han engañado\nmis ojos? He visto\012un GYARADOS rojo\nen el LAGO…\012Yo pensaba que\nlos GYARADOS eran\011siempre azules.",
  ["6c:50d3"] = "¿Me das tu número\nde teléfono?\012Me gustaría luchar\notra vez cuando\012cure a {STRBUF}\ny al resto.",
  ["1a:4d80"] = "Estoy tomando\napuntes de lo que\011dice el profesor.\012Y debería copiar\ntambién lo escrito\011en la pizarra.",
  ["6c:5136"] = "¿Cómo podré\nderrotarte?\012Me atormento sólo\nde pensarlo…",
  ["1c:454e"] = "Puede que sea un\npescador experto,\012pero soy un mal\nentrenador…",
  ["6c:517b"] = "Vale… Lo entiendo…\nPero si cambias de\011opinión, avísame.",
  ["1a:4e07"] = "¡El POKéMON que\nhe conseguido va\011equipado con algo!",
  ["6c:51c4"] = "La memoria de tu\nteléfono está\011llena.\012No puedes guardar\nmi número.",
  ["1c:45c0"] = "Haga lo que haga,\nsiempre capturo\012los mismos\nPOKéMON…",
  ["6c:51fe"] = "¡Hola! ¡Te estaba\nesperando!\012¡Esta vez te voy\na ganar!",
  ["1a:4eb2"] = "La pizarra indica\ncómo cambian de\012estado los POKéMON\nen combate.",
  ["6c:5239"] = "Hace mucho que\nperdí por última\011vez…\012Se te da muy bien\nluchar.\012Debemos luchar en\notra ocasión.\012Desafiar a alguien\ntan duro como tú,\012me hará mejorar\ntambién a mí.\012¿Qué te parece?\012¿Me das tu número\nde teléfono?",
  ["1c:4611"] = "¿Por qué no atrapo\nbuenos POKéMON?",
  ["6c:5314"] = "Desafiar a alguien\ntan duro como tú,\012me hará ser mejor\ntambién a mí.\012¿Qué te parece?\012¿Me das tu número\nde teléfono?",
  ["1a:4f80"] = "La parálisis baja\nla velocidad y\012puede impedir el\nmovimiento.\012Permanece tras el\ncombate, así que\011usa ANTIPARALIZ.",
  ["6c:5392"] = "¡Volvamos a luchar\nalgún otro día!",
  ["1c:4688"] = "¡Uauu…!\nBuen combate.",
  ["1b:72af"] = "¿Le ha pasado algo\nal guardián del\011bosque?",
  ["1a:5055"] = "Las quemaduras\nconsumen PS,\012reducen el poder\ndel ataque\012y permanecen\ntras el combate.\012Usa ANTIQUEMAR\ncomo cura.",
  ["16:5eaf"] = "Si hay luz, no me\nasusta la cueva.\012Si eres fuerte,\nlos POKéMON no\011se asustarán.",
  ["1c:46df"] = "¿Qué ocurrió con\nel GYARADOS rojo?\012¿Se ha ido?\012¡Maldición! ¿He\nvenido para nada?\012Ya sé.\n¡Luchemos!",
  ["19:6dc5"] = "¿Continúas\nviajando?\012Yo sigo entrenán-\ndome a fondo.\012¡Oooooaaarrrgh!",
  ["1a:5136"] = "Es el cuaderno de\neste niño…\012Captura POKéMON\nusando POKé BALL.\012Tu equipo puede\ntener hasta seis.\012¿Seguir leyendo?",
  ["16:5e6f"] = "Los fines de\nsemana se oyen\012extraños rugidos\nen la cueva.",
  ["1c:4752"] = "Pensándolo bien,\ncreo que vi un\011BUTTERFREE rosa.",
  ["16:5e60"] = "¡Me inflamé!",
  ["1a:5207"] = "Algunos ataques\ncausan confusión.\012Un POKéMON confuso\npuede atacarse a\011sí mismo.\012Retirarlo del\ncombate, eliminará\011su confusión.\012¿Seguir leyendo?",
  ["16:5e15"] = "El SUPERSÓNICO de\nZUBAT confunde a\011mis POKéMON.\012¡Y eso me\npreocupa!",
  ["1c:47dd"] = "Encantado de\nconocerte. Toma\011un recuerdo.",
  ["19:5c4e"] = "¡Bien, volvamos\na hablar!",
  ["1a:53fa"] = "Ella usa los\nnombres de sus\011comidas favoritas.\012Quiero decir,\ncomo motes para\011sus POKéMON.",
  ["19:6ed3"] = "Voy a parar para\ncomer, así que…\012¡Búscame entonces!\n¡Yiiija!",
  ["1c:4844"] = "MIGUEL: Como me\nhas encontrado,\012habrás visto a\nmis hermanos.\012¿O es que has\ntenido suerte?",
  ["19:6f11"] = "¡Estoy descansando\nen la RUTA 45!\012¿Por qué no te\npasas un rato?",
  ["1a:547c"] = "FRESITA: ¡Pidgey!",
  ["1b:7551"] = "Nunca antes había\nvisto a ese\011POKéMON…",
  ["1c:48d7"] = "LAGO DE LA FURIA,\nconocido como\011LAGO DE GYARADOS.",
  ["1b:7571"] = "Al usar GOLPE CA-\nBEZA en ese árbol,\012cayó un POKéMON\nque no había visto\011en mi vida.\012Creo que debo usar\nGOLPE CABEZA en\011más sitios.",
  ["1a:55c5"] = "Hemos descubierto\nque los POKéMON\012salen del HUEVO\ncuando crecen.\012Para que el HUEVO\nse abra, debe de\012estar con otros\nPOKéMON activos.\012{PLAYER}, sólo\npodemos confíar\011en ti.\012Llama al PROF. ELM\ncuando se abra el\011HUEVO, por favor.",
  ["1c:4157"] = "Este LAGO\nestá lleno de\011GYARADOS…\012Así que los\nMAGIKARP\012deben haber\nevolucionado.",
  ["1c:49ef"] = "¡Hola! ¡Bienvenido\nal CENTRO\012COMERCIAL de\nCIUDAD AZULONA!\012El directorio\nestá en la pared.",
  ["1c:41b4"] = "¿Has venido hasta\naquí por los\011rumores?\012¿Eres {PLAYER}?\nYo soy LANCE, un\011entrenador más.\012He oído rumores\ny he venido a\011investigar…\012Te he visto\nluchar, {PLAYER}.\012Creo que como\nentrenador eres\011muy bueno.\012Si no te importa,\n¿quieres ayudarme\011a investigar?",
  ["1a:56f2"] = "Pero…\nEl PROF. ELM\011preguntó por ti.",
  ["1c:42c6"] = "LANCE: ¡Excelente!\012Parece que los\nMAGIKARP del LAGO\012se ven obligados a\nevolucionar.\012La razón es una\nmisteriosa emisión\012de radio desde\nPUEBLO CAOBA.\012Te esperaré\nallí, {PLAYER}.",
  ["1c:4aa9"] = "Es la primera vez\nque vengo.\012Es muy grande…\012Me da miedo\nperderme.",
  ["1c:4371"] = "¡Oh…! Si\ncambias de opinión\012agradecería tu\nayuda.",
  ["1a:5809"] = "El sistema de\nalmacenamiento del\012PC es de un chico\nllamado BILL.",
  ["1c:43a5"] = "LANCE: ¿Qué?\n¿Me vas a ayudar?",
  ["1c:4bc9"] = "Hace poco que soy\nentrenador. Mi\012hijo me animó a\nserlo.\012Estoy impresionado\npor la cantidad de\012objetos útiles\nque hay.",
  ["1c:43cb"] = "GYARADOS: ¡Gyaraa!",
  ["1a:58b8"] = "Los POKéMON son\nlistos y no\012obedecen a quien\nno respetan.\012Sin las MEDALLAS\nnecesarias, harán\012lo que ellos\nquieran.",
  ["1c:43df"] = "{PLAYER} obtuvo\nuna ESCAMA ROJA.",
  ["1c:4c9c"] = "¡Objetos de máxima\ncalidad para\011entrenadores!\012P1: TIENDA DE\n    ENTRENADORES",
  ["1c:43f8"] = "¡Los GYARADOS\nestán enfadados!\012¡Mal presagio!",
  ["1a:5a36"] = "RUINAS ALFA\012Centro Turístico\n¡Mírame y Tócame!\012¡Intenta mover las\npiezas de piedra!",
  ["15:4e42"] = "BILL: Mi padre no\ntrabaja. Lo único\012que hace es\nholgazanear.\012Es que no da ni\ngolpe…",
  ["1c:4d86"] = "¡Oh, oh! Cambié\nmis POKéMON sin\012quitarles la\nMEJORA.",
  ["15:4ea8"] = "Anda, ¿coleccionas\nPOKéMON? Mi hijo\012BILL es todo un\nexperto.\012Le han llamado del\nCENTRO POKéMON de\011CIUDAD IRIS.\012Mi marido fue al\nCASINO sin que le\011llamara nadie…",
  ["1a:5abd"] = "Hay dibujos en las\npiezas de piedra.\012Intenté moverlas.\nMe pregunto\011qué serán.",
  ["1c:4444"] = "Dicen que este\nlago fue obra\012de violentos\nGYARADOS.\012Me pregunto si eso\nestará relacionado\012con su actual\nrebelión.",
  ["1c:4e61"] = "En la TIENDA DE MT\nhay ataques raros.",
  ["6c:5978"] = "¡Eh, espera! ¡Tu\nMOCHILA está\011llena!\012Lo dejaremos hasta\nla próxima vez.",
  ["1a:5be8"] = "Eso está\nbien.\012¡Ahora ya eres\nun pescador!",
  ["6c:59be"] = "He perdido otra\nvez…\012No hay manera de\nvencerte.\012¡Tanta derrota me\nhace sentir bien!\012Coge esto. Úsalo\npara ser aún\012mejor. ¡También\nyo mejoraré!",
  ["1c:4f21"] = "He venido a por\nuna CARTA SURF\011para mi novia.",
  ["6c:5a71"] = "¡Eres increíble!\n¡Me gustas!\012Busco POKéMON aquí\ntodos los días.\012Cuando salgo al\ncampo, encuentro\012toda clase de\nBAYAS.\012Si quieres, te\ndaré algunas.\012¿Me das tu número\nde teléfono?",
  ["1a:5c6c"] = "¡Vaya! Me has\ndecepcionado…",
  ["6c:5b1d"] = "Cuando salgo al\ncampo, encuentro\012toda clase de\nBAYAS.\012Si quieres, te\ndaré algunas.\012¿Me das tu número\nde teléfono?",
  ["1a:5c8d"] = "Hola.\n¿Están picando?",
  ["6c:5b8e"] = "Oirás de mí tan\npronto como\012encuentre algo que\nte pueda gustar.",
  ["1a:5cac"] = "¿Cómo equipar\na mi POKéMON?\012Quizá con un\nobjeto que aumente\011su ATAQUE…",
  ["6c:5bd2"] = "Bueno, no dudes\nen pedirme mi nú-\011mero de teléfono.",
  ["1a:5ddd"] = "¡Perdona, joven!\n¿Puedes hacerme un\011favor?\012¿Puedes darle este\nPOKéMON con CARTA\011a mi amigo?\012Está en la\nRUTA 31.",
  ["6c:5c06"] = "Tu agenda de\nteléfonos no tiene\012espacio para mi\nnúmero.",
  ["1a:5e48"] = "¿Lo harás? Genial.\n¡Gracias, joven!\012Mi amigo es un\nchico gordinflón\012que siempre está\ndurmiendo.\012¡Le reconocerás\nenseguida!",
  ["6c:5c32"] = "Te esperaba.\n¡Luchemos!",
  ["1a:5eb8"] = "{PLAYER} recibió\nPOKéMON con CARTA.",
  ["6c:5c57"] = "¡Qué bien que has\nvenido! Esto es lo\012que he encontrado.\n¡Es para ti!",
  ["1a:5ed6"] = "Puedes leerla,\n¡pero no la\011pierdas! ¡RUTA 31!\012Ah, sí. Un extraño\nárbol bloqueaba\011el camino.\012¿Lo habrán\nretirado ya?",
  ["1c:5274"] = "¡Clang!\012Salió\n{STRBUF}.",
  ["1a:5f56"] = "No puedes llevar\notro POKéMON…",
  ["1c:528e"] = "¡Uups, no tienes\nbastante dinero!",
  ["1a:5f74"] = "¡Oh…! Entonces,\nno importa…",
  ["1c:52a7"] = "No hay sitio\npara nada más…",
  ["1a:5f8b"] = "¡Gracias, joven!\n¡Muchas gracias\012por habérselo\nllevado!\012¡Toma esto por\nlas molestias!",
  ["15:5160"] = "El tren no ha\nllegado…\012¡Tengo una idea!\n¡Llevaré a cuestas\011a los pasajeros!\012Aunque no creo\nque funcione.",
  ["1a:5fd9"] = "¿A que mi amigo\nestaba durmiendo?\011Te lo dije.",
  ["15:51b7"] = "Pronto saldremos\npara C. AZAFRÁN.\012¿Quiere\nsubir?",
  ["1a:600a"] = "Un extraño árbol\nbloquea el camino.\012Si le hablas,\nse mueve.\012Dicen que se\nvolvió loco cuando\012alguien lo mojó\ncon una REGADERA.",
  ["1c:4632"] = "Si un entrenador\nse encuentra con\012otro entrenador,\ndebe desafiarle.\012Ése es nuestro\ndestino.",
  ["1a:609a"] = "Me gusta la Nana\nPOKéMON que ponen\011en la radio.",
  ["15:51ed"] = "Por favor, ¿puedo\nver su PASE?\012Muy bien. Pase por\naquí, por favor.",
  ["1a:60cb"] = "Me pregunto\ncuántos tipos de\012POKéMON hay en\nel mundo.\012Hace tres años, el\nPROF. OAK dijo que\012había 150 tipos\ndistintos.",
  ["15:522c"] = "Lo siento, pero\nno tiene PASE.",
  ["1a:62eb"] = "Hoy es {STRBUF}.\nEso significa que\012hoy es el Concurso\nCaptura de Bichos.\012Las reglas son\nsencillas.\012Usa uno de tus\nPOKéMON y captura\012un POKéMON bicho\npara ganar.\012¿Te gustaría\nintentarlo?",
  ["1c:469c"] = "Los POKéMON y su\nentrenador se\012hacen más fuertes\ncuanto más luchan.",
  ["15:524f"] = "Siempre a su\nservicio.",
  ["15:526a"] = "Hemos llegado a\nCIUDAD TRIGAL.\012Siempre a su\nservicio.",
  ["1c:4745"] = "¡Muy bien!",
  ["1f:482a"] = "¡Muy bien!\n¡Ya está!",
  ["15:52a3"] = "Soy el PRESIDENTE.\012Mi sueño era crear\nun tren que fuera\012más rápido que\ncualquier POKéMON.\012Hace que JOHTO\nesté mucho más\011cerca de KANTO.",
  ["1f:480e"] = "¡Vale! Ya verás lo\nbien que queda.",
  ["15:53d4"] = "¿Has visto ese\nextraño árbol que\012crece en la RUTA\n36?\012Mi hermana sintió\ncuriosidad y salió\011a verlo…\012Estoy preocupada…\n¿No es peligroso?",
  ["1f:47f1"] = "¿A qué POKéMON\nle corto el pelo?",
  ["1c:4784"] = "MIGUEL: Hola,\n¿qué tal estás?\012Hoy es miércoles\ny yo soy MIGUEL,\012por lo de\nmiércoles.",
  ["1f:475c"] = "¡Bienvenido a la\nPELUQUERÍA!\012Soy el más joven y\nel más novato de\012los dos HERMANOS\nPELUQUEROS.\012Pondré guapos a\ntus POKéMON por\011sólo 300¥.\012¿Qué dices?",
  ["15:5463"] = "¿Quieres llevarte\nla REGADERA? No\012quiero que cometas\nninguna impruden-\011cia con ella.",
  ["5d:59e7"] = "¡Hasta luego!",
  ["5d:5976"] = "¿Te apetece luchar\ncontra mí?\012¡No será como la\núltima vez!\012Estoy en\n{STRBUF}.\012Házmelo saber\ncuando llegues.",
  ["5d:58e4"] = "Oh, sí. Un\n{STRBUF} salvaje\012huyo de mí en el\núltimo segundo.\012Ya sé que es un\nPOKéMON común…\012Pero me fastidia\nque se escapase\012cuando casi le\ntenía.",
  ["5d:5869"] = "Oh, sí. Dejamos\nK.O. a un\012{STRBUF} salvaje\nde un golpe hace\011nada.\012Cayó con demasiada\nfacilidad, la\012verdad es que me\nsiento fatal.",
  ["5d:57d4"] = "¿Tus POKéMON\nestán creciendo?\012Mis POKéMON lo\nhacen demasiado\012rápido para mí.\n¡Es abrumador!\012{STRBUF} es el\nque más rápido\012crece. Creo que\nserá muy fuerte.",
  ["5d:5786"] = "¿Qué esperas,\n{PLAYER}?\012¡Enfrentémonos\nen un combate!\012¡Te espero en\n{STRBUF}!",
  ["5d:571d"] = "Estoy estudiando\nlos movimientos de\012{STRBUF} y pen-\nsando estrategias.\012Cuando encuentre\nuna buena,\011¡lucharemos!",
  ["5d:570a"] = "¡Hasta luego!",
  ["5d:5693"] = "¡Reunámonos para\nluchar!\012¡Esta vez no lo\ntendrás tan fácil!\012Estaré en\n{STRBUF}.\012Avísame cuando\nllegues.",
  ["5d:5611"] = "¡Sí, vi a un\n{STRBUF}\011salvaje!\012Pensé en ir a por\nél, pero decidí\012seguir entrenando\na mi único y amado\012POKéMON hasta el\nfinal.",
  ["5d:5591"] = "Sí, atrapé a un\n{STRBUF} salvaje\011el otro día.\012Estuvo chupado.\nEn fin, ¿qué se\012puede hacer si\nsomos tan fuertes?",
  ["5d:5530"] = "¡Mi {STRBUF}\nparece más listo\011que antes!\012¡Dudo que tengas\nun POKéMON tan\012guay como éste en\ntu equipo!",
  ["5d:54e5"] = "¿Qué haces?\012¡Te dije que te\nesperaba en\012{STRBUF}!\n¡No intentes huir!",
  ["5d:549b"] = "No te enorgullez-\ncas tanto por\011haberme vencido…\012¡Ha sido chiripa!",
  ["5d:5488"] = "Bien, puedes irte.",
  ["5d:543a"] = "¡Vamos a luchar!\012¡Te espero en\n{STRBUF}!\012¡No tardes mucho!\n¿Lo coges?",
  ["5d:53c5"] = "¿Alguna vez no he\npodido atrapar a\011un POKéMON?\012¿No lo sabes?\012Nunca dejaría\nescapar a un\012{STRBUF}\nsalvaje…\012¡Bah! ¡Da igual!",
  ["5d:536b"] = "¿Que si me he\nenfrentado a un\012{STRBUF}\nsalvaje alguna\011vez?\012¿No lo sabes?\012¡He derrotado a\nmiles de\011{STRBUF}!",
  ["5d:52f5"] = "Escucha, joven…\012¿Te acuerdas de mi\n{STRBUF}?\012Exactamente. Ese\nbonito {STRBUF}.\012¿No opinas que es\nuna pareja\011perfecta para mí?",
  ["27:6b94"] = "Ups, tu MOCHILA\nestá llena.\012Por favor, vacíala\ny vuelve.",
  ["27:6b7e"] = "",
  ["27:6aef"] = "¡Felicidades!\012¡Has derrotado a\ntodos los\011entrenadores!\012¡Por ello, toma\neste gran premio!\012",
  ["27:6a49"] = "¡Gracias por tu\nvisita!",
  ["27:6886"] = "La TORRE BATALLA\nes una instalación\012construida para\ncombates POKéMON.\012Incontables entre-\nnadores POKéMON\012llegan de todas\npartes para luchar\012en las SALAS\nBATALLA.\012Hay muchas SALAS\nBATALLA en la\011TORRE BATALLA.\012Cada SALA cuenta\ncon siete\011entrenadores.\012Derrótales a todos\ny ganarás un\011premio.\012Para interrumpir\nuna sesión, debes\012GUARDAR. Si no lo\nhaces, no podrás\012continuar tu\ndesafío.\012",
  ["27:660a"] = "Por aquí accederás\na tu SALA BATALLA.",
  ["27:65ea"] = "¿Quieres entrar en\nuna SALA BATALLA?",
  ["27:65ab"] = "¡Gracias por venir\na la TORRE\011BATALLA!\012Te mostraré una\nSALA BATALLA.",
  ["27:62a9"] = "He oído que los\nremolinos que hay\012alrededor de las\nislas son causados\012por una criatura\nmarina.\012Necesitarás una\nhabilidad especial\011para sortearlos.",
  ["27:623f"] = "Dicen que sólo\npuedes verla si\012tienes un ALA\nPLATEADA.\012Debe de tener la\nmisma esencia que\011la criatura.",
  ["27:61bc"] = "¿Vienes de\nCIUDAD OLIVO?\012¿Te acuerdas de\nlas cuatro islas\011del camino?\012Dicen que en\nellas se esconde\012una criatura\nmítica marina.",
  ["15:54c2"] = "Oh, eres mejor que\nBLANCA…\012Entonces vale.\n¡Aquí tienes la\011REGADERA!",
  ["1c:480b"] = "MIGUEL: CINTURÓN\nNEGRO potencia los\011ataques de lucha.",
  ["15:550d"] = "¡No hagas nada\npeligroso!",
  ["1c:48a9"] = "MIGUEL: Hoy no\nes miércoles.\011¡Qué pena!",
  ["15:55e6"] = "Uuau, ¿venciste a\nBLANCA? ¡Genial!",
  ["15:5604"] = "¡Entonces era un\nPOKéMON!",
  ["1c:4a35"] = "Este C. COMERCIAL\npertenece a la\012misma cadena que\nel de TRIGAL.\012Los dos fueron\nrenovados al\011mismo tiempo.",
  ["15:5993"] = "Bienvenido al\nCENTRO COMERCIAL\011de CIUDAD TRIGAL\n",
  ["15:59b7"] = "El CENTRO\nCOMERCIAL tiene\011buenos artículos.\012Pero algunos\nobjetos sólo se\012consiguen en\nel CASINO.",
  ["15:5a80"] = "PB INFORMACIÓN\012P1 TIENDA DE\n   ENTRENADORES\012P2 ARTÍCULOS\n   DE COMBATE\012P3 BOTIQUÍN\012P4 TIENDA DE MT\012P5 PLAZA TRANQUILA\012MIRADOR",
  ["15:5c25"] = "El POKéGEAR puede\nalmacenar hasta\011diez números.\012Es difícil decidir\nqué numeros debes\011guardar.",
  ["1c:4dc7"] = "¡Sí! ¡Ya tengo\nun PORYGON!\012Se me dan muy mal\nlas tragaperras.\012¡Jamás ganaría\nbastantes fichas!\012¿Ehh…?\012¡El PORYGON que he\ncambiado se ha\012convertido en otro\nPOKéMON!",
  ["1d:56f7"] = "¡Te ganaré un\ndía de éstos!",
  ["1d:5741"] = "¡Yaaaa!",
  ["1d:5797"] = "¿Estás solo?\n¡Pues luchemos!",
  ["15:5dcc"] = "¡Estoy muy\ninquieto!\012Uso VELOCIDAD X\npara acelerar\011a mis POKéMON.",
  ["1d:57d4"] = "Me pregunto si en\nKANTO habrá\012montañas que valga\nla pena escalar.",
  ["1c:4f55"] = "Éste es el único\nlugar en el que\012encontrarás\nCARTAS AMOR.",
  ["1d:5897"] = "¡Lo siento! ¡Todo\nes culpa mía!",
  ["1c:5023"] = "Quiero comprar\nobjetos que\012aumenten las\nhabilidades de\012mis POKéMON. ¡Pero\nno tengo dinero!",
  ["1c:50b6"] = "Si usas objetos en\ntus POKéMON, se\011pondrán contentos.\012Sin embargo, odian\nalgunos objetos.",
  ["1c:5250"] = "¡Una máquina\nexpendedora!",
  ["1e:5a40"] = "¿{PLAYER}? Creía\nque el huevo se\011había abierto.\012¿Dónde está el\nPOKéMON?",
  ["1e:58cf"] = "{PLAYER}. El\ncamino hacia la\012gloria será\nlargo.\012Antes de irte, no\nolvides hablar\011con tu madre.",
  ["1e:5712"] = "{PLAYER} le dio el\nHUEVO MISTERIOSO\011al PROF. ELM.",
  ["1e:5668"] = "Contiene un\nPOKéMON atrapado\011por el PROF. ELM.",
  ["27:556c"] = "Para los POKéMON,\nla felicidad es\012estar con quien\nlos quiere.",
  ["1e:5581"] = "Si tu POKéMON\nresulta dañado,\012debes curarlo con\nesta máquina.\012Úsala siempre que\nquieras.",
  ["27:56f9"] = "¡UAUUUU!\012¡Has llegado\nhasta aquí!\012¡Que sepas que\nsoy muy fuerte!\012¡Mis POKéMON\naplastarán piedras\011y romperán huesos!\012¡Atento!",
  ["1e:544d"] = "ELM: Piénsalo\ncon cuidado.\012Tu compañero es\nimportante.",
  ["27:576f"] = "ANÍBAL: ¡Urgg!\n¡Urgg…!\012¡Oooarrg!",
  ["1e:53f3"] = "ELM: ¿Quieres a\nTOTODILE, el\011POKéMON de agua?",
  ["27:578a"] = "¿Qué? Ahora tienes\nmiedo, ¿no?\012¿Qué? ¿No tiene\nnada que ver con\012los POKéMON?\n¡Es cierto!\012Venga.\n¡Luchemos!",
  ["1e:54ad"] = "¡{PLAYER}\nrecibió a\011{STRBUF}!",
  ["27:57f6"] = "¿Qué? ¿Cómo?\n¿He perdido?\012¡Muy bien!\n¡Te mereces la\011MEDALLA TORMENTA!",
  ["1e:55f3"] = "{PLAYER} anotó\nel número de ELM.",
  ["27:5835"] = "{PLAYER}\nrecibió la\011MEDALLA TORMENTA.",
  ["1e:56aa"] = "¿Quieres curar a\ntus POKéMON?",
  ["27:584d"] = "Con MED. TORMENTA,\nte obedecerán los\012POKéMON hasta\nel nivel 70.\012Y permitirá a\ntus POKéMON usar\012VUELO cuando no\nestén luchando.\012¡Toma esto\ntambién!",
  ["1e:5745"] = "Pero… ¿Es un\nHUEVO de POKéMON?\012Si lo es, ¡vaya\ndescubrimiento!",
  ["27:58da"] = "Se trata de\nPUÑODINÁMICO.\012¡No siempre golpea\npero cuando lo\012hace produce\nconfusión!",
  ["1e:597d"] = "ELM: ¿{PLAYER}?\n¿No has visto a\011mi ayudante?\012Te esperaba con\nel HUEVO en el\012CENTRO POKéMON\nde CIUDAD MALVA.\012Si no lo has\nvisto, búscalo\011ahí.",
  ["27:5930"] = "¡UAJAJAA! ¡Ha sido\nmuy divertido!\012¡Pero una derrota\nes una derrota!\012¡Desde ahora, voy\na entrenar 24\011horas al día!",
  ["1e:5a8b"] = "¿Qué?\n¿¡Ese POKéMON!?",
  ["27:5997"] = "A mis POKéMON y\na mí nos une una\011gran amistad.\012¡Nuestro vínculo\nnunca se romperá!",
  ["1c:5100"] = "P4: FARMACIA",
  ["27:59e9"] = "¡No puede ser!",
  ["1c:5072"] = "Quiero MÁS PP,\npara aumentar los\012PP de los ataques.\n¡Pero no se vende!",
  ["27:59fa"] = "¡Parece que tú y\ntus POKéMON estáis\011muy unidos!",
  ["1c:4f8c"] = "¡Dilo con un\nregalo!\012P3: REGALOS",
  ["27:5a2e"] = "¡Los expertos en\nartes marciales no\011tememos a nada!",
  ["15:5e15"] = "¡Eh! ¿Utilizas\nESPECIAL X cuando\011luchas?\012¡Es increíble!\n¡Aumenta los\012ATAQUES\nESPECIALES!",
  ["27:5a50"] = "¡Es increíble!",
  ["1c:4e85"] = "P2: TIENDA DE MT\012¡Fortalece a tus\nPOKéMON!",
  ["27:5a61"] = "Los POKéMON de\nlucha temen a los\011psíquicos…",
  ["15:5d28"] = "Tu Compañero\nde Viaje\012P1 TIENDA DE\n   ENTRENADORES",
  ["27:5a8a"] = "Las palabras no\nsirven. ¡Deja que\011hablen tus puños!",
  ["15:5cb7"] = "Este CENTRO\nCOMERCIAL indica\012que CIUDAD TRIGAL\nes muy grande.\012Su gama de\nproductos no\011tiene rival.",
  ["27:5abd"] = "…",
  ["27:5ac0"] = "¡He perdido!\n¡No sé qué decir!",
  ["15:5c7b"] = "Conseguí mi ABRA\nen el CASINO.\012Ahora es mi mejor\ncompañero.",
  ["27:5ad9"] = "¡Mis furiosos\npuños destrozarán\011a tus POKéMON!",
  ["1c:4d53"] = "No sé en qué\nPOKéMON debería\012utilizar esta\nMT…",
  ["27:5b02"] = "¡Me has aplastado!",
  ["15:5a3a"] = "Mamá es experta\nen gangas.\012Siempre compra\ncosas a precios\011más bajos.",
  ["27:5b14"] = "¡Mis POKéMON han\nperdido! Has\011herido mi orgullo.",
  ["1c:4c3e"] = "A mi padre le está\ncostando aprender\012los nombres de los\nobjetos y cómo se\012supone que debe\nutilizarlos…",
  ["27:5bed"] = "¿Conoces al\nPOKéMANÍACO?\012Siempre está\npresumiendo de sus\011raros POKéMON.",
  ["15:5a1a"] = "¡Me encanta\nir de compras!",
  ["27:5c33"] = "",
  ["1c:4aea"] = "PB: INFORMACIÓN\012P1: TIENDA DE\n    ENTRENADORES\012P2: TIENDA DE MT\012P3: REGALOS\012P4: FARMACIA\012P5: AZOTEA",
  ["27:5dc5"] = "¡{PLAYER}! ¡Has\nganado! ¡Con sólo\011mirarte, lo sé!",
  ["15:56ca"] = "A veces, un\nPOKéMON sano\012no puede usar\nsus movimientos.\012Si ocurre esto,\ncúralo en el\012CENTRO POKéMON,\no usa un objeto.",
  ["27:5ed7"] = "Me encanta fardar\nde los POKéMON\012que he mejorado.\n¿A ti no?\012¡Voy a enfrentarme\na otros entrenado-\011res para mostrar\011mis POKéMON!",
  ["15:5659"] = "Un día estaba\nluchando y mis\012POKéMON no se\npodían mover.\012Sus movimientos no\ntenían ningún\012PUNTO de PODER,\no PP.",
  ["27:5fcd"] = "Parece que tus\nPOKéMON están\012bien. ¿Hay algo\nque te preocupa?\012…\012¿El POKéMON del\nFARO tiene\011problemas?\012¡Entendido!\012Esto debería\nayudarte.",
  ["1c:4903"] = "CASA DEL GURÚ\nPESCADOR",
  ["27:6056"] = "{PLAYER}\nrecibió la\011POCIÓN SECRETA.",
  ["15:5561"] = "Cuando le conté a\nmi hermana lo del\012extraño árbol, me\ndijo que era\011peligroso.\012Si venzo a BLANCA,\nes posible que me\012preste su\nREGADERA…",
  ["27:6070"] = "Mi POCIÓN SECRETA\nes muy potente.\012Sólo la doy en\ncasos de urgencia.",
  ["15:552e"] = "Lalala lalalala.\n¡Échale mucha\011agua, cariño!",
  ["27:60f9"] = "Tienes unos\nPOKéMON\011magníficos.\012¿Quieres una foto\nde recuerdo?",
  ["5d:47ac"] = "Seguro que te\nllamaré.",
  ["27:6142"] = "¡Vale! ¡Sonríe!",
  ["5d:47cc"] = "Mi marido obtuvo\nalgunas PEPITAS.\012Si quieres, puedes\nquedarte con una\011por ayudarme.\012Estaré en\n{STRBUF}.\012Por favor, ven a\nverme cuando\011puedas.",
  ["27:6156"] = "¡Oh! ¡Qué mal!\nPensaba que sería\012un maravilloso\nrecuerdo…",
  ["5d:485b"] = "¿Están tus POKéMON\nen forma?\012Hablemos de\nPOKéMON otra vez.",
  ["5d:6816"] = "¡Escucha, escucha!\012¡Qué maravilla de\n{STRBUF}!\012A mí también me\ngustaría serlo.",
  ["5d:4895"] = "¿Perdón?\nOh… ¿la PEPITA?\012No necesitas darte\nprisa. Ven a verme\012a {STRBUF}\ncuando puedas.",
  ["5d:686d"] = "¡Escucha, escucha!\012Uh… Mm… ¡Huy!\012¡Se me olvidó lo\nque iba a decir!",
  ["5d:48ea"] = "¡Eh, quiero luchar\ncontra ti!\012¡No será como la\núltima vez!\012Te esperaré en\n{STRBUF}.\012¡Ven aquí a toda\nprisa!",
  ["5d:68b0"] = "¡Escucha, escucha!\012Mi {STRBUF}…\nes… tan bonito…\012y… se ríe mucho…\nimpresionante… sí…\012mucho… ¡Aaaaah!\nY… cariñoso…\012Encantador…\n¡Oh, ya lo creo!\012Le abrazo…\ndurmiendo… Eso es…\012bonito… (suspiro)…\nguay… muy mono…\012¡Huy! ¡Mira qué\ntarde! ¡He hablado\011demasiado!\012¡Siento haberte\nhecho perder el\012tiempo! ¡Me\nencanta hablar!",
  ["5d:4962"] = "¡Nos vemos!",
  ["5d:69da"] = "¡Tengo mucho\ntiempo libre!\012¡Luchemos ahora\nmismo!\012¡Te esperaré en\n{STRBUF}!",
  ["5d:496b"] = "Tenemos que luchar\nen otra ocasión.\012Descuida, seguiré\nretándote hasta\011que te gane.",
  ["5d:6a2f"] = "El otro día, vi\ncomo mi {STRBUF}\011comía BAYAS.\012Parecía que estaba\ndisfrutando de su\012comida, así que\ndecidí probarlas.\012¡No estoy seguro\nde que la gente\012pueda comerlas,\npero estaban\011deliciosas!",
  ["5d:49c7"] = "¡Eh! ¡Será mejor\nque no te olvides\011del combate!\012¡{STRBUF}!\012¡Date prisa!\n¡Estoy esperando!",
  ["5d:6aef"] = "Últimamente, me he\ncruzado a menudo\012con {STRBUF}\nsalvajes.\012Es fácil\ncuidarlos.",
  ["5d:4a24"] = "Mi {STRBUF}\npuede ser mejor de\011lo que imaginaba.\012Dudo que vea a un\n{STRBUF} mejor\011que el mío.",
  ["5d:6b45"] = "Oh, sí. Estuve\nluchando contra\012este {STRBUF}\nel otro día…\012Se escapó cuando\nme distraje mi-\011rando a una BELLA\011chica que pasaba.\012Aprende de mi\nerror. ¡Siempre\012debes concentrarte\nen tu objetivo!",
  ["5d:4a80"] = "Oh, el otro día\nconseguí derrotar\012a duras penas a un\n{STRBUF}.\012Nunca había visto\na un {STRBUF}\011tan fuerte…\012No debes bajar la\nguardia, ni\012siquiera ante los\nPOKéMON que te\011sueles encontrar.",
  ["5d:6bee"] = "Venga.\n¡Luchemos!\012Estoy en\n{STRBUF}.\012¡Ven hasta aquí si\nte apetece!",
  ["5d:4b2d"] = "Hace un rato,\nintenté atrapar a\012un {STRBUF}\nsalvaje.\012Pero consiguió\neludirme.\012Una decisión\nequivocada puede\012hacer fracasar\ntodo…\012Tú también debes\ntener cuidado.",
  ["5d:6c47"] = "¡Entonces vale!\n¡Pórtate bien!",
  ["5d:4bc5"] = "¡Luchemos!\012Te esperaré en\n{STRBUF}.\012Llámame cuando\nestés cerca.",
  ["5d:6c61"] = "¡{PLAYER}!\n¡Es increíble!\012Fui a pasear a\n{STRBUF}\011ayer, ¿vale?\012¡Pues había muchos\n{STRBUF}\012por allí! ¡Tienes\nque verlo!\012Pensaba que los\n{STRBUF}\012eran tímidos.\nNo los había visto\012nunca donde hay\nPOKéMON fuertes.",
  ["5d:4c0e"] = "Vale, ¡hablaremos\nmuy pronto!",
  ["5d:6d32"] = "¿POKéMON raros?\012¡Lo siento! Estaba\ntan ensimismado en\012el paseo que no\nhe prestado aten-\011ción.",
  ["5d:4c29"] = "Me obsesiona la\nidea de vencerte.",
  ["5d:6d85"] = "¡Hola! No te\nhabrás olvidado de\012nuestro combate,\n¿verdad?\012¡{STRBUF}!\n¡Estoy esperando!",
  ["5d:4c49"] = "{PLAYER}, ¿por qué\nno estás aquí?\012¡Te haré polvo con\n{STRBUF}!",
  ["5d:6dd1"] = "¿Hola? ¿Qué?\n¿Que dónde hay\011DUNSPARCE?\012¡En CUEVA OSCURA!\n¡Deprisa!\012Sé que ya lo he\ndicho antes, pero\012DUNSPARCE no\naparece donde hay\011POKéMON fuertes.",
  ["5d:4c7f"] = "¿Recuerdas a mi\ndulce {STRBUF}?\012{STRBUF}\ncorre muy rápido.\012Montar sobre su\nespalda cuando se\012pone en marcha es\nmuy emocionante.",
  ["5d:6e5d"] = "Mi {STRBUF} se\nparece cada vez\012más a mí.\n¡Está muy bonito!",
  ["5d:4cf6"] = "Oh, ¿has visto a\nun {STRBUF}\011alguna vez?\012Acabo de luchar\ncontra uno…\012No pensaba que\nfuera tan veloz.\012Me sorprendió un\npoco.\012Aun así gané, por\nsupuesto.",
  ["5d:6e9c"] = "¿Sabes?\012Ahora podemos\nacabar fácilmente\011con los {STRBUF}.\012Debo visitar el\nGIMNASIO TRIGAL.",
  ["5d:4d86"] = "",
  ["5d:6eee"] = "¿Sabes?\nPor muy poco no\012conseguimos acabar\ncon {STRBUF}.\012Creo que el nivel\nde mis POKéMON aún\012no es lo suficien-\ntemente alto…",
  ["5d:4e4e"] = "¿Quieres luchar?\n¡Esta vez ganaré!\012Te estaré\nesperando por\012{STRBUF}.\nBúscame, ¿vale?",
  ["5d:6f60"] = "Ahora debes de ser\nmucho mejor…\012¿Por qué no me\nenseñas tus\012técnicas en un\ncombate real\011conmigo?\012Te esperaré en\n{STRBUF}.",
  ["5d:4eb7"] = "Bueno, ¡adiós!",
  ["5d:6fdb"] = "¡Hasta luego!",
  ["5d:6feb"] = "Eso es. ¡Justo lo\nque esperábamos!\012¡Las rebajas del\nCENTRO COMERCIAL\012de TRIGAL han\ncomenzado!\012¿Bueno? ¿Bonito,\nbarato?\012¡No pierdas esta\noportunidad!\012¿Parezco un vende-\ndor ambulante?\012Bueno, sí… Los\nestaba imitando…\012¡De todos modos,\ntienes que ir allí\012tan pronto como te\nsea posible!",
  ["27:6ebc"] = "Ahora el oponente\nn.º {STRBUF}. ¡Adelante!",
  ["5d:70fb"] = "Estoy ahorrando\npara las próximas\012rebajas. ¿Cuándo\nhabrá rebajas otra\011vez?",
  ["27:6f1f"] = "Antes de entrar en\nla SALA BATALLA,\012tu progreso será\nguardado.",
  ["5d:7138"] = "¿Dónde estás?\012¡Luchemos pronto!\012Te esperaré en\n{STRBUF}.",
  ["27:6f5e"] = "¿GUARDAR y acabar\nla sesión?",
  ["5d:717c"] = "¿Has ido al CENTRO\nCOMERCIAL de\012CIUDAD TRIGAL?\n¡Yo ya fui!\012Tiene muy buenas\ngangas.\012Debes ir allí\nrápidamente.",
  ["27:6fbf"] = "¿Cancelar la\nSALA BATALLA?",
  ["5d:71fd"] = "Mi {STRBUF} y\nyo estamos cada\012vez más\nsincronizados.",
  ["27:7037"] = "Te esperábamos.\nPor aquí llegarás\012a una SALA\nBATALLA.",
  ["5d:7237"] = "Luchamos con un\n{STRBUF} salvaje\012y conseguimos\natraparle.\012¡Ya le estamos\ncogiendo el truco!",
  ["27:7264"] = "Destruido por el\nprimer oponente en\012un instante…\nQué malo soy…",
  ["5d:7297"] = "¿Sabes?\012Todavía no he\ncogido {STRBUF}.\012Es un poco\nfrustrante…",
  ["27:72a4"] = "¡Hay muchas SALAS\nBATALLA, pero\012voy a superarlas\ntodas!",
  ["5d:72e2"] = "¿Practicarás\nconmigo en alguna\011ocasión?\012Te esperaré en\n{STRBUF}.\012…\n¿Te lo tomarás con\012tranquilidad esta\nvez?",
  ["27:72e3"] = "Es duro no poder\nusar objetos\012durante la\nbatalla.\012Hacer que tus\nPOKéMON lleven\012objetos es clave\npara vencer.",
  ["5d:7361"] = "¡Adiós! ¡Hablemos\nen otra ocasión!",
  ["27:735b"] = "Quiero ver hasta\ndónde puedo llegar\012usando sólo\nPOKéMON bicho.\012Espero que no haya\nPOKéMON de fuego…",
  ["5d:7378"] = "¿Sabes lo del\nTEAM ROCKET?\012Han tomado la\nTORRE RADIO de\011CIUDAD TRIGAL.\012¿Estarán bien los\nrehenes?",
  ["27:7716"] = "¿Vas a la TORRE\nBATALLA?\012Es un secreto,\npero si ganas\012muchas veces\npodrás conseguir\012regalos\nespeciales.",
  ["5d:73e7"] = "Hoy he cogido algo\nmuy bonito.\012¡Quiero que lo\ntengas, por eso te\011llamaba!\012Vendrás a por\nello, ¿verdad?\012Estoy en\n{STRBUF}.",
  ["27:77c8"] = "Los niveles de los\nPOKéMON que quiero\012usar son todos\ndiferentes.\012¡Tengo que\nentrenarlos ahora!",
  ["5d:7465"] = "Lo siento. Todavía\nno he encontrado\012nada útil…\n¡Si encuentro\012algo, será tuyo,\nprometido!",
  ["27:7930"] = "¡Guau, la TORRE\nBATALLA es enorme!\012¡Debe de haber\nmuchas clases de \011POKéMON dentro!",
  ["5d:74c1"] = "¡Oh, {PLAYER}!\n¿Cuándo vendrás a\011luchar conmigo?\012No te olvides…\n¡{STRBUF}!",
  ["27:79db"] = "Sólo puedes usar\ntres POKéMON.\012Es tan difícil\ndecidir qué tres\012deberían ir a la\nbatalla…",
  ["5d:750e"] = "¡Te espero\nimpaciente para\011darte mi regalo!\012¡Ve deprisa a\n{STRBUF}!",
  ["27:7a8c"] = "Je, je… Me escapé\ndel trabajo.\012¡No puedo achicar\nagua hasta que\011haya ganado!\012Tengo que ganarlo\ntodo. ¡Debo\011ganarlo!",
  ["60:4178"] = "En la LIGA\nPOKéMON, serás\012puesto a prueba\npor el ALTO MANDO.\012Deberás vencerlos\na todos. ¡Si\012pierdes, volverás\na empezar!",
  ["27:7afc"] = "TORRE BATALLA\012¡Acepta el desafío\ndefinitivo!",
  ["60:41f5"] = "Espera.\012¿Te vas a\nenfrentar ahora\012al desafío de la\nLIGA POKéMON?\012Pues yo no\nlo creo.\012Mis POKéMON\nestán muy bien\012entrenados y van a\nacabar contigo.\012¡{PLAYER}!\n¡Te desafío!",
  ["28:4c28"] = "Hola, soy BUENA…\012¡Oh! ¡Buenos días,\n{PLAYER}!\012Estoy un poco\napagada por la\011mañana…",
  ["60:4295"] = "…\012Vale. He perdido.",
  ["28:4c72"] = "Hola, soy BUENA…\n¡Hola, {PLAYER}!\012¿Sintonizas mi\nprograma?",
  ["60:42a4"] = "¡Maldición…!\nSigo sin ganar…\012Yo… Tengo que\npensar más en mis\011POKéMON…\012¡Umm! ¡Procura\nno perder!",
  ["28:4caf"] = "Soy BUENA.\nNo puedo coger el\012teléfono en estos\nmomentos.\012¡Si quieres hablar\nconmigo, sintoniza\012CÓDIGO DE BUENA en\nla radio y llámame\012después de\nmedianoche!",
  ["60:42fd"] = "…\012¡Uau…!\nCon ayuda de mis\012compañeros, ¡voy a\nser el CAMPEÓN!",
  ["28:4d42"] = "Hola, soy BUENA…\n¡Hola, {PLAYER}!\012Acabo de salir de\ntrabajar.\012Como te lo diría…\n¡Estoy exhausta!",
  ["60:4335"] = "¿Qué? ¿Vas a\ndesafiar al ALTO\012MANDO? ¿Seguro que\nestás preparado?\012Si necesitas\nentrenarte más, mi\012ABRA te puede\nayudar.\012ABRA te puede\nTELETRANSPORTAR.\012¿Te gustaría\nvolver a casa?",
  ["28:4d96"] = "¡{PLAYER}!\n¡Hola, soy BUENA!\012¡Me he levantado\ntemprano, así que\011pensé en llamarte!",
  ["60:43e7"] = "Vale. Concéntrate\nen la imagen\011de tu casa…",
  ["28:4dcf"] = "¡{PLAYER}!\n¡Hola, soy BUENA!\012¡Necesitaba hablar\ncon alguien!",
  ["60:4411"] = "Vale, vale. ¡Que\ntengas suerte!",
  ["28:4e01"] = "¡{PLAYER}!\n¡Hola, soy BUENA!\012Estaba en mi\ndescanso.",
  ["60:4433"] = "ABRA: Aabra…",
  ["28:4e29"] = "¡{PLAYER}!\n¡Hola, soy BUENA!\012No podía dormir,\npor eso te llamo.",
  ["60:4531"] = "Bienvenido a la\nLIGA POKéMON.\012Permíteme que me\npresente. Me llamo\011MENTO.\012Me he entrenado\npor todo el mundo\012para mejorar a mis\nPOKéMON psíquicos.\012Y, por fin, me han\naceptado en el\011ALTO MANDO.\012¡Sólo puedo seguir\nmejorando!\012¡Es imposible\nque pierda!",
  ["28:4e5e"] = "¡Hola, {PLAYER}!\012¿Cómo estás?\012¡Ayyyy! ¡No es el\nmomento de\012intentar hacer\nuna gracia!\012¡La TORRE RADIO\ntiene problemas!\012¡{PLAYER}, será\nmejor que tengas\011cuidado!",
  ["60:462c"] = "No… Esto es…\nincreíble…",
  ["28:4efb"] = "¡El otro día\nestuve comiendo\012con DJ NARDO!\n¿No es genial?\012No sólo eso…\n¡Dijo que la\012música de mi pro-\ngrama es guay!\012¡Oh, uau!\n¿Qué debo hacer?\012Ups… ¡Debo\nprepararme para\012mi programa!\n¡Luego te llamo!",
  ["60:4644"] = "Aunque haya\nperdido, no\012cambiaré mis\nplanes.\012¡Seguiré luchando\nhasta ser el mejor\012de todos los\nentrenadores!\012Y ahora {PLAYER},\nexperimenta toda\012la fuerza del\nALTO MANDO.",
  ["28:4fcf"] = "¿Conoces a la\nrecepcionista de\011la TORRE RADIO?\012Siempre dice lo\nmismo.\012Pero sin embargo\nes la persona más\012habladora de la\nTORRE RADIO.\012Debe de estar\nconteniéndose.\012¿No es divertido?\012¡Luego te llamo!",
  ["60:4793"] = "¡Ja, ja, ja!\012Soy KOGA, del ALTO\nMANDO. Vivo en las\012sombras, como un\nninja.\012¡Te confundiré y\nte destruiré con\011mi estilo!\012Confusión, sueño,\nveneno…\012¡Prepárate para\nser víctima de\011mis técnicas!\012¡Ja, ja, ja!\012Los POKéMON no\nutilizan sólo\012la fuerza bruta.\n¡Ya lo verás!",
  ["28:509d"] = "Dime, {PLAYER}.\n¿Has ganado alguna\012vez el premio del\nCONCURSO DEL\012NÚMERO DE LA\nSUERTE?\012SALVA se queja de\nque nunca ha ga-\011nado, pero piensa\011el programa hasta\011lograrlo.\012¡Hablemos luego!",
  ["60:48a9"] = "¡Ah! ¡Has\ndemostrado\011tu valor!",
  ["28:5143"] = "Ya sabes, la noche\npasada…\012¡Estaba tan harta\ndel trabajo, que\012me comí una\ntonelada de comida\011basura!\012ROSA y yo hemos\ndecidido perder\011peso…\012Pero así no lo\nconseguiré…\012¿Eh? ¿Que cuánto\npesa?\012¡Eso es un\nsecreto!\012ROSA pesa…\012¡Ayyyy! ¡ROSA!\012Uh… Mm… Eh…\n¡Lo siento, se ha\012equivocado de\nnúmero!",
  ["60:48ca"] = "He probado\ncontigo todo\011lo que sé.\012Pero he fallado.\nDebería\011entrenarme más.\012¡Entra en la\nsala siguiente,\012y demuestra tus\nhabilidades!",
  ["5d:59f7"] = "El Concurso de\nCaptura de Bichos\012se celebra hoy en\nel PARQ. NACIONAL.\012¿Vas a ir,\n{PLAYER}?\012Estoy intentando\nprepararme.",
  ["60:49fe"] = "Soy BRUNO, del\nALTO MANDO.\012Entreno siempre al\nmáximo porque\012confío en nuestro\npotencial.\012Por eso somos\ntan fuertes.\012¿Resistirás\nnuestro poder?\012¿Mmm? No veo que\ntengas miedo.\012Pareces decidido.\n¡Perfecto!\012¿Listo, {PLAYER}?\n¡Te doblegarás\012ante nuestro\ninmenso poder!\012¡Ja, ja!",
  ["5d:5a60"] = "Encontré todo tipo\nde BAYAS.\012Si quieres, puedo\ncompartirlas\011contigo.\012Te esperaré en\n{STRBUF}.",
  ["60:4b23"] = "¿Qué? ¿Cómo hemos\npodido perder?",
  ["5d:5abe"] = "¿Eh? ¿BAYAS?\012Lo siento, aún no\nhe encontrado\011ninguna.\012Te llamaré si\nencuentro alguna.\012¿Puedes esperar,\npor favor?",
  ["60:4b3c"] = "Como he perdido,\nno tengo derecho\011a decir nada…\012¡Enfréntate al\nsiguiente desafío!",
  ["5d:5b1e"] = "¡Vamos a luchar\nya mismo!\012Estoy en\n{STRBUF}.\012¡Por favor, ven\ntan rápido como\011puedas!",
  ["60:4c27"] = "Soy KAREN, del\nALTO MANDO.\012¿Eres {PLAYER}?\n¡Qué gracia!\012Me gustan los\nPOKéMON de tipo\011siniestro.\012Su naturaleza tan\nfuerte y salvaje\012me parece muy\natractiva.\012¿Crees que podrás\ndetenerlos? ¡A ver\011que tal lo haces!\012¡Vamos allá!",
  ["5d:5b6d"] = "¿Cómo es que no\nhas llegado aún?\012Estoy en\n{STRBUF}.\012¡Por favor, ven\ntan rápido como\011puedas!",
  ["60:4cf8"] = "Eres bueno…\nMe gusta eso\011en un entrenador.",
  ["5d:5bc4"] = "He estado pasando\nmás tiempo con mi\012{STRBUF} que\ncon mis niños.\012En realidad es un\npoco triste.",
  ["60:4d29"] = "POKéMON fuertes.\012POKéMON débiles.\012Ésa es la visión\negoísta que tiene\011todo el mundo.\012Si un entrenador\nes bueno, debería\012ser capaz de ganar\ncon sus favoritos.\012Me gusta tu\nestilo. Sabes\011lo que importa.\012Adelante. El\nCAMPEÓN te espera.",
  ["5d:5c24"] = "Acabo de derrotar\na un {STRBUF}\011salvaje.\012Se lo he dicho a\nmi niño, pero se\012burló de mí\ndiciendo que él\012hubiera hecho lo\nmismo, pero más\011fácilmente.\012Se ha vuelto un\npoco gallito…",
  ["60:4f67"] = "LANCE: Te estaba\nesperando.\012¡{PLAYER}!\012Sabía que con tus\nhabilidades serías\012capaz de llegar\nhasta mí.\012No es necesario\ndecir nada más.\012Lucharemos para\nsaber quién es el\012más fuerte de\nlos dos.\012Como entrenador\nmás poderoso y\012CAMPEÓN de la LIGA\nPOKéMON…\012¡Yo, LANCE, el\nmaestro de los\012dragones, acepto\ntu desafío!",
  ["5d:5c9f"] = "",
  ["60:50a4"] = "Se acabó…\012Pero es\nextraño.\012No estoy enfadado\npor perder. De\012hecho, estoy\ncontento.\012Estoy contento por\nhaber presenciado\012el nacimiento de\nun nuevo CAMPEÓN.",
  ["5d:5d40"] = "¿Qué te parece\nluchar conmigo?\012¡Bien, vas a\nhacerlo!\012Para ser tan\njoven, eres bas-\011tante agradable.\012¡{STRBUF}\nes el lugar!",
  ["60:5132"] = "¡Uauu…!\012Te has vuelto muy\npoderoso,\011{PLAYER}.\012Tus POKéMON han\nrespondido bien a\012tu fuerza y\ndecisión.\012Como entrenador,\nseguirás creciendo\012fuerte con\ntus POKéMON.",
  ["5d:5db7"] = "¡Tú también llamas\na veces a tu mamá!",
  ["60:51dd"] = "ROSA: ¡Oh, no!\n¡Todo ha acabado!\012PROF. OAK, si no\nfuera tan lento.",
  ["5d:5dd9"] = "Escucha, yo… ¡Huy!\012¡Perdona! ¡Mira,\nlos {STRBUF}\012están picando como\nnunca aquí, en\011{STRBUF}!\012¡Ayyyy! ¡Huy!\n¡Me ha picado uno!\012Eh, ¡son un pelín\nagresivos!\012¡{PLAYER}, tienes\nque ver esta\012extraña vista!\n¡A pescar!",
  ["60:521b"] = "PROF. OAK: ¡Ah,\n{PLAYER}!\012Ha pasado mucho\ntiempo.\012Cada día eres más\nimpresionante.\012¡Tu conquista de\nla LIGA ha sido\011fantástica!\012Tu dedicación,\nconfianza y amor\012por tus POKéMON lo\nhan conseguido.\012Tus POKéMON\ntambién han estado\011increíbles.\012Han perseverado\nporque han creído\012en ti y en tu\nentrenamiento.\012¡Felicidades,\n{PLAYER}!",
  ["5d:5eaf"] = "Sí, ya sé.\012Estás buscando\nPOKéMON raros.\012Pero hasta ahora\nsólo he podido\011atrapar MAGIKARP…",
  ["60:534b"] = "ROSA: ¡Vamos a\nentrevistar al\011nuevo CAMPEÓN!",
  ["5d:5f11"] = "¿Dónde estás?\nEstoy esperando a\012que aparezcas por\n{STRBUF}.\012¡Deberías respetar\nmás a tus mayores!",
  ["60:537b"] = "LANCE: Aquí va a\nempezar a haber\011mucho ruido…\012{PLAYER}, ¿puedes\nvenir conmigo?",
  ["5d:5f70"] = "Eh, ¿qué te pasa?\012¿No vienes para\npescar a QWILFISH?\012Estoy en la RUTA\n32, ¡date prisa!",
  ["60:53c5"] = "ROSA: ¡Espera!\n¡No hemos hecho\011la entrevista!",
  ["5d:5fda"] = "Oh, tienes que oír\nesto.\012¡Mi {STRBUF}\nes tan encantador!\012¡Siempre está\npegado a mí!",
  ["60:54a6"] = "LANCE: Ha pasado\nmucho tiempo desde\012la última vez que\nvine aquí.\012Aquí es donde\nhonramos a los\012CAMPEONES de la\nLIGA por toda la\011eternidad.\012Y a sus valerosos\nPOKéMON también.\012Hoy, hemos sido\ntestigos de la\012aparición de un\nnuevo CAMPEÓN de\012la LIGA, alguien\nque ha creído y\012ha sabido confiar\nen sus POKéMON.\012Alguien que ha\nlogrado el éxito\012gracias a la\nperseverancia y la\011determinación.\012¡Un nuevo triunfo\nen la LIGA,\012conseguido con\ngrandeza!\012¡{PLAYER}, permite\nque te registre\012a ti y a tus\ncompañeros como\011CAMPEONES!",
  ["5d:602d"] = "¡Y, y…! Mmm…\012Derrotamos a un\n{STRBUF} salvaje\012con un único golpe\nhace un rato.\012Pero no nos alegra\ndemasiado…",
  ["61:40bc"] = "¿La CENTRAL\nENERGÍA de KANTO?\012Está al final de\nla RUTA 9, el\012camino que hay\nal este de aquí.\012Creo que hubo\nalgún tipo de\011accidente allí.",
  ["5d:6095"] = "¡Y, y…! Uh…\012Acabamos de ver a\nun {STRBUF}\011realmente hermoso.\012Pero estaba ha-\nblando por teléfo-\011no y se escapó.\011¡Estamos furiosos!",
  ["61:4144"] = "¿Vas a atrapar\ntodos los tipos\011de POKéMON?\012Parece un gran\ndesafío, pero\011será divertido.",
  ["5d:610a"] = "¡Hola! ¿Tienes un\nmomento?\012Tengo todo el\ntiempo del mundo.\012Si estás libre,\n¿querrás luchar?\012Te espero en\n{STRBUF}.\012¡Avísame cuando\nllegues!",
  ["61:41a8"] = "El CABO Norte es\nideal para llevar\012a una chica.\n¡Les encanta!",
  ["5d:61a7"] = "Hola, TANIA. ¿Qué\ntal? Soy LISI.\012Estoy bien, ¡pero\nme aburro mucho!\012¡Uy!… ¿Me he con-\nfundido? ¡Perdón!",
  ["61:41e9"] = "SLOWBRO: ¿Slow?",
  ["5d:620a"] = "¡Vale! ¡Te llamaré\nmás tarde!",
  ["61:41fa"] = "¡Mi SLOWBRO y yo\nformamos un equipo\011impresionante!",
  ["5d:6223"] = "¡Escucha, escucha!\012Estaba oyendo\nla radio en las\012RUINAS ALFA cuando\nuna extraña\012emisión cortó el\nprograma.\012Me gustaría saber\nqué era.\011¡Qué extraño!",
  ["61:4229"] = "¡SLOWBRO, enséñame\ntu CONFUSIÓN!",
  ["5d:62c3"] = "¡Escucha, escucha!\012¿No crees que\nPEGASO del GIM.\012MALVA es guapo y\nsimpático?\012Pues dicen que su\npadre, que está\012fuera entrenándo-\nse, es mucho más\012guapo y simpático\nque PEGASO.\012¡Ojalá pudiera\nconocerle!",
  ["61:424b"] = "…",
  ["61:424e"] = "Soy un gran\nseguidor de\012la LÍDER MISTY\nde CIUDAD CELESTE.",
  ["67:68fe"] = "RUTA 45\nCAMINO MONTAÑA",
  ["61:4275"] = "Vi a ese tipo\nsospechoso de\012camino al CABO de\nCIUDAD CELESTE.",
  ["67:6a7b"] = "¿Has nadado alguna\nvez en el mar por\011la noche?",
  ["61:42a9"] = "Antes había una\ncueva aquí que\012tenía POKéMON\nrealmente fuertes.",
  ["67:6aad"] = "¡Glup…!",
  ["61:42ee"] = "¡Caray!\012Mi BUSCAOBJETOS\nresponde…",
  ["67:6ab4"] = "De noche, el mar\nestá oscuro. Da la\012impresión de que\nte va a tragar.",
  ["61:4312"] = "CIUDAD CELESTE\012Una misteriosa\naura azulada la\011rodea",
  ["67:6afa"] = "(Resoplido)…\nUn… poco más…\012y… llegaré…\na CIUDAD FUCSIA…",
  ["61:4345"] = "LÍDER DEL GIMNASIO\nPOKéMON DE LA\012CIUDAD CELESTE:\nMISTY\012La Sirena\nDistorsionada",
  ["67:6b2d"] = "¡Me ahogo!",
  ["61:4381"] = "Aquí hay una\nnota…\012La TIENDA DE BICIS\nse ha trasladado a\012CIUDAD TRIGAL, en\nJOHTO…",
  ["67:6b3b"] = "Le… pedí a mi\nnovia que nadara\011a CIUDAD FUCSIA…",
  ["61:43cc"] = "Aquí hay una\nnota…\012¡Acaba con los\nladrones y haz que\012la ciudad sea más\ngrata y alegre!\012POLICÍA C. CELESTE",
  ["67:6b6f"] = "¡No me gustan los\ncanijos!",
  ["61:443b"] = "Hacia el\nCABO CELESTE",
  ["67:6b8e"] = "Podría ganarte\nnadando…",
  ["61:4450"] = "Está cerrada…",
  ["61:4523"] = "Montamos guardia\nen esta torre.\012Así expresamos\nnuestra gratitud a\011todos los POKéMON.",
  ["1d:53c0"] = "Los pasajeros son\nentrenadores.\012Están deseando\nluchar en sus\011camarotes.",
  ["61:4574"] = "¡Gra-Gracias!",
  ["1d:534f"] = "Es tu camarote.\012Puedes curar a tus\nPOKéMON durmiendo\011una siesta.\012El barco llegará\na su destino\011mientras duermes.",
  ["61:4583"] = "Todos los seres\nvivos coexisten\011en cooperación.\012Deberíamos\nestar agradecidos.",
  ["1d:52f9"] = "Éste es tu\ncamarote.\012Si están heridos\ntus POKéMON,\012échate una\nsiestecita.\012Eso los curará.",
  ["61:45d8"] = "Sólo obtendrás\nuna MO si llegas\011arriba.",
  ["1d:523b"] = "El FERRY S.S. AQUA\nse dirige a\011CIUDAD CARMÍN.\012Daremos un\naviso cuando\011lleguemos.",
  ["61:460a"] = "La TORRE\nBELLSPROUT fue\012construida para\nentrenar POKéMON.",
  ["1d:5080"] = "El FERRY zarpará\nel domingo.",
  ["61:4649"] = "Un BELLSPROUT de\n30 m de altura.\012Dice la gente que\nse convirtió en la\011columna central.",
  ["1d:4fc2"] = "{PLAYER} enseña\nel TICKET BARCO.\012Muy bien.\n¡Gracias, joven!",
  ["61:469d"] = "¿Ves cómo se\nmueve la columna?\012Arriba hay gente\nentrenando.",
  ["1b:706f"] = "¡Es el POKéMON\nperdido!",
  ["61:46d6"] = "Estatua POKéMON…\012Parece muy\nilustre.",
  ["1b:7019"] = "¡Uauu! ¡Muchísimas\ngracias!\012El POKéMON de\nmi jefe no me\012obedecía porque\nno tengo MEDALLAS.",
  ["61:47a9"] = "Por mucho que\nluchemos, la TORRE\011seguirá en pie.",
  ["1b:69a3"] = "La puerta está\ncerrada…\012{PLAYER} introdujo\ndos contraseñas.\012¡Puerta abierta!",
  ["61:47df"] = "Luché con fuerza\npero estoy débil.",
  ["1b:68ac"] = "Me da igual que\nlos POKéMON sufran\012debido a nuestros\nexperimentos.",
  ["61:47ff"] = "La columna\nflexible protege\012la TORRE hasta\nde los terremotos.",
  ["1b:6737"] = "¡Ji, Ji, Ji!\012La contraseña\nde la oficina del\011jefe es…\012¡Eh…! Creo que\nes COLARATICATE.",
  ["61:4841"] = "Se mueve como las\nhojas al viento…",
  ["1b:65af"] = "¿Conozco yo la\ncontraseña?\012A lo mejor.\012¡Pero no será de\nningún debilucho!",
  ["61:4861"] = "¡Oh, estoy débil!",
  ["1b:5cd1"] = "¡Oye! Sólo el jefe\nconoce la clave\011de esa puerta.\012¿Dónde está el\njefe? ¡Quién sabe!\011Encuéntralo tú.",
  ["61:486f"] = "Quería imitar los\nsuaves movimientos\012de BELLSPROUT\npara pelear…\012Pero no me\nentrené bastante.",
  ["15:600d"] = "¡Curamos a\ntus POKéMON!\012P3 BOTIQUÍN",
  ["61:48c8"] = "Estatua POKéMON…\012Parece muy\nilustre.",
  ["61:4a27"] = "ANCIANO: Eres\nun entrenador\011muy hábil.\012Como te prometí,\naquí tienes tu MO.\012Pero déjame que te\ndiga que deberías\012tratar mejor a\ntus POKéMON.\012Luchas de forma\nmuy violenta.\012Los POKéMON no son\narmas de guerra.",
  ["1d:56d5"] = "¿En qué somos\ntan diferentes?",
  ["61:4aec"] = "…\n¡Bah!\012Afirma ser el\nANCIANO, pero\011es muy débil.\012Es evidente.\012Jamás perdería\nante quienes dicen\012que hay que ser\nbuenos con\011los POKéMON.\012Sólo me interesan\nlos POKéMON\011ganadores.\012Paso de los\nPOKéMON\011débiles.",
  ["1e:628a"] = "{PLAYER} abrió\nun libro.\012Pista de viaje 2:\012¡Graba tu viaje\ncon GUARDAR!",
  ["61:4bc8"] = "¡{RIVAL}\nusó\011CUERDA HUIDA!",
  ["1e:61c0"] = "¡Bien! Así que su\nnombre es {RIVAL}.\012¡Gracias por tu\ncolaboración!",
  ["61:4be0"] = "¡Encantado de\nverte por aquí!\012TORRE BELLSPROUT\nes un lugar de\011entrenamiento.\012La gente y los\nPOKéMON evalúan\012sus vínculos para\nconstruir juntos\011un futuro mejor.\012Yo soy la prueba\nfinal.\012¡Déjame evaluar\ntus vínculos con\011los POKéMON!",
  ["1e:5f95"] = "Oimos un ruido\nmuy fuerte…\012Y cuando salimos\na mirar, alguien\012nos robó un\nPOKéMON.\012¡Es horrible\nque alguien\011hiciera eso!\012(Suspiro…) El\nPOKéMON robado.\012Me pregunto cómo\nestará.\012Dicen que los\nPOKéMON educados\012por malas personas\nse vuelven malos.",
  ["61:4cb2"] = "¡Ah, excelente!",
  ["1e:5df3"] = "ELM: ¡{PLAYER}!\n¿Qué tal?\012Te he llamado\nporque tengo\011algo para ti.\012Es un TICKET\nde BARCO.\012Ahora podrás\natrapar POKéMON\011en KANTO.",
  ["61:4cc2"] = "Tú y tus POKéMON\nno deberíais tener\012problemas con\neste movimiento.\012Toma esta MO.\nEs DESTELLO.",
  ["1e:5a9f"] = "¡El HUEVO se\nabrió! Los POKéMON\011deben nacer así.\012Quizá no todos\nlos POKéMON.\012¡Uauu! Aún nos\nqueda mucho por\011aprender.",
  ["61:4d13"] = "DESTELLO ilumina\nhasta el lugar\011más oscuro.\012Y con la MEDALLA\nde CIUDAD MALVA,\012podrás usarlo\nfuera del combate.",
  ["1e:5780"] = "ELM: ¿¡Qué!?\012¿El PROF. OAK te\ndio una POKéDEX?\012{PLAYER}, ¿es eso\ncierto? ¡Mm…,\011increíble!\012OAK no suele\nequivocarse al\012juzgar a un\nentrenador.\012¡Oh, {PLAYER}!\nPuede que tengas\012lo necesario para\nser un CAMPEÓN.\012Además, pareces\nllevarte bien con\011los POKéMON.\012Deberías aceptar\nel desafío de un\011GIMNASIO POKéMON.\012El GIMNASIO más\ncercano es el de\011CIUDAD MALVA.",
  ["61:4d88"] = "¡Ojalá aprendas y\nmadures con\011tu viaje!",
  ["1e:560d"] = "El SR. POKéMON\nbusca las rarezas\011en todas partes.\012Lo malo es que,\nademás de ser\012raras, no son muy\nútiles…",
  ["61:4db6"] = "¡Entreno para\nsaberlo todo\011sobre los POKéMON!",
  ["1e:541f"] = "ELM: ¿Quieres a\nCHIKORITA, el\011POKéMON planta?",
  ["61:4dde"] = "Mi entrenamiento\nes incompleto…",
  ["1d:5b52"] = "El fuego es débil\ncontra el agua.\012No te importa,\n¿verdad?",
  ["61:4dfa"] = "Cuanto más fuerte\nsea el POKéMON,\012más fuerte será\nsu entrenador.\012No, espera. Cuanto\nmás fuerte sea el\012entrenador, más\nfuerte el POKéMON.",
  ["1d:5980"] = "¡Qué mala suerte!\n¡He perdido!",
  ["61:4e60"] = "A ver cuánto\nconfías en tus\011POKéMON.",
  ["1d:58f1"] = "¡Oh, no! He\nperdido algo\011muy importante.",
  ["61:4e8a"] = "¡Sí, tu confianza\nes auténtica!",
  ["1b:4bbb"] = "Esto era una\nguarida ninja.\012Hay trampas para\nconfundir a los\011intrusos como tú.",
  ["61:4ea4"] = "No estás lejos\ndel ANCIANO.",
  ["1b:4b12"] = "¡Cuidado!\n¡Un intruso!",
  ["61:4ec1"] = "La MO del ANCIANO\nalumbra hasta\011lo más oscuro.",
  ["1b:459e"] = "Las escaleras\nestán justo aquí.",
  ["1b:4549"] = "¿Por qué tardaste\ntanto, {PLAYER}?\012Como pensaba,\nesa extraña señal\012de radio viene\nde aquí.",
  ["1b:452a"] = "LANCE: DRAGONITE,\nHÍPER RAYO.",
  ["1b:4501"] = "¡Urrg…!\012Los POKéMON dragón\nde ese chico\011son muy fuertes…",
  ["26:5688"] = "Cada mes pongo\nuna flor nueva\011en mi pasador.",
  ["26:575c"] = "¿Te gusta como\nbailo? Y también\012soy hábil con\nlos POKéMON.",
  ["26:5891"] = "¡Chico! Si vences\na todas las CHICAS\012KIMONO, te daré\nun regalo.",
  ["26:59d5"] = "Ojalá mis POKéMON\nfueran tan\012elegantes como las\nCHICAS KIMONO…",
  ["26:5b79"] = "Es un elegante\npanel decorado\011con flores.",
  ["26:5c48"] = "Mi EEVEE\nevolucionó en\011ESPEON.\012Pero el EEVEE\nde mi amigo\012evolucionó en\nUMBREON.\012No sé por qué. Los\ndos educamos a\012nuestros EEVEE de\nla misma forma…",
  ["26:600a"] = "Aún no soy lo\nbastante bueno…\012De acuerdo. Esta\nMEDALLA es tuya.",
  ["26:6043"] = "{PLAYER}\nrecibió la\011MEDALLA NIEBLA.",
  ["26:6059"] = "Con la MEDALLA\nNIEBLA, te\012obedecerán todos\nlos POKéMON\011hasta el nivel 50.\012Y los POKéMON\nque sepan SURF\012podrán usarlo en\ncualquier momento.\012Quédate con\nesto también.",
  ["26:60ec"] = "Es BOLA SOMBRA.\nCausa daños y\012puede reducir la\nDEFENSA ESPECIAL.\012Úsala si te\ngusta.",
  ["26:6145"] = "Entiendo…\012Tu viaje te\nha llevado a\011tierras lejanas.\012Y has presenciado\nmuchas más cosas\011que yo.\012¡Cómo te\nenvidio…!",
  ["26:61bd"] = "Pasé la primavera\ncon mis POKéMON.\012Y el verano, otoño\ne invierno.\012Luego volvió la\nprimavera. Hemos\012vivido juntos\nmucho tiempo.",
  ["26:623d"] = "Viví victorias\ny derrotas.",
  ["26:6263"] = "¿De dónde vienen\nlos POKéMON?",
  ["26:62a7"] = "¡Ah! ¡Bien hecho!",
  ["26:62b7"] = "Sólo usamos\nPOKéMON fantasma.\012¡Los ataques\nnormales no les\011hacen daño!",
  ["26:62fb"] = "¡Ganaré!",
  ["26:6318"] = "¡Ganará el que\nmás lo desee!",
  ["26:637f"] = "¿Có-Cómo?",
  ["26:63e8"] = "Estos entrenadores\ntienen motivos\011secretos.\012Si les ganas,\npodrían contarte\012algunos secretos\nsobre CIUDAD IRIS.",
  ["26:649c"] = "MORTI, el LÍDER de\nGIMNASIO, no está.\012Lo siento, pero\ntendrás que irte.\012Jo, jo, jo, jo.",
  ["26:66b5"] = "¡Bien! Entiendes\nel verdadero\012espíritu de\nla aventura.\012¡Me gusta!\nToma esto.",
  ["26:6805"] = "¡Oh! A cada uno lo\nsuyo, supongo…",
  ["1b:5cc9"] = "¡Grrrr…!",
  ["26:6826"] = "HISTORIA de\nCIUDAD IRIS\012¿Quieres leerla?",
  ["1c:6f91"] = "¡Vamos a proteger\na ERIKA!",
  ["26:684c"] = "En CIUDAD IRIS\nhabía dos torres.\012Cada una acogía a\nun fuerte POKéMON\011volador.\012Pero una de\nellas se quemó.\012Y desde entonces\nno se ha visto a\012ninguno de los\ndos POKéMON.\012¿Seguir leyendo?",
  ["1c:6f70"] = "¡ERIKA te lo\nhará pagar!",
  ["26:6902"] = "En CIUDAD IRIS\ntambién vivían\012tres POKéMON\nque corrían por\011toda la ciudad.\012Dicen que habían\nnacido del agua,\012del fuego y del\nrayo.\012Pero como no\npodían contener su\011enorme fuerza…\012Huyeron hacia\nlos pastos.",
  ["1c:6f62"] = "Hemos perdido…",
  ["26:6a7b"] = "AZUL: ¡Hola! Al\nfin llegaste, ¿eh?\012En ISLA CANELA no\nestaba a punto,\012pero ahora estoy\nlisto para luchar.\012…\012¿Me estás contando\nque superaste los\012GIMNASIOS de\nJOHTO?\012¡Vaya! Pues los\nGIMNASIOS de JOHTO\012deben de ser\npatéticos.\012Pero bueno, no te\npreocupes.\012Sabremos si vales\no no en un\012momento. Luchemos\nahora.\012¿Vale?",
  ["1c:6f32"] = "¡Te enseñaremos\nlos movimientos\012POKéMON que nos\nenseñó ERIKA!",
  ["26:6bae"] = "AZUL: ¿Qué?\012¿Cómo diablos he\nperdido?\012…\012¡Está bien…!\nToma, aquí tienes\011la MEDALLA TIERRA.",
  ["1c:6f01"] = "¿Cómo voy a hacer\npara llegar a ser\012tan elegante\ncomo ERIKA?",
  ["26:6c0f"] = "{PLAYER} recibió\nla MEDALLA TIERRA.",
  ["1c:6ef2"] = "¡Qué rabia!",
  ["26:6c27"] = "AZUL: …\012De acuerdo, me he\nequivocado. Tenías\012razón. Eres un\nbuen entrenador.\012Pero algún día\nte derrotaré.\012¡No lo\nolvides!",
  ["1c:6ec5"] = "¿Estabas mirando\nestas flores o\011a mí?",
  ["26:6cab"] = "AZUL: Escucha.\012Será mejor que no\npierdas hasta que\012yo te derrote.\n¿Entendido?",
  ["1c:6e8e"] = "¡Uauu! ¡Tienes\nmuchas MEDALLAS!\012¡No me extraña\nhaber perdido!",
  ["26:6cee"] = "¡Hola, futuro\nCAMPEÓN! ¿Qué\012tal te va?\nParece que estás\011de suerte.\012El LÍDER DEL\nGIMNASIO luchó\012contra el CAMPEÓN\nhace 3 años.\012¡Es un tipo duro!\012¡Debes esforzarte\nal máximo!",
  ["1c:6e7f"] = "¡Oh! ¿Se acabó?",
  ["26:6da0"] = "Tío, eres\nrealmente duro…\012¡Qué batalla más\nemocionante!\012Me ha hecho\nllorar.",
  ["1c:6e53"] = "¡Oh! ¿Un combate?\nMe da un poco de\011miedo, pero bueno.",
  ["26:6e54"] = "¿Dedicas mucho\ntiempo a pensar\012en nombres para\ntus POKéMON?\012Es más divertido\nintercambiarlos\012si les pones\nbuenos motes.",
  ["1c:6e30"] = "Tenía que haber\nestado más atenta.",
  ["26:6ecb"] = "Son SPEARY, un\nSPEAROW, y RATTEY,\011un RATTATA.",
  ["1c:6e24"] = "¡Oh, maldición!",
  ["26:6f7f"] = "Bienvenido a la\nCASA DEL\012ENTRENADOR, el\nlugar más popular\011de CIUDAD VERDE.\012Es sólo para\nentrenadores.\012Puedes luchar\ncontra los mejores\012entrenadores en el\npiso de abajo.",
  ["1c:6dfc"] = "¿Te parece raro un\nGIMNASIO exclusivo\011para chicas?",
  ["26:7025"] = "La CIUDAD VERDE\nes la más cercana\011a la MESETA AÑIL.\012Construyeron este\nlugar debido al\012gran número de\nentrenadores que\012pasaban de camino\na la MESETA AÑIL.",
  ["1c:6d8f"] = "ERIKA: La derrota\ndeja mal sabor\011de boca…\012Pero saber que\nhay entrenadores\012más fuertes me\nanima a mejorar…",
  ["26:70b5"] = "Aquí abajo tienen\nlugar combates\011de entrenamiento.\012Me encantaría ver\nlo bien que lucha\012un entrenador de\nJOHTO.",
  ["1c:6cb0"] = "ERIKA: Ha sido un\ncombate genial.\012Me has inspirado.\nAcepta esta MT\011como regalo.\012Es GIGA-DRENADO.\012Es un fantástico\nataque que drena\012la mitad del daño\nproducido para\011curar al POKéMON.\012Úsalo si\nquieres…",
  ["26:711d"] = "Creo que no puedes\nser el CAMPEÓN\012si no luchas\ncon toda la gente\012que te encuentres\npor ahí.\012El CAMPEÓN de\nPALETA viajó por\012las ciudades y\npueblos de KANTO.",
  ["1c:6c96"] = "{PLAYER} recibió\nMEDALLA ARCOIRIS.",
  ["26:71c9"] = "¡Ah…! Estoy\ndescansando de los\011combates POKéMON.",
  ["1c:6c3e"] = "ERIKA: ¡Oh! Admito\nque he perdido…\012Eres realmente\nbueno…\012Te daré la MEDALLA\nARCOIRIS…",
  ["26:71f4"] = "Los combates de\nentrenamiento se\012celebran en HALL\nDE ENTRENAMIENTO.\012Los entrenadores\nmás hábiles están\011invitados.",
  ["1c:6b28"] = "ERIKA: Hola…\nBonito día,\012¿verdad? Se está\ntan bien…\012Podría hasta\ndormirme…\012Me llamo ERIKA.\nSoy la LÍDER\012del GIMNASIO de\nCIUDAD AZULONA.\012¿Cómo? ¿Vienes\nde JOHTO?\011¡Qué bien…!\012¡Oh! Lo siento,\nno me di cuenta\012de que querías\ndesafiarme.\012Muy bien, pero\nno perderé.",
  ["1b:53bd"] = "¿Qué? ¿Tenías un\ncómplice? ¿Dónde\012está tu sentido\ndel honor?\012Como sustituto\nprovisional\012de GIOVANNI, ¡ya\nte enseñaré yo a\012no meterte con\nel TEAM ROCKET!",
  ["1b:538c"] = "¡Oye! No seas tan\negoísta. Comparte\011la diversión.",
  ["1b:52c3"] = "No podemos dejar\nque un mocoso como\011tú nos toree.\012Es malo para el\norgullo del TEAM\011ROCKET.\012Por muy fuerte que\nseas, no podrás\012derrotarnos al\nmismo tiempo.\012Lo siento, chico.\n¡Prepárate para\011ser aniquilado!",
  ["1b:52ad"] = "¡Alto ahí!",
  ["26:725d"] = "No existen reglas\nsobre los combates\012de prueba. Al\nigual que en los\012combates reales,\naquí vale todo.",
  ["1b:4dd0"] = "El interruptor\nestá apagado.",
  ["1b:4dad"] = "¡Un botón secreto!\nMejor pulsarlo.",
  ["1b:4d7c"] = "Es una estatua de\nPERSIAN…\012Sus ojos tienen un\nbrillo extraño.",
  ["1b:4d1b"] = "Yo ni siquiera sé\ndónde están las\011trampas.\012Tendrás que\nser valiente\011y caminar.",
  ["1b:4d12"] = "¡Kabum!",
  ["1b:4cb7"] = "¡Je, je! ¿Te crees\nafortunado?\012Adelante, da\notro paso.\012¡El suelo está\nlleno de trampas!",
  ["1c:6521"] = "¡Eh!\012Debajo de este\npóster…\012¡No hay nada!",
  ["26:72c1"] = "¿Qué es esto?\n¿Una estrategia?\012Esta letra se\nparece a las\012huellas de ONIX…\n¡Es ilegible…!",
  ["1c:64f3"] = "¡Eh!\012Debajo de este\npóster…\012¡No hay nada!",
  ["26:7420"] = "Bienvenido al HALL\nDE ENTRENAMIENTO.\012Puedes luchar\ncon un entrenador\011cada día.",
  ["1c:64ad"] = "¡Mmm…! Los impares\nson mejores para\012la línea PIKACHU.\n¿Qué hago?",
  ["26:746a"] = "{STRBUF}\nserá hoy tu rival.",
  ["1c:6425"] = "¡Eh! ¡Futuro\nCAMPEÓN!\012¿Tú también juegas\na las tragaperras?\012Quiero conseguir\nbastantes fichas\011para un POKéMON.\012Pero aún no tengo\nbastantes…",
  ["26:7487"] = "¿Quieres\nluchar?",
  ["1c:63d9"] = "¡Eh! Tu MONEDERO\nestá lleno, chico.\012Tú también debes\nde estar de\011suerte.",
  ["26:74a2"] = "Entra, por\nfavor.\012Puedes empezar\nahora mismo.",
  ["1c:638a"] = "¡Eh! No tienes\nningún MONEDERO.\012¿Y cómo te voy a\ndar las fichas,\011chico?",
  ["26:74d6"] = "Lo siento. Sólo\npueden entrar\012aquéllos que van\na luchar.",
  ["1c:6345"] = "¡Bien!\012¡Me gusta hacer\nfavores a la\011gente!",
  ["26:751d"] = "Lo siento, joven.\nÉsta es la segunda\012vez que viene hoy.\nSólo se puede\012entrar una vez al\ndía.",
  ["1c:62dc"] = "¡Bien!\012¡Las fichas no\ndejan de salir!\012¿Qué, chico?\n¿Quieres jugar?\012¡Compartiré la\nsuerte contigo!",
  ["26:7578"] = "He perdido…\n¡Qué pena…!",
  ["1c:6295"] = "Creo que esta\nmáquina soltará\011el dinero…\012Las posibilidades\nvarían según\011la máquina.",
  ["26:7587"] = "He viajado hasta\naquí sólo para\011luchar contra ti.",
  ["1c:6242"] = "Quiero jugar en\nesta máquina.\012Ayer me desplumó,\nasí que hoy\012soltará el\ndinero.",
  ["26:75f4"] = "El LÍDER de este\nGIMNASIO es\011genial.",
  ["1c:6215"] = "Todas las\ntragaperras son de\011última generación.",
  ["26:761a"] = "¿Has estado en\nISLA CANELA?\012Es una isla muy\nal sur de aquí.",
  ["1c:61d0"] = "¡Bienvenido!\012Al lado puedes\ncambiar tus\012fichas por\npremios fabulosos.",
  ["26:76ad"] = "¿Dónde estará el\nLÍDER del GIMNASIO\012de CIUDAD VERDE?\nQuería desafiarle.",
  ["1c:601a"] = "",
  ["26:76f5"] = "No hay ningún\nENTRENADOR en\012el GIMNASIO de\nCIUDAD VERDE.\012El LÍDER dice que\nsu política es\012ganar sin tener\nsubordinados.",
  ["1c:5f65"] = "{PLAYER}, ¿lo\nhas oído?\012Rumores recientes\ndicen que un\012POKéMON multicolor\naparece en la\011TORRE HOJALATA.\012Acabo de curar a\nmi equipo y ahora\012salgo para CIUDAD\nIRIS.\012¡Nos vemos,\n{PLAYER}!",
  ["26:776b"] = "Dicen que el\nGIMNASIO de ISLA\012CANELA está\ndestruido.\012Me pregunto que\nhabrá sido de\011BLAINE, su LÍDER.",
  ["1c:5f22"] = "EUSINE: ¡Hola!\012Vuelvo de visitar\nmi ciudad.\012Llevaba tiempo\nsin ir.",
  ["26:77c8"] = "Mi sueño es ser\nLÍDER de GIMNASIO.",
  ["1c:5ec1"] = "El TEAM ROCKET\nestá escondido\012en el sótano del\nCASINO.\012Espera. Eso fue\nhace tres años.",
  ["26:7865"] = "¡Hola! Me alegro\nde verte.\012Eres la primera\nvisita que recibo\012desde hace\nmucho tiempo.\012¡Estoy muy\ncontento! Te voy\012a hacer un\npequeño regalo.",
  ["1c:5e70"] = "ERIKA es experta\nen POKéMON planta.\012Si no tienes\ncuidado, acabará\011contigo.",
  ["26:78e5"] = "Es una PEPITA.\012No puedo darte\npepitas de la\012sabiduría,\n¡sólo esto!",
  ["1c:5db3"] = "MT03 es MALDICIÓN.\012Es un terrible\nataque que reduce\012poco a poco los\nPS de la víctima.",
  ["26:7955"] = "¿Eres {PLAYER}?\012Soy el AYUDANTE\ndel PROF. OAK.\012No sabía que\nestabas aquí.\012El LAB. del PROF.\nOAK está cerca de\011PUEBLO PALETA.",
  ["1c:5ba3"] = "Érase una vez un\nniño pequeño al\012que le regalaron\nuna BICICLETA…\012Quería probarla\nenseguida…\012Se lo estaba\npasando tan bien\012que olvidó que\nanochecía…\012De vuelta a casa,\nen plena noche,\012¡la bici empezó\na frenarse!\012¡Cada vez era más\ndifícil pedalear!\012Y cuando dejó de\npedalear, ¡la bici\012empezó a moverse\nhacia atrás!\012Era como si la\nbici estuviera\012maldita y él fuera\na desaparecer.\012…\012…\012(¡CHILLIDO!)\012¡Y el niño siguió\nsubiendo por el\011CAMINO de BICIS!\012¡Ba-dum!\n¡Ba-dum ba-dum!\012Por haberme\nescuchado, ¡aquí\011tienes esta MT03!",
  ["26:7a29"] = "Sólo pueden pasar\nlos entrenadores\012que demuestren\nsu valía.",
  ["1c:5b4a"] = "Pero no te dará\ntanto miedo si\011aún es de día.\012Vuelve cuando\nanochezca, ¿vale?",
  ["26:7a5f"] = "No tienes todas\nlas MEDALLAS\011de JOHTO.\012Lo siento, pero no\npuedo dejarte\011pasar.",
  ["1c:5b27"] = "Te contaré una\nhistoria de miedo.",
  ["26:7ab4"] = "¡Oh! ¡Las ocho\nMEDALLAS de JOHTO!\012¡Le ruego que\npase, por favor!",
  ["1c:5aa1"] = "Hay un graffiti\nen la pared…\012¡{PLAYER} añadió\nun bigote!",
  ["26:7af1"] = "Este camino lleva\na MT.PLATEADO.\012Donde verás a unos\nPOKéMON fuertes\011y terribles.",
  ["1c:5a3f"] = "Las alturas…\n¡me gustan tanto…!\012¡Me atrevería a\ndecir que la única\012cosa que ama las\nalturas como yo es\011el humo!",
  ["26:7b37"] = "Vas a la LIGA\nPOKéMON, ¿verdad?\012El ALTO MANDO es\ntan fuerte que da\012miedo. ¡Están\nesperándote!",
  ["1c:5996"] = "Está lleno de\nmaterial de\012referencia: hasta\nun POKé MUÑECO.",
  ["27:400e"] = "El MARINERO del\nCAFÉ OLIVO de aquí\012al lado es muy\ngeneroso.\012Le enseñó FUERZA a\nmi POKéMON.\012Ahora puede mover\nrocas grandes.",
  ["1c:5928"] = "Es un dibujo\ndetallado de\011una chica guapa.",
  ["27:41b9"] = "Gracias por\nayudarnos en el\011FARO…\012Pero esto es\ndistinto. Déjame\011que me presente.\012Soy YASMINA, una\nLÍDER de GIMNASIO.\011Uso el tipo acero.\012¿Sabes algo\ndel tipo acero?\012Fue descubierto\nhace poco\011tiempo.\012¡Um…! ¡Veamos!",
  ["1c:58ca"] = "¿A que las GEMELAS\nson adorables?\012Y YASMINA también\nes muy guapa.\012¡Me encantan!",
  ["27:433a"] = "{PLAYER}\nrecibió la\011MEDALLA MINERAL.",
  ["1c:5830"] = "Avísame si quieres\nque te imprima tu\011DIPLOMA.",
  ["27:43a5"] = "Usa esta MT\npara enseñar\011COLA FÉRREA.",
  ["1c:57b4"] = "Soy el ARTISTA\nGRÁFICO.\012¡Te he dibujado!",
  ["27:4402"] = "YASMINA usa el\ntipo acero recién\011descubierto.\012No sé mucho\nsobre ese tipo.",
  ["27:44a8"] = "YASMINA, la LÍDER\ndel GIMNASIO, está\011en el FARO.\012Ha estado cuidando\na un POKéMON\011enfermo.\012Un buen entrenador\ndebe de ser\011compasivo.",
  ["27:49c5"] = "¡El menú del CAFÉ\nOLIVO está repleto\012de buena comida\npara fornidos\011MARINEROS!",
  ["1a:6823"] = "Vale. Vuelve fuera\ny termina\011el juego.",
  ["1a:679a"] = "Aún te quedan\n{STRBUF} minuto(s).\012¿Quieres terminar\nahora?",
  ["1a:667c"] = "¡Oh, oh…!\nTu equipo y\012tu CAJA del PC\nestán llenos.\012No tienes sitio\npara guardar el\011POKéMON bicho.\012Haz sitio en\ntu equipo o en\012la CAJA del PC y\nluego ven a verme.",
  ["27:4d70"] = "MUU-MUU: ¡Muu…!",
  ["1a:65dc"] = "Muy bien.\nEsperamos verte\011pronto por aquí.",
  ["27:4d80"] = "Está débil…",
  ["1a:656b"] = "Los POKéMON de\n{PLAYER} se quedan\011con el AYUDANTE.",
  ["1a:64c6"] = "¡Oh, oh…!\012Tienes más de\nun POKéMON.\012Tendrás que usar\na {STRBUF},\012el primer POKéMON\nde tu equipo.\012¿Te parece\nbien?",
  ["27:4dd8"] = "¡MUU-MUU está un\npoco mejor!",
  ["27:5303"] = "¡Estoy alucinado!\012Vino un chico\nde tu edad, de\012pelo largo y\nmirada penetrante.\012¡Y me obligó a\ndarle mis\011queridos POKéMON!\012Todavía me queda\nuno, ¿pero qué\011hago si vuelve?\012Pareces fuerte.\n¿Podrías cuidar\012de mi POKéMON\nun rato?",
  ["27:53ed"] = "¡Oh, gracias!\012¡Cuídale bien,\npor favor!",
  ["1d:5b8e"] = "¡Voy a ver a mi\nabuela para que me\012atrape unos\ncuantos bichos!",
  ["1d:5b38"] = "La débil llama\npierde fuerza.",
  ["1d:5996"] = "He encontrado una\nmoneda muy bonita.\012Alguien debe de\nhaberla perdido…",
  ["1d:5970"] = "¡Yujuu!\n¡Qué suerte!",
  ["1d:5923"] = "No… No lo\nencuentro…",
  ["1d:58b1"] = "Los marineros\nhacemos mucho\012trabajo físico.\n¡Es agotador!",
  ["1d:5812"] = "Sí, es verdad,\nsoy un marinero.\012¡No hacía\nnada malo!\012Como el camarote\nestaba vacío, me\011eché un sueñecito.\012¡Ah! ¡Olvídalo!\n¡Luchemos!",
  ["1d:57b9"] = "¡Es demasiado!\n",
  ["1d:56b3"] = "¡Me entreno para\nser la CAMPEONA!",
  ["1d:5669"] = "¡Quería ganar!",
  ["1d:54be"] = "El FERRY S.S. AQUA\nha llegado a\011CIUDAD CARMÍN.",
  ["1d:529b"] = "El FERRY S.S. AQUA\nse dirige a\011CIUDAD OLIVO.\012Daremos un\naviso cuando\011lleguemos.",
  ["1d:50a6"] = "¿Vienes de\nJOHTO?\012Dicen que allí\nviven muchos\011POKéMON raros.",
  ["1d:5059"] = "El FERRY zarpará\nel miércoles.",
  ["1d:4f8b"] = "¿Puedo ver tu\nTICKET BARCO?",
  ["27:6c09"] = "Esperamos poder\nayudarte de nuevo.",
  ["27:6c26"] = "Por aquí, por\nfavor.",
  ["27:6c3d"] = "¿Quieres saber\nmás sobre la\011TORRE BATALLA?",
  ["27:6d3c"] = "Las reglas de la\nTORRE BATALLA\012están aquí.\n¿Quieres leerlas?",
  ["27:6d72"] = "Pueden combatir\ntres POKéMON.\012Los tres deben ser\ndiferentes.\012Los objetos que\nlleven también\011serán diferentes.\012Ciertos POKéMON\npueden tener\012restricciones de\nnivel.",
  ["27:6e18"] = "¡Perdona!\nNo has GUARDADO\012antes de salir de\nla SALA.\012Lo siento mucho,\npero tu batalla se\012declarará no\nválida.",
  ["27:6e92"] = "Tus POKéMON\nserán curados\011completamente.",
  ["18:7237"] = "No tienes sitio\npara esto.",
  ["18:71c3"] = "Lo encontré\nmientras cuidaba\012el POKéMON de\nalguien.\012Pero el entrenador\nno quiso el HUEVO,\012así que lo dejé\npor aquí.",
  ["18:71ae"] = "¡{PLAYER} recibió\nel HUEVO RARO!",
  ["18:70ce"] = "Soy el ENCARGADO\nde la GUARDERÍA.\012¿Sabes algo acerca\nde los HUEVOS?\012He estado cuidando\nPOKéMON junto con\011mi esposa.\012¡Y hemos consegui-\ndo un HUEVO!\012¿A que es\nincreíble?\012¿Qué? ¿Te gusta\neste HUEVO?\012¡Entonces, \nquédatelo!",
  ["18:6fda"] = "El abuelo te\nestaba buscando.",
  ["18:6e97"] = "¿Has visto el\nsantuario en honor\011del guardián?\012Protege el\nBOSQUE desde\011antaño.\012Creo que debe\nde ser un POKéMON\011del tipo planta.",
  ["18:6e83"] = "BUTTERFREE: ¡Frii!",
  ["18:6e41"] = "Algo va mal en el\nENCINAR…\012Deberías alejarte.",
  ["18:6df6"] = "Es DULCE AROMA.\012Úsala siempre que\naparezcan POKéMON.\012Atraerá a los\nPOKéMON.",
  ["18:6d9d"] = "¿Estás completando\nuna POKéDEX?\012Sería duro si los\nPOKéMON no\012aparecieran.\nPrueba esta MT.",
  ["18:6359"] = "¡Vuelve cuando\nquieras!",
  ["28:5244"] = "Ayer, el PROF. OAK\nestuvo en el\012estudio para\ngrabar su\011programa.\012Así que fui a\nverle y me\011presenté.\012¿Sabes qué? ¡Escu-\ncha mi programa!\012¡Oh! ¡Aquí viene\nel PROF. OAK de\011nuevo!\012¡Me voy a hablar\ncon él!\012¡Luego te llamo!",
  ["1e:5b1c"] = "¡Gracias, {PLAYER}!\nNos estás ayudando\012a descubrir los\nmisterios POKéMON.\012¡Recibe esto\ncomo prueba\011de nuestra estima!",
  ["1e:5d31"] = "¡La MASTER BALL es\nla mejor!\012¡Es la BALL\ndefinitiva!\012Captura cualquier\nPOKéMON sin\011fallar.\012Se les entrega a\nlos grandes\012investigadores\nPOKéMON.\012¡Creo que tú harás\nun mejor uso de\012ella que yo,\n{PLAYER}!",
  ["1e:5f65"] = "Sólo somos dos,\nasí que siempre\011estamos ocupados.",
  ["5d:519b"] = "No he conseguido\nlo que te prometí.\012Te llamaré en\ncuanto lo tenga,\012así que… ¿puedes\nesperar un poco?",
  ["5d:638a"] = "¡Escucha, escucha!\012¿Conoces a PRIMO,\nel profesor que\012dirige la ACADEMIA\nPOKéMON en MALVA?\012Le vi haciendo\npiruetas mientras\012corría. ¡Era muy\ndivertido!",
  ["5d:66ac"] = "¡Escucha, escucha!\012¡BLANCA del GIM.\nTRIGAL comenzó a\012luchar hace poco\ntiempo!\012¡Pero la LIGA\nPOKéMON la eligió\012como LíDER de\nGIMNASIO!\012Creo que debe de\nser muy buena.",
  ["18:42cb"] = "¿Me recuerdas del\nESCONDITE de\011PUEBLO CAOBA?\012Entonces perdí,\npero esta vez no\011lo haré.",
  ["18:4246"] = "Escondimos al\nauténtico DIRECTOR\012en el ALMACÉN\nSUBTERRÁNEO.\012Está al otro\nextremo del\011SUBTERRÁNEO.\012Pero dudo que\nllegues tan lejos.",
  ["18:4223"] = "Muy bien. Te diré\ndónde está.",
  ["17:6f15"] = "¡Oh, no! ¡Son\ntan inútiles!",
  ["1e:5739"] = "ELM: ¿Esto?",
  ["1e:593c"] = "ELM: ¡No te\nrindas! Si sé algo\012sobre ese HUEVO,\nte llamaré.",
  ["1e:5a72"] = "ELM: ¡Qué buen\naspecto, {PLAYER}!",
  ["28:5318"] = "¡Cof, cof…!\012Mmm siento uh que\ncódigo dit ahora.\012Buh uma pro so uh\ntienes que id ub\012so no un puede que\nmie uhm en l aire.\012Uh fidz muh voz\nahora.\012Nos vemos en las\nondas. ¡Al habla\011BUENA!",
  ["1e:5cd0"] = "ELM: ¡{PLAYER}!\nGracias a ti,\012mis estudios\nvan fenomenal.\012Toma esto como\nprueba de mi\011estima.",
  ["28:53d8"] = "Hola, {PLAYER}.\nGanaste esa\012TARJETA RADIO\nacertando el\012concurso de la\nrecepción,\011¿verdad?\012¿Sabes qué? ¡Yo\npreparé las\011preguntas!\012¿Fueron demasiado\nfáciles para ti…?\012¡Bueno, ya\nhablaremos!",
  ["1e:5e6f"] = "El barco zarpa de\nCIUDAD OLIVO.\012Pero eso ya lo\nsabías, {PLAYER}.\012Has viajado por\ntodas partes con\011tus POKéMON.\012¡Dale recuerdos\nal PROF. OAK\011en KANTO!",
  ["28:5488"] = "Estoy eufórica\nporque cada vez\012hay más gente que\nparticipa en mi\011programa CÓDIGO.\012Pero cuando el có-\ndigo fue PIKACHU,\012fue… uh… ejem…\nabrumador.\012La gente del CLUB\nde FANS gritaba\012'¡PIKACHU!' una y\notra vez. Vamos,\012que eran muy\nruidosos.\012¡Los oyentes\nestaban aturdidos\011por el jaleo!\012¡De todas formas,\ndebo volver al\011trabajo!\012¡Ya hablaremos!",
  ["1e:6078"] = "¡{PLAYER}!\012¡Usa esto para\nllenar tu POKéDEX!",
  ["28:55de"] = "¿Sabes qué?\n¡El DIRECTOR de la\012TORRE RADIO es\nun gran fan de la\011televisión!\012Hace nada, en un\nprograma de TV de\012moda, se decía que\nlos trajes negros\011estaban de moda.\012Ahora siempre\nviste de negro.\012Pero es un secreto\nlo de que nuestro\012DIRECTOR es un fan\nde la TV, así que\012si le ves, ¡no se\nlo menciones!\012¡Oh! ¡El DIRECTOR\nllegará pronto!\012¡Hasta luego!\n¡Sintoniza mi\011programa!",
  ["1e:61fd"] = "La ventana está\nabierta.\012Entra una\nsuave brisa.",
  ["28:5717"] = "",
  ["1e:62c6"] = "{PLAYER} abrió\nun libro.\012Pista de viaje 3:\012Abre tu MOCHILA y\npulsa SELECT para\011mover objetos.",
  ["28:583d"] = "{PLAYER}… ¿cuál fue\nel primer POKéMON\011que atrapaste?\012Oh, ¿de verdad…?\012He visto muchos\nPOKéMON por aquí,\012pero nunca he\natrapado ninguno.\012Debería intentarlo\nalguna vez.\012¿Sabías que el\nprimer POKéMON que\012atrapó ROSA fue un\nDROWZEE?\012Eso no es muy\nhabitual…\012Pero el DROWZEE de\nROSA la hacía\012dormirse en el\ntrabajo, así que\012se lo cambió a un\nfan por un MEOWTH.\012¡Hablemos de\nPOKéMON en otra\011ocasión!\012¡Adiós!",
  ["1d:567b"] = "Los entrenadores\nde JOHTO pueden\012luchar contra los\nLÍDERES de KANTO.",
  ["28:59b1"] = "¿Sabes qué? Todos\nlos de la TORRE\012RADIO nos vamos de\nvacaciones a la\012TORRE RADIO de\nPUEBLO LAVANDA.\012¿Vamos a desperdi-\nciar nuestras\012vacaciones yendo a\notra TORRE RADIO?\012¡Preferiría ir a\nla playa!\012¡{PLAYER}, espero\nque te diviertas\012por los dos en tu\nviaje!\012¡Adiós!",
  ["5d:4ee2"] = "Mmm… ¿{PLAYER}?\n¿Qué ocurre?\012¿Olvidaste nuestro\ntrato?\012{STRBUF}.\012Allí te espero.",
  ["28:5ac0"] = "¿Sabías…?\012NARDO y FLORO\nhablan por teléfo-\011no durante horas\011acerca de la músi-\011ca POKéMON que\011deben poner los\012diferentes días de\nla semana.\012Una vez, el estilo\nrapero de FLORO\012enfadó bastante a\nNARDO.\012Así que tuvimos\nque aguantar la\012estúpida verbo-\nrrea sin sentido\012de NARDO un buen\nrato.\012¡Hablamos otra vez\ncuando quieras!",
  ["5d:4f90"] = "Hace un tiempo, mi\nFARFETCH'D derrotó\011a {STRBUF}.\012Deberías haber\nvisto a FARFETCH'D\012con ese puerro.\n¡Impresionante!",
  ["28:5bed"] = "Pronto me iré de\ncompras con ROSA\011y LILA.\012Sería genial que\nel CENTRO COMER-\011CIAL de TRIGAL\011tuviera rebajas\011cuando vayamos…\012¡{PLAYER}, quizá\npudiéramos ir\011contigo!\012¡Luego te llamo!",
  ["5d:507d"] = "¿Quieres volver a\nluchar?\012Por alguna razón,\nmi FARFETCH'D está\012nerviosísimo y\ndeseando irse.\012Estoy en\n{STRBUF}.\012Mira a ver si\nme ves, ¿vale?",
  ["28:5c88"] = "Estoy pensando en\nir mañana al\012CASINO. Hace mucho\nque no voy.\012Sabes… Tengo mi\nmáquina favorita…\012Da muchos premios…\n¡no te engaño!\012¿Eh? No, no…\n¡Es mi secreto!\012¡Debes encontrarla\ntú!\012¡Te llamo luego!",
  ["5d:5116"] = "Mi FARFETCH'D\nllevaba en el pico\011algo bonito.\012Como prometí,\npuedes quedártelo.\012Búscame en\n{STRBUF} y\011te lo daré.",
  ["28:5d5f"] = "",
  ["5d:520a"] = "{PLAYER}, ¿puedes\ndarte prisa?\012FARFETCH'D está\nnervioso.\012¡Si no vienes\npronto, podría\012golpearme con el\npuerro!\012¡{STRBUF}!\012¡Por favor, ven en\ncuanto puedas!",
  ["28:5e2f"] = "¿Hace sol hoy?\012Cuando se pasa\ntanto tiempo en la\012TORRE RADIO como\nyo hago, se pierde\012el contacto con el\nexterior.\012Puede ser muy\naburrido.\012¡Por favor, llama\nde nuevo!",
  ["5d:6424"] = "¡Escucha, escucha!\012Colecciono muñecos\nde peluche de\011POKéMON.\012Pero no sé como\nconseguir un MU-\011ÑECO PIKACHU SURF.\012Ninguno de mis\namigos lo tiene.\012¡Debe de ser\nrealmente raro!\012Puedes enorgulle-\ncerte de verdad si\011consigues uno.",
  ["29:4000"] = "Por cierto, soy un\nMONTAÑERO, así que\012suelo ir a cuevas\ny montañas.\012De vez en cuando\nveo POKéMON raros.\012Puedo llamarte la\npróxima vez que\011vea uno.\012¿Quieres inter-\ncambiar números de\011teléfono?",
  ["5d:6599"] = "¡Escucha, escucha!\012Hay una PELUQUERÍA\nPOKéMON en CIUDAD\012TRIGAL que dirigen\ndos hermanos.\012El hermano mayor\nes bueno y el\011menor más bien no.\012Pero a veces, el\nmenor hace mejor\012el trabajo que\nsu hermano.\012Cada vez que voy,\nlo paso mal\012decidiendo a\nquién elijo…",
  ["29:40a9"] = "Puedo llamarte la\npróxima vez que\011vea uno.\012¿Quieres inter-\ncambiar números de\011teléfono?",
  ["5d:674f"] = "¡Escucha, escucha!\012¿Has participado\nen el Concurso de\012Captura de Bichos\ndel PARQUE\011NACIONAL?\012Lo hice una vez,\npero todo lo que\012pude atrapar fue\nun CATERPIE.\012Pero, ¿sabes qué?\012Gané con ese\nCATERPIE.\011¿No es genial?",
}
